RG.HK["15"] = [{"id":"15_kasugayama","n":"春日山城（上杉謙信の居城）","yomi":"かすがやまじょう","cat":"城","rank":"S","y":1548,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"上越市中屋敷・大豆","st":"えちごトキめき鉄道 春日山駅から歩いて約40分（中屋敷のバス停から登り口まで約15分）","la":37.1497,"lo":138.2036,"hook":"«越後の龍» 上杉謙信が生まれ、戦いに出かけ、そして最期を迎えた山。石垣のない «土の城» が山まるごと残る。","lead":"春日山城は、標高約180mの春日山にきずかれた大きな山城です。戦国時代に上杉謙信が本拠地にし、ここから川中島や関東へ何度も出陣しました。建物は残っていませんが、曲輪（平らな段）や空堀、井戸のあとが山のあちこちに残り、歩くと城の広さを体で感じられます。","story":["1530年、越後の守護代・長尾為景の子として、一人の男の子がこの城で生まれたと伝わります。幼名は虎千代。のちの上杉謙信です。父の死後、兄の晴景が家をつぎましたが、国の中の争いをおさえきれません。家臣たちは «若いが戦に強い» 弟に期待をかけ、1548年、景虎（謙信）は19歳で春日山城の主になりました。","春日山の頂上に立つと、北に日本海、南に頸城平野が広がります。«なぜこの山だったのか?» 答えは景色にあります。海の港・直江津と、国府のあった平野を一度に見わたせ、しかも山は急で攻めにくい。見張りと守りの両方にぴったりの場所だったのです。","謙信は信仰のあつい武将でした。本丸のそばには «毘沙門堂» があり、戦の前にはここにこもって祈ったといわれます。旗じるしは «毘» の一字。«われは毘沙門天の生まれかわりなり» という気持ちで、武田信玄との川中島の戦いや、北条氏をせめる関東出陣に向かいました。1561年には上杉憲政から «上杉» の名と関東管領の職をゆずられています。","1578年3月、次の遠征の準備をしていた謙信は、城の中でたおれ、数日後に49歳で亡くなりました。«四十九年一睡の夢 一期の栄華一盃の酒» という辞世の句が伝わっています。あとつぎを決めていなかったため、養子の景勝と景虎が争う «御館の乱» が起き、越後は二つに割れました。","勝った景勝も、1598年に豊臣秀吉の命令で会津へ移ります。代わりに入った堀氏は、山の上では不便だとして、1607年ごろ直江津の近くに福島城をきずいて移り、春日山城は役目を終えました。いま山を歩くと、400年以上前の土の段が、草木の下でじっと主の帰りを待っているように見えます。"],"tl":[["1530年","長尾為景の子・虎千代（謙信）が生まれる（春日山城で、と伝わる）"],["1548年","景虎（謙信）が兄にかわって家をつぎ、城主に"],["1561年","上杉の名と関東管領職をつぎ «上杉政虎» に"],["1578年","謙信が城内で倒れ死去。御館の乱が始まる"],["1598年","上杉景勝が会津へ移り、堀秀治が入る"],["1607年ごろ","堀氏が福島城へ移り、春日山城は廃城に"],["1935年","国の史跡に指定"]],"who":[["上杉謙信","この城で生まれ、城主として越後を治めた武将"],["長尾為景","謙信の父。越後の実権をにぎった守護代"],["上杉景勝","謙信の養子。御館の乱に勝ち、城をついだ"],["直江兼続","景勝の重臣。山の中腹に屋敷跡と伝わる場所がある"],["堀秀治","上杉家のあとに入り、城を平地へ移した大名"]],"deep":["城域は山全体から麓の «総構» まで広がり、土塁と堀で城下をかこっていたと考えられています。麓に残る «監物堀» はその一部とされ、発掘調査で確かめられました。","石垣はほとんど使われていません。戦国時代の越後の城は、土を削り盛って曲輪や堀をつくる «土の城» が中心。春日山城は、そのもっとも大きな例の一つです。","本丸近くの «大井戸» は、今も水をたたえています。山城で一番こまるのは水。籠城できるかどうかは、井戸があるかにかかっていました。","謙信の死因は、当時の記録から脳の病気（脳卒中）と考える説が有力ですが、くわしいことは分かっていません。«厠で倒れた» という話も伝わります。","麓の «春日山神社» は1901年、謙信をまつるために建てられた神社で、戦国時代の城の建物ではありません。童話作家・小川未明の父が建てたことでも知られます。","城の近くには «上越市埋蔵文化財センター» があり、城や城下の発掘成果を見ることができます。日本100名城の一つです。"],"look":["本丸跡からの日本海と頸城平野の眺め","毘沙門堂（謙信がこもって祈ったと伝わる場所・建物は再建）","大井戸","直江屋敷跡・景勝屋敷跡など家臣の曲輪","春日山神社と謙信の銅像","麓の監物堀と総構の土塁"],"q":["謙信が戦の旗に使った文字は？","«毘»。毘沙門天の «毘» で、ほかに «龍» の旗もあったといわれます。"],"koji":[{"w":"敵に塩を送る","m":"困っている敵を助けること。謙信が武田信玄の領国に塩を送った話から。ただし史実かどうかは確かではない"}],"myth":"生誕地、厠で倒れた話、辞世の句、«敵に塩を送る» の逸話は伝承。","img":["上杉謙信","上杉景勝","御館の乱","春日山神社"],"wp":"春日山城","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Kasaugayama_Castle.jpg",5248,3936,"春日山城"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:2/26/Kasugayama_jinjya_1.jpg",640,480,"春日山神社"]]},{"id":"15_sado_kinzan","n":"佐渡金山（道遊の割戸と宗太夫坑）","yomi":"さどきんざん","cat":"産業","rank":"S","y":1601,"era":["edo","meiji","showa"],"sh":"国指定史跡（佐渡金山遺跡）・世界遺産「佐渡島の金山」","ad":"佐渡市下相川","st":"両津港からバスで約1時間、「佐渡金山前」下車すぐ","la":38.0412,"lo":138.2482,"hook":"山が真っ二つ! 金を追いかけて人の手が掘り割った «道遊の割戸» は、400年の採掘の迫力をそのまま見せてくれる。","lead":"佐渡金山は、江戸時代のはじめから1989年まで、およそ400年近く金や銀を掘りつづけた日本最大級の金銀山です。江戸幕府のお金をささえ、明治からは近代的な鉱山になりました。2024年には «佐渡島の金山» として世界遺産に登録されています。","story":["江戸時代のはじめ、相川の山で大きな金銀の鉱脈が見つかりました。1601年に山師たちが発見したと伝わります。ちょうど徳川家康が天下をにぎったころ。幕府はすぐに佐渡を直接おさめる土地にし、全国から人が集まって、ただの海辺の村だった相川は、あっという間に数万人がくらす鉱山町になったといわれます。","最初は、地表に出ている鉱脈を上からどんどん掘りました。そのあとが «道遊の割戸»。山のてっぺんがV字に割れ、深さは70mをこえます。«なぜこんな形に?» 金をふくむ石の帯が、山を縦につらぬいていたからです。人々はその帯だけを追いかけて、ノミとツチで掘り進めたのです。","やがて坑道は地下深くへ。«宗太夫坑» では、江戸時代の坑道のようすが人形で再現されています。一番の敵は «水»。掘れば掘るほど地下水がわき、放っておけば坑道はしずんでしまいます。水をくみ上げる «水替» は、つらく危険な仕事でした。18世紀後半からは、江戸などの無宿人が送られてこの仕事をさせられ、多くの人が命を落としたといわれます。","明治になると、佐渡鉱山は国の経営となり、西洋の技術が入ります。1896年には三菱に払い下げられ、大立竪坑や北沢浮遊選鉱場などの近代的な施設がつくられました。昭和の戦争の時代には、朝鮮半島出身の人びとも働かされた歴史があり、世界遺産登録のときにはそのことをどう伝えるかも話し合われました。","1989年、鉱石が少なくなり、佐渡金山は操業を休止しました。今は、江戸の手掘りの跡、明治・昭和のコンクリートの施設が、同じ山に重なるように残っています。«金を掘る» という一つの仕事に、何世代もの人の汗と苦しみと工夫がつまっている。それを歩いて感じられる場所です。"],"tl":[["1601年","相川で大鉱脈が見つかったと伝わる"],["1603年","佐渡奉行所が置かれ、幕府直轄の鉱山に"],["1778年","江戸などの無宿人を水替人足として送り始める"],["1869年","明治政府の官営鉱山に"],["1896年","三菱合資会社に払い下げられる"],["1938年","北沢浮遊選鉱場が完成（大量処理の時代へ）"],["1989年","操業を休止"],["2024年","«佐渡島の金山» が世界遺産に"]],"who":[["大久保長安","初期の佐渡の支配を任され、鉱山開発を進めた"],["相川の鉱夫・水替人足","坑内で掘り、水をくみ出して金山をささえた無名の人々"],["三菱","明治から昭和まで鉱山を経営した"]],"deep":["産出量は、江戸時代から休山までで金約78トン、銀約2,300トンといわれます。数字は資料によって少しちがいます。","江戸時代の坑内の排水には、木製の «水上輪»（アルキメデスのねじ式ポンプ）も使われました。人の力で回して、水を少しずつ上へ送る道具です。","佐渡の金は «小判» の材料になり、幕府の財政をささえました。相川には «佐渡小判» をつくる後藤役所もありました。","世界遺産の構成資産は «西三川砂金山» と «相川鶴子金銀山» の2つ。道遊の割戸は相川の区域に入ります。","北沢浮遊選鉱場は、昭和のはじめに1か月で5万トンの鉱石を処理できたといわれ、«東洋一» とよばれました。今はコンクリートの遺構が遺跡のように残っています。","休止は «閉山» ではなく «操業休止» という形です。坑道の総延長は約400kmともいわれます。"],"look":["道遊の割戸（山頂がV字に割れた露頭掘り跡）","宗太夫坑（江戸時代の坑道と作業の再現）","道遊坑（明治以降の坑道とトロッコ）","北沢浮遊選鉱場跡とシックナー","大立竪坑の櫓"],"q":["道遊の割戸は何を追いかけて掘られた？","金銀をふくむ «鉱脈»。鉱脈が縦に走っていたので、山がV字に割れた形になりました。"],"koji":[],"myth":"1601年発見の話は伝承。産出量の数字は資料で差がある。","img":["佐渡島の金山","北沢浮遊選鉱場","相川 (佐渡市)","大久保長安"],"wp":"佐渡金山","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"],["c:8/87/Sadokinzan-doyunowareto_01.JPG",1024,712,"佐渡島の金山"],["c:5/5d/Kitazawa_Flotation_Plant_ac_%282%29.jpg",5990,3983,"北沢浮遊選鉱場"],["c:d/d8/Sado_bugyousyo.JPG",3072,2304,"相川 (佐渡市)"]]},{"id":"15_sado_bugyosho","n":"佐渡奉行所跡（相川）","yomi":"さどぶぎょうしょあと","cat":"町","rank":"S","y":1603,"era":["edo"],"sh":"国指定史跡（佐渡金山遺跡）","ad":"佐渡市相川広間町","st":"両津港からバスで約1時間、「佐渡版画村」付近で下車して歩いて約5分","la":38.0213,"lo":138.24,"hook":"金の島をおさめた «役所» と «工場» がひとつになった場所。復元された建物の中で、江戸の金づくりの音が聞こえてきそう。","lead":"佐渡奉行所は、江戸幕府が佐渡を直接おさめるために置いた役所です。島の政治や裁判だけでなく、掘り出した金銀の石をくだいて選り分ける «勝場» も同じ敷地にありました。今の建物は、発掘調査と古い絵図をもとに2000年に復元されたものです。","story":["1603年、佐渡金山の開発が本格的になると、幕府は相川の台地の上に奉行所を置きました。海を見下ろし、金山にも近い場所です。ここに江戸から «佐渡奉行» がやってきて、島の村々、港、そして金山のすべてを取りしきりました。","奉行所で一番大事だったのは、もちろん金と銀です。«なぜ役所の中に工場があるの?» それは、金を横流しされないためでした。山から運ばれた鉱石は、敷地内の «勝場» で細かくくだかれ、水で洗って金をふくむ重い粒だけを集めます。役人の目の前で作業させ、一粒ものがさない仕組みでした。","奉行所には、島の人びとの訴えを聞く «お白洲» もありました。佐渡は流人の島でもあり、金山ではたくさんの人が働いたので、争いやもめごとも少なくありません。奉行所はそれを裁き、ときには厳しい罰をあたえました。","奉行所の建物は、江戸時代に何度も火事で焼け、そのたびに建て直されました。明治になると役所として使われましたが、昭和の火災で焼けてしまいます。その後、発掘調査で建物の礎石や勝場の跡が見つかり、残っていた絵図と照らし合わせて復元が行われました。","今は、奉行が執務した御役所の部屋や、ゴトンゴトンと石をくだいた勝場の道具を見学できます。«島全体が一つの会社のようなもの» だった江戸時代の佐渡。その本社と工場を、いっしょに見られる場所です。"],"tl":[["1603年","相川に佐渡奉行所が置かれる"],["江戸時代","火事で何度も焼け、再建をくり返す"],["1868年","明治維新。奉行所の役目が終わる"],["明治以降","役所の庁舎などとして使われる"],["昭和","火災で建物が焼失"],["1994年","国の史跡（佐渡金山遺跡）に追加される"],["2000年","御役所・勝場などが復元される"]],"who":[["大久保長安","初期の佐渡支配を任され、奉行所の仕組みをつくった"],["佐渡奉行","江戸から派遣され、島と金山を治めた役人"],["勝場の職人","鉱石をくだき、金を選り分けた人々"]],"deep":["«勝場» の «せり» とは選り分けること。石うす、ねこ流し（布を張った斜面に鉱石の泥を流して金粒をひっかける方法）など、比重の差を使った技術が再現されています。","復元は、発掘で見つかった礎石の位置と、嘉永年間（1850年代）ころのものとされる絵図などを手がかりに行われました。","佐渡奉行は多いときに2人いて、1人は江戸、1人は佐渡に交代でつとめる形でした。","奉行所の周りには、京町・米屋町・大工町など職業の名がついた町が広がっていました。今も相川の町名にその名残があります。","«佐渡金山遺跡» の史跡には、奉行所跡のほか道遊の割戸、宗太夫坑などもふくまれ、町と山をセットで保存しているのが特徴です。"],"look":["復元された御役所（奉行の執務の間・お白洲）","勝場（鉱石を選り分ける工程の再現）","発掘で見つかった礎石や遺構表示","周りの京町通りの坂道と町並み"],"q":["奉行所の中にあった、金を選り分ける工場を何という？","«勝場（せりば）»。役人の目の前で作業させ、金の持ち出しをふせぎました。"],"koji":[],"myth":"","img":["佐渡島の金山","相川 (佐渡市)","佐渡奉行"],"wp":"佐渡奉行所","rel":{"ev":[],"grave":[]},"ph":[["c:d/d8/Sado_bugyousyo.JPG",3072,2304,"佐渡奉行所"],["c:8/87/Sadokinzan-doyunowareto_01.JPG",1024,712,"佐渡島の金山"]]},{"id":"15_yahiko","n":"彌彦神社（越後一宮）","yomi":"いやひこじんじゃ","cat":"寺社","rank":"S","y":927,"era":["nara","heian","taisho"],"sh":"国の重要文化財（宝物の志田大太刀など）","ad":"西蒲原郡弥彦村弥彦","st":"JR弥彦線 弥彦駅から歩いて約15分","la":37.7017,"lo":138.8267,"hook":"«おやひこさま»。万葉集にもうたわれた神の山のふもとで、越後の人は1000年以上いのりつづけてきた。","lead":"彌彦神社は、弥彦山を神の山としてまつる、越後でもっとも古く大切にされてきた神社の一つです。まつられている神さまは天香山命（あめのかごやまのみこと）。今の社殿は、火事で焼けたあと大正時代に建て直されたものです。","story":["奈良時代にできた «万葉集» に、こんな歌があります。«伊夜比古 おのれ神さび 青雲の たなびく日すら 小雨そほ降る»。いやひこの山は神々しく、晴れた日でも雨が降る——。越後平野にぽつんとそびえる弥彦山は、昔から «神のいる山» として人々に見上げられてきました。","伝説によると、天香山命は船で越後の海岸に上陸し、人々に漁のしかたや塩づくり、稲づくりなどを教えたといいます。«だから越後の人は、この神さまを親のようにしたうのか» ——地元では «おやひこさま» と親しみをこめてよびます。","平安時代の «延喜式» では、国の大事な神社として名前がのっています。武士の時代になっても、源氏や上杉氏など越後をおさめた人々がこの神社を重んじ、刀やよろいを奉納しました。宝物殿には、長さ2m をこえる大きな太刀など、たくさんの宝がのこっています。","1912年、町の大火で社殿が焼けてしまいました。人々は悲しみましたが、すぐに再建が始まり、1916年に今の社殿ができあがります。境内の杉の大木や玉砂利の参道は、そのとき以前からの神社の空気を今に伝えています。","毎年7月25日の夜には «燈籠神事»（灯籠おし）が行われ、たくさんの灯籠が暗い境内をねり歩きます。弥彦山の山頂には神さまのお墓とされる «御神廟» があり、ロープウェイで登ることもできます。"],"tl":[["奈良時代","«万葉集» に伊夜比古の歌がのる"],["927年","«延喜式» に名神大社として記される"],["中世","越後一宮として武士たちの信仰を集める"],["1912年","大火で社殿が焼失"],["1916年","今の社殿が再建される"],["1982年","参道入口近くに高さ約30mの大鳥居が建つ"]],"who":[["天香山命","まつられている神。越後に産業を伝えたと伝わる"],["上杉謙信","越後の支配者として彌彦神社を崇敬したといわれる"],["万葉集の歌人","弥彦山の神々しさを歌にした（作者名は不明）"]],"deep":["«越後一宮» は、上越市の居多神社も名乗っていて、時代によって二つの神社が並び立っていたと考えられています。","拝礼は «二礼四拍手一礼»。出雲大社などと同じく、ふつうの二拍手とちがう作法です。","宝物の «志田大太刀» は室町時代の作とされ、刃の長さが2m をこえる大太刀です。国の重要文化財に指定されています。","社殿は、弥彦山を背にして建っており、山そのものを神と考える古い信仰のかたちを感じさせます。","燈籠神事は国の重要無形民俗文化財。神楽や舞もあわせて奉納されます。","境内には «鹿苑» があり、神の使いとされる鹿が飼われています。弥彦山とともに、自然そのものを神聖なものとする信仰が感じられます。"],"look":["大正時代に再建された拝殿と、背後の弥彦山","玉の橋（神さまが渡る橋で、人は渡れない）","宝物殿の志田大太刀","火の玉石（持ち上げて願いを占う石）","弥彦山頂の御神廟と日本海の眺め"],"q":["彌彦神社での拍手の回数は？","4回。«二礼四拍手一礼» が正式な作法です。"],"koji":[],"myth":"天香山命の上陸や産業を教えた話は伝説。","img":["弥彦山","越後国","一宮"],"wp":"彌彦神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/7e/Iyahiko-jinja_1.JPG",2500,1639,"彌彦神社"],["c:9/92/Mt.Yahiko_from_Sakae_PA.jpg",1000,701,"弥彦山"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"15_nagaoka_jo","n":"長岡城跡（北越戦争の激戦地）","yomi":"ながおかじょうあと","cat":"幕末","rank":"S","y":1868,"era":["edo","meiji"],"sh":"","ad":"長岡市城内町（JR長岡駅周辺）","st":"JR長岡駅の大手口を出てすぐ（本丸跡の碑）","la":37.4475,"lo":138.8514,"hook":"今は新幹線の駅。250年つづいた城は、戊辰戦争で二度落ち、一度は取りもどされた。","lead":"長岡城は、江戸時代に牧野家が約250年おさめた長岡藩のお城です。1868年の北越戦争で、家老・河井継之助の長岡藩は新政府軍と戦い、城は落城、奪回、再落城という激しい運命をたどりました。城のあとは今、JR長岡駅になっていて、駅前に本丸跡の碑があります。","story":["江戸時代のはじめ、堀直寄が信濃川のそばに城をきずき始め、1618年に牧野忠成が入りました。以後250年、牧野家が長岡をおさめます。藩の心がまえは «常在戦場»——いつも戦場にいるつもりで、という意味でした。まさかその言葉どおりの日が来るとは、だれも思っていなかったでしょう。","1868年、戊辰戦争。長岡藩の家老・河井継之助は、西洋式の武器をそろえ、どちらにもつかない «武装中立» を目指しました。«長岡を戦場にしたくない»。しかし小千谷で新政府軍と話し合ったものの、交渉は決裂。長岡藩は奥羽越列藩同盟に加わり、戦いが始まります。","5月、新政府軍は信濃川をわたって攻め入り、長岡城はわずか一日で落ちてしまいました。長岡藩はねばり強く反撃を続けます。7月、河井は大きな賭けに出ました。城の北にある «八丁沖» という広い沼地を、夜の闇にまぎれて渡り、敵のうしろから襲ったのです。«まさかあの沼を!» ——城はふたたび長岡藩の手にもどりました。","しかし喜びは長く続きませんでした。この戦いで河井は足に大けがをし、数日後、新政府軍の大軍がふたたび城を奪います。藩士や家族は会津をめざして山道を退き、河井は途中の只見（今の福島県）で亡くなりました。町は焼け、たくさんの人が命を落としました。","戦いのあと、城は取りこわされ、明治には鉄道の駅ができました。焼け野原からの立て直しの中で生まれたのが «米百俵» の話です。さらに昭和の戦争では、長岡は1945年8月の空襲で大きな被害を受けました。二度の焼け野原から立ち上がった町の中心に、静かに本丸跡の碑が立っています。"],"tl":[["1618年","牧野忠成が長岡に入る"],["1868年5月2日","小千谷談判が決裂"],["1868年5月19日","新政府軍の攻撃で長岡城が落城"],["1868年7月24〜25日","八丁沖を渡る奇襲で城を奪回"],["1868年7月29日","ふたたび落城"],["1868年8月16日","河井継之助が只見で死去"],["1870年","小林虎三郎が見舞いの米百俵を学校の資金に"],["1898年","長岡駅が開業（城跡の上に）"]],"who":[["河井継之助","長岡藩家老。武装中立をめざし、北越戦争を指揮した"],["牧野忠恭・忠訓","幕末の長岡藩主"],["小林虎三郎","戦後、米百俵を学校建設にあてた"],["山県有朋","新政府軍の参謀として北越の戦いを指揮した一人"]],"deep":["河井継之助はガトリング砲（連発銃）を2門買ったとされ、日本にあった数少ない例の一つでした。","城は «苧引形兜城（おびきがたかぶとじょう）» という別名があったといわれます。天守はなく、三階櫓が天守の役割を果たしていました。","駅の大手口の広場には «長岡城本丸跡» の碑、市内には «八丁沖古戦場» の碑が残ります。","戦いの評価は今も分かれます。«藩を守ろうとした英雄» という見方と、«町を戦火に巻きこんだ» という見方の両方が長岡に残っています。","河井継之助記念館（長町）、長岡戦争資料もある «長岡市郷土史料館»（悠久山）などで、北越戦争をくわしく学べます。"],"look":["JR長岡駅大手口の «長岡城本丸跡» 碑","アオーレ長岡周辺（二の丸あたり）","河井継之助記念館","八丁沖古戦場パーク","悠久山公園の郷土史料館（模擬天守）"],"q":["長岡藩の藩風を表す四文字は？","«常在戦場»。いつも戦場にいる気持ちで心を引きしめよ、という教えです。"],"koji":[{"w":"米百俵","m":"目先の食べ物より、未来のために教育にお金を使うこと。戦後の長岡の小林虎三郎の話から"}],"myth":"«苧引形兜城» の別名、ガトリング砲の数は伝承・諸説あり。","img":["河井継之助","北越戦争","米百俵","長岡駅"],"wp":"長岡城","rel":{"ev":[],"grave":[]},"ph":[["c:1/1e/Nagaoka_Zyo_Honmaru_Ato_Sekihi.jpg",2448,3264,"長岡城"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040,"北越戦争"],["c:e/ec/%E9%95%B7%E5%B2%A1%E9%A7%85_-_panoramio_%281%29.jpg",5472,3648,"長岡駅"]]},{"id":"15_shibata_jo","n":"新発田城（三階櫓と表門）","yomi":"しばたじょう","cat":"城","rank":"S","y":1654,"era":["edo"],"sh":"国の重要文化財（表門・旧二の丸隅櫓）","ad":"新発田市大手町","st":"JR新発田駅から歩いて約20分","la":37.9536,"lo":139.3275,"hook":"屋根の上にシャチホコが3匹! 全国でもめずらしい «T字の屋根» の三階櫓が、雪国の空ににらみをきかせる。","lead":"新発田城は、江戸時代に溝口家が約270年おさめた新発田藩の城です。江戸時代から残る表門と旧二の丸隅櫓は国の重要文化財。天守の代わりだった三階櫓は、2004年に木造で復元されました。城の多くは今も陸上自衛隊の駐屯地の中にあります。","story":["1598年、豊臣秀吉の命令で、加賀の大聖寺から溝口秀勝が新発田にやってきました。あたりは川と沼が多い低い土地。«こんなところに城がきずけるのか?» 溝口家は水をおさめ、田んぼを広げながら、何代もかけて城と町をつくっていきました。城が完成したのは、17世紀の半ばごろといわれます。","新発田城の一番の見どころは三階櫓です。ふつうの天守は屋根の棟が一本ですが、この櫓は上から見ると屋根が «T» の字になっていて、棟の先の3か所にシャチホコがのっています。«なぜ3匹?» はっきりした理由は分かっていませんが、ほかの城にはない、新発田だけの姿です。","城の石垣は «切込はぎ» というきれいに加工した石を、なまこ壁と組み合わせています。雪の多い土地なので、白い壁に黒い瓦を張った «なまこ壁» は、壁を雨や雪から守る工夫でもありました。","新発田藩からは、忠臣蔵で有名な赤穂浪士の一人、堀部安兵衛が出ています。安兵衛は新発田藩士の家に生まれ、江戸に出て «高田馬場の決闘» で名を上げたと伝わります。城のそばの公園には、安兵衛の像が立っています。","明治になると、城のほとんどの建物は取りこわされ、陸軍の兵営になりました。それでも表門と隅櫓は残り、戦後には自衛隊がその場所を受けつぎます。2004年、古い写真や図面をもとに三階櫓と辰巳櫓が木で建て直され、3匹のシャチホコがふたたび空に上がりました。"],"tl":[["1598年","溝口秀勝が新発田に入る"],["17世紀半ば","城がほぼ完成したといわれる"],["1668年","大火で城の建物の多くが焼け、その後再建"],["1872年ごろ","明治政府の方針で多くの建物が取りこわされ、陸軍の兵営に"],["1957年","表門と旧二の丸隅櫓が国の重要文化財に"],["2004年","三階櫓・辰巳櫓が木造で復元"]],"who":[["溝口秀勝","新発田藩の初代藩主。城と町づくりを始めた"],["溝口家の歴代藩主","明治まで約270年、新発田をおさめた"],["堀部安兵衛","新発田出身の赤穂浪士の一人"]],"deep":["三階櫓は、上から見てT字型に棟が組まれ、3匹のシャチホコがのる珍しい形。明治の古写真や絵図などを手がかりに復元されました。","三階櫓は自衛隊の駐屯地の中にあるため、ふだんは外から眺めるだけです（公開日がもうけられることもあります）。","表門は江戸時代中期の再建とされ、二階建ての櫓門。鉄板を張った扉など、実戦を意識した造りが見られます。","旧二の丸隅櫓は、もとは別の場所にあったものを、昭和の修理のときに本丸の今の位置へ移したものです。","日本100名城の一つ。石垣の切込はぎと、海鼠壁（なまこ壁）の組み合わせが雪国の城らしさをよく表しています。","城下の «清水園» は藩主の下屋敷の庭園、«足軽長屋» は江戸時代の足軽の住まいが残る貴重な建物です。"],"look":["三階櫓（3匹のシャチホコ・外から見学）","表門（重要文化財・中に入れる）","旧二の丸隅櫓（重要文化財）","本丸の切込はぎの石垣と水堀","城前の堀部安兵衛像","清水園と足軽長屋"],"q":["新発田城の三階櫓の屋根には、シャチホコが何匹のっている？","3匹。屋根の棟がT字型になっているためです。"],"koji":[],"myth":"堀部安兵衛の «高田馬場の決闘» の細部は講談などで脚色されている。","img":["溝口秀勝","新発田藩","堀部武庸","清水園"],"wp":"新発田城","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Shibata_Castle_001_May2020.jpg",2364,1773,"新発田城"],["c:1/14/Hidekatsu_Mizoguchi.png",120,116,"溝口秀勝"],["c:1/10/Utagawa_Kunisada-c1850-Horibe_Yahei-Horibe_Yasubei.jpg",880,1254,"堀部武庸"],["c:6/60/160716_Shimizuen_Shibata_Niigata_pref_Japan29s3.jpg",6000,4000,"清水園"]]},{"id":"15_konponji","n":"根本寺（日蓮配流・塚原三昧堂）","yomi":"こんぽんじ","cat":"寺社","rank":"S","y":1271,"era":["kamakura"],"sh":"","ad":"佐渡市新穂大野","st":"両津港から車で約20分（バスは本数が少ない）","la":38.027,"lo":138.417,"hook":"雪がふきこむ荒れたお堂で、流された日蓮は筆をとった。«ここで死ぬかもしれない» 冬に書かれた言葉が、今も読みつがれている。","lead":"根本寺は、鎌倉時代に佐渡へ流された日蓮が、最初の冬をすごした «塚原三昧堂» の跡と伝わる日蓮宗のお寺です。日蓮はここで «開目抄» という大切な書物を書きました。境内には、そのころの三昧堂を思わせるお堂や、流罪をしのぶ碑が並びます。","story":["1271年、鎌倉幕府は一人の僧を佐渡へ流しました。日蓮です。«法華経を信じなければ国がほろびる» と強くとなえ、ほかの宗派や幕府をきびしく批判したためでした。その年の秋、処刑されそうになる事件（龍ノ口法難）をへて、日蓮は冬の日本海をわたります。","佐渡で日蓮が入れられたのは、塚原という場所の «三昧堂»。死んだ人をほうむる墓地の小さなお堂で、屋根も壁も荒れはてていたといいます。日蓮はのちの手紙で、雪がふりつもり、風がふきこむ中で、毛皮を着て夜をすごしたと書いています。«なぜそんな場所に?» 島の人にとって、流人は «近づいてはいけない人» だったからです。","そんな中でも、日蓮は書くことをやめませんでした。1272年の2月ごろ、塚原で書き上げたのが «開目抄»。«われ日本の柱とならん、われ日本の眼目とならん、われ日本の大船とならん» という誓いの言葉が出てきます。死と隣りあわせの冬に、日蓮は自分の役目を確かめたのです。","1272年の初め、島の念仏僧たちが集まり、日蓮と教えを議論したと伝わります（塚原問答）。やがて日蓮を支える島の人も現れました。阿仏房とその妻・千日尼は、夜にこっそり食べ物を運んだといわれます。日蓮はその後、一谷という場所に移り、1274年に許されて鎌倉へ帰りました。","根本寺は、この塚原の地に、のちに建てられたと伝わるお寺です。境内には、茅ぶきのお堂や大きな杉の木があり、今も日蓮宗の人びとがお参りにおとずれます。雪の日にここに立つと、たった一人で冬をこえた僧の心細さと強さが、少しだけ想像できます。"],"tl":[["1271年9月","龍ノ口法難。日蓮が処刑されかける"],["1271年10月","日蓮が佐渡に着き、塚原三昧堂に入る"],["1272年1月","塚原問答（島の僧たちとの議論）と伝わる"],["1272年2月","«開目抄» を書き上げる"],["1272年夏ごろ","一谷へ移される"],["1274年3月","許されて佐渡を離れる"]],"who":[["日蓮","日蓮宗を開いた僧。佐渡に約2年半流された"],["阿仏房","佐渡の武士（元は念仏者）。日蓮を支えたと伝わる"],["千日尼","阿仏房の妻。夫とともに日蓮を助けた"],["北条時宗","当時の執権。日蓮の流罪は幕府の判断だった"]],"deep":["塚原三昧堂が正確にどこにあったかは諸説があり、根本寺のほかにも «ここが塚原» とする説があります。","«開目抄» は «観心本尊抄»（一谷で書かれたとされる）とならび、日蓮の教えの中心となる書物とされています。","日蓮の佐渡での暮らしは、日蓮自身が弟子や信者に書いた手紙（遺文）から具体的に分かります。雪や寒さの描写は、その手紙によるものです。","佐渡にはこのほか、妙宣寺（阿仏房ゆかり）、妙照寺（一谷の地）、実相寺など、日蓮ゆかりの寺が島の中央部に集まっています。","日蓮が流されたのは «佐渡国» の国府の近く。当時、佐渡は都や鎌倉から遠い、流刑の島とされていました。順徳天皇、のちには世阿弥も流されています。"],"look":["山門から本堂へつづく杉並木","三昧堂を思わせる茅ぶきのお堂","日蓮像や配流をしのぶ碑","境内の大杉と静かな雰囲気"],"q":["日蓮が塚原で書いた書物の名前は？","«開目抄»。«われ日本の柱とならん» という言葉で知られます。"],"koji":[{"w":"われ日本の柱とならん","m":"開目抄の一節。自分が日本を支える柱になるという日蓮の誓い"}],"myth":"塚原三昧堂の場所は諸説あり。阿仏房夫妻の話は伝承をふくむ。","img":["日蓮","開目抄","龍ノ口法難","佐渡国"],"wp":"根本寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"],["c:4/4c/Ryukoji-goreikutsu.jpg",3072,1728,"龍ノ口法難"]]},{"id":"15_minamata","n":"新潟水俣病と阿賀野川","yomi":"にいがたみなまたびょう","cat":"昭和","rank":"S","y":1965,"era":["showa","heisei"],"sh":"","ad":"新潟市北区前新田（新潟県立環境と人間のふれあい館）","st":"JR豊栄駅から車で約10分","la":37.916,"lo":139.247,"hook":"川の魚を食べていただけなのに。阿賀野川で起きた公害は、«二度と起こさない» ための大切な教訓を今も語りかけている。","lead":"新潟水俣病は、阿賀野川の上流にあった化学工場が流したメチル水銀が川の魚にたまり、その魚を食べた人びとが手足のしびれなどの重い症状に苦しんだ公害です。1965年に明らかになり、日本の «四大公害病» の一つとされています。新潟市北区の «ふれあい館» で、その歴史を学ぶことができます。","story":["阿賀野川は、福島県から新潟平野を流れ、日本海にそそぐ大きな川です。川ぞいの村の人びとにとって、ウグイやニゴイなどの魚は毎日のごはんのおかずでした。«川がくれるものは、ありがたくいただく»——それが当たり前の暮らしだったのです。","ところが1960年代のはじめ、下流の村で、手足がしびれる、言葉がうまく話せない、目が見えにくい、といった症状の人が出てきました。1965年、新潟大学の椿忠雄教授らが、熊本県の水俣病と同じ病気だと発表します。«なぜ、遠い新潟で?» ——原因は上流の鹿瀬にあった昭和電工の工場でした。","工場では、化学製品をつくる途中でメチル水銀ができ、それが排水といっしょに川へ流されていました。水銀は魚の体にたまり、その魚をたくさん食べた人の体にも、少しずつたまっていったのです。熊本の水俣病の原因がすでに問われていたのに、同じことがくり返されてしまいました。","1967年、患者と家族は会社を相手に裁判を起こしました。«四大公害訴訟» の中で一番早く始まった裁判です。偏見やいやがらせに苦しみながらも、人びとは声を上げつづけ、1971年に勝訴します。しかし、病気と認められない人も多く、救済をめぐる問題はその後も長く続きました。","今、ふれあい館では、患者さんの語りや写真、資料を通して、何が起きたのかを伝えています。ここは «だれかが悪い» と責めるためだけの場所ではありません。命と暮らしをどう守るか、私たちが考えるための場所です。亡くなった方、今も苦しむ方への思いをもって訪れたい場所です。"],"tl":[["1936年","昭和電工鹿瀬工場でアセトアルデヒドの製造が始まる"],["1965年","新潟大学が «第二の水俣病» の発生を発表"],["1965年","工場でのアセトアルデヒド製造が終わる（発表の年のはじめ）"],["1967年","第一次訴訟が起こされる"],["1968年","国が公害病と正式に認める"],["1971年","新潟地裁で原告勝訴の判決"],["2001年","新潟県立環境と人間のふれあい館が開館"],["2009年","水俣病被害者救済特別措置法ができる"]],"who":[["椿忠雄","新潟大学の医師。病気を見つけ、原因をつきとめる調査を進めた"],["患者と家族","病気に苦しみ、裁判で責任を問うた人びと"],["昭和電工","原因となった工場を経営していた会社"]],"deep":["新潟水俣病は «第二水俣病» ともよばれます。熊本の水俣病（1956年に公式確認）と同じメチル水銀中毒です。","四大公害病は、熊本水俣病・新潟水俣病・イタイイタイ病・四日市ぜんそく。新潟の裁判は、この中で最初に起こされました。","会社側は当初、新潟地震（1964年）で倉庫から流れた農薬が原因だと主張しましたが、裁判では認められませんでした。","メチル水銀は、胎盤を通じておなかの赤ちゃんにも影響しました（胎児性水俣病）。そのため当時、妊娠をひかえるよう指導されたこともありました。","患者として認められるかどうか（認定）の基準をめぐって長く争いが続き、今も裁判が行われています。","ふれあい館は福島潟の近くにあり、患者さんが自分の体験を話す «語り部» の活動も行われてきました。"],"look":["ふれあい館の展示（被害の実態、裁判の歴史）","患者さんの語りの映像","阿賀野川の流れ（川の恵みと被害の両方を思う）","福島潟の自然"],"q":["新潟水俣病の原因となった物質は？","メチル水銀。工場の排水にふくまれ、魚を通じて人の体に入りました。"],"koji":[],"myth":"","img":["阿賀野川","水俣病","四大公害病","昭和電工"],"wp":"新潟水俣病","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/Kanose_Denko_Kanose_plant_1976.jpg",1204,902,"新潟水俣病"],["c:7/75/Agano_River_and_Uetsu_Main_Line_bridge.jpg",4000,3000,"阿賀野川"],["c:d/db/%E6%B0%B4%E4%BF%A3%E7%97%85-%E4%BD%8D%E7%BD%AE-%E5%9C%B0%E5%9B%B3.jpg",1130,1490,"水俣病"],["c:4/4f/Conrad_Tokyo_2014_%E2%85%B1.JPG",2150,3247,"昭和電工"]]},{"id":"15_sasayama","n":"笹山遺跡（国宝・火焔型土器）","yomi":"ささやまいせき","cat":"遺跡","rank":"S","y":-3000,"era":["jomon"],"sh":"国宝（出土した土器・石器など）","ad":"十日町市中条","st":"JR飯山線 魚沼中条駅から歩いて約20分（出土品は十日町市博物館）","la":37.15,"lo":138.777,"hook":"燃えあがる炎か、はげしい水しぶきか。5000年前の縄文人がつくった土器は、新潟県で初めての国宝になった。","lead":"笹山遺跡は、今から約5000年前の縄文時代中ごろのムラの跡です。ここから見つかった «火焔型土器» をふくむ土器や石器など928点が、1999年に国宝に指定されました。新潟県で初めての国宝です。実物は近くの十日町市博物館で見ることができます。","story":["信濃川がつくった段丘の上、雪深い十日町に、縄文時代の人びとのムラがありました。1980年から発掘がはじまると、地面の下から住まいの跡や、たくさんの土器のかけらが出てきました。","その中に、ひときわ目をひく土器がありました。口のまわりに、ぐにゃりと大きくうねる飾りが4つ。のこぎりの歯のようなギザギザ、渦をまく線。«まるで炎が燃えあがっているみたいだ» ——このタイプの土器は «火焔型土器» とよばれています。","«なぜこんな形に?» 答えはだれにもわかりません。火の形、水の流れ、あるいは神さまへの祈り。ただ、中にこげあとがある土器もあり、実際に煮炊きに使われたこともわかっています。飾りのための道具ではなく、くらしの中で使われた土器だったのです。","火焔型土器は、信濃川の流域、とくに今の新潟県の中越地方に集中して見つかります。つまり «この地域の縄文人の流行デザイン»。十日町や長岡のムラの人びとは、同じような形の土器を作り、使い、おそらく交流していたのでしょう。","1999年、笹山遺跡の出土品は国宝に選ばれました。その中の一つ、«No.1» とよばれる火焔型土器は、とくに形が整い、火焔型土器の代表とされています。遺跡の場所は公園になり、ムラの一部が復元されています。雪国の森の中で、縄文の人びとが土をこね、火で焼いたすがたを思いうかべてみてください。"],"tl":[["約5000年前","縄文時代中期、笹山にムラが営まれる"],["1980年","発掘調査が始まる（〜1985年ごろ）"],["1999年","出土品928点が国宝に指定される（新潟県初）"],["2020年","十日町市博物館が新しい建物に移り、国宝を展示"]],"who":[["笹山の縄文人","ムラをつくり、火焔型土器を作った人びと"],["近藤篤三郎","長岡の馬高遺跡で最初の «火焔土器» を見つけた人（名前の由来）"],["岡本太郎","縄文土器の美しさを世に広めた芸術家"]],"deep":["国宝の内訳は、火焔型土器・王冠型土器をふくむ深鉢形土器などの土器類と、石器・装身具など。数は928点とされます。","«火焔土器» は長岡市の馬高遺跡で見つかった特定の一点の愛称で、似た形のものをまとめて «火焔型土器» とよびます。","火焔型土器の多くは、口の部分に «鶏頭冠» とよばれる大きな突起が4つつきます。これとは別に、ギザギザの王冠のような飾りの «王冠型土器» もあります。","火焔型土器が作られたのは縄文時代中期の数百年間とされ、その後は姿を消します。","火焔型土器は、2020年の東京オリンピック・パラリンピックの聖火台のデザイン案として地元が提案したことでも話題になりました。","十日町市博物館では、雪国のくらしを伝える民俗資料も展示されています。"],"look":["十日町市博物館の国宝展示室（火焔型土器 No.1）","笹山縄文の里（遺跡公園と復元住居）","段丘の上から信濃川の流れを見る","王冠型土器とのちがいを見くらべる"],"q":["笹山遺跡の出土品は、新潟県で何番目の国宝？","1番目。1999年に新潟県で初めての国宝になりました。"],"koji":[],"myth":"火焔型土器の飾りが何を表すかは分かっていない（炎・水・祈りなどは推測）。","img":["火焔型土器","縄文土器","十日町市博物館","馬高遺跡"],"wp":"笹山遺跡","rel":{"ev":[],"grave":[]},"ph":[["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"笹山遺跡"],["j:f/f6/%E4%BC%9D%E6%96%B0%E6%BD%9F%E7%9C%8C%E9%95%B7%E5%B2%A1%E5%B8%82%E9%A6%AC%E9%AB%98%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28J-39036%29-1.JPG",3378,3104,"火焔型土器"],["c:8/88/%E5%8D%81%E6%97%A5%E7%94%BA%E5%B8%82%E5%8D%9A%E7%89%A9%E9%A4%A8%E5%A4%96%E8%A6%B3.jpg",1534,1219,"十日町市博物館"],["c:8/85/Umataka_Site%2C_gaikan.jpg",5514,3630,"馬高遺跡"]]},{"id":"15_zeikan","n":"旧新潟税関庁舎（開港五港）","yomi":"きゅうにいがたぜいかんちょうしゃ","cat":"幕末","rank":"S","y":1869,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"新潟市中央区緑町（みなとぴあ）","st":"JR新潟駅からバスで約15分、「みなとぴあ」付近で下車","la":37.927,"lo":139.054,"hook":"開国のとき日本に5つできた «開港場»。その税関の建物がそのまま残るのは、ここ新潟だけ。","lead":"旧新潟税関庁舎は、1869年、新潟港が外国に開かれたときに建てられた «運上所»（のちの税関）の建物です。和風の瓦屋根に西洋風のアーチや塔をのせた、ふしぎで楽しい形をしています。開港五港の税関として当時の建物が残る唯一の例で、国の重要文化財です。","story":["1858年、江戸幕府はアメリカなどと «修好通商条約» を結び、箱館・神奈川（横浜）・長崎・新潟・兵庫（神戸）の5つの港を外国に開くことを約束しました。«開港五港» です。日本海側で選ばれたのは新潟だけでした。","ところが新潟の開港はなかなか進みません。信濃川の河口にある港は、砂がたまって浅く、大きな船が入りにくかったのです。«本当にここで大丈夫?» 外国側も心配しました。結局、新潟が開港したのは明治元年の終わり、西暦では1869年1月1日のことでした。","開港にあわせて建てられたのが運上所です。外国船の荷物を調べ、税をとる役所でした。建てたのは日本の大工たち。西洋の建物を見よう見まねで取り入れ、なまこ壁の和風の壁に、アーチの窓、屋根の上には小さな塔をのせました。«和洋折衷» ——日本が西洋と出会ったとまどいとワクワクが、そのまま形になっています。","実際には、港が浅いこともあって、新潟に来る外国船はあまり多くありませんでした。それでも運上所は税関として使われ、明治から昭和のはじめまで港の仕事を見守りました。そのあとも建物は大事に残され、1969年に国の重要文化財になります。","今、建物は «新潟市歴史博物館（みなとぴあ）» の敷地にあり、中を見学できます。すぐそばには、同じころに建てられた石造りの倉庫 «石庫» もあります。信濃川の河口に立つと、帆船がゆれる明治の港の音が聞こえてくるようです。"],"tl":[["1858年","日米修好通商条約。新潟が開港場の一つに"],["1868年","明治維新"],["1869年1月1日","新潟港が開港（旧暦明治元年11月19日）。運上所が建つ"],["明治のはじめ","運上所が «税関» と改められる"],["昭和","税関が新しい庁舎に移り、建物は保存される"],["1969年","国の重要文化財に指定"],["2004年","新潟市歴史博物館（みなとぴあ）が開館"]],"who":[["タウンゼント・ハリス","アメリカ総領事。修好通商条約を結んだ"],["新潟の大工たち","西洋建築をまねて和洋折衷の建物をつくった"],["新潟の港の人びと","北前船の時代から港をささえた商人や船乗り"]],"deep":["屋根の上の塔屋、正面のアーチの車寄せ、なまこ壁の組み合わせは «擬洋風建築» とよばれ、明治初期の日本各地に見られます。","開港五港のうち、横浜・神戸・長崎・函館の最初の運上所の建物はいずれも残っておらず、新潟のものは貴重です。","新潟が開港場に選ばれた理由には、日本海側の大きな港で、北前船の寄港地としてにぎわっていたことが挙げられます。","開港の時期は、条約では1860年の予定でしたが、港の問題や国内の混乱などで大きく遅れました。","同じ敷地の «石庫» は、輸出入の品物をおさめた石造りの倉庫で、庁舎とともに文化財として大切に残されています。"],"look":["和洋折衷の外観（塔屋・アーチ・なまこ壁）","税関の仕事を伝える内部の展示","となりの石庫","みなとぴあ本館の新潟の歴史展示","信濃川河口の風景"],"q":["開港五港の中で、日本海側にある港は？","新潟。ほかの4つは箱館・神奈川（横浜）・長崎・兵庫（神戸）です。"],"koji":[],"myth":"","img":["開港五港","擬洋風建築","日米修好通商条約"],"wp":"新潟港","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/Niigata_West_Port_2019.jpg",4320,2883,"新潟港"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"],["c:e/e5/Treaty_of_Amity_and_Commerce_between_Japan_and_the_United_States_29_July_1858.jpg",2445,2174,"日米修好通商条約"]]},{"id":"15_jigenji","n":"慈眼寺（小千谷談判の場）","yomi":"じげんじ","cat":"幕末","rank":"S","y":1868,"era":["edo","meiji"],"sh":"","ad":"小千谷市平成2丁目","st":"JR上越線 小千谷駅から歩いて約25分","la":37.3143,"lo":138.7946,"hook":"話し合いはわずか30分。この寺の一室で交渉が決裂したことが、長岡を戦火へと向かわせた。","lead":"慈眼寺は、1868年5月2日、長岡藩家老・河井継之助と新政府軍の軍監・岩村精一郎が話し合いをした «小千谷談判» の舞台です。戦いを避けたい河井の願いは受け入れられず、会談は短い時間で終わりました。会談をした部屋 «会見の間» が今も残っています。","story":["1868年春、新政府軍は北陸道を北へ進み、越後に入ってきました。長岡藩の家老・河井継之助の考えは «長岡は新政府にも旧幕府側にもつかない»。武器をそろえた上で中立を守り、戦争を越後に持ちこませない、というものでした。","5月2日、河井は信濃川の上流、小千谷に陣をおいた新政府軍のもとへ向かいます。会談の場所に選ばれたのが慈眼寺でした。相手は土佐藩出身の軍監・岩村精一郎。まだ20代前半の若い指揮官でした。","河井は、新政府にあてた嘆願書をさし出し、«これを総督にとりついでほしい、時間をもらえれば会津や米沢を説いて戦いをやめさせる» とうったえたと伝わります。しかし岩村は «時間かせぎだ» と取り合いませんでした。«出兵か、恭順か、答えよ»。話し合いは30分ほどで終わったといわれます。","«なぜ決裂したのか?» 河井の中立案は、新政府側から見れば «ぐずぐずしている» と映りました。一方で、もし岩村がもう少し話を聞いていたら、という «もしも» は今も語られます。後年、岩村自身も自分の若さを悔いるような言葉を残したと伝わります。","談判が決裂して、長岡藩は奥羽越列藩同盟に加わり、北越戦争が始まりました。多くの命がうしなわれた戦いの入り口に、この静かな寺の一室がありました。«会見の間» には、当時をしのぶ資料が置かれ、訪れる人は畳の上で、それぞれの «もしも» を考えます。"],"tl":[["1868年1月","戊辰戦争が始まる"],["1868年4月","新政府軍が越後に入る"],["1868年5月2日","慈眼寺で小千谷談判。決裂"],["1868年5月","長岡藩が奥羽越列藩同盟に加わる"],["1868年5月19日","長岡城落城"],["1868年8月16日","河井継之助が只見で死去"]],"who":[["河井継之助","長岡藩家老。武装中立を訴えたが受け入れられなかった"],["岩村精一郎（高俊）","新政府軍の軍監。談判の相手。のちに県知事などをつとめた"],["山県有朋","新政府軍の参謀。北越の戦いを指揮した一人"]],"deep":["«小千谷談判» の中身は、双方の回想などをもとに伝わっており、細かいやりとりには諸説があります。","岩村精一郎（のちの高俊）は土佐藩出身。明治には佐賀県令などをつとめ、のちに男爵となりました。","会見の間には、河井と岩村の座った位置を示すものや、関係資料が展示されています（見学は事前に確認を）。","慈眼寺は真言宗の寺。小千谷の町の東、信濃川の段丘の上にあります。","小千谷には、北越戦争で亡くなった人をまつる碑や、会津藩士の墓なども残り、戦いの広がりを感じさせます。","北越戦争は長岡だけでなく、小千谷・片貝・見附・新潟など越後の広い範囲に及び、農民や町人も物資運びなどで戦いに巻きこまれました。談判の決裂は、そうした広い地域の運命も左右したのです。"],"look":["本堂と «会見の間»","河井継之助と岩村精一郎の談判を伝える展示","境内の記念碑","近くの船岡公園（戦死者の墓碑・信濃川の眺め）"],"q":["小千谷談判の話し合いはどのくらいで終わったと伝わる？","約30分。河井の嘆願は受け入れられず、北越戦争が始まりました。"],"koji":[],"myth":"談判の細かいやりとり、時間、岩村の後悔の言葉は回想による伝承。","img":["河井継之助","岩村高俊","北越戦争","小千谷市"],"wp":"慈眼寺 (小千谷市)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/Ojiya_city_Jigenji_ac_%282%29.jpg",6016,4000,"慈眼寺 (小千谷市)"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:7/7e/Takatoshi_Iwamura.jpg",321,436,"岩村高俊"],["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040,"北越戦争"],["c:1/10/Ojiya_Nishikigoi_no_Sato_ac_%283%29.jpg",6016,4000,"小千谷市"]]},{"id":"15_okozu","n":"大河津分水（可動堰と旧洗堰）","yomi":"おおこうづぶんすい","cat":"近代","rank":"S","y":1922,"era":["meiji","taisho","showa"],"sh":"","ad":"燕市大川津・長岡市寺泊","st":"JR越後線 分水駅から車で約10分（信濃川大河津資料館）","la":37.669,"lo":138.857,"hook":"暴れ川・信濃川の水を、山をけずって日本海へ逃がす。越後平野を水害から救った «人の手でつくった川»。","lead":"大河津分水は、信濃川の水を途中から日本海へ流すために掘られた、長さ約10kmの人工の川です。明治の終わりに工事が始まり、1922年に水が流れました。これで越後平野は大洪水から守られ、日本一の米どころになりました。","story":["信濃川は日本で一番長い川です。その下流の越後平野は低い土地が多く、昔から大雨のたびに堤防が切れ、村も田んぼも水につかりました。1896年の «横田切れ» では、堤防がくずれて平野の広い範囲が水びたしになったといわれます。","«川の水を途中で海へ流せばいい»。じつは江戸時代から、寺泊の方へ分水路を掘ってほしいという願いが出されていました。しかし、あいだには山があり、工事はとても大がかり。何度も願いが出されては、見送られてきたのです。","1909年、ついに国の事業として工事が始まりました。山をけずる工事には、たくさんの人とトロッコ、それに外国から来た大型の掘削機も使われました。1922年、ついに信濃川の水が分水路を通って日本海へ流れました。越後平野の人びとの長い願いがかなった瞬間でした。","ところが1927年、分水路の入口にあった «自在堰» が川底のえぐれで壊れ、水を調節できなくなってしまいます。«このままでは、また平野が水びたしになる»。内務省の青山士が責任者となり、宮本武之輔らが現場で工事を進めて、1931年に新しい «可動堰» を完成させました。","完成の記念碑には «万象ニ天意ヲ覚ル者ハ幸ナリ» «人類ノ為メ国ノ為メ» という言葉が日本語とエスペラント語で刻まれています。工事にかかわった青山士の思いといわれます。今は新しい可動堰にかわっていますが、資料館では、自然とたたかい、自然に学んだ人びとの歴史を知ることができます。"],"tl":[["江戸時代中ごろ","分水路の開削を求める請願が始まったと伝わる"],["1896年","«横田切れ»。越後平野が大洪水に"],["1909年","分水路の工事が始まる"],["1922年","通水（水が分水路に流れる）"],["1927年","自在堰が陥没する"],["1931年","可動堰が完成（補修工事）"],["2010年代","新しい可動堰に切り替わる"]],"who":[["青山士","パナマ運河の工事に加わった唯一の日本人技師。補修工事を指揮した"],["宮本武之輔","内務省の技師。可動堰の補修工事の現場を担った"],["越後平野の人びと","洪水に苦しみ、分水の実現を願いつづけた"]],"deep":["分水路は河口に近づくほど幅がせまくなっています。«ふつうは逆なのに、なぜ?» 山を切り開く工事の都合で、海側の区間の幅を広くできなかったためといわれます。","«洗堰» は信濃川本流の側にあり、平野へ流す水の量を調節します。«可動堰» は分水路の側にあり、洪水のときに開けて水を海へ逃がします。二つの堰が組になって働きます。","工事で掘った土の量は約2,880万立方メートルともいわれ、明治・大正の土木工事としては最大級でした。","記念碑の言葉は、日本語とエスペラント語の両方で書かれています。青山士が国際語のエスペラントに共感していたためとされます。","大河津分水ができたことで、越後平野の田んぼは水はけがよくなり、湿田から乾田への改良が進み、米どころへとつながりました。","大河津分水の完成後、河口の寺泊の海岸では砂が増え、海岸線が変わったことも知られています。"],"look":["信濃川大河津資料館（展望室から分水と堰を一望）","可動堰（新旧の堰の位置関係）","旧洗堰・新洗堰","補修工事の記念碑（日本語とエスペラント語）","堤防の桜並木（春）"],"q":["大河津分水の記念碑には、日本語ともう一つ何語で言葉が刻まれている？","エスペラント語。国際語で «人類のため» の思いを残しました。"],"koji":[],"myth":"江戸時代の請願の始まりの時期、掘削土量の数字は資料によって差がある。","img":["信濃川","青山士","宮本武之輔","越後平野"],"wp":"大河津分水","rel":{"ev":[],"grave":[]},"ph":[["c:0/03/Nagaoka_from_the_sky.jpg",4000,3000,"大河津分水"],["c:7/7a/Find47_Niigata-River_%28Shinano_River%2C_Ojiya_City%29-m.jpg",1920,1280,"信濃川"],["c:e/e2/Akira_Aoyama_cropped_4_Akira_Aoyama_193405.jpg",241,308,"青山士"],["c:c/c6/Echigo-plain.jpg",2848,1868,"越後平野"]]},{"id":"15_mano_goryo","n":"真野御陵（順徳天皇火葬塚）","yomi":"まのごりょう","cat":"墓所","rank":"S","y":1242,"era":["kamakura"],"sh":"宮内庁管理（順徳天皇火葬塚）","ad":"佐渡市真野","st":"両津港から車で約30分、佐渡交通バス「真野新町」から歩いて約20分","la":38.0,"lo":138.369,"hook":"«ももしきや 古き軒端の…» 百人一首の最後の歌の作者は、この島で21年をすごし、都へ帰ることなく亡くなった。","lead":"真野御陵は、承久の乱のあと佐渡へ流された順徳天皇（順徳上皇）が亡くなったあと、火葬された場所とされるところです。宮内庁が管理していて、杉木立の奥に静かな参道がつづきます。となりには天皇をまつる真野宮があります。","story":["順徳天皇は、後鳥羽上皇の子として生まれ、14歳で天皇になりました。和歌や学問を好み、宮中の決まりごとを書いた書物も残した、才能ゆたかな天皇でした。","1221年、後鳥羽上皇は鎌倉幕府をたおそうと兵をあげます。«承久の乱» です。順徳天皇はその直前に位をゆずり、上皇として父を助けました。しかし幕府軍は強く、戦いはわずか一か月ほどで朝廷側の負けに終わりました。","幕府は3人の上皇を遠い島や国へ流しました。後鳥羽上皇は隠岐へ、土御門上皇は土佐へ、そして順徳上皇は佐渡へ。«いつか都へ帰れる日が来る» ——そう信じて、順徳上皇は真野のあたりで暮らしたと伝わります。","けれども、その日は来ませんでした。1242年、順徳上皇は佐渡で亡くなります。46歳。都へ帰る望みを失って、自ら命を終えたともいわれます。なきがらはこの地で火葬され、遺骨は都へ運ばれて京都の大原に葬られました。火葬した場所が、今の真野御陵です。","都にいたころに詠んだ歌 «ももしきや 古き軒端の しのぶにも なほあまりある 昔なりけり» は、百人一首の100番目、最後の歌です。宮中の古い軒に生えるしのぶ草を見て、栄えた昔をなつかしむ——。島で過ごした長い年月を思うと、いっそう胸にしみる歌です。"],"tl":[["1197年","順徳天皇が生まれる"],["1210年","天皇に即位"],["1221年","承久の乱。位をゆずり上皇に。敗れて佐渡へ流される"],["1242年","佐渡で死去。真野で火葬される"],["明治時代","真野宮が整えられ、上皇をまつる"]],"who":[["順徳天皇（上皇）","佐渡に流され、この地で亡くなった"],["後鳥羽上皇","順徳天皇の父。承久の乱を起こし、隠岐へ流された"],["北条義時","鎌倉幕府の執権。承久の乱で朝廷軍を破った"],["世阿弥","室町時代に佐渡へ流された能の大成者。順徳上皇の旧跡を訪ねたと伝わる"]],"deep":["«御陵» とよばれていますが、宮内庁の正式な扱いは «火葬塚»。遺骨がおさめられた陵は京都の大原陵です。","順徳天皇は歌学書 «八雲御抄» や、宮中のしきたりを記した «禁秘抄» の作者として知られます。","佐渡での住まいは «黒木御所» とよばれ、真野の近くの泉に跡とされる場所があります。","亡くなり方について、食を断った、焼いた石で体を傷めた、などの伝承がありますが、確かではありません。","世阿弥は1434年に佐渡へ流され、そのときの記録 «金島書» に順徳院ゆかりの地のことを書いたとされます。","承久の乱で流された3人の上皇のうち、土御門上皇は自ら望んで都を離れたとされ、乱に深くかかわった後鳥羽・順徳の両上皇とは立場が少しちがいました。","真野宮は、もとは真輪寺というお寺の中にあった御堂が、明治の神仏分離で神社として整えられたものと伝わります。天神（菅原道真）もあわせてまつられています。"],"look":["杉木立の参道と御陵（柵の外から拝む）","となりの真野宮","近くの黒木御所跡","真野湾の風景"],"q":["百人一首の100番目の歌の作者はだれ？","順徳院（順徳天皇）。«ももしきや…» の歌です。"],"koji":[],"myth":"亡くなり方（自ら食を断った等）や島での暮らしの細部は伝承。","img":["承久の乱","真野宮","後鳥羽天皇"],"wp":"順徳天皇","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Emperor_Juntoku_large.jpg",2208,2680,"順徳天皇"],["c:5/5c/Setagawa%EF%BC%88Yodogawa%EF%BC%89_Karahashi.jpg",800,600,"承久の乱"],["c:c/cd/Emperor_Go-Toba.jpg",2268,2301,"後鳥羽天皇"]]},{"id":"15_kotaki_hisui","n":"小滝川ヒスイ峡（日本の翡翠の源）","yomi":"こたきがわひすいきょう","cat":"遺跡","rank":"S","y":-3000,"era":["jomon","kofun","showa"],"sh":"国指定天然記念物（小滝川硬玉産地）","ad":"糸魚川市小滝","st":"JR糸魚川駅から車で約40分（公共交通では行きにくい。冬は道が閉鎖）","la":36.908,"lo":137.83,"hook":"縄文人が愛し、1000年以上わすれられ、昭和になってふたたび見つかった «緑の宝石» のふるさと。","lead":"小滝川ヒスイ峡は、日本でヒスイ（硬玉）がとれる代表的な場所です。縄文時代から古墳時代まで、ここのヒスイは玉や勾玉に加工され、日本各地へ運ばれました。ところがその後、国内にヒスイがあることは忘れられ、1938年に再発見されました。国の天然記念物で、石を持ち帰ることは禁止されています。","story":["切り立った明星山の岩壁の下、小滝川の河原に、白や緑の大きな岩がごろごろ転がっています。これがヒスイの原石です。ヒスイはとても硬く、ねばり強い石。磨くと深い緑にかがやきます。","縄文の人びとは、この石を見のがしませんでした。今から5000年ほど前、糸魚川のムラでは、ヒスイに穴をあけ、みがいて大珠（たいしゅ）という飾りを作っていました。できたヒスイは、青森の三内丸山遺跡など遠い土地からも見つかっています。«どうやってそんな遠くまで?» 人から人へ、ムラからムラへ、手渡しでつながっていったと考えられています。","古墳時代にはヒスイの勾玉が大切にされ、王や豪族の墓にもおさめられました。ところが奈良時代のころから、ヒスイはぱったり使われなくなります。やがて «日本にヒスイがとれる» ことさえ忘れられ、古墳から出るヒスイは «中国や朝鮮から来たもの» と考えられるようになりました。","昭和のはじめ、糸魚川出身の文学者・相馬御風は、古事記に出てくる «奴奈川姫» が玉をもっていたという話から、«このあたりにヒスイがあるのでは» と考えたといわれます。その話を聞いた伊藤栄蔵が、1938年、小滝川で緑の石を見つけました。翌年、東北帝国大学の河野義礼が調べ、ヒスイだと確かめられたのです。","1000年以上の眠りから覚めたヒスイ。2016年には、日本鉱物科学会によって «国石» にも選ばれました。今、ヒスイ峡は大切に守られていて、石をとることはできません。河原を見下ろしながら、縄文の人が初めてこの緑を見つけた日のことを思いうかべてみましょう。"],"tl":[["約5000年前","縄文時代中期、糸魚川でヒスイの玉づくりがさかんに"],["古墳時代","ヒスイの勾玉が各地の豪族に大切にされる"],["奈良時代ごろ","ヒスイの利用がとだえ、やがて忘れられる"],["1938年","伊藤栄蔵が小滝川でヒスイを発見"],["1939年","河野義礼が調査し、ヒスイと確認"],["1956年","«小滝川硬玉産地» として国の天然記念物に"],["2016年","日本鉱物科学会がヒスイを «国石» に選ぶ"]],"who":[["奴奈川姫","古事記に登場する越の国の姫。ヒスイの女神ともいわれる"],["相馬御風","糸魚川出身の文学者。ヒスイがあるのではと考えた"],["伊藤栄蔵","1938年に小滝川でヒスイを見つけた"],["河野義礼","東北帝国大学の研究者。ヒスイであることを確かめた"]],"deep":["ヒスイには «硬玉（ヒスイ輝石）» と «軟玉» があり、日本で古代に使われたのは硬玉。小滝川は硬玉の産地として指定されています。","糸魚川のヒスイは、プレートの沈みこみ帯で、高い圧力のもとで生まれたと考えられています。フォッサマグナの西の縁の地質と深くかかわります。","«奴奈川姫とヒスイ» の結びつきは、古事記の記述と近代の解釈を合わせたもので、古事記に «ヒスイ» と書いてあるわけではありません。","ヒスイ峡の近くの青海川にも国の天然記念物 «青海川の硬玉産地» があります。","ヒスイの岩壁の上にそびえる明星山の石灰岩の大岩壁は、ロッククライミングの名所としても知られます。"],"look":["展望台から見る河原のヒスイの巨岩","明星山の大岩壁","ヒスイ峡の案内板（見分け方の解説）","糸魚川市のフォッサマグナミュージアムの大ヒスイ"],"q":["ヒスイが «日本の国石» に選ばれたのは何年？","2016年。日本鉱物科学会が選びました。"],"koji":[],"myth":"奴奈川姫とヒスイを結びつける話は近代の解釈をふくむ伝承。","img":["翡翠","奴奈川姫","相馬御風","フォッサマグナミュージアム"],"wp":"小滝川硬玉産地","rel":{"ev":[],"grave":[]},"ph":[["c:0/0c/%E3%83%92%E3%82%B9%E3%82%A4%E5%B3%A120180915.JPG",1372,772,"小滝川硬玉産地"],["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"翡翠"],["c:3/35/Suwa_taisha_Shimosha_Harumiya_%2C_%E8%AB%8F%E8%A8%AA%E5%A4%A7%E7%A4%BE_%E4%B8%8B%E7%A4%BE_%E6%98%A5%E5%AE%AE_%E5%AD%90%E5%AE%89%E7%A4%BE_-_panoramio.jpg",2400,1600,"奴奈川姫"],["c:d/d5/Soma_Gyofu.JPG",449,596,"相馬御風"],["c:c/c0/Fossa_Magna_Museum.JPG",5184,3456,"フォッサマグナミュージアム"]]},{"id":"15_isoroku","n":"山本五十六記念館と生家跡","yomi":"やまもといそろくきねんかん","cat":"昭和","rank":"S","y":1943,"era":["meiji","showa"],"sh":"","ad":"長岡市呉服町1丁目（記念館）","st":"JR長岡駅から歩いて約10分","la":37.4455,"lo":138.8475,"hook":"«アメリカと戦ってはいけない» と考えながら、真珠湾攻撃を指揮することになった提督。そのふるさとが長岡にある。","lead":"山本五十六は長岡で生まれ、太平洋戦争のはじめに連合艦隊司令長官として真珠湾攻撃を指揮した海軍の軍人です。1943年、南太平洋で乗っていた飛行機がうち落とされ、亡くなりました。記念館では遺品を展示し、近くの山本記念公園には生家が復元されています。","story":["1884年、長岡藩士の家に生まれた男の子は、父の高野貞吉が56歳のときの子だったので «五十六» と名づけられました。長岡は、北越戦争で焼け野原になった町。«負けた藩の子» として、五十六は懸命に勉強し、海軍兵学校へ進みました。","1905年、日露戦争の日本海海戦に若い士官として加わり、大けがをして左手の指を2本うしないました。その後、山本家を継いで «山本五十六» となります。アメリカに留学・駐在し、ハーバード大学で学び、アメリカの工業の大きさを自分の目で見ました。","«アメリカと戦えば、日本は勝てない»。山本はそう考え、ドイツ・イタリアとの同盟にも反対したといわれます。しかし1939年に連合艦隊司令長官になると、戦争を止めることはできず、1941年12月、ハワイの真珠湾への攻撃を指揮する立場になりました。«なぜ反対していた人が?» ——その矛盾は、今も多くの人に考えさせる問いです。","戦争はそのあと、日本にとって苦しいものになっていきます。1943年4月18日、前線の見まわりに向かう途中、山本の乗った飛行機はアメリカ軍の戦闘機に待ちぶせされ、ブーゲンビル島の上空でうち落とされました。暗号が読まれていたのです。","記念館には、山本の書や手紙、そして墜落した飛行機（一式陸上攻撃機）の翼の一部が展示されています。戦争で亡くなった人は、日本にもアメリカにも数えきれないほどいます。この場所は、一人の軍人をほめたたえる所ではなく、戦争とは何かを静かに考える場所として訪ねたいところです。"],"tl":[["1884年","長岡で高野家の六男として生まれる"],["1904年","海軍兵学校を卒業"],["1905年","日本海海戦で負傷し、左手の指2本を失う"],["1916年","山本家を継ぎ «山本五十六» に"],["1939年","連合艦隊司令長官になる"],["1941年12月","真珠湾攻撃"],["1943年4月18日","ブーゲンビル島上空で戦死"],["1999年","山本五十六記念館が開館"]],"who":[["山本五十六","長岡出身の海軍軍人。連合艦隊司令長官"],["高野貞吉","五十六の父。長岡藩士"],["河井継之助","同じ長岡の先人。北越戦争を指揮した"]],"deep":["«やってみせ、言って聞かせて、させてみせ、ほめてやらねば、人は動かじ» という言葉が山本のものとして有名ですが、出典ははっきりしていません。","山本家は、北越戦争で戦い処刑された長岡藩家老・山本帯刀の家。いったん絶えた家を、五十六が継いで再興しました。","山本の搭乗機がうち落とされた作戦を、アメリカでは «ヴェンジェンス作戦» とよびます。暗号を解読して移動の予定を知っていました。","山本の死後、日本では国葬が行われました。遺骨の一部は長岡の長興寺の墓におさめられています。","生家跡の山本記念公園には、生家が復元されています。記念館の展示の中心は、ブーゲンビル島から運ばれた一式陸攻の左翼の一部です。"],"look":["記念館の一式陸攻の翼の展示","遺墨や書簡","山本記念公園の復元生家と胸像","長興寺の墓所"],"q":["«五十六» という名前の由来は？","生まれたとき、父親が56歳だったから。"],"koji":[{"w":"やってみせ、言って聞かせて、させてみせ、ほめてやらねば、人は動かじ","m":"人を育てるには、自ら手本を示し、説明し、やらせ、ほめることが大切。山本の言葉として伝わるが出典は不明"}],"myth":"名言の出典は不明。三国同盟への反対の度合いには諸説。","img":["真珠湾攻撃","連合艦隊","海軍甲事件","山本帯刀"],"wp":"山本五十六","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Portrait_of_Yamamoto_Isoroku.jpg",915,1297,"山本五十六"],["c:c/c4/Pearl_Harbor-_Nakajima_B5N2_over_Hickam-_80G178985.jpg",707,506,"真珠湾攻撃"],["c:6/66/Yamamoto%27s_airplane_crash.jpg",1114,746,"海軍甲事件"],["c:7/79/Yamamoto_Tatewaki_-_Teisei_Boshin_Hokuetsu_Senso_ki.jpg",542,814,"山本帯刀"]]},{"id":"15_takada_jo","n":"高田城（松平忠輝の城）","yomi":"たかだじょう","cat":"城","rank":"A","y":1614,"era":["edo","meiji"],"sh":"県指定史跡","ad":"上越市本城町（高田公園）","st":"えちごトキめき鉄道 高田駅から歩いて約20分","la":37.1033,"lo":138.2545,"hook":"石垣を一つも積まずに、わずか4か月で完成。徳川家康が息子のために、全国の大名を動員して造らせた «土の巨城»。","lead":"高田城は、1614年に徳川家康の六男・松平忠輝の城として造られました。家康は13の大名に工事を命じ、伊達政宗がその指揮をとりました。石垣を使わず、土を盛った土塁と広い堀で守る城です。今は高田公園となり、復元された三重櫓と、日本有数の夜桜で知られます。","story":["1614年、徳川家康は越後の新しい城づくりを命じました。城主は六男の松平忠輝。その妻は伊達政宗の娘・五郎八姫でした。家康は忠輝の義父である政宗を工事の総責任者にし、前田家や上杉家など13の大名に手伝わせました。大名の力で城をつくる、いわゆる «天下普請» です。","«なぜそんなに急いだのか?» ちょうど大坂の豊臣家との対立が深まっていた時期でした。北陸と関東、東北をつなぐ越後に、徳川の強い拠点をおく必要があったのです。工事はわずか4か月ほどで終わったといわれます。","急ぎの工事だったため、高田城には石垣がありません。そのかわり、高い土塁と幅の広い堀で城をかこみました。天守もなく、本丸の三重櫓が城のシンボルでした。まわりの川や沼も守りに使っています。","ところが、城主の忠輝は長くここにいられませんでした。大坂の陣での行動などが父・家康や兄の将軍・秀忠の怒りを買い、1616年に領地を取り上げられて流されてしまいます。その後、高田城には松平家、稲葉家、戸田家などが次々と入り、江戸時代の後半からは榊原家が明治まで治めました。","明治の終わりには陸軍の第13師団がおかれ、1911年、師団をたずねたオーストリアのレルヒ少佐が、日本で初めて本格的なスキーの指導をしました。今の高田公園では、1993年に三重櫓が復元され、春には外堀のまわりの約4000本の桜が夜空をいろどります。"],"tl":[["1614年","天下普請で高田城がきずかれる。城主は松平忠輝"],["1616年","松平忠輝が改易される"],["1741年","榊原家が入り、明治まで治める"],["1908年","陸軍第13師団がおかれる"],["1911年","レルヒ少佐が日本初の本格的なスキー指導"],["1993年","三重櫓が復元される"]],"who":[["松平忠輝","徳川家康の六男。高田城の最初の城主"],["伊達政宗","忠輝の義父。築城工事の総指揮をとった"],["徳川家康","城づくりを命じた"],["テオドール・フォン・レルヒ","陸軍第13師団でスキーを伝えたオーストリアの軍人"]],"deep":["天下普請に加わったのは、前田利常・上杉景勝・真田信之など13の大名といわれます（顔ぶれは史料により多少ちがいます）。","三重櫓は、昭和の前に取りこわされていたものを、古い図面などをもとに1993年に復元したもの。内部は資料館になっています。","石垣がない理由は «工事を急いだから» とされることが多いですが、近くに良い石が少なかったからという見方もあります。","高田公園の外堀は夏にハスが一面に咲くことで知られ、«東洋一» とよばれたこともあります。","城跡の一部は、今も学校などに使われています。本丸の土塁は、雪国の土の城の姿をよく残しています。"],"look":["復元された三重櫓（内部は展示）","本丸をかこむ土塁と堀","外堀の桜（春の夜桜）とハス（夏）","上越市立歴史博物館","金谷山のレルヒ像"],"q":["高田城の工事の総指揮をとった東北の大名は？","伊達政宗。城主・松平忠輝の義父でした。"],"koji":[],"myth":"工事期間約4か月、大名の数は史料による差がある。","img":["松平忠輝","伊達政宗","テオドール・フォン・レルヒ","高田公園"],"wp":"高田城","rel":{"ev":[],"grave":[]},"ph":[["c:6/69/Takada_Castle_yagura.JPG",3763,2504,"高田城"],["c:8/8f/Matsudaira_Tadateru.jpg",299,368,"松平忠輝"],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:9/97/Theodor_Edler_von_Lerch.jpg",300,438,"テオドール・フォン・レルヒ"]]},{"id":"15_murakami_jo","n":"村上城（臥牛山の石垣）","yomi":"むらかみじょう","cat":"城","rank":"A","y":1618,"era":["muromachi","edo"],"sh":"国指定史跡","ad":"村上市二之町（臥牛山）","st":"JR羽越本線 村上駅から歩いて約20分で登山口、そこから約20分登る","la":38.223,"lo":139.486,"hook":"牛が寝そべったような山のてっぺんに、江戸時代の立派な石垣がずらり。越後の北のはしを守った城。","lead":"村上城は、標高約135mの臥牛山にある山城です。戦国時代には本庄氏が本拠とし、江戸時代のはじめに堀氏が石垣を積んで近世の城に造りかえました。天守は落雷で焼け、建物は残っていませんが、山の上には高い石垣がよく残り、国の史跡になっています。","story":["村上の町の東にこんもりとした山があります。形が、牛が寝そべっているように見えることから «臥牛山» とよばれます。戦国時代、この山には本庄氏の城がありました。越後北部の武士たちのなかでも、本庄氏は強い力をもっていました。","1568年、城主の本庄繁長は、主君の上杉謙信にそむいて兵をあげます。«なぜ謙信に?» 武田信玄にさそわれたといわれます。謙信は自ら大軍をひきいて村上城を囲みました。しかし城は落ちず、翌年に和解。繁長はふたたび上杉家の家臣となり、のちに景勝のもとで活躍しました。","江戸時代になると、村上には新しい大名が入ります。1618年に入った堀直竒（なおより）は、城の大改修を行い、山の上に高い石垣を積みあげました。今見られる石垣の多くは、このころからあとのものです。やがて天守も建てられました。","ところが1667年、天守は雷に打たれて焼けてしまいます。その後、天守は建て直されませんでした。18世紀からは内藤家が村上藩をおさめ、明治をむかえます。戊辰戦争では、城は藩士たちの手で焼かれたと伝わります。","今、臥牛山に登ると、木々の間から見上げるような石垣があらわれます。本丸からは、村上の町並み、日本海、そして晴れた日には遠くの山々まで見わたせます。戦国の土の城と江戸の石の城が一つの山に重なっているのが、村上城のおもしろさです。"],"tl":[["16世紀","本庄氏が臥牛山に城をかまえる"],["1568年","本庄繁長が謙信にそむき、城が囲まれる"],["1598年","上杉家が会津へ移り、村上頼勝が入る"],["1618年","堀直竒が入り、石垣の城に改修"],["1667年","天守が落雷で焼失"],["1720年","内藤家が入り、明治まで治める"],["1993年","国の史跡に指定"]],"who":[["本庄繁長","戦国時代の城主。謙信にそむいたが、のちに許された"],["上杉謙信","本庄繁長の反乱をしずめた"],["堀直竒","江戸時代初期に石垣の城に造りかえた大名"],["内藤家","江戸時代後半から明治まで村上藩をおさめた"]],"deep":["臥牛山には、戦国期の曲輪や堀切と、江戸期の石垣が混在しています。山の中腹から上を石垣で固め、麓に藩主の居館をおく構えでした。","堀直竒は、長岡城をきずいた大名としても知られます（長岡から村上へ移りました）。","村上城は続日本100名城に選ばれています。","本丸・二の丸・三の丸などの石垣は、時代ごとに積み方がちがい、野面積みや打込はぎなどを見くらべることができます。","村上の町は城下町の町割りをよく残し、武家屋敷や町屋、«黒塀» の通りなど、城とあわせて歩くと楽しい町です。","本庄繁長の反乱のとき、謙信は城を力攻めにせず、長く囲んで降伏を待ちました。繁長はそのあと上杉家で重く用いられ、景勝の代には出羽の庄内などで活躍しています。«そむいた家臣をもう一度使う» 謙信の判断も、この城の物語の一部です。"],"look":["本丸の石垣と天守台","出櫓台・四ツ門跡などの石垣","本丸からの日本海と村上市街の眺め","麓の城下町（武家屋敷・町屋）"],"q":["村上城の山 «臥牛山» の名前の由来は？","山の形が、牛が寝そべっている姿に見えることから。"],"koji":[],"myth":"本庄繁長が武田信玄にさそわれた話は諸説。戊辰戦争での自焼は伝承。","img":["本庄繁長","堀直寄","村上藩","村上市"],"wp":"村上城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Murakami_Castle.JPG",3648,2736,"村上城"],["c:e/e1/Honjo_Shigenaga_parriying_an_exploding_shell.jpg",1400,2028,"本庄繁長"],["c:d/d0/Murakami_Montage.jpg",1024,1258,"村上市"]]},{"id":"15_rinsenji","n":"林泉寺（上杉謙信の墓・春日山）","yomi":"りんせんじ","cat":"墓所","rank":"A","y":1497,"era":["muromachi"],"sh":"","ad":"上越市中門前1丁目","st":"えちごトキめき鉄道 春日山駅から歩いて約20分","la":37.149,"lo":138.224,"hook":"7歳の虎千代が学び、やがて «第一義» の文字を書くまでに育った寺。謙信の心のふるさと。","lead":"林泉寺は、春日山城のふもとにある曹洞宗のお寺です。戦国時代、長尾家（のちの上杉家）の菩提寺として建てられました。上杉謙信は子どものころここで学び、境内には謙信の墓があります。山門には謙信が書いた «第一義» の額がかかります（現物は宝物館）。","story":["1497年、越後の守護代・長尾能景は、父の供養のためにこの寺を建てました。春日山城のすぐ下、城を守るようにして建てられた、長尾家の大切なお寺でした。","それから30年あまりのち、7歳の男の子がこの寺にあずけられます。長尾為景の末っ子、虎千代。のちの上杉謙信です。«なぜ寺に?» 当時、家をつがない武家の子どもが寺に入るのはよくあることでした。虎千代は住職の天室光育から、読み書きや仏の教え、そして武士としての心がまえを学んだと伝わります。","やがて虎千代は武将となり、越後の主となります。けれども謙信は、一生仏教を深く信じ、ときに出家して寺に入ろうとさえしました。謙信が書いたとされる «第一義» の文字は、«もっとも大切な真理» という意味の禅のことばです。力強い筆のあとに、林泉寺で学んだ少年の日の心が見えるようです。","1578年、謙信は亡くなりました。その後、上杉家は会津、さらに米沢へと移り、謙信のなきがらも上杉家とともに米沢へうつされました。林泉寺にある謙信の墓は、ふるさと越後で謙信をしのぶためのものです。","境内には、川中島の戦いで亡くなった人びとの供養塔もあり、敵味方をこえて弔う心を伝えています。宝物館には謙信ゆかりの品が並びます。春日山城に登る前か後に、この寺で静かに手を合わせると、戦国の武将の別の顔にふれられます。"],"tl":[["1497年","長尾能景が林泉寺を建てる"],["1536年ごろ","虎千代（謙信）が寺にあずけられる"],["1548年","景虎（謙信）が長尾家をつぐ"],["1578年","謙信死去"],["1598年","上杉家が会津へ移る"],["江戸時代","寺は高田藩のもとで続き、謙信の墓が守られる"]],"who":[["上杉謙信","少年時代にこの寺で学んだ。墓がある"],["長尾能景","謙信の祖父。寺を建てた"],["天室光育","林泉寺の住職。謙信の師"],["上杉景勝","謙信の養子。上杉家とともに米沢へ移った"]],"deep":["謙信の遺骸は、上杉家の移封にともない米沢へ移され、今は米沢の上杉家廟所に眠っています。林泉寺の墓は «遺骸のない墓» と考えてよいでしょう。","米沢にも同じ名の «林泉寺» があります。上杉家が移るとき、ゆかりの寺も米沢へ移したためです。","山門の «第一義» の額は複製で、本物は宝物館に保管されています。","寺の惣門は、春日山城の門を移したものと伝えられますが、確かな証拠はありません。","境内には、謙信の家臣らの墓や、江戸時代の高田藩主ゆかりの墓もあります。","天室光育は曹洞宗の僧で、謙信は成長してからも禅の修行を大切にしました。のちに謙信が出家を宣言して高野山へ向かおうとした騒ぎ（1556年ごろ）も、少年時代の寺での日々と無関係ではないといわれます。","上杉家が米沢へ移ってからも、越後の人びとは謙信を «春日山の殿さま» として語りつぎ、林泉寺はその記憶をつなぐ場所になりました。今も謙信をしのんで多くの人がお参りに訪れます。"],"look":["山門と «第一義» の額","上杉謙信の墓","川中島戦死者供養塔","宝物館（謙信ゆかりの品）","惣門（春日山城の門を移したと伝わる）"],"q":["謙信の書いた «第一義» の意味は？","«もっとも大切な真理»。禅の言葉です。"],"koji":[{"w":"第一義","m":"いちばん根本的で大切な道理。謙信が書いた額で知られる"}],"myth":"虎千代の入寺年、惣門の春日山城移築は伝承。","img":["上杉謙信","春日山城","長尾為景","長尾能景"],"wp":"林泉寺 (上越市)","rel":{"ev":[],"grave":[]},"ph":[["c:8/8e/Linsenji_1.jpg",640,480,"林泉寺 (上越市)"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:e/ea/Kasaugayama_Castle.jpg",5248,3936,"春日山城"]]},{"id":"15_otate","n":"御館跡（御館の乱）","yomi":"おたてあと","cat":"古戦場","rank":"A","y":1578,"era":["azuchi"],"sh":"","ad":"上越市五智1丁目（御館公園）","st":"えちごトキめき鉄道 直江津駅から歩いて約20分","la":37.1615,"lo":138.243,"hook":"謙信が遺言を残さずに亡くなったとき、二人の養子が越後を二つに割った。その一方の本拠が、この小さな公園だった。","lead":"御館は、上杉謙信が関東管領・上杉憲政のために建てた館です。謙信の死後、養子の景勝と景虎があとつぎを争い、景虎はこの御館にこもりました。この争いを «御館の乱» といいます。今は «御館公園» になり、案内板と碑が当時を伝えています。","story":["1552年、北条氏に追われた関東管領・上杉憲政が、越後の長尾景虎（謙信）をたよって逃げてきました。謙信は憲政を大切にもてなし、春日山のふもと、直江津に近いこの場所に館を建てました。«御館» とよばれた、大きく立派な館だったといわれます。","1578年3月、謙信が急に亡くなります。養子は二人。一人は謙信の姉の子・景勝。もう一人は北条氏康の子で、人質として来て謙信に気に入られ、謙信の若いころの名 «景虎» をもらった上杉景虎。«どちらが跡つぎか» を謙信ははっきり決めていませんでした。","景勝はすばやく春日山城の本丸と金蔵をおさえました。景虎は城を出て、この御館に入ります。越後の武士たちは二つに分かれ、国中で戦いが起きました。景虎の後ろには実家の北条氏、そして北条と同盟を結ぶ武田勝頼がひかえていました。«景虎が有利»——多くの人がそう思ったことでしょう。","ところが景勝は、武田勝頼に黄金や領地をわたして味方につけ、勝頼の妹・菊姫をめとる約束をします。武田軍は兵を引き、北条の助けも雪にはばまれて届きません。1579年3月、御館は攻め落とされました。憲政は和平のために春日山へ向かう途中、景虎の幼い子とともに殺されたと伝わります。","景虎は実家の小田原へ逃れようとしましたが、途中の鮫ヶ尾城で味方にうらぎられ、自害しました。二人の養子のどちらを選ぶかで、越後の武士の運命が分かれた戦い。今は静かな公園ですが、ここで多くの人が命を落としたことを心にとめておきたい場所です。"],"tl":[["1552年","上杉憲政が越後へ逃れてくる"],["1561年","謙信が憲政から上杉の名と関東管領職をつぐ"],["1578年3月","謙信死去。景勝が春日山城の本丸をおさえ、景虎は御館へ"],["1578年","武田勝頼と景勝が和を結ぶ"],["1579年3月","御館が落城。上杉憲政が殺される"],["1579年3月","上杉景虎が鮫ヶ尾城で自害"]],"who":[["上杉景勝","謙信の甥で養子。乱に勝ち、上杉家をついだ"],["上杉景虎","北条氏康の子で謙信の養子。御館にこもり敗れた"],["上杉憲政","もと関東管領。御館の主。乱の中で殺された"],["武田勝頼","景勝と同盟し、乱の行方を大きく変えた"],["直江兼続","若き景勝の側近として支えた"]],"deep":["«謙信は景勝を跡つぎに決めていた» という上杉家側の記録もありますが、後から書かれたものとも考えられ、諸説があります。","景勝と武田勝頼の同盟は «甲越同盟» とよばれます。これで北条との «甲相同盟» がこわれ、のちの武田家滅亡の遠因ともいわれます。","乱の影響で上杉家の力は弱まり、そのすきに織田信長の勢力が越中から越後にせまってきました。","御館の跡は、発掘調査で堀や建物の跡が見つかり、館の規模が確かめられています。今の公園はその一部です。","景虎が自害した鮫ヶ尾城（妙高市）は国の史跡。発掘では、焼けた米などが見つかり、落城のようすを物語っています。"],"look":["御館公園の碑と案内板","公園の形に残る館の区画","近くの五智国分寺・居多神社（あわせて歩ける）","妙高市の鮫ヶ尾城跡（車で）"],"q":["御館の乱で、景勝が味方につけた甲斐の大名は？","武田勝頼。景勝は勝頼の妹・菊姫をめとりました。"],"koji":[],"myth":"謙信の跡つぎ指名の有無、憲政の最期の様子は諸説。","img":["上杉景虎","上杉憲政","鮫ヶ尾城","甲越同盟"],"wp":"御館の乱","rel":{"ev":[],"grave":[]},"ph":[["c:a/a1/%E4%B8%8A%E6%9D%89%E6%99%AF%E8%99%8E%EF%BC%88%E5%8C%97%E6%9D%A1%E4%B8%89%E9%83%8E%EF%BC%89%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1850,1536,"上杉景虎"],["c:d/db/%E4%B8%8A%E6%9D%89%E6%86%B2%E6%94%BF%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1125,883,"上杉憲政"],["c:0/0a/Samegao_Castle_ruins.jpg",5248,3936,"鮫ヶ尾城"]]},{"id":"15_tochio_jo","n":"栃尾城（謙信旗揚げの城）","yomi":"とちおじょう","cat":"城","rank":"A","y":1544,"era":["muromachi"],"sh":"","ad":"長岡市栃尾地域（秋葉公園の奥の鶴城山）","st":"JR長岡駅からバスで約40分「栃尾車庫」下車、登山口まで歩いて約15分","la":37.4735,"lo":138.995,"hook":"14歳の少年が、兄の代わりに城に入り、はじめての戦いに勝った。«越後の龍» が目をさました山。","lead":"栃尾城は、上杉謙信（長尾景虎）が14歳のときに入った城です。ここで反乱を起こした武士たちをしりぞけ、若き景虎の名は越後中に知られるようになりました。山の上には曲輪や堀切の跡が残り、ふもとの秋葉公園には謙信の像があります。","story":["1543年、長尾為景の子・景虎はまだ14歳でした。兄の晴景が越後の守護代でしたが、体が弱く、国の中では反乱があいついでいました。景虎は林泉寺での修行から呼びもどされ、越後の中央、栃尾城へ送られます。","«こんな少年に何ができる?» ——周りの豪族たちは景虎をあなどりました。翌年、反乱軍が栃尾城へ攻めよせます。しかし景虎は、城将の本庄実乃らとともに城を守り、たくみに兵を動かして反乱軍をやぶりました。これが景虎の初陣だったと伝わります。","栃尾での勝利をきっかけに、景虎のもとには武士たちが集まりはじめました。一方で、兄・晴景との関係は難しくなっていきます。«弟のほうが頼りになる»。家臣たちの声におされ、1548年、景虎は兄にかわって春日山城に入り、長尾家をつぎました。","栃尾城は、鶴城山とよばれる山の上にあります。本丸からは栃尾の盆地が見わたせ、まわりを山に囲まれた天然の要害であることがわかります。尾根には曲輪がいくつも連なり、尾根を切った堀切が敵の進入をふせいでいました。","ふもとの秋葉公園には、若き謙信の銅像が立っています。栃尾の町は、雪から歩行者を守る «雁木» や、大きな油揚げでも知られます。町を歩いてから城山に登ると、少年景虎が見た景色が、少しだけ近くに感じられるはずです。"],"tl":[["1543年","長尾景虎（謙信）が14歳で栃尾城に入る"],["1544年","反乱軍を栃尾城でしりぞける（初陣と伝わる）"],["1548年","景虎が春日山城に入り長尾家をつぐ"],["1578年","謙信死去。御館の乱では栃尾も戦いにまきこまれる"],["江戸時代初め","城が使われなくなる（廃城）"]],"who":[["上杉謙信（長尾景虎）","少年時代に城に入り、最初の勝利をあげた"],["本庄実乃","栃尾城の城将。若い景虎をささえた"],["長尾晴景","謙信の兄。景虎に家をゆずった"]],"deep":["景虎の栃尾入城は、兄・晴景の命令によるもので、中越の反乱勢をおさえるための配置でした。","«栃尾城の戦い» の年や規模は、後世の記録にたよる部分が多く、くわしいことには諸説があります。","城は山頂の本丸を中心に、尾根づたいに多くの曲輪が並ぶ連郭式の山城。石垣はほとんどなく、土の城の姿です。","栃尾には謙信が学んだと伝わる常安寺があり、謙信ゆかりの品が伝わります。","秋葉公園は、火伏せの神・秋葉三尺坊をまつる秋葉神社の境内。謙信の銅像はここに建てられています。","栃尾は越後の中央部、中越の山あいにあり、会津や魚沼へ通じる道をおさえる位置でした。若い景虎をここに置いたのは、反乱の多い中越ににらみをきかせるためだったと考えられます。","景虎の初陣の勝利は、のちの «戦上手の謙信» のイメージのはじまりとして語られます。戦国時代の軍記物には、少年景虎の采配をほめる話がいくつも出てきますが、後の時代の脚色もふくまれます。"],"look":["鶴城山の本丸跡と栃尾盆地の眺め","尾根の曲輪と堀切","秋葉公園の謙信像","栃尾の雁木通り","常安寺"],"q":["謙信（景虎）が栃尾城に入ったのは何歳のとき？","14歳。ここで最初の勝利をあげたと伝わります。"],"koji":[],"myth":"初陣の年・経過は後世の記録による。常安寺で学んだ話は伝承。","img":["上杉謙信","長尾晴景","本庄実乃","栃尾市"],"wp":"栃尾城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Tochio_Castle_Honmaru_ruins_from_Akiba_Park_20170504.jpg",5472,3648,"栃尾城"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:7/78/%E9%95%B7%E5%B0%BE%E6%99%B4%E6%99%AF%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1536,1959,"長尾晴景"],["c:c/c1/Tochio_city.PNG",405,326,"栃尾市"]]},{"id":"15_sakado_jo","n":"坂戸城（上田長尾氏・直江兼続ゆかり）","yomi":"さかどじょう","cat":"城","rank":"A","y":1556,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"南魚沼市坂戸（坂戸山）","st":"JR上越線 六日町駅から歩いて約20分で登山口。山頂まではさらに約1時間","la":37.055,"lo":138.89,"hook":"上杉景勝が生まれ、直江兼続が育った魚沼の山城。戦国の名コンビは、この山のふもとで出会った。","lead":"坂戸城は、魚沼地方をおさめた上田長尾氏の本拠地だった山城です。標高634mの坂戸山全体が城で、山頂には本丸、ふもとには城主の館がありました。上杉謙信の跡をついだ上杉景勝はここで生まれ、景勝をささえた直江兼続もこの地で少年時代をすごしたといわれます。国の史跡です。","story":["魚沼の平野の東に、ぐっと立ち上がる坂戸山。戦国時代、この山には上田長尾氏の城がありました。上田長尾氏は、春日山の長尾氏（謙信の家）と並ぶ力をもつ一族で、関東へ向かう三国街道をおさえる大事な位置にいました。","城主の長尾政景は、はじめ若い景虎（謙信）と対立しましたが、やがて和解し、謙信の姉を妻にむかえます。1556年、二人の間に生まれたのが卯松、のちの上杉景勝です。坂戸城のふもとの館で、景勝は少年時代をすごしました。","1564年、政景は近くの野尻池で舟遊びをしていたとき、池に落ちて亡くなりました。いっしょにいた宇佐美定満も死んでいます。«ただの事故だったのか?» ——謙信の命令による暗殺だという説、定満との争いだという説などがあり、今も謎のままです。父を失った景勝は謙信の養子となり、春日山へ移りました。","景勝にはいつも、一人の少年がつきしたがっていました。上田長尾家の家臣・樋口兼豊の子、与六。のちの直江兼続です。兼続は1560年、坂戸城下で生まれたと伝わります。二人は近くの雲洞庵で学んだともいわれ、景勝と兼続の主従の絆は、この魚沼の地で育まれました。","上杉家が会津へ移ったあと、坂戸城には堀氏の家臣が入りましたが、1610年ごろに城は使われなくなりました。ふもとには館跡の石垣がのこり、山頂の本丸からは魚沼の平野と越後三山が一望できます。二人の少年が見上げた山を、今は多くの登山者が歩いています。"],"tl":[["16世紀前半","上田長尾氏が坂戸城を本拠とする"],["1551年","長尾政景が景虎（謙信）と和解する"],["1556年","上杉景勝が生まれる"],["1560年","直江兼続（樋口与六）が生まれる（坂戸城下と伝わる）"],["1564年","長尾政景が野尻池で死去"],["1598年","上杉家が会津へ移り、堀氏の支配に"],["1610年ごろ","廃城となる"],["1979年","国の史跡に指定"]],"who":[["上杉景勝","この城で生まれ、のちに謙信の後継者となった"],["直江兼続","景勝の家臣。坂戸城下で生まれたと伝わる"],["長尾政景","上田長尾氏の当主。景勝の父"],["仙桃院","謙信の姉で景勝の母。兼続を景勝の近習に推したとも伝わる"],["宇佐美定満","政景とともに野尻池で亡くなった武将"]],"deep":["城は山頂の «実城»（本丸）を中心に、尾根にそって曲輪が連なり、ふもとに «城主館» と家臣の屋敷がある、戦国の典型的な山城です。","ふもとの館跡には石垣が残ります。これは江戸時代のはじめ、堀氏の時代に整えられたものと考えられています。","長尾政景の死については、後世の軍記物で «宇佐美定満が謙信の命で政景を道づれにした» という話が語られますが、確かな史料はありません。","直江兼続の生まれた場所には、坂戸城下のほか与板（長岡市）とする説もあります。","坂戸山は地元の人に親しまれる登山の山で、春にはカタクリの花が山をうめます。"],"look":["ふもとの城主館跡の石垣","山頂の実城（本丸）跡と魚沼平野の眺め","尾根の曲輪と堀切","直江兼続・景勝ゆかりの碑","春のカタクリの群生"],"q":["坂戸城で生まれた、上杉謙信の後継者はだれ？","上杉景勝。父は長尾政景、母は謙信の姉です。"],"koji":[],"myth":"政景の死因、兼続の生誕地、雲洞庵で学んだ話は諸説・伝承。","img":["上杉景勝","直江兼続","長尾政景","宇佐美定満"],"wp":"坂戸城","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:3/34/Naoe_Kanetsugu02.jpg",800,1159,"直江兼続"],["c:b/bd/Nagao_Masakage_and_His_wife.jpg",2553,1446,"長尾政景"],["c:1/16/Usami_Suruga_no_kami.jpg",800,1200,"宇佐美定満"]]},{"id":"15_tounan","n":"雲洞庵（兼続と景勝の学び舎）","yomi":"うんとうあん","cat":"寺社","rank":"A","y":1420,"era":["muromachi","azuchi"],"sh":"","ad":"南魚沼市雲洞","st":"JR上越線 塩沢駅または六日町駅から車で約10分","la":37.03,"lo":138.85,"hook":"«雲洞庵の土踏んだか»。一度はふみたいと言われた越後一の寺で、戦国の少年たちが学んだと伝わる。","lead":"雲洞庵は、南魚沼の山すそにある曹洞宗のお寺です。室町時代に関東管領の上杉氏によって再興され、«越後一の寺» とよばれるほど栄えました。上杉景勝と直江兼続が少年時代に学んだ寺と伝わり、赤門から本堂へ続く石畳の参道がとても美しいお寺です。","story":["雲洞庵のはじまりは古く、奈良時代に藤原氏の一族が建てた尼寺だったという言い伝えがあります。その後、室町時代の1420年ごろ、関東管領の上杉憲実が曹洞宗の寺として建て直したといわれます。上杉氏の保護を受けて、雲洞庵は越後でも指折りの大寺になりました。","«雲洞庵の土踏んだか»。越後ではこんな言葉があったといいます。«あの有名な寺にお参りしたか» という意味で、この寺の土をふむとご利益がある、とまで言われました。赤門から本堂までの石畳の下には、法華経の文字を一字ずつ書いた石が埋められていると伝わり、参道を歩くことそのものがお参りになる、というわけです。","戦国時代、この寺にやってきたのが、坂戸城主・長尾政景の子、喜平次（のちの上杉景勝）と、その家臣の子・与六（のちの直江兼続）でした。二人は住職のもとで学問や禅の修行にはげんだと伝わります。«なぜ寺で?» 当時、寺は学校でもありました。読み書き、漢籍、そして心をきたえる修行を、ここで身につけたのです。","のちに景勝は上杉家の当主となり、兼続はその片腕として、関ヶ原のころには徳川家康に «直江状» を送ったと伝わるほどの人物に成長します。二人の強い絆は、この静かな山寺での日々から育ったのかもしれません。","2009年の大河ドラマ «天地人» では、少年時代の兼続が雲洞庵で学ぶ場面が描かれ、多くの人がおとずれるようになりました（ドラマの場面には創作がふくまれます）。宝物殿には上杉家ゆかりの品々が伝わり、苔むした庭と石畳は、戦国の少年たちが歩いた日々を思わせます。"],"tl":[["奈良時代","藤原氏ゆかりの尼寺として始まったと伝わる"],["1420年ごろ","上杉憲実が曹洞宗の寺として再興したと伝わる"],["戦国時代","上杉景勝・直江兼続が学んだと伝わる"],["江戸時代","越後の曹洞宗の中心寺院の一つとして栄える"],["2009年","大河ドラマ «天地人» で注目される"]],"who":[["上杉景勝","少年時代にここで学んだと伝わる"],["直江兼続","景勝とともに学んだと伝わる"],["上杉憲実","関東管領。寺を再興したとされる"],["北高全祝","戦国時代の雲洞庵の住職の一人。上杉氏とかかわった禅僧"]],"deep":["«越後一の寺» という呼び名は、寺格の高さと、上杉氏の庇護の厚さを表すものとされます。","参道の石畳の下の法華経一字一石の話は寺の伝えです。一字一石経は、石一つに経文を一字ずつ書いて埋める供養のしかたで、各地に例があります。","景勝と兼続が学んだという話は、主に寺や地元の伝承によるもので、同時代の史料で確かめられるわけではありません。","寺には上杉家や直江兼続にかかわる文書や品が伝わり、宝物殿で見ることができます。","赤門の «赤» は、格式の高い寺に許されたものといわれます。"],"look":["赤門と石畳の参道","本堂と苔の庭","宝物殿（上杉家ゆかりの品）","景勝・兼続が学んだと伝わる場所の案内"],"q":["«雲洞庵の土踏んだか» とはどういう意味？","«雲洞庵にお参りしたか» ということ。土をふむだけでご利益があるといわれました。"],"koji":[{"w":"雲洞庵の土踏んだか","m":"越後一の寺・雲洞庵にお参りしたかと問う言葉。寺の格の高さを表す"}],"myth":"寺の起こり、景勝・兼続の修学、石畳の下の経石は伝承。ドラマ «天地人» の場面は創作をふくむ。","img":["上杉景勝","直江兼続","天地人 (NHK大河ドラマ)","上杉憲実"],"wp":"雲洞庵","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Untoan1.jpg",1000,750,"雲洞庵"],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:3/34/Naoe_Kanetsugu02.jpg",800,1159,"直江兼続"],["c:7/78/Uesugi_Norizane._1535_CE._Ashikaga_Gakko.jpg",815,768,"上杉憲実"]]},{"id":"15_kotaji","n":"居多神社（越後一宮・親鸞上陸の居多ヶ浜）","yomi":"こたじんじゃ","cat":"寺社","rank":"A","y":1207,"era":["heian","kamakura"],"sh":"","ad":"上越市五智6丁目","st":"えちごトキめき鉄道 直江津駅から歩いて約30分（バスもある）","la":37.169,"lo":138.231,"hook":"流罪の船が着いた浜で、若き親鸞は神社に手を合わせた。越後の国府のそばに立つ、古い一宮。","lead":"居多神社は、越後の国府があったといわれる直江津の近くにある、とても古い神社です。平安時代の «延喜式» にも名前がのり、«越後一宮» とされてきました。すぐ近くの居多ヶ浜は、鎌倉時代のはじめに流罪となった親鸞が上陸した場所と伝わります。","story":["日本海に面した直江津のあたりには、古代、越後の国の役所 «国府» がおかれていたと考えられています。居多神社は、その国府のそばにまつられた神社でした。国司が国の神々をお参りするとき、最初におとずれる神社——それが «一宮» です。","1207年、京都で念仏の教えを広めていた法然とその弟子たちが、朝廷から罰を受けました。«承元の法難» です。弟子の一人、35歳の親鸞は越後へ流されます。船で日本海をわたり、たどり着いたのが居多ヶ浜だったと伝わります。","浜に上がった親鸞は、まず居多神社にお参りし、«すえ遠く 法を守らせ 居多の神 弥陀と衆生の あらん限りは» と歌を詠んだと伝えられます。«なぜ念仏の僧が神社に?» 当時の人にとって、土地の神にあいさつするのは自然なことでした。","神社の境内には «片葉の葦» が生えています。親鸞が教えを説くと、池の葦がみな片側だけに葉をつけるようになった——という «越後七不思議» の一つの言い伝えです。越後で親鸞は、恵信尼と家庭をもち、農民たちとともに暮らしながら、念仏の教えを深めていきました。","1211年、親鸞は罪を許されますが、すぐには京へ帰らず、のちに関東へ向かいました。越後での約7年間は、«僧でも俗人でもない» という親鸞の生き方が形になった大切な時間だったといわれます。居多ヶ浜には親鸞上陸を記念するお堂が建ち、日本海の夕日が美しく見えます。"],"tl":[["927年","«延喜式» に居多神社の名がのる"],["平安〜鎌倉時代","越後国府のそばの一宮として信仰される"],["1207年","親鸞が流罪となり、居多ヶ浜に上陸したと伝わる"],["1211年","親鸞が赦免される"],["戦国時代","上杉氏の信仰を受けたと伝わる"]],"who":[["親鸞","浄土真宗の開祖。越後に流され、居多ヶ浜に上陸したと伝わる"],["恵信尼","親鸞の妻。越後で親鸞とともに暮らした"],["法然","親鸞の師。承元の法難で土佐（のち讃岐）に流された"],["上杉謙信","越後の支配者として神社を崇敬したといわれる"]],"deep":["«越後一宮» は、居多神社と彌彦神社の両方が名乗っています。国府に近い居多神社が一宮とされた時期があったと考えられています。","祭神は大国主命と、その妻とされる奴奈川姫命など。奴奈川姫は糸魚川のヒスイの伝説とも結びつく女神です。","越後国府の正確な位置は分かっておらず、今の直江津周辺（五智地区など）がその候補とされています。","«片葉の葦» は、実際には風の強い場所で葦の葉が片側に寄る現象とも説明されます。","近くの五智国分寺には、親鸞が住んだと伝わる «竹之内草庵» の跡もあります。","恵信尼が越後から娘の覚信尼に送った手紙（恵信尼消息）は、親鸞の生活を知る貴重な史料です。"],"look":["居多神社の社殿と片葉の葦","居多ヶ浜の親鸞聖人上陸の地記念堂","日本海に沈む夕日","近くの五智国分寺と竹之内草庵跡"],"q":["親鸞が越後に流された法難を何という？","«承元の法難»（1207年）。師の法然も流罪になりました。"],"koji":[],"myth":"親鸞の居多ヶ浜上陸、神社で詠んだ歌、片葉の葦は伝承。","img":["親鸞","恵信尼","承元の法難","越後国府"],"wp":"居多神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/Kota-jinja_%28Joetsu%29_shaden.JPG",5653,3746,"居多神社"],["c:a/ad/ShinranShonin.png",371,507,"親鸞"],["c:b/b6/Eshin-ni.jpg",3547,4692,"恵信尼"]]},{"id":"15_chojagahara","n":"長者ケ原遺跡（ヒスイ工房のムラ）","yomi":"ちょうじゃがはらいせき","cat":"遺跡","rank":"A","y":-3000,"era":["jomon"],"sh":"国指定史跡","ad":"糸魚川市一の宮","st":"JR糸魚川駅から車で約10分（フォッサマグナミュージアムのとなり）","la":37.025,"lo":137.861,"hook":"5000年前、ここは日本中にヒスイを送り出す «玉づくりの村» だった。","lead":"長者ケ原遺跡は、縄文時代中期（約5000〜4000年前）の大きなムラの跡です。ヒスイの大珠（たいしゅ）や、蛇紋岩の石斧をつくった工房のあとが見つかり、ここでつくられた品が日本各地へ運ばれたと考えられています。国の史跡で、遺跡公園と考古館があります。","story":["糸魚川の町を見下ろす丘の上に、縄文の人びとのムラがありました。姫川と海のめぐみ、山のめぐみ。そして、ほかの土地にはない特別な宝がありました。川原や海岸に流れつくヒスイと蛇紋岩です。","ヒスイはとても硬い石です。«そんな石にどうやって穴をあけたの?» 縄文の人びとは、竹や細い棒と砂と水を使い、長い時間をかけてこすって穴をあけたと考えられています。こうしてできた大きな玉 «大珠» は、首にかける特別な飾りでした。","蛇紋岩からは、木を切るための «磨製石斧» がたくさんつくられました。ムラの中からは、作りかけの石や、みがくための砥石、こわれた道具などがたくさん見つかり、ここが大きな «工場» だったことがわかります。","ここでつくられたヒスイの玉は、北は北海道、南は九州の近くまで、日本各地の遺跡から見つかっています。お金も車もない時代に、人から人へ手わたされ、遠くまで旅をしたのです。長者ケ原のヒスイは、縄文の人びとが広くつながっていた証拠です。","ところで «長者ケ原» という名前は、昔ここに大金持ちの長者が住んでいたという言い伝えからきています。地面からたくさんの宝のような石が出てきたことが、そんな話を生んだのかもしれません。今は遺跡公園に竪穴住居が復元され、となりの考古館で出土品を見ることができます。"],"tl":[["約5000年前","縄文時代中期、ムラが営まれ、ヒスイや石斧づくりがさかんに"],["約4000年前","縄文時代後期のはじめごろまでムラが続く"],["1954年","本格的な発掘調査が始まる"],["1971年","国の史跡に指定"],["1990年代","遺跡公園と長者ケ原考古館が整備される"]],"who":[["長者ケ原の縄文人","ヒスイの玉や石斧をつくり、各地へ送り出した人びと"],["奴奈川姫","ヒスイの女神と伝わる、越の国の姫"],["相馬御風","ヒスイ再発見のきっかけをつくった糸魚川の文学者"]],"deep":["長者ケ原で見つかった住居跡には、床に石を敷いた «敷石住居» もあります。","ヒスイの加工には、穴をあける «穿孔»、形をととのえる «研磨» などの工程があり、途中でこわれた未完成品から作業の順番がわかります。","三内丸山遺跡（青森）で見つかったヒスイも、分析から糸魚川産と考えられています。","蛇紋岩製の磨製石斧は、糸魚川周辺から北陸・中部・関東などへ広く運ばれたと考えられています。","すぐとなりのフォッサマグナミュージアムでは、ヒスイのでき方や糸魚川の地質（フォッサマグナ）について学べます。","ムラは丘の上の広場をかこむように住まいが並ぶ «環状集落» の形だったと考えられ、同じころの東日本の大きなムラと共通する特徴をもっています。ヒスイの工房は、ムラの暮らしの中にとけこんでいたのです。"],"look":["遺跡公園の復元竪穴住居","長者ケ原考古館のヒスイの大珠と石斧","作りかけのヒスイ（未完成品）","となりのフォッサマグナミュージアム"],"q":["縄文人がヒスイで作った大きな玉を何という？","«大珠（たいしゅ）»。穴をあけて首にかけた特別な飾りです。"],"koji":[],"myth":"長者伝説は言い伝え。ヒスイの穴のあけ方は実験などからの推定。","img":["翡翠","フォッサマグナミュージアム","縄文時代","糸魚川市"],"wp":"長者ヶ原遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"翡翠"],["c:c/c0/Fossa_Magna_Museum.JPG",5184,3456,"フォッサマグナミュージアム"],["c:1/16/Itoigawa_Montage.jpg",1024,1300,"糸魚川市"]]},{"id":"15_umataka","n":"馬高遺跡（火焔土器命名の地）","yomi":"うまたかいせき","cat":"遺跡","rank":"A","y":-3000,"era":["jomon","showa"],"sh":"国指定史跡（馬高・三十稲場遺跡）","ad":"長岡市関原町","st":"JR長岡駅からバスで約30分、新潟県立歴史博物館の近くで下車","la":37.462,"lo":138.77,"hook":"1936年の大みそか、畑から燃えるような土器があらわれた。«火焔土器» という名前が生まれた場所。","lead":"馬高遺跡は、縄文時代中期の大きなムラの跡です。1936年、ここで見つかった一つの土器が、その形から «火焔土器» と名づけられました。これが、今ではよく知られる «火焔型土器» のはじまりです。となりの三十稲場遺跡とあわせて国の史跡になっていて、近くの «馬高縄文館» で出土品を見ることができます。","story":["長岡の西、信濃川を見下ろす台地の上に、縄文時代の人びとのムラがありました。その場所 «馬高» では、昔から畑を耕すと土器のかけらが出てくることが知られていました。","1936年の大みそか、地元の考古学好きの近藤篤三郎が、ここで一つの土器を掘り出しました。口のまわりに大きな飾りが燃えあがるようにのびている土器。«まるで火焔のようだ»。この土器は «火焔土器» とよばれるようになりました。","じつは «火焔土器» というのは、この一点につけられた愛称です。のちに同じような形の土器が各地から見つかると、それらはまとめて «火焔型土器» とよばれるようになりました。つまり馬高は、全国の «火焔型» の名前の原点なのです。","«どうしてこんな飾りを?» 馬高の人びとが何を思ってこの形を作ったのかは分かっていません。けれども、同じ時期の信濃川ぞいのムラでは似た土器が作られていて、人びとが同じ «デザイン» を分かち合っていたことがうかがえます。","となりの三十稲場遺跡は、馬高より少しあとの縄文時代後期のムラで、フタのついた土器などが見つかっています。二つの遺跡を合わせると、縄文の人びとが同じ台地で長くくらしを続けたことがわかります。今は遺跡の広場を歩いたあと、馬高縄文館で本物の火焔土器（国の重要文化財）に会うことができます。"],"tl":[["約5000年前","縄文時代中期、馬高にムラが営まれる"],["約4000年前","縄文時代後期、となりの三十稲場にムラが営まれる"],["1936年","近藤篤三郎が «火焔土器» を発見"],["1979年","«馬高・三十稲場遺跡» として国の史跡に"],["1990年","馬高遺跡の出土品が国の重要文化財に"],["2009年","長岡市馬高縄文館が開館"]],"who":[["近藤篤三郎","火焔土器を発見した人"],["近藤勘治郎","篤三郎の父。地元で遺物を集め研究した"],["岡本太郎","縄文土器の造形のすばらしさを広く伝えた芸術家"]],"deep":["«火焔土器» の一点は、縄文時代中期の深鉢形土器。口の上に大きな «鶏頭冠» 突起が4つつき、全体に隆線の文様がめぐります。","近藤家は代々この土地の出身で、父の勘治郎の代から遺物の採集と記録を行っていました。","馬高遺跡の出土品は1990年に国の重要文化財に指定されています。笹山遺跡の国宝とあわせて見ると、火焔型土器の広がりがわかります。","三十稲場遺跡の土器は、口にフタを受ける部分がある «三十稲場式土器» として、縄文時代後期の土器の基準になっています。","遺跡の近くには新潟県立歴史博物館があり、縄文のムラの実物大の再現展示など、縄文文化を幅広く学べます。"],"look":["馬高縄文館の火焔土器（重要文化財）","遺跡の広場と台地からの眺め","三十稲場遺跡の範囲","となりの新潟県立歴史博物館の縄文展示"],"q":["«火焔土器» と «火焔型土器» のちがいは？","«火焔土器» は馬高で見つかった一点の愛称。似た形の土器をまとめて «火焔型土器» とよびます。"],"koji":[],"myth":"発見日（大みそか）は伝えによる。","img":["火焔型土器","新潟県立歴史博物館","縄文土器","笹山遺跡"],"wp":"馬高遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:8/85/Umataka_Site%2C_gaikan.jpg",5514,3630,"馬高遺跡"],["j:f/f6/%E4%BC%9D%E6%96%B0%E6%BD%9F%E7%9C%8C%E9%95%B7%E5%B2%A1%E5%B8%82%E9%A6%AC%E9%AB%98%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28J-39036%29-1.JPG",3378,3104,"火焔型土器"],["c:5/56/Niigata_Prefectural_Museum_of_History.jpg",640,480,"新潟県立歴史博物館"],["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"縄文土器"]]},{"id":"15_tsuginosuke","n":"河井継之助記念館","yomi":"かわいつぎのすけきねんかん","cat":"幕末","rank":"A","y":1868,"era":["edo"],"sh":"","ad":"長岡市長町1丁目","st":"JR長岡駅から歩いて約10分","la":37.4436,"lo":138.853,"hook":"«戦うか、従うか» の二択を拒み、小さな藩を «武装中立» で守ろうとした男。その生まれた屋敷の跡に記念館が建つ。","lead":"河井継之助は幕末の長岡藩の家老です。藩のお金を立て直し、西洋の新しい武器をそろえて、新政府軍にも旧幕府側にもつかない道を探しました。記念館は継之助が生まれ育った屋敷の跡に建ち、その考え方と最期までを紹介しています。","story":["1827年、継之助は長岡藩の中級の武士の家に生まれました。若いころから «本を読むだけでは意味がない、どう行うかが大事だ» という陽明学に心をひかれ、江戸で学んだあと、はるばる備中松山（今の岡山県）の山田方谷をたずねます。方谷は借金まみれの藩を立て直した名人でした。«なぜ遠い西国まで?» それは本物の改革を自分の目で見たかったからです。","長岡に戻った継之助は、郡奉行などを経て藩の中心に立ちます。賭博や遊郭を取りしまり、藩の借金を減らし、ためたお金で新しい銃をそろえました。長岡藩は、当時日本に数門しかなかったといわれる連射式の «ガトリング砲» まで手に入れたと伝わります。«小さな藩でも、強ければ誰にも踏みにじられない» ——それが継之助の考えでした。","1868年、戊辰戦争が始まり、新政府軍が越後へ迫ります。継之助は小千谷の慈眼寺で、新政府軍の軍監・岩村精一郎と会い、«長岡は中立を守り、会津との間を取りもちたい» と嘆願しました。しかし若い岩村は聞き入れず、話し合いはわずか短い時間で決裂したといわれます。ここで長岡の運命が決まりました。","長岡藩は奥羽越列藩同盟に加わり、北越戦争が始まります。長岡城は一度落ち、継之助は沼地の «八丁沖» をひそかに渡る奇襲で城を取り戻しますが、その戦いで左ひざに銃弾を受けました。城は数日でふたたび落ち、継之助は担架に乗せられて会津へ向かいます。","峠道の途中で継之助は «八十里 こしぬけ武士の 越す峠» と自分をあざ笑う句を詠んだと伝わります。そして会津領の塩沢村（今の福島県只見町）で、42歳で亡くなりました。長岡の町は焼け、多くの人が彼をうらんだともいわれます。英雄か、町を戦火に巻きこんだ人か——記念館は、その問いを今も来館者に投げかけています。"],"tl":[["1827年","長岡藩士の家に生まれる"],["1859年","備中松山の山田方谷をたずねて学ぶ"],["1867年","家老に進み、藩政改革を本格化"],["1868年5月","小千谷の慈眼寺で岩村精一郎と会談、決裂"],["1868年5月","長岡城が落城"],["1868年7月","八丁沖を渡って長岡城を奪い返すが負傷"],["1868年8月","八十里越を越えて会津へ。塩沢村で死去"],["2006年","生家跡に長岡市の河井継之助記念館が開館"]],"who":[["河井継之助","長岡藩家老。この場所で生まれ育った"],["山田方谷","備中松山藩の改革者。継之助の師"],["岩村精一郎（高俊）","新政府軍の軍監。小千谷談判の相手"],["牧野忠訓","長岡藩主。継之助を重く用いた"],["司馬遼太郎","継之助を主人公にした小説『峠』を書いた作家"]],"deep":["«武装中立» は、スイスのような永世中立国の考えに学んだともいわれますが、継之助自身がどこまでそれを意識していたかは史料で確かめにくく、諸説があります。","ガトリング砲の数は «2門» とする説が有名ですが、何門あったかははっきりしません。当時の日本では非常にめずらしい武器でした。","小千谷談判の相手・岩村精一郎は当時まだ20代前半。のちに本人が «もっと話を聞くべきだった» と振り返ったとする話もありますが、伝聞です。","継之助の名が全国に広まったのは、司馬遼太郎の小説『峠』（1960年代に新聞連載）の影響が大きく、2022年には映画にもなりました。小説の場面には創作が含まれます。","福島県只見町にも «河井継之助記念館» があり、亡くなった場所の近くです。長岡と只見、二つの記念館を訪ねると最期の道のりがつながります。","長岡藩の藩風 «常在戦場»（いつも戦場にいる心がまえで）は、継之助の改革とも重ねて語られます。"],"look":["生家跡であることを示す碑と、館の前の小さな庭","ガトリング砲の復元模型（展示内容は時期により変わることがある）","継之助の書や遺品、ゆかりの資料","小千谷談判から八十里越までの道のりを示す展示","近くの栄涼寺にある継之助の墓（あわせて参拝を）"],"q":["継之助が自分をあざ笑って詠んだとされる句に出てくる峠の名前は？","«八十里越»。実際は8里ほどなのに、けわしくて80里に感じる峠道でした。"],"koji":[{"w":"常在戦場","m":"いつも戦場にいるつもりで気を引きしめること。長岡藩の心がまえとして知られる"}],"myth":"ガトリング砲の数、武装中立の発想の由来、岩村の後年の反省の話は諸説・伝聞。小説『峠』の場面には創作を含む。","img":["北越戦争","長岡藩"],"wp":"河井継之助","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040,"北越戦争"]]},{"id":"15_komehyappyo","n":"米百俵の国漢学校跡","yomi":"こめひゃっぴょうのこっかんがっこうあと","cat":"学び","rank":"A","y":1870,"era":["meiji"],"sh":"","ad":"長岡市大手通2丁目","st":"JR長岡駅から歩いて約5分","la":37.447,"lo":138.848,"hook":"おなかをすかせた人たちの前で、届いた米百俵を «食べずに学校をつくる» と決めた——その学校の跡。","lead":"戊辰戦争で町が焼け、長岡の人々は食べ物にも困っていました。そこへ親せきの藩から米百俵が届きます。藩の役人・小林虎三郎はこの米を売って学校の資金にし、«国漢学校» を開きました。今は学校はなく、跡地を示す碑が町の中に立っています。","story":["1868年の北越戦争で、長岡の城下町は焼け野原になりました。藩の石高（米の取れ高の目安）は大きく減らされ、武士の家族たちはその日の食べ物にも困るほどでした。そんな1870年のある日、長岡藩の分家筋にあたる三根山藩から、お見舞いとして米百俵が届きます。","«これで少しは腹がふくれる» と喜んだ藩士たち。ところが藩の大参事・小林虎三郎は、この米を分けずに売ってしまい、そのお金で学校を建てると言い出しました。«なぜ今、学校なんだ!» と怒った藩士たちが詰め寄った、と伝わります。","虎三郎は若いころ、江戸の佐久間象山の塾で学び、吉田松陰とならんで «象山門下の二虎» と呼ばれた人でした。病気がちで体は弱かったものの、«国が立ち直るもとは人を育てることだ» という考えは誰よりもかたかったのです。","こうして国漢学校が開かれました。はじめは寺を借りて授業をし、のちに坂之上町（今の大手通あたり）に校舎が建ちます。武士の子だけでなく町人の子にも門を開いたといわれ、漢学だけでなく、洋学や医学も学べるようにしました。","この話が全国に知られるようになったのは、作家・山本有三が1943年に戯曲『米百俵』を書いてからです。「百俵の米も、食えばたちまちなくなるが、教育にあてれば明日の一万、百万俵となる」というせりふは、この戯曲の中で虎三郎が語る言葉として有名になりました。2001年には首相の所信表明演説でも引用され、再び話題になりました。"],"tl":[["1828年","小林虎三郎、長岡藩士の家に生まれる"],["1868年","北越戦争。長岡城下が焼ける"],["1870年","三根山藩から米百俵が届き、これを資金に国漢学校を開く"],["1877年","小林虎三郎が亡くなる"],["1943年","山本有三が戯曲『米百俵』を発表"],["2001年","首相の所信表明演説で米百俵の話が引用され話題に"]],"who":[["小林虎三郎","長岡藩の大参事。米を学校の資金にあてた"],["佐久間象山","虎三郎の師。洋学と兵学を教えた"],["吉田松陰","虎三郎とともに «象山門下の二虎» と呼ばれた"],["山本有三","戯曲『米百俵』の作者"]],"deep":["三根山藩は今の新潟市西蒲区あたりにあった小藩で、長岡藩牧野家の分家筋。自分たちも楽ではない中で米を送ったことにも注目したい。","国漢学校は、のちの長岡の中学校（今の県立長岡高校）の源流の一つとされ、長岡の教育熱の象徴として語られます。","有名な «百俵の米も〜» のせりふは山本有三の戯曲のもの。虎三郎本人がそのとおりに言ったと記す同時代史料は確認されていません。","戯曲が発表された1943年は戦争のさなか。«国のために今は耐えよ» という読み方もされ、上演の意味をめぐっては戦後に議論もありました。","米百俵の話は、目の前の欲をこらえて将来に投資する «長期的な視点» のたとえとして、企業や政治の場でもしばしば使われます。","長岡市内には «米百俵之碑» や、虎三郎をしのぶ碑があり、国漢学校跡の碑とあわせて歩けます。"],"look":["大手通の «国漢学校跡» の碑","米百俵にちなむ碑・像（市内各所）","長岡藩ゆかりの資料を見られる市内の資料館","駅前から続く大手通そのもの（戦災と復興の町並み）"],"q":["米百俵を送ってくれたのはどこの藩？","長岡藩の分家筋にあたる «三根山藩» です。"],"koji":[{"w":"米百俵の精神","m":"今の苦しさをこらえて、将来のために人づくりや投資をすること"}],"myth":"«百俵の米も〜» の名せりふは戯曲による。藩士が詰め寄った場面も伝承的要素を含む。","img":["小林虎三郎","山本有三","長岡藩"],"wp":"米百俵","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Kobayashi_Torasaburo_BW.jpg",810,1098,"小林虎三郎"],["c:5/5e/Yuzo_Yamamoto%2C_1954.jpg",1418,2087,"山本有三"]]},{"id":"15_kugamiji","n":"国上寺と五合庵（良寛の庵）","yomi":"こくじょうじとごごうあん","cat":"寺社","rank":"A","y":1797,"era":["nara","edo"],"sh":"","ad":"燕市国上","st":"JR越後線 分水駅から車で約10分（車が便利）","la":37.7035,"lo":138.823,"hook":"«焚くほどは 風がもてくる 落ち葉かな»——お坊さん良寛が、欲をすてて暮らした山の小さな庵。","lead":"国上寺は国上山の中腹にある古いお寺で、越後でもっとも古いお寺の一つと伝わります。その境内の林の中に、良寛が長く暮らした «五合庵» があります。今の庵は大正時代に建て直されたものですが、良寛がいた場所の雰囲気をよく伝えています。","story":["国上寺は、奈良時代のはじめに開かれたと伝わる真言宗のお寺です。国上山のうっそうとした杉林の中にあり、昔から修行の山として人々に大切にされてきました。このお寺には «酒呑童子は、じつはここの稚児（見習いの少年）だった» という、ちょっと不思議な言い伝えも残っています。","江戸時代、国上寺には «五合庵» という小さな庵がありました。名前の由来は、かつてここに住んだお坊さんが、お寺から毎日五合のお米をもらっていたからだといわれます。«五合で足りるの?» と思うかもしれませんが、一人で静かに暮らすには十分でした。","その五合庵に、出雲崎生まれの僧・良寛がやってきます。良寛は岡山の円通寺で修行したあと、各地を旅してふるさとの越後に戻りました。お寺の住職にはならず、托鉢（家々を回って食べ物をもらうこと）をしながら、この庵で20年ほど暮らしたと考えられています。","良寛は子どもたちと手まりやかくれんぼをして遊ぶのが大好きでした。かくれんぼで隠れたまま、子どもたちが帰ってしまっても翌朝まで待っていた——そんなほほえましい話がたくさん伝わっています。一方で、良寛の書や和歌、漢詩は今でも一流とされ、多くの人をひきつけています。","年をとった良寛は山の暮らしがつらくなり、ふもとの乙子神社のそばの庵へ、さらに島崎（今の長岡市）の木村家の離れへと移りました。晩年には若い尼僧・貞心尼との心あたたまる歌のやりとりもありました。五合庵のわびしい小屋の前に立つと、«ものを持たない豊かさ» とは何かを考えさせられます。"],"tl":[["709年","国上寺が開かれたと伝わる（寺伝）"],["1758年","良寛、出雲崎に生まれる"],["1790年代後半","良寛、五合庵に住みはじめる（諸説あり）"],["1816年ごろ","良寛、ふもとの乙子神社の草庵に移る"],["1826年","良寛、島崎の木村家に移る"],["1831年","良寛、島崎で亡くなる"],["1914年","五合庵が建て直される（現在の庵）"]],"who":[["良寛","江戸時代後期の僧・歌人・書家。五合庵で長く暮らした"],["貞心尼","晩年の良寛と歌をかわした尼僧。『はちすの露』をまとめた"],["萬元","五合庵にかつて住み、名前の由来になったといわれる僧"],["酒呑童子","国上寺の稚児だったという伝説がある鬼"]],"deep":["五合庵に住みはじめた年は諸説あり、一度離れてまた戻ったとも考えられています。住んだ期間をあわせるとおよそ20年とされます。","現在の五合庵は1914年の再建で、良寛が住んだ建物そのものではありません。広さは畳数枚ほどの質素なつくりです。","良寛の弟子・貞心尼がまとめた『はちすの露』は、良寛の歌を後世に伝えた大切な書物で、二人の贈答歌がおさめられています。","良寛は«天上大風»の字を、凧をもった子どもにたのまれて書いたという話が有名です（字は現存するとされますが、場面は伝承）。","国上寺の酒呑童子伝説は、京都の大江山の話と結びつけて語られますが、鬼の出身地には各地に説があり、確かな話ではありません。","ふもとの燕市には良寛の資料を集めた «良寛史料館» があり、国上山とあわせて訪ねると理解が深まります。"],"look":["杉木立の中にひっそり建つ五合庵","国上寺の本堂と、山の上の境内の雰囲気","良寛の歌碑（境内や参道に点在）","ふもとの乙子神社と、良寛が晩年に住んだ草庵の跡","燕市分水良寛史料館"],"q":["五合庵の «五合» はなんの量のこと？","かつての住人がお寺から毎日もらったお米の量（五合）に由来するといわれます。"],"koji":[{"w":"焚くほどは 風がもてくる 落ち葉かな","m":"たき火に使う分の落ち葉は風が運んでくれる。必要以上を求めない良寛の心を表す句"}],"myth":"国上寺の創建年と酒呑童子の稚児説は寺伝・伝承。良寛のかくれんぼの話など逸話の多くは伝承。","img":["良寛","五合庵","貞心尼"],"wp":"国上寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/f5/Kokujouji_Temple%2C_Tsubame%2C_Niigata%2C_Japan%2C_May_2021.jpg",4032,3024,"国上寺"]]},{"id":"15_izumozaki","n":"出雲崎（北国街道・佐渡金の荷揚げ港・良寛生誕地）","yomi":"いずもざき","cat":"町","rank":"A","y":1758,"era":["edo"],"sh":"","ad":"三島郡出雲崎町尼瀬・石井町ほか","st":"JR越後線 出雲崎駅からバスで約10分（駅は町の中心から離れている）","la":37.531,"lo":138.706,"hook":"海のむこうの佐渡から、金と銀がこの浜に上がった。細長い «妻入り» の家並みが、4km近く海沿いに続く町。","lead":"出雲崎は、江戸時代に幕府が直接おさめた «天領» の港町です。佐渡でとれた金銀はここで陸にあげられ、北国街道を通って江戸へ運ばれました。お坊さんの良寛が生まれた町でもあり、生家の跡には良寛堂が建っています。","story":["出雲崎の町を歩くと、家の «妻»（屋根の三角形の面）が道のほうを向いた «妻入り» の家がずらりと並んでいます。間口はせまく、奥にとても長い。«なぜこんな形?» ——海と山にはさまれた細長い土地に、たくさんの家をつめこむための工夫だったといわれます。","江戸時代、佐渡金山でとれた金銀は船で佐渡の小木港から運ばれ、出雲崎に陸あげされました。そこから北国街道を通って江戸へ。港には代官所がおかれ、佐渡へ渡る役人や流人もここから船に乗りました。町は人と荷物でにぎわい、越後でも有数の宿場町になりました。","1689年の夏、松尾芭蕉も『おくのほそ道』の旅で出雲崎に泊まりました。夜の海のむこうに佐渡が横たわり、空には天の川。«荒海や 佐渡によこたふ 天河» の句は、このあたりの情景から生まれたと考えられています（詠んだ場所には諸説あります）。","1758年、この町の名主・橘屋山本家に一人の男の子が生まれました。のちの良寛です。名主のあとつぎになるはずでしたが、18歳ごろ家を出て仏の道に入ります。«なぜ裕福な家をすてたのか?» 理由ははっきりしません。生家の跡には1922年に良寛堂が建てられ、良寛が母の面影をしのんだという佐渡の島を見わたしています。","明治になると、出雲崎の海岸では石油がわき出し、油田の町としてにぎわった時代もありました。金、宿場、石油——出雲崎はいつも «何かが運ばれてくる町» だったのです。今は静かな町並みに、その重なった歴史が眠っています。"],"tl":[["1616年ごろ","江戸幕府の天領となり、代官所がおかれる（時期は諸説）"],["1689年","松尾芭蕉が出雲崎に泊まる"],["1758年","良寛、名主橘屋に生まれる"],["明治時代","海岸で石油の採掘が盛んになる"],["1922年","良寛の生家跡に良寛堂が建つ"],["1965年","良寛記念館が開館"]],"who":[["良寛","この町の名主の家に生まれた僧・歌人"],["松尾芭蕉","『おくのほそ道』の旅で宿泊"],["安田靫彦","良寛堂の設計にかかわった日本画家"],["佐渡奉行","佐渡へ渡る際に出雲崎を通った幕府の役人"]],"deep":["佐渡の金銀は、小木港から出雲崎へ運ばれるのが基本ルートでした。荷を守る役人がつき、街道の宿場は «御金荷» の通行に気をつかいました。","«荒海や〜» の句は、出雲崎で詠んだとする説と、のちの直江津などで作品にまとめたとする説があります。芭蕉の実際の旅の記録は、同行した曽良の日記で確かめられます。","良寛堂は日本画家・安田靫彦が設計にかかわったお堂で、中に良寛が大切にした枕地蔵をまつるといわれます。","出雲崎の妻入りの町並みは海岸線にそって約4kmも続くとされ、日本海側の街道町の姿をよく残しています。","出雲崎の尼瀬地区は、明治期に日本でも早い時期に機械で石油を掘った場所の一つとされ、町には石油の記念館もあります。"],"look":["妻入りの家が続く北国街道の町並み","良寛堂と、海をみつめる良寛像","良寛記念館（高台から佐渡を一望）","天領出雲崎時代館（代官所や北前船の展示）","海岸に残る石油関連の記念施設"],"q":["佐渡の金銀はどこの港から出雲崎へ運ばれた？","主に佐渡南部の «小木港» からです。"],"koji":[{"w":"荒海や 佐渡によこたふ 天河","m":"荒れる日本海のむこうに佐渡島があり、その上に天の川が横たわっている、という芭蕉の句"}],"myth":"芭蕉の句を詠んだ場所、良寛の出家の理由、天領となった年は諸説。","img":["良寛","北国街道","佐渡金山"],"wp":"出雲崎町","rel":{"ev":[],"grave":[]},"ph":[["c:4/41/Find47_Niigata-_Ryokan_and_Yuhi-no-oka_Park_%28Izumozaki_Town%29-m.jpg",1920,1280,"出雲崎町"],["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"]]},{"id":"15_oyashirazu","n":"親不知（北陸道最大の難所）","yomi":"おやしらず","cat":"街道","rank":"A","y":1883,"era":["heian","edo","meiji"],"sh":"","ad":"糸魚川市市振・外波ほか","st":"えちごトキめき鉄道 日本海ひすいライン 親不知駅から天険親不知記念広場まで車で約5〜10分","la":37.001,"lo":137.701,"hook":"断崖と荒波のすき間を、波が引いたすきに駆けぬけた——親は子を、子は親をかえりみる余裕さえなかった道。","lead":"親不知は、北アルプスの山が日本海に直接落ちこむ、約15kmの断崖の海岸です。昔の旅人は、崖の下のせまい浜を、波が引いた一瞬をねらって走りぬけました。明治に崖を切り開いた道ができ、今は鉄道や高速道路がトンネルと海の上の橋で通っています。","story":["京都から越後、そして東北へ向かう北陸道。その途中に、どうしてもよけて通れない場所がありました。高さ数百メートルの崖が、そのまま海に落ちこむ親不知です。道といえるものは波打ち際だけ。旅人は岩かげで波を見はからい、波が引いたとたんに次の岩かげまで走りました。","«親不知子不知» という名前には、悲しい言い伝えがあります。平清盛の弟・平頼盛の妻が、越後にいる夫をたずねてこの浜を通ったとき、連れていた幼い子を波にさらわれてしまいました。«親知らず 子はこの浦の 波枕 越路の磯の 泡と消えゆく»——そう嘆く歌を詠んだと伝わります。親も子もおたがいをかえりみる余裕がない場所、という意味だともいわれます。","江戸時代、加賀藩の大名行列もここを通りました。数百人の行列が、波の合間をぬって進むのです。村の人々は «波除け人足» として旅人を助け、荒れた日には何日も足止めされることもありました。1689年には松尾芭蕉もこの難所を越え、すぐ西の市振の宿で句を残しています。","明治になると、ついに崖を削って道をつくる工事が行われ、1883年に完成しました。岩には、道が «砥石のように平らで、矢のようにまっすぐ» になったことを喜ぶ «如砥如矢» の文字が刻まれています。«あの崖に道を?» 当時の人にとって、それは夢のような出来事でした。","その後、鉄道はトンネルで、国道は崖の中腹で、そして1980年代には北陸自動車道が海の上に張り出した高架で、この難所を越えるようになりました。天険親不知の展望台から見下ろすと、古い道、明治の道、現代の道が何段にも重なり、人がこの崖とどう向き合ってきたかが一目でわかります。"],"tl":[["平安時代末","平頼盛の妻の悲話が生まれたと伝わる"],["江戸時代","加賀藩など北陸の大名が参勤交代で通行"],["1689年","松尾芭蕉が通過し、市振に泊まる"],["1883年","崖を削った新道が完成。«如砥如矢» を刻む"],["1912年","北陸本線がこの区間で開通"],["1988年","北陸自動車道が全線開通。海上高架で通過"]],"who":[["平頼盛の妻","子を波にさらわれた悲話の主人公と伝わる"],["松尾芭蕉","『おくのほそ道』で通過"],["ウォルター・ウェストン","明治に訪れた英国人宣教師・登山家。記念碑が立つ"],["波除け人足","旅人の通行を助けた地元の人々"]],"deep":["«親不知» は狭い意味では市振〜外波あたりの断崖の一部の名前で、広く «親不知子不知» と呼ばれる約15kmの海岸をさすこともあります。","平頼盛の妻の話は伝説で、史料で確かめられるものではありません。歌の文句にもいくつかの形があります。","«如砥如矢» は中国の古典『詩経』にある言葉に由来するといわれ、道が平らで真っすぐなことをたたえる表現です。","明治の旧国道の一部はトンネルごと «親不知コミュニティロード» として歩けるよう整備され、断崖を体感できます。","親不知はフォッサマグナ（本州を横切る大きな溝）の西の端に近く、糸魚川ユネスコ世界ジオパークの見どころの一つにもなっています。","芭蕉が市振の宿で詠んだ «一家に 遊女もねたり 萩と月» は、この難所を越えた疲れの夜の句として知られます。"],"look":["天険親不知の展望台と «如砥如矢» の刻字","親不知コミュニティロード（明治の道とトンネル）","海の上に張り出した北陸自動車道の眺め","ウェストンの記念碑","親不知記念広場から見下ろす波打ち際（下りる場合は波と足元に注意）"],"q":["明治に崖を切り開いてできた道をたたえて、岩に刻まれた4文字は？","«如砥如矢»（砥石のように平らで、矢のようにまっすぐ）です。"],"koji":[{"w":"親知らず子知らず","m":"危なすぎて、親は子を、子は親をかえりみる余裕もないこと"}],"myth":"平頼盛の妻の悲話は伝説。名前の由来にはほかの説もある。","img":["北陸道","糸魚川ジオパーク"],"wp":"親不知","rel":{"ev":[],"grave":[]}},{"id":"15_shukunegi","n":"宿根木（千石船の集落）","yomi":"しゅくねぎ","cat":"町","rank":"A","y":1800,"era":["edo"],"sh":"国の重要伝統的建造物群保存地区","ad":"佐渡市宿根木","st":"小木港から車で約10分（路線バスもあるが本数は少ない）","la":37.8065,"lo":138.2525,"hook":"船大工がつくった家が、肩をよせ合うように建つ小さな入り江。路地に入ると、江戸の千石船の時代にまぎれこんだよう。","lead":"宿根木は佐渡の南の端にある小さな集落です。江戸時代、ここは千石船をつくり、動かす人たちの村として大いに栄えました。約1ヘクタールほどの土地に百棟あまりの建物がぎっしりと並び、国の重要伝統的建造物群保存地区に選ばれています。","story":["佐渡の南西、小さな入り江にひっそりとある宿根木。一歩路地に入ると、黒っぽい板張りの家が両側からせまり、人がやっとすれちがえるほどの細い道が迷路のように続いています。«なぜこんなに家がくっついているの?» ——入り江のわずかな平地に、たくさんの家を建てる必要があったからです。","江戸時代の中ごろから、宿根木は千石船の村として栄えました。千石船とは、米を千石（約150トン）ほど積める大きな木造の帆船のこと。宿根木には船主、船乗り、そして船をつくる船大工が住み、日本海から瀬戸内海、大坂まで荷を運んで大きなもうけを上げたといわれます。","家々には船大工の技がいっぱいです。外壁に使われた板には、古い船の材料を再利用したものもあると伝わります。いちばん有名なのは、三角形の土地にぴったり合わせて建てた «三角家»。船の舳先のような形をしていて、ポスターなどでもよく紹介されてきました。","明治になって蒸気船や鉄道の時代が来ると、千石船の出番は減り、宿根木の繁栄も静かに終わりました。けれど、そのおかげで町並みは大きく変わらず、江戸から明治の姿をよく残すことになったのです。1991年、国の重要伝統的建造物群保存地区に選ばれました。","近くの «佐渡国小木民俗博物館» には、古い図面をもとに実物大で復元された千石船 «白山丸» が展示されています。見上げるほど大きな船体を前にすると、«この船で本当に日本海を渡ったのか!» と驚かされます。宿根木の人々の度胸と技術が、この村をつくったのです。"],"tl":[["中世","称光寺など寺を中心に集落がひらける（詳細は不明な点が多い）"],["江戸時代中期〜後期","千石船の船主・船大工の村として繁栄"],["明治時代","汽船の時代となり、廻船業がおとろえる"],["1991年","国の重要伝統的建造物群保存地区に選定"],["1998年","千石船 «白山丸» の実物大復元が完成"]],"who":[["船主・船乗りたち","千石船で日本各地と交易し、村を豊かにした"],["船大工","船の技術で家々も建てた"],["称光寺","集落の中心となってきたお寺"]],"deep":["保存地区の広さは約28ヘクタールとされますが、家々が集中する中心部はごく小さな範囲です。狭い土地に百棟あまりの建物がひしめくのが特徴です。","宿根木の家は、外は質素な板張り、中は漆塗りの柱や豪華な建具という «外は地味、中はぜいたく» のつくりが見られ、公開されている家もあります。","白山丸は、安政年間（1850年代）に宿根木で造られた船の図面をもとに復元されたと説明されています。帆柱の高さも圧倒的です。","宿根木の近くには、良質な «小木の石» を切り出した場所もあり、石臼や石垣など、石の文化も発達していました。","千石船の «千石» は船の大きさの目安で、ちょうど千石積みとは限りません。北前船とも呼ばれる日本海の商船と同じ系統の船です。","三角家は現在も住まいとして使われてきた家があるなど、町並み全体が生活の場です。見学のときは住む人への配慮を。"],"look":["船の舳先のような «三角家»","人がすれちがうのがやっとの石畳の路地","公開されている古い民家（清九郎家など、公開状況は要確認）","称光寺","佐渡国小木民俗博物館の千石船 «白山丸»"],"q":["千石船の «千石» とはなにを表している？","船にのせられる米の量（約千石＝約150トン）で、船の大きさの目安です。"],"koji":[],"myth":"船材を家の壁に再利用した話は伝承的な説明を含む。白山丸の元図面の詳細は資料館の説明による。","img":["千石船","北前船","佐渡島"],"wp":"宿根木","rel":{"ev":[],"grave":[]},"ph":[["c:0/0c/Sado_Shukunegi.jpg",5184,3456,"宿根木"],["c:f/fa/Ueno_junks.jpg",2560,1980,"千石船"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:8/89/SadoGaShima.jpg",1280,960,"佐渡島"]]},{"id":"15_kitazawa","n":"北沢浮遊選鉱場跡（相川）","yomi":"きたざわふゆうせんこうじょうあと","cat":"近代","rank":"A","y":1938,"era":["meiji","showa"],"sh":"国指定史跡（佐渡金山遺跡の一部）","ad":"佐渡市相川北沢町","st":"両津港から車で約1時間。相川方面のバスで «佐渡版画村» 付近下車、歩いて約5分","la":38.0435,"lo":138.2445,"hook":"山の斜面をおおう巨大なコンクリートの段々。«東洋一» とよばれた金銀の工場は、いま緑に飲まれかけた遺跡になった。","lead":"北沢浮遊選鉱場は、佐渡金山の鉱石から金や銀をとり出すための巨大な工場でした。1938年に完成し、当時は東洋一の規模といわれました。今は屋根のない骨組みだけが残り、まるで古代の遺跡のような姿で人気を集めています。","story":["佐渡の相川は、江戸時代から金銀の島の中心でした。明治になると鉱山は国の経営になり、その後、民間の三菱に払い下げられます。機械で掘る時代になり、とれる鉱石の量はぐんと増えました。«でも、石の中の金をどうやって取り出す?» それが新しい課題でした。","答えの一つが «浮遊選鉱» です。細かくくだいた鉱石を、薬を入れた水の中でかきまぜて泡を立てると、金や銀をふくむ粒だけが泡にくっついて浮かび上がります。これを集めれば、効率よく金銀を取り出せるのです。北沢では大正時代からこの方法が試され、改良が重ねられました。","1930年代、日本は戦争に向かう中で、外国との支払いに使う金を大量に必要としていました。国の方針で金の増産が進められ、1938年、北沢に巨大な浮遊選鉱場が完成します。山の斜面に階段のように建物を並べ、鉱石が上から下へ流れるしくみでした。一か月に何万トンもの鉱石を処理できたといわれます。","しかし戦争が進むと、金よりも銅など軍事に必要な金属が優先され、選鉱場の役割も変わっていきました。戦後は鉱石の質の低下もあり、施設は縮小されます。そして1989年、佐渡金山は長い操業に幕を下ろしました。","屋根がなくなり、コンクリートの壁だけが残った選鉱場は、夏はツタにおおわれ、夜はライトアップで浮かび上がります。«ラピュタみたい» と話題になることもあります。すぐそばには、直径約50mの丸い沈殿池 «シックナー» も残っています。ここで働いた多くの人の汗と、国策にほんろうされた時代の記憶が、静かに刻まれています。"],"tl":[["1601年ごろ","相川で金銀山が本格的にひらかれる（江戸時代の佐渡金山）"],["1869年","明治政府の官営鉱山となる"],["1896年","三菱合資会社に払い下げられる"],["1938年","北沢に大規模な浮遊選鉱場が完成"],["1952年ごろ","戦後の縮小で選鉱場の操業が大きく減る（時期は諸説）"],["1989年","佐渡金山が操業を終える"],["2024年","«佐渡島の金山» が世界文化遺産に登録"]],"who":[["三菱","明治から佐渡鉱山を経営した企業"],["鉱山で働いた人々","掘る・運ぶ・選鉱する作業を担った"]],"deep":["浮遊選鉱は20世紀初めに欧米で広まった技術で、北沢の選鉱場はその大規模な実用例として、日本の鉱業史でも注目されています。","北沢地区には選鉱場のほか、明治に建てられた火力発電所の建物や、鉱石を運んだ施設の跡など、近代の遺構がまとまって残っています。","2024年に世界遺産となった «佐渡島の金山» は、主に江戸時代までの手作業による金生産が評価の中心です。北沢の近代遺構は、その後の歴史を伝えるものとして一体的に見学できます。","戦時中の佐渡鉱山では朝鮮半島出身の人々も働いており、その労働のあり方をめぐっては世界遺産登録の際にも議論がありました。現地の展示もあわせて見たい。","選鉱場の «段々» は、重力を利用して鉱石と水を上から下へ流すための配置です。上から順に見ていくと工程の流れが想像できます。"],"look":["斜面に並ぶ選鉱場のコンクリート遺構（立入りできる範囲に注意）","直径約50mのシックナー（沈殿池）","旧北沢火力発電所の建物","夜間のライトアップ（期間・時間は要確認）","近くの大間港や道遊の割戸へも足をのばして"],"q":["泡を使って金や銀の粒を取り出す方法を何という？","«浮遊選鉱»。薬を入れた水をかきまぜ、泡に金属の粒をくっつけて集めます。"],"koji":[],"myth":"«東洋一» は当時の宣伝的な呼び名。処理量の数字は資料によって異なる。","img":["佐渡金山","相川","佐渡島の金山"],"wp":"北沢浮遊選鉱場","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/Kitazawa_Flotation_Plant_ac_%282%29.jpg",5990,3983,"北沢浮遊選鉱場"],["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"],["c:8/87/Sadokinzan-doyunowareto_01.JPG",1024,712,"佐渡島の金山"]]},{"id":"15_sado_kokubunji","n":"佐渡国分寺跡","yomi":"さどこくぶんじあと","cat":"寺社","rank":"A","y":760,"era":["nara","heian"],"sh":"国指定史跡","ad":"佐渡市国分寺","st":"両津港から車で約30分（バスは本数が少ない）","la":38.0205,"lo":138.3665,"hook":"日本海の島にも、奈良の都と同じ «国分寺» が建てられた。田んぼのわきに残る大きな礎石が、千年以上前の大伽藍を語る。","lead":"741年、聖武天皇は国ごとに国分寺をつくるよう命じました。海をへだてた佐渡国にも国分寺が建てられ、その跡地には金堂や塔などの礎石が今も残っています。すぐそばには、あとをつぐ現在の国分寺があり、平安時代の仏さまが伝わっています。","story":["奈良時代、都では病気や災害、反乱が次々と起こっていました。«仏の力で国を守りたい» と考えた聖武天皇は、741年、全国の国ごとに «国分寺» と «国分尼寺» を建てるよう命じます。その命令は、船で海を渡らなければ行けない佐渡にも届きました。","佐渡国分寺は、国の役所・国府があった真野のあたりにつくられました。金堂、講堂、七重の塔……都と同じような立派な伽藍を、島の人々が力を合わせて建てたのです。完成は8世紀の後半と考えられています。«こんな島に、どうしてこれほどの寺が?» それだけ朝廷にとって、国ごとの国分寺は大切な «国家プロジェクト» でした。","しかし、古代の建物は長くはもちませんでした。火災や時代の移り変わりの中で伽藍は失われ、やがて田畑の中に礎石だけが残ることになります。大きな石の上に柱が立っていた——そのことを、礎石のくぼみが静かに教えてくれます。","古代の寺はなくなっても、国分寺の名前と仏さまは受けつがれました。すぐ近くの現在の国分寺には、平安時代につくられた薬師如来坐像がまつられ、国の重要文化財になっています。江戸時代に建てられた瑠璃堂（薬師堂）もあります。","このあたりは、流されてきた人々ともゆかりの深い土地です。順徳上皇、日蓮、世阿弥——都から遠く離れたこの島で、彼らも同じ真野の空を見上げました。礎石の並ぶ草地に立つと、都の文化が海を越えて根をおろした長い時間が感じられます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["8世紀後半","佐渡国分寺の伽藍が整う（時期は推定）"],["平安時代","薬師如来坐像がつくられる"],["中世","古代の伽藍が失われる"],["江戸時代","現在の国分寺に瑠璃堂が建てられる"],["1929年","佐渡国分寺跡が国の史跡に指定"]],"who":[["聖武天皇","国分寺建立の詔を出した"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立を後押ししたとされる"],["順徳上皇","承久の乱のあと佐渡に流され、真野の近くで亡くなった"],["世阿弥","室町時代に佐渡に流された能の大成者"]],"deep":["発掘で、金堂・講堂・中門・塔などの位置が確かめられ、塔を回廊の外に置く配置と考えられています。礎石の多くは元の位置に残るとされます。","出土した瓦から、国分寺の造営時期や、どこで瓦を焼いたかが研究されています。島内に瓦窯の跡も見つかっています。","現在の国分寺の本尊・木造薬師如来坐像は平安時代の作とされ、国の重要文化財です（拝観は寺の都合によるので事前確認を）。","国分寺の正式名は «金光明四天王護国之寺»。お経の力で国を守るという考えがこめられています。","佐渡国分寺跡の近くには、順徳上皇の火葬塚（真野御陵）や、日蓮ゆかりの寺も集まり、真野は «流人の島・佐渡» の歴史をたどる拠点です。"],"look":["草地に残る金堂・塔などの礎石","史跡の説明板と伽藍配置の図","現在の国分寺の瑠璃堂","近くの真野御陵や妙宣寺とあわせた散策"],"q":["国分寺の建立を命じた天皇はだれ？","聖武天皇です。741年に詔を出しました。"],"koji":[],"myth":"伽藍の完成時期、塔の層数などは推定を含む。","img":["国分寺","聖武天皇","佐渡国"],"wp":"佐渡国分寺","rel":{"ev":["nichiren"],"grave":[]},"ph":[["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"]]},{"id":"15_myosenji","n":"妙宣寺五重塔（佐渡）","yomi":"みょうせんじごじゅうのとう","cat":"寺社","rank":"A","y":1825,"era":["kamakura","edo"],"sh":"国の重要文化財（五重塔）","ad":"佐渡市阿仏坊","st":"両津港から車で約30分","la":38.018,"lo":138.379,"hook":"新潟県でただ一つの五重塔。田園の中にすっくと立つその姿は、流罪の日蓮に仕えた老夫婦の信心から始まった。","lead":"妙宣寺は、佐渡に流された日蓮を支えた «阿仏房» が開いたと伝わる日蓮宗のお寺です。境内には江戸時代後期に建てられた五重塔があり、新潟県内で唯一の五重塔として国の重要文化財になっています。","story":["1271年、鎌倉幕府を批判した日蓮は、罪人として佐渡へ流されました。冬の佐渡で、日蓮はあばら家のような «三昧堂» に入れられ、雪にうもれながら暮らします。その日蓮を、命がけで支えた夫婦がいました。阿仏房と、その妻・千日尼です。","阿仏房は、もとは承久の乱で佐渡に流された順徳上皇に仕えていた武士だったとも伝わります。熱心な念仏の信者で、はじめは日蓮を «けしからぬ坊主» と思っていたといわれます。ところが話をするうちに心を打たれ、夜ごとに食べ物を背負って日蓮のもとへ通うようになりました。«見つかれば罰を受ける。それでも行くのか?» ——夫婦は迷わなかったと伝わります。","日蓮が許されて佐渡を去ったあとも、阿仏房は老いた体で、日蓮のいる遠い身延山まで何度も会いに行ったといわれます。日蓮が千日尼にあてた手紙が伝わっていて、夫婦への深い感謝がつづられています。阿仏房の屋敷がのちに寺となったのが、妙宣寺のはじまりとされます。","寺は戦国時代の終わりごろ、今の場所へ移りました。ここはかつて佐渡の豪族・本間氏の雑太城があった場所だといわれます。そして江戸時代後期の1825年、境内に五重塔が完成しました。相川の宮大工が、日光東照宮の五重塔を手本にして建てたと伝わります。","高さは約24m。田んぼの向こうに見える五重塔は、佐渡の人々にとって心のよりどころでした。«なぜ島にこれほどの塔が?» 金山で栄えた佐渡の経済力と、日蓮以来の厚い信仰——その両方がそろって、この塔が生まれたのです。"],"tl":[["1271年","日蓮が佐渡に流される"],["1274年","日蓮が許されて佐渡を去る"],["鎌倉時代","阿仏房の屋敷が寺となったと伝わる（妙宣寺のはじまり）"],["戦国時代末","現在地（雑太城跡と伝わる場所）へ移る"],["1825年","五重塔が完成"],["昭和時代","五重塔が国の重要文化財に指定される"]],"who":[["阿仏房","日蓮を支えた佐渡の信者。妙宣寺の開基と伝わる"],["千日尼","阿仏房の妻。日蓮から手紙を受けた"],["日蓮","佐渡に流された日蓮宗の開祖"],["順徳上皇","阿仏房が仕えていたと伝わる上皇"]],"deep":["妙宣寺五重塔は新潟県内に現存する唯一の五重塔とされ、江戸時代後期の地方の塔として貴重です。","塔の設計・建築を担ったのは相川の大工とされ、日光東照宮の五重塔を手本にしたとの伝えがありますが、細部の比較には研究の余地があります。","日蓮の手紙のうち、千日尼にあてたものは、女性信者との交流を伝える史料として重視されています（真筆かどうかは手紙ごとに検討されています）。","阿仏房が順徳上皇の家来だったという話は寺伝で、確かな史料では確かめにくいとされます。","境内には日野資朝の墓と伝わる塔もあります。資朝は鎌倉幕府を倒そうとした罪で佐渡に流され、この地で処刑されたといわれます。"],"look":["新潟県唯一の五重塔と、その屋根の反り","境内の日野資朝の墓と伝わる塔","雑太城跡と伝わる地形（堀や土塁の名残）","近くの佐渡国分寺跡・真野御陵とのセット散策"],"q":["妙宣寺をひらいたと伝わる、日蓮を支えた人の名前は？","«阿仏房» です。妻の千日尼とともに日蓮を助けました。"],"koji":[],"myth":"阿仏房の出自、身延山へ何度も通った話、日光を手本にした話は寺伝・伝承。","img":["日蓮","阿仏房","雑太城"],"wp":"妙宣寺 (佐渡市)","rel":{"ev":[],"grave":[]},"ph":[["c:d/d1/Myousenji_temple_%E9%98%BF%E4%BB%8F%E5%9D%8A%E5%A6%99%E5%AE%A3%E5%AF%BA_%283658494016%29.jpg",1280,853,"妙宣寺 (佐渡市)"],["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"]]},{"id":"15_nagaoka_kushu","n":"長岡空襲と長岡戦災資料館","yomi":"ながおかくうしゅうとながおかせんさいしりょうかん","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"長岡市大手通2丁目","st":"JR長岡駅から歩いて約5分","la":37.4485,"lo":138.85,"hook":"1945年8月1日の夜、わずか2時間足らずで町の8割が焼けた。夏の夜空に上がる長岡の花火は、そのとき亡くなった人々への祈りでもある。","lead":"太平洋戦争の終わり近く、1945年8月1日の夜、長岡はアメリカ軍のB29の大編隊に焼夷弾で攻撃されました。1,480人をこえる人が亡くなり、市街地の大部分が焼けました。長岡戦災資料館は、その記憶と記録を伝える施設です。","story":["1945年の夏、日本の大都市はすでに空襲で焼かれ、アメリカ軍は地方の中小都市にも攻撃を広げていました。8月1日の夜10時半ごろ、長岡の空に空襲警報が鳴りひびきます。やがて100機をこえるB29が現れ、町の上に焼夷弾の雨を降らせました。","焼夷弾は、落ちると油をまきちらして燃え広がる爆弾です。木造の家がびっしり並ぶ町は、あっという間に火の海になりました。人々は信濃川や神社、防空壕へ逃げましたが、炎と熱風に追いつかれた人も多かったのです。平潟神社の境内では、逃げこんだ多くの人が命を落としました。","空襲はわずか2時間足らずでしたが、市街地の約8割が焼け、1,480人をこえる人が亡くなりました。その中には多くの子どもやお年寄りも含まれていました。«なぜ長岡が?» 長岡には工場や鉄道の拠点があったこと、そして中小都市を次々に焼く作戦の対象の一つになったことが理由とされています。","この空襲の少し前の7月20日、長岡には原子爆弾の投下訓練のためとされる模擬爆弾が落とされ、死者も出ていました。のちに、その事実が研究によって明らかになり、改めて平和について考えるきっかけになっています。","戦後、長岡の人々は焼け跡から町を立て直しました。1946年8月1日には «戦災復興祭» が開かれ、翌年から花火も打ち上げられるようになります。これが今の «長岡まつり大花火大会» のはじまりです。8月1日の夜10時30分には、空襲の時刻にあわせて慰霊の花火が上がり、町中が祈りに包まれます。長岡戦災資料館では、焼け跡の写真や遺品、体験者の言葉を通して、その夜の出来事を伝えています。"],"tl":[["1945年7月20日","模擬原爆とされる爆弾が長岡に投下される"],["1945年8月1日夜","B29の大編隊による長岡空襲"],["1945年8月15日","終戦"],["1946年8月1日","戦災復興祭が開かれる"],["1947年","復興祭で花火大会が再開される"],["2003年","長岡戦災資料館が開館"]],"who":[["長岡の市民","空襲で被災し、町を復興した"],["空襲で亡くなった人々","1,480人をこえる。多くの子どもやお年寄りも"],["山本五十六","長岡出身の連合艦隊司令長官。長岡空襲とは直接の関係はないが、ふるさととして語られる"]],"deep":["死者数は «1,480人余り» とされ、調査が続けられて数字が見直されてきました。資料館では一人ひとりの名前や写真を集める取り組みが行われています。","投下された焼夷弾は16万発をこえたともいわれますが、数字は資料により異なります。","模擬原爆（通称 «パンプキン»）は長崎型原爆と同じ形・重さの爆弾で、全国各地に投下されました。長岡もその一つで、犠牲者が出ています。","長岡花火の «白菊» は、花火師・嘉瀬誠次が、シベリア抑留で亡くなった戦友への鎮魂として打ち上げたのがはじまりとされます。空襲とは別の祈りが込められています。","長岡市は毎年8月1日に平和祈念式典を行い、空襲の時刻には市内でサイレンが鳴らされるなど、記憶を受けつぐ取り組みを続けています。"],"look":["長岡戦災資料館の写真・遺品・体験記の展示","亡くなった方の遺影を集めた展示","平潟神社の慰霊の碑","8月1日夜の慰霊の花火（白一色の «白菊» など）"],"q":["長岡空襲があったのは何月何日？","1945年8月1日の夜です。いまはこの日に慰霊の花火が上がります。"],"koji":[],"myth":"死者数・焼夷弾の数は調査により変動。","img":["長岡まつり大花火大会","模擬原子爆弾"],"wp":"長岡空襲","rel":{"ev":[],"grave":[]},"ph":[["c:4/43/Air_raid-Nagaoka.jpg",918,643,"長岡空襲"],["c:1/12/Find47_Niigata-The_Nagaoka_Fireworks_Festival-m2.jpg",1920,1080,"長岡まつり大花火大会"]]},{"id":"15_bandaibashi","n":"萬代橋（三代目・国重文）","yomi":"ばんだいばし","cat":"近代","rank":"A","y":1929,"era":["meiji","showa"],"sh":"国の重要文化財","ad":"新潟市中央区万代〜川端町","st":"JR新潟駅から歩いて約15分","la":37.9166,"lo":139.054,"hook":"新潟地震で周りの橋がくずれ落ちても、この石張りの6つのアーチは立ち続けた。新潟の人が «ばんだいさん» と呼ぶ町のシンボル。","lead":"萬代橋は、信濃川にかかる新潟市のシンボルの橋です。今の橋は1929年に完成した3代目で、6つのアーチが連なる鉄筋コンクリートの橋に御影石がはられています。2004年、道路の橋として現役のまま国の重要文化財に指定されました。","story":["明治のはじめ、新潟の町は信濃川によって二つに分けられていました。港のある新潟町と、対岸の沼垂。行き来は渡し船だけで、雨や雪の日にはとても不便でした。«橋があれば、町は一つになれるのに» ——人々のそんな願いから、1886年、はじめての萬代橋がかけられます。","初代の橋は木でできていて、長さはなんと約780m。当時の信濃川は今よりずっと川幅が広かったのです。しかし1908年、新潟の大火で橋は焼けてしまいます。翌年には2代目の木の橋がかけられましたが、木の橋は傷みやすく、車の時代には向きませんでした。","そこで昭和のはじめ、じょうぶな鉄筋コンクリートの橋に造りかえることになりました。川の両岸を埋め立てて川幅をせばめ、1929年に3代目の萬代橋が完成します。長さは約307m、6つのアーチが優雅に連なり、表面は御影石でおおわれました。«なんて立派な橋だ!» と、新潟の人々は大喜びしたといいます。","1964年6月16日、新潟地震が町をおそいました。地面が液状化し、すぐ近くの昭和大橋は橋げたが次々に落ちてしまいます。ところが萬代橋は、一部が傷んだものの落ちることはなく、救援の車や人を通す命の道になりました。","それから半世紀以上、萬代橋は今も毎日たくさんの車と人を運んでいます。2004年には、使われ続けている道路の橋として国の重要文化財に指定されました。夕暮れにライトアップされたアーチが川面に映る姿は、新潟の人々にとって «ふるさとの顔» そのものです。"],"tl":[["1886年","初代萬代橋（木橋・約780m）が完成"],["1908年","新潟大火で初代の橋が焼ける"],["1909年","2代目の木橋が完成"],["1929年","3代目（現在の橋）が完成"],["1964年","新潟地震。萬代橋は落橋をまぬがれる"],["2004年","国の重要文化財に指定"]],"who":[["新潟の市民","橋の建設を願い、地震のあとも橋を守った"],["内務省の技術者たち","3代目の設計・工事にかかわった"],["沼垂と新潟町の人々","橋によって一つの町になった"]],"deep":["3代目の長さは約307m、幅は約22mとされます。初代が約780mもあったのは、明治の信濃川が今よりはるかに広かったためです。","橋の外側に張られた御影石は、コンクリートの橋を重厚に見せる工夫。当時の «都市の顔» としてのデザインが重視されていました。","新潟地震では、完成したばかりの昭和大橋が落橋した一方、萬代橋は取り付け部分などに被害を受けたものの持ちこたえ、耐震の研究でも注目されました。","漢字は «萬代»（まんだい）と書いて «ばんだい» と読みます。周辺の地名 «万代» はこの橋の名前から来ています。","重要文化財の道路橋は全国でもめずらしく、現役で車が通る橋としての価値が評価されました。"],"look":["6つのアーチを川岸から横に眺める（やすらぎ堤から）","御影石張りの欄干と親柱","夜のライトアップ","萬代橋のたもとにある説明板や記念碑","近くのみなとぴあ（新潟市歴史博物館）で新潟の町の歴史も"],"q":["新潟地震のとき、近くで橋げたが落ちてしまった橋はどれ？","«昭和大橋» です。萬代橋は落ちずに持ちこたえました。"],"koji":[],"myth":"","img":["新潟地震","信濃川"],"wp":"萬代橋","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Bandaibashi-Bridge_20130929.JPG",1600,1200,"萬代橋"],["c:7/7a/Find47_Niigata-River_%28Shinano_River%2C_Ojiya_City%29-m.jpg",1920,1280,"信濃川"]]},{"id":"15_kenseikinenkan","n":"新潟県政記念館（旧県会議事堂）","yomi":"にいがたけんせいきねんかん","cat":"近代","rank":"A","y":1883,"era":["meiji"],"sh":"国の重要文化財","ad":"新潟市中央区一番堀通町","st":"JR新潟駅からバスで約15分、«市役所前» 下車、歩いて約3分","la":37.916,"lo":139.0425,"hook":"«みんなで話し合って決める» ——日本で民主主義が芽生えたころの議場が、そのままの姿で残っている。","lead":"新潟県政記念館は、1883年に建てられた新潟県会の議事堂です。明治のはじめにつくられた府県会の議事堂として、今も建っているものでは全国でもっとも古いといわれ、国の重要文化財になっています。中の議場を見学できます。","story":["明治のはじめ、日本はまだ国会もない国でした。けれど1878年、国の法律で府や県ごとに «府県会» をつくることが決まり、選ばれた人々が集まって県のお金の使い方などを話し合うようになります。«みんなで話し合って決める» ——それは日本人にとって、まったく新しい体験でした。","新潟県会のために建てられたのがこの議事堂です。1883年に完成し、設計は新潟県の技術者・星野総四郎が担当しました。西洋の建物をまねながら、日本の大工の技で建てた «擬洋風建築» と呼ばれるスタイルで、正面には塔がそびえています。","中に入ると、2階まで吹き抜けになった議場が広がります。前には議長席、半円形にならぶ議員の席、そして2階には傍聴席。«どうして傍聴席があるの?» ——県民が議論を見守れるようにするためです。当時の新潟は日本でも人口の多い県で、議論もさかんだったといわれます。","この建物は、1932年まで県会議事堂として使われました。その後は県庁の一部などとして使われましたが、古くなって取りこわしの話も出ます。しかし、その価値が見直され、1969年に国の重要文化財に指定。修理のあと、1975年に «新潟県政記念館» として公開されました。","となりには、明治時代に整えられた白山公園と白山神社があります。公園の緑の中に立つ白い議事堂は、明治の人々が «これからの日本» を夢見た時代の空気を、今に伝えています。"],"tl":[["1878年","府県会規則が定められる"],["1883年","新潟県会議事堂が完成"],["1932年","県会議事堂としての役目を終える"],["1969年","国の重要文化財に指定"],["1975年","修理を終え、新潟県政記念館として公開"]],"who":[["星野総四郎","議事堂を設計した新潟県の技術者"],["新潟県会の議員たち","ここで県の予算などを議論した"],["新潟の県民","傍聴席から議論を見守った"]],"deep":["明治初期の府県会議事堂で現存するものとしては、全国最古級とされます。当時の議場のつくりをそのまま残している点が大きな価値です。","擬洋風建築とは、西洋風の見た目を、日本の在来工法や大工の感覚でつくった明治初期の建物のこと。細部に和の技が見られます。","議場は2層吹き抜けで、議長席を中心に議席が弧を描くように配置されています。のちの国会議事堂とは違う、明治初期の «議会の形» がわかります。","国会（帝国議会）が開かれたのは1890年。それより前から、府県会が各地で «話し合いの政治» の練習の場になっていました。","白山公園は明治初期に整えられた公園で、日本で最初期の «都市公園» の一つとされています。","新潟県は明治の中ごろ、全国でもっとも人口の多い県だった時期があります。米どころの豊かさを背景に、県会では治水や道路などをめぐって熱い議論がかわされました。"],"look":["正面の塔屋と白い外観","2層吹き抜けの議場（議長席・議員席・傍聴席）","明治の県会の様子を伝える展示","となりの白山公園と白山神社"],"q":["議場の2階にある席は、だれのための席？","県民が議論を見守るための «傍聴席» です。"],"koji":[],"myth":"«現存最古» は府県会議事堂としての評価。","img":["擬洋風建築","白山公園"],"wp":"新潟県政記念館","rel":{"ev":[],"grave":[]},"ph":[["c:9/93/Niigata_Prefectural_Government_Memorial_Hall1.JPG",1600,1200,"新潟県政記念館"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"]]},{"id":"15_hoppo_bunka","n":"北方文化博物館（豪農伊藤家の館）","yomi":"ほっぽうぶんかはくぶつかん","cat":"町","rank":"A","y":1887,"era":["edo","meiji","showa"],"sh":"国の登録有形文化財（主屋など）","ad":"新潟市江南区沢海","st":"JR新潟駅からバスで約40分、または車で約30分","la":37.8317,"lo":139.1236,"hook":"部屋の数はおよそ65、100畳の大広間。«越後一の大地主» の屋敷は、終戦直後にみずから博物館へと生まれ変わった。","lead":"北方文化博物館は、越後の大地主・伊藤家の屋敷をそのまま生かした博物館です。明治の中ごろに完成した広大な屋敷には、たくさんの部屋と美しい庭があります。戦後、財産を失う危機の中で、伊藤家は屋敷と美術品を博物館として残す道を選びました。","story":["新潟平野は、昔は水びたしの低い土地が多く、農業には苦労の多い場所でした。その中で、江戸時代の中ごろから農業と商いで少しずつ力をつけ、土地を広げていったのが沢海村の伊藤家です。やがて伊藤家は、1,000町歩をこえる田を持つ、越後でも指折りの大地主になりました。","明治の中ごろ、伊藤家は新しい本邸を完成させます。敷地はおよそ8,800坪。大広間は100畳もあり、部屋の数は65ほど。«なぜこんなに大きな家を?» ——たくさんの小作人との行き来や、米の取引、客のもてなしなど、大地主の屋敷は一つの «役所» のような働きをしていたのです。","1945年、戦争が終わると、日本では «農地改革» が始まりました。大地主の土地は、実際に耕している小作人に安く売りわたされることになったのです。伊藤家も、ほとんどの田を手放すことになります。«このままでは、屋敷も美術品もばらばらになってしまう»。","当主の伊藤文吉は、屋敷と集めた美術品を守るため、1946年に財団法人 «北方文化博物館» をつくりました。このとき力になったのが、新潟に駐留していたアメリカ軍の将校で、伊藤家の文化財の価値を理解し、博物館化を後押ししたと伝わります。","今、屋敷をめぐると、ぴかぴかにみがかれた縁側、100畳の大広間、池を回遊する庭園、三角形の茶室 «三楽亭» などが次々に現れます。越後平野の米がつくった豊かさと、それを未来へ残そうとした人々の決断が、ここに詰まっています。"],"tl":[["江戸時代中期","伊藤家が沢海村で農業と商いにより台頭"],["明治時代","大地主として1,000町歩をこえる田を持つ"],["1880年代","現在の本邸が完成（明治中期）"],["1946年","財団法人北方文化博物館を設立"],["農地改革期","伊藤家の農地の多くが小作人へ"],["2000年代","主屋などが国の登録有形文化財に"]],"who":[["伊藤文吉（歴代）","伊藤家の当主は代々 «文吉» を名のった"],["博物館を設立した伊藤文吉","戦後、屋敷を博物館として残す決断をした当主"],["アメリカ軍の将校","博物館設立を後押ししたと伝わる"],["小作人たち","伊藤家の田を耕した人々"]],"deep":["«町歩» は田畑の広さの単位で、1町歩は約1ヘクタール。1,000町歩は東京ドーム200個分以上の広さにあたります（数字は時期により変わる）。","農地改革（1946〜50年ごろ）で、日本の大地主の多くは土地を失いました。伊藤家が博物館をつくったのはその直前・直後の決断でした。","博物館の設立を後押ししたアメリカ軍の将校については、伊藤家との友情の話として館で紹介されていますが、細部は伝承的に語られる部分もあります。","敷地内の «三楽亭» は、三角形を基本にした珍しい茶室で、柱や畳、窓まで三角が使われているといわれます。","新発田市の清水園も、戦後に伊藤家（北方文化博物館）が引き受けて保存しており、「北方文化博物館新発田分館」として公開されています。"],"look":["100畳の大広間","回遊式の庭園と池","三角形の茶室 «三楽亭»","集古館の美術品・考古資料","豪農の暮らしがわかる台所や土蔵"],"q":["戦後、大地主の土地を小作人に売りわたした改革を何という？","«農地改革» です。伊藤家もこのとき多くの田を失いました。"],"koji":[],"myth":"アメリカ軍将校とのエピソードの細部、田の広さの数字は伝承・資料により差がある。","img":["農地改革","豪農"],"wp":"北方文化博物館","rel":{"ev":[],"grave":[]},"ph":[["c:b/ba/Northern_Culture_Museum_002.jpg",980,693,"北方文化博物館"]]},{"id":"15_shimizuen","n":"清水園（新発田藩下屋敷）","yomi":"しみずえん","cat":"大名屋敷","rank":"A","y":1693,"era":["edo"],"sh":"国の名勝","ad":"新発田市大栄町","st":"JR新発田駅から歩いて約7分","la":37.948,"lo":139.3235,"hook":"池のまわりをめぐるたび、景色が変わる。越後の大名・溝口家が、江戸の庭師を呼んで仕上げた «近江八景» の庭。","lead":"清水園は、新発田藩主の溝口家が別邸として使った下屋敷の庭園です。江戸時代前期に屋敷がつくられ、幕府の茶道方だった県宗知が庭をととのえたと伝わります。池を中心に歩いて回る回遊式の庭で、国の名勝に指定されています。","story":["1598年、豊臣秀吉の命令で、溝口秀勝が加賀から越後の新発田にやってきました。当時の新発田は、川がまがりくねる湿地だらけの土地。溝口家は城を築き、町をつくり、田をひらいて、少しずつ豊かな藩へと育てていきました。溝口家は、江戸時代の終わりまで一度も国替えされずに新発田をおさめ続けます。","江戸時代前期、藩主は城の近くに «下屋敷» をつくりました。下屋敷は、藩主がくつろいだり、客をもてなしたりするための別荘のような場所です。«清水谷御殿» と呼ばれたこの屋敷の庭は、江戸から招かれた幕府の茶道方・県宗知が手を入れ、元禄時代に今の姿の基礎ができたと伝わります。","庭の中心は、«水» の字をかたどったともいわれる大きな池。そのまわりを歩くと、橋、石、築山、茶室が、角を曲がるたびに新しい景色として現れます。琵琶湖のほとりの名所 «近江八景» になぞらえたといわれ、«次はどんな景色が?» と歩く人を楽しませるしかけになっています。","明治になると屋敷は溝口家の手を離れ、やがて戦後、新潟の大地主・伊藤家（北方文化博物館）が引き受けて保存することになりました。こうして大名の庭は失われずにすみ、今は博物館の新発田分館として公開されています。","すぐ近くには、江戸時代の足軽たちが住んだ長屋も残っています。殿さまの優雅な庭と、下級武士の質素な住まい。その両方を見くらべると、同じ藩の中にあった暮らしの違いがよくわかります。"],"tl":[["1598年","溝口秀勝が新発田に入る"],["1660年代","下屋敷（清水谷御殿）がつくられる（時期は諸説）"],["1693年ごろ","県宗知が庭をととのえたと伝わる"],["1842年","近くに足軽長屋が建てられる"],["1946年","伊藤家（北方文化博物館）が引き受ける"],["2003年","清水園が国の名勝に指定"]],"who":[["溝口秀勝","新発田藩の初代藩主"],["県宗知","庭をととのえたと伝わる幕府の茶道方"],["溝口家の歴代藩主","下屋敷を別邸として使った"],["堀部安兵衛","新発田出身の赤穂浪士。新発田の町の誇り"]],"deep":["溝口家は新発田に入ってから明治維新まで約270年、国替えなしで同じ土地をおさめた、全国でもめずらしい大名家です。","庭を手がけたとされる県宗知は、茶道の石州流の流れをくむ人物とされます。茶の湯の感覚が、庭の視点の変化にいかされています。","«近江八景» になぞらえた庭は各地にありますが、清水園では池と石組で琵琶湖の名所を表したといわれ、どこが何にあたるかを探すのも楽しみです。","近くの «足軽長屋» は1842年に建てられた、足軽の住まいとして全国でも貴重な建物で、国の重要文化財になっています。","新発田は赤穂浪士・堀部安兵衛の出身地とされ、城下には安兵衛の碑などゆかりの場所があります。"],"look":["池を一周する回遊路と、景色の変化","書院から眺める庭","茶室と露地","近くの足軽長屋（国の重要文化財）","新発田城の表門・隅櫓もあわせて"],"q":["清水園の庭は、どこの名所の景色になぞらえたといわれる？","琵琶湖のほとりの名所 «近江八景» です。"],"koji":[],"myth":"作庭の年や «水» の字をかたどった池の話は伝承的。","img":["新発田藩","溝口秀勝","新発田城"],"wp":"清水園","rel":{"ev":[],"grave":[]},"ph":[["c:6/60/160716_Shimizuen_Shibata_Niigata_pref_Japan29s3.jpg",6000,4000,"清水園"],["c:1/14/Hidekatsu_Mizoguchi.png",120,116,"溝口秀勝"],["c:e/eb/Shibata_Castle_001_May2020.jpg",2364,1773,"新発田城"]]},{"id":"15_kanayayama","n":"金谷山（レルヒ少佐・日本スキー発祥）","yomi":"かなやさん","cat":"近代","rank":"A","y":1911,"era":["meiji"],"sh":"","ad":"上越市大貫","st":"えちごトキめき鉄道 高田駅から車で約10分","la":37.087,"lo":138.243,"hook":"1911年の冬、オーストリアの軍人が1本の杖で雪山をすべり降りた。日本人がはじめて «スキー» を本格的に習った場所。","lead":"金谷山は、上越市高田の町の南にある小高い山です。1911年、オーストリア＝ハンガリーの軍人レルヒ少佐が、ここで高田の陸軍の人たちにスキーを教えました。これが日本で本格的にスキーが広まるきっかけとなり、金谷山は «日本スキー発祥の地» と呼ばれています。","story":["明治の終わり、日本の陸軍は雪の中での戦いに備える方法を探していました。1902年、青森の八甲田山で雪中行軍中の部隊が遭難し、多くの兵士が亡くなるという悲しい事件も起きていたのです。«雪の上を自由に動ける道具はないか?» ——そこで注目されたのがスキーでした。","1910年、オーストリア＝ハンガリー帝国の軍人テオドール・フォン・レルヒ少佐が、日本の軍隊の研究のために来日します。レルヒは、アルペンスキーの名人から学んだスキーの達人でした。彼がやって来たのが、雪の多い高田に置かれた陸軍の第13師団でした。","1911年1月12日、金谷山でスキーの講習が始まりました。レルヒが使ったのは、長い1本の杖でバランスをとる «一本杖スキー»。はじめて見る日本の将校たちは、雪の斜面をすいすいとすべり降りる姿にびっくりしたといいます。やがて将校たちから町の人々へ、スキーは急速に広まっていきました。","高田の師団長・長岡外史は、スキーを熱心にすすめた人物でした。軍の中だけでなく、学校や町の人々にもスキーを広め、スキー大会が開かれるようになります。レルヒは翌年には北海道でも指導し、スキーは全国の雪国へ広がっていきました。","今、金谷山には «大日本スキー発祥之地» の碑や、1本杖を持ったレルヒの像が立ち、日本スキー発祥記念館もあります。毎年1月12日は «スキーの日»。雪の斜面を見上げると、100年あまり前、この場所から日本のスキーの歴史が始まったことが実感できます。"],"tl":[["1902年","八甲田雪中行軍遭難事件"],["1910年","レルヒ少佐が来日し、高田の第13師団へ"],["1911年1月12日","金谷山でスキー講習が始まる"],["1912年","レルヒが北海道でもスキーを指導"],["昭和初期","金谷山に «大日本スキー発祥之地» の碑が建つ"],["現在","1月12日は «スキーの日» とされる"]],"who":[["テオドール・フォン・レルヒ","オーストリア＝ハンガリーの軍人。日本に本格的なスキーを伝えた"],["長岡外史","第13師団長。スキーの普及に力をつくした"],["第13師団の将校たち","最初の講習を受けた"]],"deep":["日本でスキーの道具が紹介されたのはレルヒ以前ともいわれますが、組織的な指導が始まり広く普及したのは1911年の金谷山がはじまりとされます。","レルヒの «一本杖スキー» は、アルペンスキーの先駆者マティアス・ツダルスキーが考えた技術の流れをくむといわれます。今の2本ストックとは違う滑り方です。","金谷山にはレルヒの像があり、軍服姿で一本杖を持つ姿で表されています。レルヒが残したスケッチなども記念館で紹介されています。","長岡外史はのちに飛行機の研究にも関わるなど、新しい技術を積極的に取り入れた軍人として知られます。","上越市では、レルヒにちなんだイベントや «レルヒさん» というキャラクターも生まれ、スキー発祥の地として町ぐるみで発信しています。"],"look":["«大日本スキー発祥之地» の碑","一本杖を持つレルヒ少佐の像","日本スキー発祥記念館","金谷山の斜面（冬はスキー・そり遊びも）","高田の町並みと高田城跡"],"q":["レルヒ少佐が日本で教えたスキーは、杖を何本使う滑り方？","1本です。«一本杖スキー» と呼ばれます。"],"koji":[],"myth":"日本最初のスキーについては、レルヒ以前の紹介例もあり諸説。碑の建立年などは資料で確認を。","img":["テオドール・フォン・レルヒ","長岡外史","高田城"],"wp":"金谷山","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Mountain_Ski_Kanaya_01.jpg",4288,3216,"金谷山"],["c:9/97/Theodor_Edler_von_Lerch.jpg",300,438,"テオドール・フォン・レルヒ"],["c:7/79/Lieutenant_General_Gaishi_Nagaoka.jpg",950,1214,"長岡外史"],["c:6/69/Takada_Castle_yagura.JPG",3763,2504,"高田城"]]},{"id":"15_niitsu_yuden","n":"新津油田と石油の世界館","yomi":"にいつゆでんとせきゆのせかいかん","cat":"産業","rank":"A","y":1917,"era":["meiji","taisho"],"sh":"国指定史跡（新津油田金津鉱場跡）","ad":"新潟市秋葉区金津","st":"JR新津駅からバスまたは車で約15分","la":37.769,"lo":139.108,"hook":"«燃える水» がわき出す村から、日本一の油田へ。森の中に、木の櫓と手掘りの井戸が今も残っている。","lead":"新潟県は、日本で古くから石油がとれた土地です。中でも秋葉区の新津油田は、大正時代に日本一の産油量をほこった時期がありました。金津地区の «石油の世界館» と周辺の鉱場跡では、手掘りの井戸や当時の道具を見ることができます。","story":["新潟の人々は、昔から地面からしみ出す黒くて臭い油を知っていました。«臭い水» という意味で «くそうず» と呼び、明かりに使うこともあったといいます。『日本書紀』には、668年に越の国から天智天皇へ «燃える土と燃える水» が献上されたという記事があり、日本の石油の歴史の始まりとして有名です。","明治時代、ランプの明かりが広まると、石油の値打ちはぐんと上がりました。金津村では人々が競うように井戸を掘りはじめます。はじめは人の手で、深さ何十メートルもの穴を掘りました。«穴の底でガスを吸ったら命が危ない» ——そんな危険と隣り合わせの仕事でした。","この地で大きな成功をおさめたのが、金津出身の中野貫一です。中野は粘り強く井戸を掘り続け、やがて油田を大きく育てて «石油王» と呼ばれるようになりました。やがて機械で掘る方法が導入され、新津油田の産油量は大正時代に日本一になったといわれます。","しかし、新津の石油は限られた量しかありませんでした。やがて産出は減り、昭和の終わりごろには、ほとんどの井戸が役目を終えます。1990年代に採掘は完全に終わりました。","けれど金津の森には、木で組んだ櫓（やぐら）や、手掘りの井戸、石油を運んだ設備の跡が残されました。2018年、これらは «新津油田金津鉱場跡» として国の史跡に指定されます。石油の世界館で、実際の石油のにおいや、掘削の道具にふれてみると、明治の人々の «燃える水» への情熱が伝わってきます。"],"tl":[["668年","越の国から燃える土・燃える水が献上される（『日本書紀』）"],["明治時代初め","金津で石油の採掘が本格化"],["明治〜大正","機械掘りが導入され、生産が増える"],["大正時代","新津油田が日本一の産油量となった時期がある"],["1990年代","新津油田での採掘が終わる"],["2018年","新津油田金津鉱場跡が国の史跡に指定"]],"who":[["中野貫一","金津出身の実業家。«石油王» と呼ばれた"],["天智天皇","燃える水の献上を受けたと『日本書紀』にある"],["油井で働いた人々","危険な手掘りや機械掘りの作業を担った"]],"deep":["«燃える水» を献上した場所がどこかは史料に書かれておらず、新潟県内でも胎内市（旧黒川村）などが名乗りをあげています。どこが最初かは諸説あります。","手掘り井戸は、人が中に入って掘り進める方法で、送風機で空気を送りながら作業しました。ガスや酸欠による事故もあったとされます。","中野家の屋敷は «中野邸記念館» として公開され、秋の紅葉の名所としても知られます。石油で得た富がどう使われたかがわかります。","日本の石油の産地は、新潟県と秋田県が二大産地でした。新潟では出雲崎・長岡の東山油田なども知られます。","国の史跡 «新津油田金津鉱場跡» には、明治から昭和までの採掘施設が面としてまとまって残り、石油産業の移り変わりを一つの場所でたどれる点が評価されました。"],"look":["石油の世界館の展示（石油のにおいや掘削の道具）","森の中に残る木の櫓と手掘りの井戸跡","石油を送ったパイプや施設の跡","近くの中野邸記念館と庭園"],"q":["昔の新潟で、地面からしみ出る石油は何と呼ばれていた？","«くそうず»（臭い水）です。"],"koji":[],"myth":"«燃える水» の献上地は諸説。«日本一» の時期や産出量の数字は資料により異なる。","img":["中野貫一","石油"],"wp":"新津油田","rel":{"ev":[],"grave":[]},"ph":[["c:0/02/Niitsu_Oil_field_in_1930s.JPG",497,284,"新津油田"],["c:1/17/Kanichi_Nakano.jpg",360,478,"中野貫一"],["c:a/ae/Petroleum_cm05.jpg",461,563,"石油"]]},{"id":"15_echigo_kokubunji","n":"越後国分寺（五智国分寺）","yomi":"えちごこくぶんじ（ごちこくぶんじ）","cat":"寺社","rank":"A","y":1562,"era":["nara","kamakura","muromachi"],"sh":"","ad":"上越市五智","st":"えちごトキめき鉄道 直江津駅から車で約5分、歩いて約30分","la":37.1705,"lo":138.23,"hook":"都を追われた親鸞がたどりつき、上杉謙信がよみがえらせたお寺。古代の本当の国分寺はどこにあったのか——いまも謎のまま。","lead":"五智国分寺は、上越市五智にある天台宗のお寺で、越後国分寺の名をつぐお寺です。奈良時代の古代の国分寺がどこにあったかはわかっておらず、今のお寺は戦国時代に上杉謙信が建て直したと伝わります。流罪になった親鸞が暮らした場所とされる «竹之内草庵» もあります。","story":["奈良時代、聖武天皇の命令で越後国にも国分寺が建てられました。けれど不思議なことに、その古代の国分寺がどこにあったのか、今もはっきりわかっていません。«国府の近くにあったはず» と、上越市のあちこちで調査が続けられてきましたが、決め手は見つかっていないのです。","1207年、京都で念仏の教えを広めていた親鸞は、朝廷によって罪人として越後へ流されました。親鸞が上陸したと伝わるのは、近くの居多ヶ浜。そして最初に暮らしたのが、国分寺の境内にあったとされる «竹之内草庵» だといわれます。«なぜ罪人に?» 念仏の教えが古い仏教の人々から強く反発されたからでした。","越後で親鸞は、恵信尼と家庭をもち、土地の人々とともに暮らしながら教えを深めました。やがて許されたあとも、親鸞は関東へ向かい、浄土真宗の教えを広めていきます。越後での数年間は、親鸞にとって «民衆の中で生きる» 大切な時間だったといわれます。","戦国時代、国分寺は荒れていましたが、1562年、春日山城の上杉謙信が建て直したと伝わります。謙信は仏教をあつく信じた武将でした。国分寺の名前の «五智» は、大日如来をはじめとする五つの仏さま «五智如来» をまつることに由来します。","境内には江戸時代末に完成した三重塔があり、そのすらりとした姿が見どころです。本堂は昭和の終わりに火災で失われましたが、その後再建されました。すぐ近くには越後一宮の居多神社もあり、親鸞と謙信、二人の足あとをたどる散策が楽しめます。"],"tl":[["741年","聖武天皇、国分寺建立の詔を出す"],["奈良時代","越後国分寺が建てられる（場所は不明）"],["1207年","親鸞が越後に流され、竹之内草庵に住んだと伝わる"],["1211年","親鸞、流罪を許される"],["1562年","上杉謙信が国分寺を再興したと伝わる"],["江戸時代末","三重塔が完成"],["昭和時代末","本堂が火災で焼失し、のちに再建"]],"who":[["親鸞","浄土真宗の開祖。越後に流された"],["恵信尼","親鸞の妻。越後の出身とされる"],["上杉謙信","戦国時代に国分寺を再興したと伝わる"],["聖武天皇","国分寺建立の詔を出した"]],"deep":["古代越後国分寺の場所は不明です。越後の国府も上越市内のどこかにあったと考えられていますが、確定していません。","親鸞が流されたのは «承元の法難»（1207年）で、師の法然も讃岐（四国）へ流されました。","親鸞の妻・恵信尼は、越後の豪族・三善氏の出身とする説が有力です。恵信尼が晩年に娘に書いた手紙 «恵信尼消息» は、親鸞を知る第一級の史料です。","三重塔は江戸時代末に長い年月をかけて完成したとされ、新潟県の文化財に指定されています。","上越市には、親鸞が上陸したとされる居多ヶ浜、居多神社、親鸞の像など、流罪時代のゆかりの地が集まっています。"],"look":["三重塔","親鸞ゆかりの竹之内草庵","境内の親鸞聖人像","再建された本堂","近くの居多神社と居多ヶ浜"],"q":["国分寺の名前の «五智» は何に由来する？","大日如来など五つの仏さま «五智如来» をまつることに由来します。"],"koji":[],"myth":"古代国分寺の場所は不明。竹之内草庵や謙信再興は寺伝。","img":["親鸞","恵信尼","居多神社"],"wp":"越後国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Gochi-kokubunji_hondou.JPG",5873,3892,"越後国分寺"],["c:a/ad/ShinranShonin.png",371,507,"親鸞"],["c:b/b6/Eshin-ni.jpg",3547,4692,"恵信尼"],["c:f/fb/Kota-jinja_%28Joetsu%29_shaden.JPG",5653,3746,"居多神社"]]},{"id":"15_jonoyama","n":"城の山古墳（日本海側最北の大型円墳）","yomi":"じょうのやまこふん","cat":"遺跡","rank":"A","y":330,"era":["kofun"],"sh":"","ad":"胎内市大塚","st":"JR羽越本線 中条駅から車で約10分","la":38.0615,"lo":139.396,"hook":"ヤマト王権の «北の最前線» か。越後平野の北のはしで、1,600年前の木の棺から鏡と弓矢が見つかった。","lead":"城の山古墳は、胎内市にある古墳時代前期（4世紀前半ごろ）の円墳です。直径は40mほど。日本海側で見つかった大型の前期古墳としては、もっとも北にあるものとされます。発掘で木の棺の中から鏡や玉、弓矢の入れ物などが見つかり、全国の注目を集めました。","story":["新潟平野の北のはし、なだらかな砂丘の上に、こんもりとした丘があります。地元では昔から «城の山» と呼ばれてきましたが、その正体はお城ではなく、古墳でした。«こんな北の地に、本格的な古墳が?» ——それが研究者たちをおどろかせたのです。","4世紀ごろ、奈良盆地を中心としたヤマト王権は、各地の有力者とつながりを広げていました。古墳をつくることは、その仲間に入った証のようなものだったと考えられています。城の山古墳は、その広がりが日本海側のどこまで届いていたかを示す、大切な手がかりです。","2000年代から始まった発掘調査で、墳丘の中心から木の棺の跡が見つかりました。棺の中には、銅の鏡、勾玉や管玉などの玉、そして矢を入れる «靫（ゆき）» や、漆を塗った弓などがおさめられていました。«弓矢と鏡を持つ人» ——それは、戦いと祈りの両方をになう地域のリーダーの姿だったのかもしれません。","この古墳にほうむられた人の名前は、わかっていません。けれど、はるか遠い近畿地方と同じような品々を持っていたことから、ヤマト王権と深いつながりをもった人物だったと考えられています。当時、この地は «北の境目» に近い場所でした。","今の城の山古墳は、ふつうの丘のように見えるかもしれません。けれど、ここから北へは、同じ時期の大きな古墳はほとんど見つかっていないのです。丘の上に立って北を見わたすと、1,600年前の人々が見ていた «王権の世界の果て» を想像できます。"],"tl":[["4世紀前半ごろ","城の山古墳がつくられる（推定）"],["昭和時代","地元で «城の山» と呼ばれ、古墳と考えられる"],["2005年ごろ","胎内市による発掘調査が始まる"],["2012年ごろ","木棺の中から鏡・玉・靫・弓などが見つかる"],["現在","出土品の研究と公開が進む"]],"who":[["城の山古墳の被葬者","名前は不明。ヤマト王権とつながった地域の有力者と考えられる"],["胎内市の調査団","長年にわたり発掘を続けた"],["ヤマト王権","古墳文化を各地に広げた勢力"]],"deep":["墳丘は正円ではなく少し楕円形で、長いほうの径が約41mとされます。前方後円墳ではなく円墳と考えられています。","出土した鏡は中国風の文様をもつ鏡とされ、近畿地方の古墳との関係を考える手がかりになっています。","«靫» は矢を入れて背負う入れ物。漆塗りのものが良い状態で見つかった例はめずらしく、古墳時代の武具研究でも注目されました。","年代は出土品から4世紀前半ごろと考えられており、日本海側の前期古墳の北限を示すものとして重要です。","新潟県内では、ほかに古津八幡山古墳（新潟市）や菖蒲塚古墳（新潟市）などの前期古墳が知られ、越後平野の古墳文化の広がりを比べる研究が進んでいます。"],"look":["墳丘の形（なだらかな丘に見える）","説明板と出土品の写真","胎内市の資料館などでの出土品の展示（公開時期は要確認）","周辺の砂丘地形"],"q":["城の山古墳で見つかった «靫» とは何？","矢を入れて背負う入れ物です。"],"koji":[],"myth":"被葬者は不明。鏡の種類や年代は研究途中で、見解が変わる可能性がある。","img":["古墳時代","円墳","ヤマト王権"],"wp":"城の山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/J%C5%8Dnoyama_Tomb%2C_Tainai%2C_Niigata%2C_Japan%2C_March_2021.jpg",4032,3024,"城の山古墳"],["c:3/37/Hachimanyama_kofun-Aichi02.jpg",712,440,"円墳"],["c:1/19/Mount_Miwa.jpg",6004,4008,"ヤマト王権"]]},{"id":"15_furutsu","n":"古津八幡山遺跡（弥生の高地性集落と古墳）","yomi":"ふるつはちまんやまいせき","cat":"遺跡","rank":"A","y":150,"era":["yayoi","kofun"],"sh":"国指定史跡","ad":"新潟市秋葉区蒲ヶ沢・古津","st":"JR新津駅から車で約10分","la":37.776,"lo":139.096,"hook":"«なぜ、わざわざ山の上に村をつくったのか?» 堀で囲まれた丘の上のムラは、弥生の人々の不安を語る。","lead":"古津八幡山遺跡は、新潟市秋葉区の丘の上にある、弥生時代後期の «高地性環濠集落» の遺跡です。まわりを堀で囲んだ村のあとで、同じ丘には新潟県で最大級の円墳・古津八幡山古墳もあります。国の史跡に指定され、竪穴住居などが復元されています。","story":["弥生時代、人々は米づくりのために、ふつうは川の近くの低い土地にムラをつくりました。ところが古津八幡山遺跡のムラは、見晴らしのよい丘の上にあります。水をくむのも田んぼへ行くのも大変なはずなのに、«なぜわざわざ高い所へ?» ——そこに、この遺跡のなぞがあります。","ムラのまわりには、深い堀（環濠）がめぐらされていました。これは敵の攻撃から身を守るためと考えられています。弥生時代の後期（2世紀ごろ）は、中国の歴史書に «倭国大いに乱れる» と書かれた時代。遠く越後の地でも、争いへの不安があったのかもしれません。","このムラからは、北陸地方の土器と、東北地方の特徴をもつ土器の両方が見つかっています。«ここは、西と北の文化がまじり合う場所だったのでは?» と研究者たちは考えています。信濃川と阿賀野川の流れる平野を見下ろすこの丘は、人や物が行き交う交差点でもあったのです。","やがて弥生時代が終わり、古墳時代になると、同じ丘の上に大きな円墳がつくられました。これが古津八幡山古墳で、直径約60mと、新潟県内で最大級の円墳です。かつてムラがあった場所に、地域の王の墓が築かれたことになります。","今、遺跡は «古津八幡山 弥生の丘» として整備され、竪穴住居が復元されています。丘の上から越後平野を見わたすと、1,800年ほど前、ここで暮らした人々が、遠くを見張りながら日々を送っていた姿が目に浮かぶようです。"],"tl":[["2世紀ごろ","丘の上に環濠をめぐらせた集落がいとなまれる（弥生時代後期）"],["4世紀後半ごろ","同じ丘に古津八幡山古墳がつくられる（推定）"],["1990年代","発掘調査で環濠集落の姿が明らかに"],["2005年","国の史跡に指定"],["2010年代","«古津八幡山 弥生の丘» として公開"]],"who":[["弥生のムラの人々","丘の上に堀をめぐらせて暮らした"],["古津八幡山古墳の被葬者","名前は不明。越後平野の有力者と考えられる"],["新潟市の調査団","発掘と整備を進めた"]],"deep":["高地性集落は、瀬戸内海沿岸など西日本に多く見られます。日本海側の北のほうでこれだけはっきりした例は貴重とされます。","出土した土器には、北陸系のものと、東北南部の «天王山式» と呼ばれる系統のものが混ざっており、文化の境目を考えるうえで重要です。","古津八幡山古墳は直径約60mとされ、新潟県内の円墳では最大級。年代は4世紀後半ごろと考えられています。","環濠の規模や、集落がどれくらいの期間続いたかは調査で少しずつ明らかになってきましたが、なぜ短い期間で消えたのかなど、まだなぞも残ります。","展示館では出土品のほか、弥生時代の暮らしを体験できる催しが行われることもあります。"],"look":["復元された竪穴住居","環濠（堀）のあとをしめす表示","丘の上の古津八幡山古墳","展示館の土器や石器","丘から見わたす越後平野"],"q":["ムラのまわりにめぐらせた堀のことを何という？","«環濠» です。敵から身を守るためと考えられています。"],"koji":[{"w":"倭国大いに乱る","m":"中国の歴史書に記された、2世紀後半ごろの倭（日本）の争いの時代をさす言葉"}],"myth":"高地に集落をつくった理由は、争いへの備え以外にも諸説がある。","img":["高地性集落","環濠集落","弥生時代"],"wp":"古津八幡山遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/23/NiigataCityOpenData_rekishinohiroba02.jpg",5184,3456,"古津八幡山遺跡"],["c:6/68/Egenoyamaiseki1.jpg",3264,2448,"高地性集落"],["c:7/76/%E5%90%89%E9%87%8E%E3%83%B6%E9%87%8C%E9%81%BA%E8%B7%A1%E7%92%B0%E6%BF%A0.JPG",3456,2304,"環濠集落"]]},{"id":"15_yoita_jo","n":"与板城（直江氏の本拠）","yomi":"よいたじょう","cat":"城","rank":"A","y":1581,"era":["muromachi","azuchi"],"sh":"","ad":"長岡市与板町与板","st":"JR長岡駅からバスで約30分、与板で下車して登山口まで歩く（車が便利）","la":37.552,"lo":138.809,"hook":"兜に «愛» の字をかかげた武将・直江兼続。その妻お船とともに暮らした、信濃川を見下ろす山城。","lead":"与板城は、上杉家の重臣・直江氏がおさめた山城です。直江兼続は、この直江家に婿として入り、与板を本拠に上杉景勝を支えました。建物は残っていませんが、山の上には曲輪（平らにならした場所）や堀切などの跡があり、城の姿をしのぶことができます。","story":["戦国時代、越後の上杉家を支えた家臣の中に、直江家がありました。直江景綱は上杉謙信の信頼があつく、与板を本拠地として重要な役目をはたしていました。与板は信濃川の水運に近く、春日山城と越後の北や中央を結ぶ、大切な場所だったのです。","謙信が亡くなったあと、跡目をめぐる «御館の乱» が起こり、上杉景勝が勝ちました。その混乱の余波の中、1581年、直江家を継いでいた直江信綱が、春日山城内で起きた争いにまきこまれて殺されてしまいます。«直江の家はどうなる?» ——そこで景勝が選んだのが、自分の側近の樋口兼続でした。","兼続は、信綱の妻だったお船と結婚して直江家を継ぎ、«直江兼続» となります。与板城は兼続とお船の本拠となりました。兼続は頭がよく、景勝の片腕として政治も戦も取りしきり、豊臣秀吉にもその才能をみとめられたといわれます。","兼続の兜には、大きな «愛» の文字がかかげられていました。«愛» は、愛宕権現や愛染明王など、戦いの神仏を表すという説が有力です。現在、その兜は山形県米沢市の上杉神社に伝わっています。","1598年、上杉家は会津へ移ることになり、兼続も与板を離れました。城はやがて使われなくなります。今、与板城の山に登ると、曲輪や堀切の跡が木々の間に残り、ふもとの与板の町には、兼続とお船を紹介する資料館があります。2009年の大河ドラマ『天地人』で、与板は一躍注目を集めました。"],"tl":[["戦国時代","直江氏が与板を本拠とする"],["1578年","上杉謙信が亡くなり、御館の乱が起こる"],["1581年","直江信綱が殺され、兼続がお船と結婚して直江家を継ぐ"],["1598年","上杉家の会津移封にともない、兼続も与板を離れる"],["1619年","直江兼続が亡くなる"],["2009年","大河ドラマ『天地人』で注目される"]],"who":[["直江兼続","上杉景勝の重臣。与板城を本拠とした"],["お船","直江景綱の娘。兼続の妻"],["直江景綱","謙信に仕えた直江家の当主"],["上杉景勝","謙信の後継者。兼続の主君"],["直江信綱","お船の前夫。1581年に殺された"]],"deep":["直江氏の城は、古い «本与板城» と、のちの «与板城» の二つがあり、本拠を移したと考えられています。いつ移したかには諸説あります。","直江信綱が殺された事件は、恩賞をめぐる争いから起きたとされ、斬りつけた人物の名も伝わりますが、細部は史料によって違いがあります。","«愛» の兜の意味は、愛宕権現・愛染明王説が有力で、«人を愛する» という意味とする解釈は近代以降の見方ともいわれます。","兼続が送ったとされる «直江状» は、徳川家康を痛烈に批判した手紙として有名ですが、原本は残っておらず、内容の信ぴょう性には議論があります。","与板城は山城で、山頂の本丸から信濃川流域がよく見わたせます。この見晴らしが、城を置いた大きな理由と考えられます。"],"look":["山頂の本丸跡と、信濃川を望む眺め","曲輪・堀切などの遺構","ふもとの与板の町並み","兼続とお船を紹介する資料館（兼続お船ミュージアム）"],"q":["直江兼続の兜にかかげられた一文字は？","«愛» です。愛宕権現や愛染明王を表すという説が有力です。"],"koji":[],"myth":"«愛» の意味、直江状の真偽、本拠移転の時期は諸説。","img":["直江兼続","お船の方","御館の乱"],"wp":"与板城","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/Naoe_Kanetsugu02.jpg",800,1159,"直江兼続"]]},{"id":"15_same_ga_o","n":"鮫ヶ尾城（上杉景虎自刃の地）","yomi":"さめがおじょう","cat":"城","rank":"A","y":1579,"era":["muromachi"],"sh":"国指定史跡","ad":"妙高市宮内・雪森","st":"えちごトキめき鉄道 北新井駅から歩いて約30分で登山口（車が便利）","la":36.9985,"lo":138.222,"hook":"謙信の養子として迎えられ、謙信の後継ぎを争い、敗れて逃げた先で裏切られた。北条から来た若き貴公子の最期の城。","lead":"鮫ヶ尾城は、妙高市の山の上にあった戦国時代の山城です。上杉謙信の死後に起きた跡継ぎ争い «御館の乱» で敗れた上杉景虎が、実家の北条氏をたよって逃げる途中、この城で裏切りにあい、自ら命を絶ちました。山の上には曲輪や堀の跡が残り、国の史跡になっています。","story":["上杉景虎は、関東の大名・北条氏康の子として生まれました。上杉と北条が同盟を結んだとき、人質として越後にやってきます。上杉謙信は景虎をたいへん気に入り、自分の若いころの名 «景虎» をあたえて養子にしました。謙信のめいを妻にむかえ、子どもも生まれます。","1578年、謙信が急に亡くなります。謙信にはもう一人の養子、上杉景勝がいました。謙信は跡継ぎをはっきり決めていなかったといわれ、二人の間で激しい争いが始まります。これが «御館の乱» です。景虎は春日山城のふもとの «御館» にたてこもり、景勝は春日山城を押さえました。","はじめは実家の北条や、北条と組む武田の助けを期待できた景虎が有利とも見られました。ところが、景勝は武田勝頼と手を結び、景虎は孤立していきます。1579年、御館はついに落ち、景虎は実家のある関東へ逃げようと、鮫ヶ尾城に入りました。","鮫ヶ尾城を守っていたのは、景虎の味方のはずの堀江宗親でした。しかし宗親は景勝方に寝返り、城に火を放ったといわれます。«もはやこれまで» ——追いつめられた景虎は、城の中で自ら命を絶ちました。まだ20代の若さだったと伝わります。","発掘調査では、城の中から焼けた米（炭化米）などが見つかっており、城が燃えた当時の様子を想像させます。山道を登って本丸跡に立つと、景虎がめざした関東の方角がはるかに見わたせます。«もし景虎が勝っていたら、上杉家はどうなっていたか?» ——歴史ファンの間で今も語られる問いです。"],"tl":[["1570年","北条氏康の子・三郎が越後に来て、上杉景虎と名のる"],["1578年3月","上杉謙信が死去。御館の乱が始まる"],["1579年3月","御館が落ちる。景虎は鮫ヶ尾城へ逃れる"],["1579年3月","堀江宗親の寝返りにより、景虎が鮫ヶ尾城で自刃"],["現在","鮫ヶ尾城跡は国の史跡に指定されている"]],"who":[["上杉景虎","北条氏康の子。謙信の養子。鮫ヶ尾城で自刃"],["上杉景勝","謙信のもう一人の養子。御館の乱に勝利"],["堀江宗親","鮫ヶ尾城の城主。景勝方に寝返ったとされる"],["上杉謙信","景虎を養子に迎えた越後の大名"],["武田勝頼","景勝と手を結び、情勢を変えた"]],"deep":["景虎が自刃したのは天正7年（1579）3月24日とされます。年齢は20代半ばとする説が多いですが、生年には諸説があります。","発掘で出土した炭化米は、籠城に備えた米が火事で焼けたものと考えられ、落城の様子を示す物証として注目されました。","御館の乱では、上杉憲政や景虎の幼い子・道満丸も、和議の交渉に向かう途中で殺されたといわれ、乱の悲劇を深めています。","景勝が武田勝頼と結んだ «甲越同盟» では、景勝から勝頼へ金などが送られたとも伝わり、情勢を大きく変えました。","鮫ヶ尾城は、春日山城から関東へ向かう道をおさえる位置にあり、曲輪・堀切・土塁などが山の地形を生かして配置されています。"],"look":["山頂の本丸跡と、関東方面の眺め","尾根に続く曲輪と堀切","説明板と城の縄張り図","ふもとの «斐太歴史の里»（弥生の斐太遺跡もあわせて）"],"q":["上杉謙信の死後、景虎と景勝が跡継ぎをめぐって争った戦いを何という？","«御館の乱» です。景勝が勝ち、景虎は鮫ヶ尾城で自刃しました。"],"koji":[],"myth":"堀江宗親の寝返りの詳しい経緯、景虎の年齢は諸説。","img":["上杉景虎","御館の乱","上杉景勝"],"wp":"鮫ヶ尾城","rel":{"ev":[],"grave":[]},"ph":[["c:0/0a/Samegao_Castle_ruins.jpg",5248,3936,"鮫ヶ尾城"],["c:a/a1/%E4%B8%8A%E6%9D%89%E6%99%AF%E8%99%8E%EF%BC%88%E5%8C%97%E6%9D%A1%E4%B8%89%E9%83%8E%EF%BC%89%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1850,1536,"上杉景虎"],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"]]},{"id":"15_enokitoge","n":"榎峠・朝日山古戦場（北越戦争）","yomi":"えのきとうげ・あさひやまこせんじょう","cat":"古戦場","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"長岡市妙見町〜小千谷市浦柄","st":"JR上越線 越後滝谷駅から車で約10分（朝日山は山道を歩く）","la":37.357,"lo":138.819,"hook":"信濃川ぞいの峠と、それを見下ろす山。話し合いが決裂した8日後、長岡の運命をかけた戦いがここで始まった。","lead":"榎峠と朝日山は、長岡と小千谷の間にある戊辰戦争・北越戦争の古戦場です。1868年5月、長岡藩・会津藩・桑名藩などの同盟軍と新政府軍が、信濃川ぞいの交通の要所をめぐって激しく戦いました。朝日山には、今も当時の陣地の跡が残っているといわれます。","story":["1868年5月2日、長岡藩の河井継之助は小千谷で新政府軍と話し合いましたが、決裂しました。長岡藩は同盟軍に加わることを決め、戦いが始まります。まず争われたのが、三国街道が信濃川ぞいを通る «榎峠» でした。ここを押さえられると、長岡へ一気に攻めこまれてしまうのです。","5月10日、長岡藩と会津藩などの兵が榎峠を攻め、新政府軍から奪い返しました。するとそのすぐ上にそびえる朝日山が、次の焦点になります。«山の上を取った方が勝つ» ——峠を見下ろす朝日山は、戦いの行方を左右する場所でした。","5月13日の朝、深い霧の中で、新政府軍が朝日山をめざして攻め上がりました。山の上で待ち受けていたのは、長岡藩の兵と、桑名藩の «雷神隊» をひきいた若き指揮官・立見鑑三郎（のちの立見尚文）でした。激しい撃ち合いの中、新政府軍の奇兵隊の指揮官・時山直八が撃たれて亡くなり、新政府軍は退きました。","朝日山の戦いは、同盟軍の勝利に終わりました。しかし新政府軍は別の方面から信濃川を渡り、5月19日、長岡城は落ちてしまいます。榎峠と朝日山での勝利は、長岡藩にとってほんのわずかな希望の時間だったのかもしれません。","今、榎峠には古戦場の碑と、両軍の戦死者をとむらう碑が立っています。朝日山に登ると、塹壕や陣地の跡とされる地形が残り、信濃川と越後の山々が見わたせます。敵も味方も、それぞれの信じるもののために命を落とした場所です。静かに手を合わせて歩きたい古戦場です。"],"tl":[["1868年5月2日","小千谷談判が決裂"],["1868年5月10日","同盟軍が榎峠を奪い返す"],["1868年5月13日","朝日山の戦い。時山直八が戦死し、新政府軍が退く"],["1868年5月19日","長岡城が落城"],["1868年7月","長岡藩が長岡城を一時奪い返す"],["1868年9月","戊辰戦争で長岡藩など越後の同盟軍の戦いが終わる"]],"who":[["河井継之助","長岡藩の軍事の指揮をとった家老"],["立見鑑三郎（立見尚文）","桑名藩雷神隊の隊長。のちに明治陸軍の将軍"],["時山直八","長州藩の奇兵隊の指揮官。朝日山で戦死"],["山県有朋","新政府軍の参謀。時山の死を悼んだと伝わる"]],"deep":["榎峠は三国街道が信濃川と山にはさまれてせまくなる地点で、昔から交通の «のど» にあたる場所でした。","朝日山の戦いで活躍した立見鑑三郎は、のちに明治の陸軍で日露戦争に師団長として出陣し、«東洋一の用兵家» と評されたともいわれます。","時山直八の戦死を知った山県有朋は、深く悲しんで歌を詠んだと伝わり、朝日山には時山の碑があるとされます。","朝日山の山頂付近に残る土塁や塹壕状の地形は、戊辰戦争のときの陣地の跡と考えられていますが、細かい位置や用途には検討の余地があります。","榎峠の近くには、戦いで亡くなった人々を敵味方の区別なくとむらう碑があり、地域の人々が長く手入れを続けてきました。"],"look":["榎峠の古戦場碑と慰霊碑","朝日山の陣地跡・塹壕跡とされる地形","朝日山からの信濃川の眺め","小千谷談判の地・慈眼寺もあわせて訪問"],"q":["朝日山の戦いで、新政府軍の奇兵隊を率いて戦死した人物は？","長州藩の時山直八です。"],"koji":[],"myth":"陣地跡の比定や、山県有朋の歌の逸話は伝承を含む。","img":["立見尚文","河井継之助"],"wp":"北越戦争","rel":{"ev":[],"grave":[]},"ph":[["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040,"北越戦争"],["c:5/5b/Naofumi_Tatsumi_army_uniform.jpg",729,972,"立見尚文"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"]]},{"id":"15_hachijuri","n":"八十里越（継之助の退路）","yomi":"はちじゅうりごえ","cat":"街道","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"三条市吉ヶ平（越後側の登山口）","st":"越後側の登山口・吉ヶ平までは車で。JR東三条駅から車で約1時間。峠越えは登山経験者向け","la":37.532,"lo":139.155,"hook":"«八十里 こしぬけ武士の 越す峠»——担架の上で自分をあざ笑った継之助が、最後に越えた山道。","lead":"八十里越は、越後（今の三条市）と会津（今の福島県只見町）を結ぶ山越えの道です。実際の距離は8里ほどなのに、道があまりにけわしいので «10倍の80里に感じる» ことからこの名がついたといわれます。北越戦争に敗れた河井継之助が、重傷を負いながら会津へ落ちのびた道として知られます。","story":["越後と会津の間には、高い山々がつらなっています。その山を越える道の一つが八十里越です。江戸時代には、越後からは塩や魚、会津からは山の産物などが運ばれ、人々の暮らしを支える道でした。けれど道は急な坂と深い谷の連続で、冬は雪にとざされる、きびしい道でした。","1868年7月、北越戦争で長岡城を奪い返した長岡藩でしたが、その戦いで河井継之助は左ひざに銃弾を受けてしまいます。数日後、長岡城はふたたび新政府軍の手に落ちました。長岡藩の人々は、同盟を結ぶ会津をめざして退くことになります。そのとき通ったのが、この八十里越でした。","傷がひどく歩けない継之助は、担架に乗せられて山道を運ばれました。藩士や家族たち、多くの人々が、けわしい峠道を一歩ずつ越えていきます。その途中で継之助は、«八十里 こしぬけ武士の 越す峠» という句を詠んだと伝わります。«腰の抜けた武士が越える峠» ——歩けない自分を、苦くあざ笑った句でした。","峠を越えて会津領に入った継之助は、只見の塩沢村で傷が悪化し、1868年8月、42歳で亡くなりました。継之助が最期に «自分の棺を用意せよ» と命じたという話も伝わります。長岡の人々にとって、八十里越は悲しみの道として記憶されることになりました。","越後側の登山口・吉ヶ平は、かつて集落がありましたが、今は人の住まない場所になっています。昔の道は一部が登山道として残り、峠越えは経験者向けのきびしい山歩きです。«歩いてみたい» と思ったら、十分な準備と情報収集を。長い年月をかけて、この山を越える新しい道路の整備も進められてきました。"],"tl":[["江戸時代","越後と会津を結ぶ物資の道として使われる"],["1868年7月","長岡城の再落城。長岡藩の人々が会津へ退く"],["1868年8月","継之助が担架で八十里越を越える"],["1868年8月16日","継之助、只見の塩沢村で死去"],["昭和時代","吉ヶ平の集落が離村し、無人となる"],["現在","新しい道路（国道289号）の整備が長く続けられている"]],"who":[["河井継之助","長岡藩家老。負傷して八十里越を越えた"],["長岡藩の人々","会津へ落ちのびた藩士と家族"],["八十里越を行き来した人々","塩や山の産物を運んだ"]],"deep":["«八十里» は実際の距離ではなく、けわしさを表した名前。実際は8里（約32km）ほどといわれます。","継之助の句 «八十里 こしぬけ武士の 越す峠» は伝承として広く知られ、只見町の記念館にも関連の展示があります。","継之助が死の前に棺の用意を命じ、それを見届けたという話は、小説『峠』でも印象的に描かれますが、創作を含む部分があります。","八十里越の途中には鞍掛峠や木ノ根峠などの峠があり、道はいくつもの尾根を越えていきます。","三条市側の吉ヶ平は、雪深い山間の集落でしたが、昭和の時代に住民がそろって山を下り、今は «吉ヶ平自然体験の森» として利用されています。"],"look":["越後側の登山口・吉ヶ平（旧集落の跡）","峠道の一部（歩く場合は登山装備で）","福島県只見町の河井継之助記念館（最期の地の近く）","長岡市の河井継之助記念館とあわせて"],"q":["«八十里越» の本当の距離はどれくらい？","8里（約32km）ほどといわれます。けわしくて80里に感じるのが名前の由来です。"],"koji":[],"myth":"句の詠まれた場面、棺の逸話は伝承。距離の数字も目安。","img":["河井継之助","只見町"],"wp":"八十里越","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/OSM_Hachijurigoe.png",460,460,"八十里越"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:6/66/Lake_Tagokura-2.JPG",3072,2304,"只見町"]]},{"id":"15_okuyamasho","n":"奥山荘城館遺跡（中条・三浦和田氏）","yomi":"おくやまのしょうじょうかんいせき","cat":"遺跡","rank":"A","y":1400,"era":["kamakura","muromachi"],"sh":"国指定史跡","ad":"胎内市本郷町（江上館跡）ほか","st":"JR羽越本線 中条駅から江上館跡まで歩いて約20分","la":38.052,"lo":139.413,"hook":"鎌倉の御家人が、はるか越後の北へ。800年前の荘園の «絵図» と館の跡が、中世の武士の暮らしを語る。","lead":"奥山荘は、中世の越後北部に広がっていた荘園（貴族や寺社などの私有地）です。鎌倉時代に三浦一族の和田氏がこの地の地頭となり、その子孫の中条氏などが治めました。館や山城の跡がいくつも残っていて、まとめて国の史跡 «奥山荘城館遺跡» になっています。","story":["平安時代の終わり、越後北部には «城氏» という強い一族がいました。城氏は平家の味方でしたが、源平の争いのあと勢いを失います。1201年、城氏の城長茂が鎌倉幕府に反乱を起こし、越後では一族の女性・板額御前が鳥坂城にたてこもって勇ましく戦ったと伝えられます。","城氏が滅びたあと、奥山荘の地頭になったのが、鎌倉幕府の御家人・和田宗実でした。和田氏は三浦半島の三浦一族の出身で、その子孫はこの地に根をおろし、«三浦和田氏» と呼ばれます。やがて一族は中条氏、黒川氏などに分かれ、それぞれの土地を治めるようになりました。","奥山荘の様子を今に伝える宝物があります。鎌倉時代に描かれた荘園の絵図です。そこには、川、道、田、家、館などが細かく描かれていて、«800年前の地図» として全国でも貴重な史料になっています。«絵図に描かれた場所は今どこ?» ——研究者たちは現地と照らし合わせて調べてきました。","中でも見どころは、中条氏の館とされる «江上館跡» です。15世紀ごろの館で、四角い敷地のまわりを土塁と堀が囲んでいます。発掘調査の結果、門や建物の配置がわかり、門や土塁の一部が復元されました。中世の武士が、戦いに備えつつ、ふだんはどんな暮らしをしていたかがよくわかります。","近くには、中世の資料を展示する «奥山荘歴史館» もあります。鎌倉の御家人が遠い北の地に移り住み、何百年もかけてその土地の領主になっていく——奥山荘は、そんな中世武士の «ふるさとづくり» の物語を今に伝えています。"],"tl":[["平安時代末","越後北部で城氏が勢力をもつ"],["1201年","城長茂が反乱。板額御前が鳥坂城で戦ったと伝わる"],["鎌倉時代初め","和田宗実が奥山荘の地頭となる"],["鎌倉時代","奥山荘の絵図が描かれる"],["15世紀ごろ","中条氏の館・江上館が使われる"],["1984年","奥山荘城館遺跡が国の史跡に指定"]],"who":[["和田宗実","三浦一族。奥山荘の地頭となった"],["中条氏","三浦和田氏の一族。江上館を本拠とした"],["城長茂","城氏の武将。鎌倉幕府に反乱を起こした"],["板額御前","城氏の女性。鳥坂城で戦ったと伝わる"]],"deep":["奥山荘の絵図（波月条絵図など）は、鎌倉時代の荘園の様子を伝える貴重な史料で、中世の村や屋敷の配置を知る手がかりになっています。","板額御前の活躍は『吾妻鏡』に記され、女性ながら弓の名手として描かれています。捕らえられたのち、甲斐の浅利与一の妻になったと伝わります。","三浦和田氏の古文書 «中条家文書» などが残り、荘園の土地がどう分けられ、相続されたかがくわしくわかる点で、全国的にも研究の多い地域です。","江上館跡は、一辺が約60mほどの方形の館とされ、四方を土塁と堀で囲む典型的な中世の «方形館» の姿を示しています。","国の史跡は、江上館跡のほか、鳥坂城跡、坊城館跡など複数の遺跡で構成されています。"],"look":["江上館跡の復元された門と土塁・堀","奥山荘歴史館の展示（絵図の複製など）","鳥坂城跡の山（登る場合は山歩きの準備を）","館の中の建物配置を示す表示"],"q":["奥山荘の地頭となった和田宗実は、どこの一族の出身？","相模国（今の神奈川県）の «三浦一族» です。"],"koji":[],"myth":"板額御前の後日談は伝承的。絵図の年代や描写の比定には諸説。","img":["板額御前","三浦氏"],"wp":"奥山荘","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Hangaku_Gozen_by_Yoshitoshi.jpg",5184,7736,"板額御前"]]},{"id":"15_otoboji","n":"乙宝寺（今昔物語の猿の写経）","yomi":"おっぽうじ","cat":"寺社","rank":"A","y":736,"era":["nara","heian","edo"],"sh":"国の重要文化財（三重塔）","ad":"胎内市乙","st":"JR羽越本線 中条駅から車で約10分","la":38.087,"lo":139.402,"hook":"«お経を書いてください» ——木の皮を持ってきたのは、2匹の猿だった。平安の説話集に登場する、越後の古いお寺。","lead":"乙宝寺は、奈良時代にひらかれたと伝わる真言宗のお寺です。お釈迦さまの左目の舎利（遺骨）をおさめたという伝えがあります。平安時代の『今昔物語集』には、このお寺で猿がお経の写しをたのんだという不思議な話がのっています。境内には江戸時代はじめに建てられた三重塔があり、国の重要文化財です。","story":["乙宝寺は、奈良時代の736年、行基と、インドから来た僧・婆羅門僧正がひらいたと伝わります。聖武天皇の願いによって、お釈迦さまの左目の舎利をおさめたともいわれます。«なぜ越後の北のはしに?» 真相はわかりませんが、それほど古くから人々の信仰を集めてきたお寺だということです。","平安時代の説話集『今昔物語集』には、この «乙寺» の話がのっています。あるとき、法華経を読むお坊さんのもとに、2匹の猿がやってきて、じっとお経を聞いていました。やがて猿たちは、木の皮を持ってきて、«このお経を書き写してください» とお願いするようなしぐさをしたのです。","お坊さんが写経を始めると、猿たちは毎日山の芋や木の実を運んできました。ところがある日、猿たちがぱったり来なくなります。心配して探しに行くと、2匹は山の芋を掘ろうとした穴の中で死んでいました。お坊さんは涙を流し、写経は途中で止まってしまいます。","それから何十年もたって、越後に新しい国司がやってきました。国司はこの寺をたずね、書きかけのお経を完成させたといいます。じつはこの国司夫婦こそ、あの2匹の猿の生まれ変わりだった——というのがお話の結末です。«誠の心は、生まれ変わっても報われる» という教えが込められています。","江戸時代のはじめ、村上藩主が寄進した三重塔が境内に建てられました。杉木立の中にすっと立つ塔は、この地方に残る古い塔として貴重です。1689年には、松尾芭蕉も『おくのほそ道』の旅の途中にこの寺をおとずれたといわれます。猿の話を思いながら境内を歩くと、千年の信仰が静かに息づいているのを感じます。"],"tl":[["736年","行基と婆羅門僧正がひらいたと伝わる"],["平安時代後期","『今昔物語集』に乙寺の猿の写経の話がのる"],["江戸時代初め","村上藩主の寄進により三重塔が建てられる"],["1689年","松尾芭蕉が参詣したと伝わる"],["現在","三重塔は国の重要文化財"]],"who":[["行基","奈良時代の僧。乙宝寺をひらいたと伝わる"],["婆羅門僧正（菩提僊那）","インド出身の僧。東大寺大仏の開眼を行った"],["2匹の猿","写経をたのんだという説話の主人公"],["村上藩主","三重塔を寄進したと伝わる"],["松尾芭蕉","旅の途中に参詣したといわれる"]],"deep":["『今昔物語集』巻十四には、越後国の乙寺の僧が猿のために法華経を写す話がおさめられ、写経の功徳を説く説話として知られます。","猿が生まれ変わった国司の名前は説話の中に記されていますが、実在の人物かどうかは確かではありません。","婆羅門僧正（菩提僊那）は752年の東大寺大仏開眼供養で導師をつとめた実在の僧ですが、越後まで来たという話は寺伝です。","三重塔は江戸時代はじめの元和年間ごろの建立とされ、桃山時代の雰囲気を残す塔として評価されています。","芭蕉の乙宝寺参詣は、同行した曽良の旅日記に関連する記録があるとされます。"],"look":["杉木立の中の三重塔","本堂と、お釈迦さまの舎利にまつわる伝え","猿の写経の説話を伝える碑や絵","門前の «乙まんじゅう» などの名物"],"q":["『今昔物語集』で、乙寺の僧にお経を書いてほしいとたのんだ動物は？","2匹の猿です。木の皮を持ってきたと語られます。"],"koji":[],"myth":"開山の年と開山者、舎利の伝え、芭蕉の参詣は寺伝・伝承を含む。","img":["今昔物語集","行基","菩提僊那"],"wp":"乙宝寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Oppoji_Temple_Dainichido.jpg",2592,1944,"乙宝寺"],["c:5/52/KonjakuMonogatarisyu_codex_Suzuka.png",1409,1888,"今昔物語集"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:f/fc/Bodhisena_Four_Saintly_Figures_%28Eiwa_Version%29_%28cropped%29.jpg",400,500,"菩提僊那"]]},{"id":"15_jokoji","n":"浄興寺（親鸞ゆかり・高田寺町）","yomi":"じょうこうじ","cat":"寺社","rank":"A","y":1224,"era":["kamakura","edo"],"sh":"国の重要文化財（本堂）","ad":"上越市寺町2丁目","st":"JR・えちごトキめき鉄道 高田駅から歩いて約15分","la":37.1044,"lo":138.2393,"hook":"親鸞がひらいたと伝わる寺が、関東から信濃、春日山をへて、雪国・高田の寺町にたどりついた。旅する本山の物語。","lead":"浄興寺は «真宗浄興寺派» の本山です。はじまりは常陸国（いまの茨城県）で、親鸞がひらいたと伝わります。そのあと戦乱をさけて何度も引っこし、江戸時代のはじめに高田の城下町へやってきました。大きな本堂は国の重要文化財です。","story":["お寺が «引っこし» をする、と聞くとふしぎに思うかもしれません。でも浄興寺は、何百年もかけて長い旅をしてきたお寺です。寺の伝えでは、はじまりは鎌倉時代の1224年ごろ。越後への流罪を許されたあと関東で教えを広めていた親鸞が、常陸国の稲田（いまの茨城県笠間市）で念仏の道場をひらいたのがもとだといいます。","親鸞は «南無阿弥陀仏ととなえれば、だれでも救われる» と説きました。武士でも農民でも、字の読めない人でも同じだ、という教えは、多くの人の心をつかみました。弟子たちは «念仏の道場» を守り、それがのちに寺になっていきます。浄興寺はその中でも古い由緒をもつ寺として大切にされてきました。","ところが戦国時代、関東は戦いの場になります。寺は信濃国へ移り、長沼（いまの長野市）などで教えを守ったと伝わります。そこも武田と上杉がぶつかる危ない土地でした。«どこなら安心して念仏をとなえられるのか?» 寺の人びとは、越後の上杉謙信をたより、春日山のふもとへ移ったといわれます。","江戸時代のはじめ、徳川家康の六男・松平忠輝が高田に新しい城を築くと、春日山のまわりにあった寺々も新しい城下町へ集められました。城を守る «とりで» の役目も期待されて、寺は町の西側にずらりと並びます。これがいまも «寺町» とよばれる通りで、浄興寺もそのひとつとして腰を落ちつけました。","境内に入ると、どっしりした本堂が目にとびこんできます。雪の重さにたえる太い柱と大きな屋根は、豪雪地の寺らしい姿です。浄興寺は親鸞の遺骨をまつると伝える廟も守っていて、いまも全国から門徒がお参りに来ます。旅をつづけた寺が、ついに雪の町に根をおろした――そう思って歩くと、寺町の景色がちがって見えてきます。"],"tl":[["1224年","親鸞が常陸国稲田で浄興寺をひらいたと伝わる"],["戦国時代","戦乱をさけて信濃国へ移ったと伝わる"],["1560年代ごろ","上杉謙信をたより越後・春日山のふもとへ移ったといわれる"],["1614年","松平忠輝の高田城築城。寺町ができ、浄興寺も高田へ（時期は諸説）"],["江戸時代前期","現在の本堂が建てられる"],["1989年","本堂が国の重要文化財に指定される"]],"who":[["親鸞","浄土真宗の祖。浄興寺をひらいたと伝わる。若いころ越後に流された"],["上杉謙信","越後の大名。寺を春日山のふもとにむかえたと伝わる"],["松平忠輝","高田藩主。高田城と城下町をつくり、寺町の形ができた"],["恵信尼","親鸞の妻。越後出身といわれ、晩年も越後で暮らした"]],"deep":["本堂は江戸時代前期の大きな真宗本堂で、1989年に国の重要文化財になりました。雪国の寺らしく、屋根を支える木組みがとても太いのが見どころです。","高田の寺町には60をこえる寺が南北に並ぶといわれ、城下町の西の守りをかねていたと考えられています。寺の門や墓地が道の片側に延々とつづく眺めは全国でも珍しいものです。","浄興寺は «真宗十派» のひとつ «真宗浄興寺派» の本山です。東西の本願寺とは別の流れで、独自の歴史をたどってきました。","寺には親鸞ゆかりと伝える宝物が多く伝わりますが、一般公開は時期が限られます。拝観の方法は事前に寺や市の観光案内で確かめるのが安心です。","親鸞は1207年の «承元の法難» で越後国府（いまの上越市）に流されました。浄興寺が最後に上越へ来たのは、師の流罪の地に帰ってきたともいえる、ふしぎなめぐり合わせです。"],"look":["国の重要文化財の本堂（雪国ならではの太い柱と大屋根）","親鸞の遺骨をまつると伝わる廟所","寺町通りの寺の連なり（歩いて寺の門を数えてみよう）","近くの高田城址公園・雁木通りもあわせて"],"q":["浄興寺がはじめにひらかれたと伝わるのは、いまの何県？","茨城県です。常陸国稲田で親鸞がひらいたと伝わり、そこから信濃・越後へと移ってきました。"],"koji":[{"w":"善人なおもて往生をとぐ、いわんや悪人をや","m":"『歎異抄』に伝わる親鸞のことば。自分の力にたよれない人こそ阿弥陀仏に救われる、という教え"}],"myth":"創建年・移転の年代や経路には寺伝と諸説がある。遺骨の伝えも寺の伝承。","img":["親鸞","高田城","浄土真宗"],"wp":"浄興寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/Joko-ji_%28Joetsu%29.JPG",3648,2736,"浄興寺"],["c:a/ad/ShinranShonin.png",371,507,"親鸞"],["c:6/69/Takada_Castle_yagura.JPG",3763,2504,"高田城"]]},{"id":"15_nishimikawa","n":"西三川砂金山跡","yomi":"にしみかわさきんざんあと","cat":"産業","rank":"A","y":1600,"era":["heian","azuchi","edo"],"sh":"国指定史跡（佐渡金山遺跡）・世界遺産「佐渡島の金山」構成資産","ad":"佐渡市西三川・笹川","st":"両津港から車で約1時間、小木港から車で約20分。路線バスは本数が少なく車が便利","la":37.856,"lo":138.328,"hook":"山をくずし、水で流して、砂の中から金の粒をすくう。佐渡でいちばん古い金山は、山そのものを «洗った» 場所だった。","lead":"西三川は、佐渡で最も早くから金がとれたといわれる砂金山です。山の土を水路の水で流し、重い砂金だけを残す «大流し» という方法で金を集めました。2024年に «佐渡島の金山» として世界遺産になった場所のひとつです。","story":["平安時代の説話集『今昔物語集』には、佐渡の国で金をとる男の話がのっています。どこの山かは書かれていませんが、佐渡に金があることは、そのころから都の人にも知られていたのです。その候補として名があがるのが、島の南西、真野湾の南にある西三川の山あいです。","ここの金は、岩の中の «金の鉱脈» ではなく、土や砂にまじった細かな砂金でした。«どうすれば山の土から金だけを取り出せるのか?» 人びとが考えたのが、水の力です。山の上から水路で水を引き、ためた水を一気に流して土をくずし、下の «ひ» と呼ぶ流し場で軽い土を洗い流します。重い金の粒だけが底に残るのです。","これが «大流し»。山をまるごと洗うような大がかりな仕事で、何本もの水路と、水をためる池が必要でした。いまでも山の斜面がえぐれて地肌が見える場所や、山腹をはうように続く水路の跡が残っています。人の手が長い年月をかけて山の形を変えてしまったのです。","砂金とりの人びとが暮らした笹川の集落は、石垣や水路、家並みがいまもまとまって残り、«砂金山由来の農山村景観» として国の重要文化的景観にも選ばれています。やがて相川で大きな金銀山が見つかると、佐渡の中心はそちらへ移りますが、西三川での採掘は明治のはじめまで続いたといわれます。","近くの «西三川ゴールドパーク» では、砂金とりの体験ができます。水の中で皿をゆらし、黒い砂の中にきらりと光る粒を見つけたときの «あった!» という声は、何百年も前の人たちと同じかもしれません。"],"tl":[["平安時代後期","『今昔物語集』に佐渡で金をとる話がのる"],["戦国時代末〜江戸時代初め","大流しによる砂金採りがさかんになる"],["1601年","相川で大鉱脈が見つかり、佐渡の中心が相川へ移る"],["1872年","西三川砂金山の採掘が終わる（明治5年、とされる）"],["2011年","笹川の景観が国の重要文化的景観に選ばれる"],["2024年","«佐渡島の金山» が世界遺産に登録。西三川砂金山が構成資産に"]],"who":[["砂金とりの人びと（笹川の住民）","水路をつくり山を流して砂金を集めた。集落の景観が今に残る"],["上杉景勝","戦国時代末に佐渡を支配下に置き、金銀山に力を入れた"],["徳川家康","佐渡を幕府の直轄地とし、金銀を幕府の財源にした"]],"deep":["«大流し» は、上の池にためた水を一気に流して土砂をくずす方法です。山の斜面が大きくえぐれた «採掘跡» が今も見え、人の力で地形が変わった例として注目されています。","水を運ぶ水路は «江（え）» と呼ばれ、山腹を何kmもめぐっていたといわれます。水の確保こそが砂金山の命でした。","世界遺産 «佐渡島の金山» は、西三川砂金山と相川鶴子金銀山の2つの構成資産からなります。«砂金» から «鉱脈掘り» への技術の移り変わりを見られるのが強みです。","笹川集落は、砂金とりの家々と農地が一体になった景観として、2011年に国の重要文化的景観 «佐渡西三川の砂金山由来の農山村景観» に選ばれました。","『今昔物語集』の佐渡の金の話は場所がはっきりしません。西三川をその舞台とする見方は有力ですが、確かめられてはいません。"],"look":["笹川集落の石垣と家並み","山の斜面の採掘跡（虎丸山など）","山腹をめぐる水路の跡","西三川ゴールドパークで砂金とり体験"],"q":["山の土を水で流して砂金を集める、西三川の方法を何という？","«大流し»。ためた水を一気に流して土をくずし、重い金だけを残しました。"],"koji":[],"myth":"『今昔物語集』の話の舞台を西三川とする説、採掘開始・終了の年には諸説。","img":["佐渡島の金山","佐渡金山","今昔物語集"],"wp":"西三川砂金山","rel":{"ev":[],"grave":[]},"ph":[["c:8/87/Sadokinzan-doyunowareto_01.JPG",1024,712,"佐渡島の金山"],["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"],["c:5/52/KonjakuMonogatarisyu_codex_Suzuka.png",1409,1888,"今昔物語集"]]},{"id":"15_tsurushi","n":"鶴子銀山跡（佐渡最初の大鉱山）","yomi":"つるしぎんざんあと","cat":"産業","rank":"A","y":1542,"era":["muromachi","azuchi","edo"],"sh":"国指定史跡（佐渡金山遺跡）・世界遺産「佐渡島の金山」構成資産の一部","ad":"佐渡市沢根・鶴子","st":"両津港から車で約45分。相川方面へ向かう途中。見学は現地ガイドつきのツアーが安心","la":37.999,"lo":138.31,"hook":"相川の «金の山» を見つけたのは、じつはこの銀山の山師たちだった。佐渡のゴールドラッシュはここから始まる。","lead":"鶴子銀山は、戦国時代に見つかった佐渡で最初の大きな鉱山です。銀の鉱脈を掘るため、石見銀山から来た山師が坑道を掘る技術を伝えました。ここで力をつけた山師たちが、のちに相川で大金銀山を見つけます。","story":["戦国時代の1542年ごろ、越後の商人が佐渡の沢根の山で銀を見つけたと伝わります。それが鶴子銀山のはじまりです。島を治めていた本間氏は、ここから出る銀で力をたくわえたといわれます。銀は刀や鉄砲と同じくらい、戦国大名にとって大切な «戦うための財産» でした。","はじめは地面に見えている鉱脈を、上から掘り下げる «露頭掘り» でした。しかし浅いところはすぐに掘りつくしてしまいます。«もっと深く掘るにはどうすればいい?» その答えを持ってきたのが、石見銀山（島根県）から来た山師たちでした。山の横から穴をうがち、鉱脈を追いかける «坑道掘り» の技術です。","坑道掘りが始まると、鶴子の山には人が集まり、町ができました。山には «間歩（まぶ）» と呼ばれる坑道の入り口がいくつもあき、掘る人、運ぶ人、鉱石をくだく人、灰吹きで銀をとり出す人が働きました。代官の屋敷も置かれ、鶴子は佐渡の鉱山の中心になっていきます。","1601年ごろ、鶴子の山師たちが北の相川の山で、大きな金銀の鉱脈を見つけたと伝わります。のちに «道遊の割戸» と呼ばれる、山が真っ二つに割れたような露頭です。人も技術も相川へ移り、佐渡金銀山の黄金時代が始まりました。鶴子はいわば «相川の親» なのです。","その後も鶴子では採掘が続き、終わったのは昭和の戦後だといわれます。いまは森に包まれ、ひっそりと坑道の口や、掘りあとのくぼみが点々と残るだけ。足もとの悪い山の中なので、ガイドといっしょに歩くのがおすすめです。"],"tl":[["1542年","越後の商人が銀の鉱脈を見つけたと伝わる"],["戦国時代","佐渡の本間氏が銀山を支配"],["1589年","上杉景勝が佐渡を攻め、本間氏がほろびる。銀山は上杉の支配下に"],["1595年ごろ","石見の山師が坑道掘りの技術を伝えたといわれる"],["1601年","鶴子の山師が相川で大鉱脈を見つけたと伝わる"],["1946年","鶴子での採掘が終わったとされる"],["2024年","«佐渡島の金山» が世界遺産に（相川鶴子金銀山の一部）"]],"who":[["外山茂右衛門","銀山を見つけたと伝わる越後の商人"],["本間氏","戦国時代に佐渡を治めた一族。銀山から財力を得た"],["石見の山師たち","坑道掘りの技術を伝えたといわれる"],["上杉景勝","佐渡を支配下に置き、金銀を財源にした"]],"deep":["鶴子銀山跡は «佐渡金山遺跡» の一部として国史跡に追加され、世界遺産では «相川鶴子金銀山» という1つの構成資産に相川とまとめて入っています。","坑道掘りの技術が石見銀山から来たという話は、日本の鉱山技術が西から東へ伝わったことを示す例としてよく語られます。人数や年は史料によってちがいます。","山中には «間歩» の口のほか、露頭掘りのあと、山師の屋敷跡、代官所の跡などが確認されています。","«灰吹法» は、銀をふくむ鉱石を鉛といっしょにとかし、灰の上で鉛を吸わせて銀を残す方法。16世紀に石見銀山で広まり、各地の銀山に伝わりました。","発見者の名前や年は江戸時代の記録や伝えによるもので、同時代の史料で確かめられているわけではありません。"],"look":["森の中に残る間歩（坑道の入り口）","露頭掘りのあとの溝","代官屋敷跡などの説明板","あわせて相川の «道遊の割戸» を見ると、つながりがよくわかる"],"q":["鶴子の山師たちがのちに見つけた、山が割れたような金銀の露頭の名前は？","«道遊の割戸»。相川にあり、佐渡金銀山のシンボルになっています。"],"koji":[],"myth":"発見年・発見者、石見からの技術伝来の年、採掘終了年には伝承・諸説がある。","img":["佐渡島の金山","佐渡金山","石見銀山"],"wp":"鶴子銀山","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/%E9%B6%B4%E5%AD%90%E9%8A%80%E5%B1%B1_01.jpg",4320,3240,"鶴子銀山"],["c:8/87/Sadokinzan-doyunowareto_01.JPG",1024,712,"佐渡島の金山"],["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"],["c:b/bd/Shimizudani_Refinery_Ruins_at_Iwami_Ginzan_Silver_Mine_001.jpg",3264,2448,"石見銀山"]]},{"id":"15_zeami","n":"正法寺（世阿弥配流の寺）","yomi":"しょうぼうじ","cat":"伝承","rank":"A","y":1434,"era":["muromachi"],"sh":"","ad":"佐渡市泉","st":"両津港から車で約30分。佐渡金井地区、国道350号から少し入る","la":38.044,"lo":138.376,"hook":"72歳で島へ流された «能の天才»。彼が暮らしたと伝わる小さな寺で、能は島の人びとの文化になった。","lead":"能を大成した世阿弥は、1434年、室町幕府の将軍・足利義教の怒りにふれて佐渡に流されました。正法寺は、世阿弥が島で暮らしたと伝わるお寺です。ここには世阿弥が使ったと伝わる面や、腰かけたという石が残ります。","story":["世阿弥は、父の観阿弥とともに能をつくりあげた人です。«秘すれば花» の言葉で知られる『風姿花伝』を書き、将軍・足利義満にも愛されました。ところが時代が変わり、6代将軍・足利義教の世になると、世阿弥の一座は冷たくされます。そして1434年、72歳の世阿弥に «佐渡へ流す» という命令がくだりました。","«なぜ、そこまで?» はっきりした理由はわかっていません。甥の音阿弥をひいきにした義教との対立、後継ぎ問題など、いくつもの説があります。わかっているのは、年老いた世阿弥が若狭の小浜から船に乗り、日本海をわたったことです。","その旅と島の暮らしを、世阿弥は『金島書』という小さな本にのこしました。船で着いた浦、島の神社や寺、流人として過ごした日々が、美しい文で書かれています。はじめは新保の万福寺にいましたが、島で戦さわぎが起こったため、泉という場所に移ったといいます。その泉の住まいが、この正法寺だと伝わるのです。","正法寺には、世阿弥が雨ごいのために舞ったときにつけたと伝わる «神事面» や、世阿弥が腰かけたという石があります。«都の天才が、流された島でも舞った» という話は、島の人びとの誇りになりました。のちに佐渡には能舞台がいくつも建てられ、農民や町人も能を楽しむ «能の島» になっていきます。","世阿弥がその後、都に帰れたのか、島で亡くなったのかは、よくわかっていません。静かな境内に立つと、海をこえてきた老いた芸術家が、島の風の中で何を思ったのか、想像がふくらみます。"],"tl":[["1363年ごろ","世阿弥が生まれる（生年は諸説）"],["1374年ごろ","今熊野で観阿弥・世阿弥の能を足利義満が見る"],["1400年ごろ","『風姿花伝』の最初の部分が書かれる"],["1434年","足利義教の命で佐渡に流される"],["1436年","佐渡で『金島書』をまとめる"],["1443年ごろ","世阿弥が亡くなったとされる（場所・年は諸説）"]],"who":[["世阿弥","能を大成した人。佐渡に流され、正法寺で暮らしたと伝わる"],["観阿弥","世阿弥の父。能の基礎をつくった"],["足利義満","3代将軍。少年の世阿弥をかわいがった"],["足利義教","6代将軍。世阿弥を佐渡へ流した"],["音阿弥","世阿弥の甥。義教にひいきされた"]],"deep":["『金島書』は世阿弥が佐渡で書いた小謡（こうたい）の集まりで、配流の旅の道筋や島の名所が読みこまれています。流人自身が流刑地を書いた、珍しい記録です。","配流の理由は諸説あります。後継ぎを甥の音阿弥にするよう求められて断った説、世阿弥の子・元雅の一座との対立説などがあり、決め手はありません。","正法寺に伝わる «神事面べしみ» は、世阿弥が雨ごいのときにつけたと伝わる面で、県の文化財に指定されていると紹介されます。公開は限られるので、見学は事前に確かめましょう。","佐渡には30をこえる能舞台があるといわれ、全国の能舞台の多くがここに集まっています。江戸時代に佐渡奉行となった大久保長安が能を広めたことも大きな理由です。","世阿弥が佐渡で亡くなったのか、許されて都へ戻ったのかは史料がなく、わかっていません。«娘むこの金春禅竹にあてた手紙» が佐渡から送られたと考えられています。"],"look":["世阿弥が腰かけたと伝わる «腰掛石»","本堂と静かな境内","世阿弥ゆかりの神事面（公開日に注意）","近くの能舞台（佐渡各地に点在）"],"q":["世阿弥が佐渡での体験を書いた本の名前は？","『金島書』。佐渡を «金の島» と呼んだ題名とされ、配流の旅と島のようすが書かれています。"],"koji":[{"w":"秘すれば花","m":"『風姿花伝』のことば。すべてを見せず、かくしてこそ人の心を動かす «花» になる"},{"w":"初心忘るべからず","m":"世阿弥の『花鏡』にある言葉。修行を始めたころのつたなさを忘れず、それぞれの段階の «初心» を大切にせよ"}],"myth":"正法寺を配所とすること、面・腰掛石の伝え、配流の理由、晩年は伝承・諸説。","img":["金島書","風姿花伝","足利義教"],"wp":"世阿弥","rel":{"ev":[],"grave":[]},"ph":[["c:1/11/%E8%B6%B3%E5%88%A9%E7%BE%A9%E6%95%99%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1320,1410,"足利義教"]]},{"id":"15_renge","n":"蓮華峰寺（小比叡・小木）","yomi":"れんげぶじ","cat":"寺社","rank":"A","y":807,"era":["heian","muromachi","edo"],"sh":"国の重要文化財（金堂・弘法堂・骨堂）","ad":"佐渡市小比叡","st":"小木港から車で約10分。バスは本数が少ない","la":37.836,"lo":138.304,"hook":"杉木立の谷に、室町の «骨堂» がひっそり建つ。佐渡の «小比叡山» は、島の西の比叡山と呼ばれた古寺。","lead":"蓮華峰寺は、佐渡の南、小木半島の山あいにある真言宗のお寺です。空海がひらいたと伝わり、地元では «小比叡（こびえ）» とも呼ばれます。金堂・弘法堂・骨堂の3つが国の重要文化財です。","story":["小木港から山へ入ると、深い杉の森にかこまれた谷にお堂が並んでいます。ここが蓮華峰寺。寺の伝えでは、平安時代のはじめの807年、空海（弘法大師）がこの地に寺をひらいたといいます。空海が本当に佐渡へ来たかどうかは確かめられませんが、それほど古く、尊い寺だと信じられてきたのです。","«なぜ小比叡と呼ぶの?» 京都の比叡山延暦寺にならって、山の名を «小比叡山» としたからだといわれます。都から遠い島でも、都の大寺院に負けない信仰の場をつくりたい――そんな思いが、この名前にこめられているのかもしれません。","境内でいちばん古い建物が «骨堂» です。室町時代に建てられたといわれ、小さいながら軒のそりや木組みが美しく、昔の人の骨をおさめる堂だったと伝わります。ほかにも本尊をまつる金堂、空海をまつる弘法堂があり、どれも国の重要文化財。佐渡の小さな谷に、これほどの建物が残っていることに驚かされます。","戦国時代、佐渡は本間氏の一族どうしが争い、やがて上杉景勝の軍が攻めこんできました。江戸時代には佐渡は幕府の直轄地となり、蓮華峰寺は島を代表する真言宗の寺として、奉行所からも重んじられたといわれます。","春には桜、秋には紅葉がお堂をいろどります。苔むした石段をのぼり、しんと静まった杉の谷に立つと、千年の祈りの時間がゆっくりと流れているのを感じます。"],"tl":[["807年","空海がひらいたと伝わる"],["室町時代","骨堂が建てられたとされる"],["1589年","上杉景勝の佐渡攻め。島の支配者が変わる"],["江戸時代","佐渡の代表的な真言寺院として栄える。金堂・弘法堂が整えられる"],["昭和時代","金堂・弘法堂・骨堂が国の重要文化財に指定される"]],"who":[["空海（弘法大師）","真言宗をひらいた僧。寺をひらいたと伝わる"],["本間氏","中世に佐渡を治めた一族。島の寺社を保護した"],["上杉景勝","1589年に佐渡を攻め、支配下に置いた"]],"deep":["«骨堂» は室町時代の建築とされる小さな仏堂で、名前のとおり遺骨をおさめた堂と伝わります。佐渡に残る中世建築として特に貴重です。","金堂・弘法堂・骨堂の3棟が国の重要文化財。1つの寺でこれだけの重文建築が残るのは、佐渡ではまれです。","寺名の «蓮華峰» は、まわりの山が蓮の花びらのように重なっていることから、という説明が伝わります。","空海の開基は寺の伝えで、同時代の史料はありません。空海ゆかりを名乗る寺は全国に数多く、信仰の広がりを示すものとして読むのがよいでしょう。","近くの小木は、江戸時代に佐渡の金銀を本土へ運ぶ港として栄えました。宿根木の町並み（国の重要伝統的建造物群保存地区）も近くにあります。"],"look":["室町時代の骨堂（軒のそりと木組み）","金堂と弘法堂","杉木立の参道と石段","近くの宿根木の町並み"],"q":["蓮華峰寺が地元で呼ばれている別の名前は？","«小比叡（こびえ）»。京都の比叡山にならって山を «小比叡山» と呼んだことから、といわれます。"],"koji":[],"myth":"空海の開基は寺伝。骨堂の建築年代にも幅のある見方がある。","img":["空海","小木港"],"wp":"蓮華峰寺","rel":{"ev":[],"grave":[]},"ph":[["c:2/23/%E8%93%AE%E8%8F%AF%E5%B3%B0%E5%AF%BA.jpg",4011,2674,"蓮華峰寺"],["c:9/98/Kobo_Daishi_%28Taisanji_Matsuyama%29.jpg",260,270,"空海"],["c:8/88/Sadokisen_Ogi_terminal.jpg",5736,3828,"小木港"]]},{"id":"15_sawata_jo","n":"雑太城（佐渡守護代本間氏）","yomi":"さわたじょう","cat":"城","rank":"A","y":1300,"era":["kamakura","muromachi","azuchi"],"sh":"","ad":"佐渡市竹田","st":"両津港から車で約30分。真野地区、大膳神社の近く","la":37.969,"lo":138.361,"hook":"日蓮を見はり、少年に父のかたきを討たれた――佐渡を400年治めた本間氏の本拠は、いまは静かな丘の上。","lead":"雑太城は、鎌倉時代から戦国時代まで佐渡を治めた本間氏の本家の城です。本間氏は鎌倉幕府から佐渡の支配をまかされた «守護代» の家でした。流されてきた日蓮や日野資朝とも深くかかわり、『太平記』の名場面の舞台にもなりました。","story":["鎌倉時代、佐渡の守護は北条氏の一族がつとめましたが、実際に島を治めたのは家来の本間氏でした。本間氏はもとは相模国（神奈川県）の武士で、佐渡に移って根をはり、やがて島のあちこちに一族が分かれて城をかまえます。その本家が住んだのが、島のまん中の国仲平野をのぞむこの雑太の地でした。","1271年、日蓮が佐渡に流されてきます。流人をあずかったのは本間氏でした。日蓮は塚原の三昧堂という粗末なお堂に入れられ、冬の雪の中で『開目抄』などを書いたといわれます。本間六郎左衛門重連は、はじめは日蓮をきびしく扱いましたが、やがてその人柄に打たれ、帰依したとも伝わります。","鎌倉時代の終わり、後醍醐天皇の倒幕計画にかかわった貴族・日野資朝も佐渡に流され、本間氏にあずけられました。『太平記』によると、資朝の子・阿新丸（くまわかまる）は父に会うため13歳で島へわたりますが、会えないまま父は処刑されてしまいます。«せめて父のかたきを!» 阿新丸は夜の館にしのびこみ、本間の一族を討ってにげ延びたと描かれています。","このため雑太城は «檀風城（だんぷうじょう）» の名でも語られ、のちに能 «檀風» の題材にもなりました。戦国時代になると本間氏は一族どうしの争いで力を弱め、1589年、上杉景勝の軍が佐渡に攻めこむと、雑太の本間氏もほろびます。","いまの城跡は畑や林になり、大きな石垣などは残っていません。でも近くの大膳神社には能舞台があり、国分寺跡や順徳上皇の真野御陵もすぐそば。流人と島の武士たちが出会った «佐渡の中世» を感じられる場所です。"],"tl":[["鎌倉時代","本間氏が守護代として佐渡に入る"],["1271年","日蓮が佐渡に流され、本間氏があずかる"],["1332年","日野資朝が佐渡で処刑される。子の阿新丸の敵討ちの話が『太平記』に"],["戦国時代","本間一族（雑太・河原田・羽茂など）が争う"],["1589年","上杉景勝が佐渡を攻め、本間氏がほろびる"]],"who":[["本間氏（雑太本間）","佐渡守護代の本家。雑太城を本拠とした"],["日蓮","1271年に佐渡へ流された僧。本間氏があずかった"],["日野資朝","倒幕計画にかかわり佐渡に流された貴族"],["阿新丸（日野邦光）","資朝の子。父のかたきを討ったと『太平記』に描かれる"],["上杉景勝","1589年に佐渡を攻め、本間氏をほろぼした"]],"deep":["本間氏のルーツは相模国愛甲郡の本間の地とされます。佐渡守護の大仏（おさらぎ）流北条氏の代官として島に入ったと考えられています。","阿新丸の敵討ちは『太平記』の物語で、どこまで史実かははっきりしません。討たれた相手や場所の細かい話は、物語としての脚色がふくまれると考えるのが安全です。","«檀風城» の名は、阿新丸の話にちなむ能 «檀風» と結びついています。城跡の比定にも諸説があります。","雑太は古代の佐渡国の郡名（雑太郡）でもあり、近くに国分寺跡がある、島の政治の中心地でした。","1589年の上杉軍の佐渡攻めは、豊臣秀吉の許しを得て行われたといわれ、これで中世以来の本間氏の支配が終わりました。"],"look":["城跡の地形（ゆるやかな丘と空堀のあと）","近くの大膳神社の能舞台","佐渡国分寺跡","順徳上皇の真野御陵"],"q":["『太平記』で、父のかたきを討つため佐渡へわたった少年の名前は？","阿新丸（くまわかまる）。日野資朝の子で、のちに日野邦光と名のりました。"],"koji":[],"myth":"阿新丸の敵討ちは『太平記』の物語。城跡の位置・«檀風城» との関係には諸説。","img":["本間氏","日野資朝","日蓮","太平記"],"wp":"雑太城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Hino-Suketomo.jpg",1187,1625,"日野資朝"],["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"],["c:7/7c/Taiheiki_-_1698_-_1-5.jpg",2592,1728,"太平記"]]},{"id":"15_hokkoku","n":"北国街道（高田〜直江津〜出雲崎）","yomi":"ほっこくかいどう","cat":"街道","rank":"A","y":1650,"era":["edo"],"sh":"","ad":"上越市〜柏崎市〜三島郡出雲崎町（写真の基準点は出雲崎の町並み）","st":"出雲崎へはJR越後線 出雲崎駅からバスで約10分。高田・直江津は駅から歩ける","la":37.53,"lo":138.709,"hook":"佐渡の金は、この道を通って江戸へ運ばれた。«荒海や» の句が生まれたのも、この街道の宿だった。","lead":"北国街道は、中山道の追分（長野県）から善光寺をへて越後の高田・直江津へ、さらに日本海ぞいに出雲崎へ続く道です。加賀藩の大名行列や、佐渡の金銀を運ぶ一行が通りました。宿場町の町並みが今も残ります。","story":["江戸時代、日本海の港・出雲崎には、佐渡から船で運ばれた金や銀が陸あげされました。«金の荷» は厳重に守られて北国街道を南へ。高田をへて信濃に入り、追分で中山道に合流して江戸へ向かいました。この道は、幕府のお金を運ぶ大切な «金の道» だったのです。","街道には宿場が置かれ、旅人が泊まる宿や荷物を運ぶ馬が用意されました。高田の城下には雪から道を守る «雁木（がんぎ）» が続き、直江津は港町としてにぎわいました。加賀藩前田家の大名行列も、この道を使って江戸へ向かうことがありました。何百人もの行列が通る日は、宿場じゅうが大さわぎです。","1689年、松尾芭蕉は『おくのほそ道』の旅で出雲崎に泊まりました。夜の海の向こうに佐渡が黒く横たわり、空には天の川。そこで生まれたのが «荒海や 佐渡によこたふ 天河» の句です。«なぜ佐渡を詠んだの?» 佐渡は金の島であり、同時に日蓮や世阿弥、順徳上皇が流された悲しみの島でもありました。芭蕉はその両方を感じていたのかもしれません。","出雲崎は、禅僧で歌人の良寛が生まれた町でもあります。海ぞいの細長い土地に、入口がせまく奥行きの長い «妻入り» の家がびっしり並ぶ町並みは、今も約4kmにわたって続いています。","明治になり鉄道が通ると、街道を歩く旅人は減りました。けれど高田の雁木、直江津の港、出雲崎の妻入りの家並みをたどると、雪国を行き来した人びとの足音が聞こえてくるようです。"],"tl":[["1601年","佐渡の金銀山が本格的に開発され、金銀輸送が始まる"],["江戸時代初め","街道と宿場が整えられる"],["1614年","高田城ができ、城下町が北国街道の宿場を兼ねる"],["1689年","芭蕉が出雲崎で «荒海や» の句を詠む"],["1758年","良寛が出雲崎で生まれる"],["明治時代","信越線が開通し、街道の役目が小さくなる"]],"who":[["松尾芭蕉","『おくのほそ道』の旅で出雲崎に泊まった俳人"],["良寛","出雲崎生まれの禅僧・歌人"],["前田家（加賀藩）","参勤交代でこの道を使うことがあった"],["佐渡奉行","佐渡の金銀の輸送を管理した"]],"deep":["«北国街道» の名は地域によって指す道がちがいます。狭い意味では追分〜善光寺〜高田（〜直江津）の道で、越後では出雲崎方面の北陸道ぞいの道も合わせてこう呼ぶことがあります。","佐渡の金銀は小木や赤泊から出雲崎・寺泊へ運ばれ、陸路で江戸へ向かいました。季節や時期によってルートは変わったといわれます。","出雲崎の «妻入り» の家並みは、間口の広さで税がかけられたから細長くなった、とよく説明されますが、これは俗説ともいわれ、はっきりしません。","芭蕉が出雲崎に泊まったのは旧暦7月4日と『曾良旅日記』からわかっています。実際には雨の日が多く、天の川が見えたかは疑問とする説もあります。","高田の雁木は総延長が長く、日本有数の規模といわれます。雪の季節でも歩ける «アーケード» の先祖です。"],"look":["出雲崎の妻入りの町並みと芭蕉園","良寛記念館と良寛堂","高田の雁木通り","直江津の港と、五智国分寺の親鸞ゆかりの地"],"q":["芭蕉が出雲崎で詠んだ句の «佐渡によこたふ» ものは何？","«天河（あまのがわ）»。荒れた日本海の向こうの佐渡に、天の川がかかる景色を詠みました。"],"koji":[{"w":"荒海や 佐渡によこたふ 天河","m":"芭蕉『おくのほそ道』の句。荒れる海と、佐渡の上にかかる天の川の大きな景色"}],"myth":"妻入りの由来（税の話）は俗説とも。芭蕉が実際に天の川を見たかは諸説。","img":["出雲崎町","良寛","おくのほそ道"],"wp":"北国街道","rel":{"ev":[],"grave":[]},"ph":[["c:4/41/Find47_Niigata-_Ryokan_and_Yuhi-no-oka_Park_%28Izumozaki_Town%29-m.jpg",1920,1280,"出雲崎町"]]},{"id":"15_mikuni","n":"三国街道と三国峠","yomi":"みくにかいどうとみくにとうげ","cat":"街道","rank":"A","y":1650,"era":["muromachi","edo"],"sh":"","ad":"南魚沼郡湯沢町三国（三国峠付近）","st":"車が便利。JR越後湯沢駅から苗場方面のバスで浅貝・二居へ。峠は登山道","la":36.822,"lo":138.813,"hook":"謙信は関東へ、佐渡奉行は島へ。上州と越後をへだてる峠を、何百年も人と荷が越えていった。","lead":"三国街道は、中山道の高崎（群馬県）から三国峠をこえ、越後の長岡・寺泊へ続いた道です。上杉謙信の関東出兵、佐渡へ向かう役人や流人、雪深い魚沼の人びとの暮らしを支えました。浅貝・二居・三俣など、峠の宿場の名が今も残ります。","story":["群馬県と新潟県の境、標高1200mをこえる三国峠。上野（こうずけ）・越後・信濃の三つの国の神をまつったことから «三国» の名がついたといわれ、峠には三国権現の社があります。冬は深い雪にとざされ、昔の人にとっては命がけの峠でした。","戦国時代、この峠をたびたび越えたのが上杉謙信です。«関東の北条をたおし、関東管領としての役目をはたす!» 謙信は冬のはじめに雪の峠を越えて関東へ出陣し、春に戻るということをくりかえしたといわれます。越後の兵にとって三国峠は、戦場への入り口でした。","江戸時代になると、三国街道は越後と江戸を結ぶ大切な道として整えられました。佐渡へ向かう佐渡奉行の一行や、佐渡へ送られる人びともこの道を通ったといわれます。越後の大名の参勤交代にも使われ、峠の下の浅貝・二居・三俣には、大名や役人が泊まる本陣が置かれました。","峠を下った魚沼の塩沢は、『北越雪譜』を書いた鈴木牧之のふるさとです。«雪の国の暮らしを江戸の人は知らない» と、牧之は雪の結晶や雪国の仕事を本にまとめました。三国街道を行き来する人の話も、牧之の目に入っていたことでしょう。","昭和になって三国トンネルが通り、国道17号として車が走るようになると、峠道を歩く人はいなくなりました。いまは苗場や湯沢のスキー場で知られる地域ですが、山の中には石畳や道しるべがひっそり残り、街道歩きのルートとして整備されている区間もあります。"],"tl":[["戦国時代","上杉謙信が三国峠を越えて関東へたびたび出兵"],["江戸時代初め","三国街道として宿場が整えられる"],["江戸時代","佐渡奉行や参勤交代の大名が通る"],["1837年","鈴木牧之『北越雪譜』初編が出版される"],["1959年","三国トンネルが開通（年は資料により諸説）"]],"who":[["上杉謙信","三国峠を越えて関東へ何度も出兵した"],["佐渡奉行","佐渡へ行き来するとき街道を使ったといわれる"],["鈴木牧之","塩沢の商人・文人。『北越雪譜』の作者"],["北条氏の軍勢","1578年の御館の乱で、上杉景虎を助けようと三国峠を越えて越後へ攻めこんだ"]],"deep":["«三国» の由来は、上野・越後・信濃の三国の神をまつる三国権現にある、と説明されます。峠の社は «御坂三社神社» とも呼ばれます。","謙信の «越山» は十数回といわれますが、どの遠征でどの峠を使ったかはすべてがわかっているわけではありません。清水峠などを使った可能性もあります。","二居宿には本陣をつとめた家が残り、峠の宿場の暮らしを伝えています。見学できる時期や方法は湯沢町の案内で確かめましょう。","三国街道は、群馬側では «佐渡奉行が通る道» として «佐渡街道» と呼ばれることもありました。","峠の区間は登山道で、雪の季節は歩けません。夏でも装備を整え、クマに注意が必要です。"],"look":["三国峠と三国権現（御坂三社神社）","浅貝・二居・三俣の宿場跡","街道の石畳や道しるべ","塩沢の牧之通り（鈴木牧之記念館）"],"q":["三国峠の «三国» は、どの三つの国のこと？","上野（群馬）・越後（新潟）・信濃（長野）。三国の神をまつったことが名の由来といわれます。"],"koji":[],"myth":"謙信が越えた峠の特定、名前の由来、トンネル開通年には諸説がある。","img":["三国峠","北越雪譜","上杉謙信"],"wp":"三国街道","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/FutaiChouseichi.jpg",1280,960,"三国街道"],["c:0/01/Hokuetsu_Seppu_Part_2_volume_1.jpg",1753,2776,"北越雪譜"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"15_niigata_jishin","n":"新潟地震（1964年）の記憶","yomi":"にいがたじしん","cat":"事件","rank":"A","y":1964,"era":["showa"],"sh":"","ad":"新潟市中央区川岸町・信濃川河口周辺","st":"JR新潟駅からバスで約15分（昭和大橋・川岸町付近）","la":37.915,"lo":139.038,"hook":"地面が «液体» になり、アパートがそのまま横にたおれた。日本の地震対策を変えた、昼下がりの大地震。","lead":"1964年6月16日の午後1時すぎ、新潟県の沖を震源とするマグニチュード7.5の地震が起きました。新潟市では «液状化» で建物がかたむき、完成したばかりの橋が落ち、石油タンクが燃えつづけました。亡くなった方は26人。この地震は、日本の防災や地震保険のしくみを変えるきっかけになりました。","story":["その日、新潟の人びとは晴れやかな気分でした。数日前まで新潟で国民体育大会が開かれ、町は新しい道路や橋、競技場で生まれ変わったばかりだったからです。午後1時すぎ、突然、地面が大きくゆれました。震源は粟島の近くの海の下。新潟市は震度5と記録されましたが、被害は想像をこえるものでした。","信濃川ぞいの川岸町では、鉄筋コンクリートの県営アパートが、ほとんどこわれないまま、ゆっくりと横にたおれました。«どうして、じょうぶな建物がたおれたの?» 原因は地面でした。水をふくんだ砂の地盤が、ゆれで水と砂がまざった状態になり、建物を支えられなくなったのです。これが «液状化» です。","信濃川にかかる昭和大橋は、開通からまもないのに、橋げたがつぎつぎと川に落ちました。港に近い石油タンクからは火が出て、黒い煙が何日も空をおおいました。津波も押しよせ、海ぞいの低い土地は水につかりました。多くの人が家を失い、不安な夜をすごしました。","この地震で、液状化という現象が世界中の研究者に注目されるようになりました。地盤を調べて建物を建てることや、橋の設計の見直しが進みます。さらに、地震で家を失った人を助けるしくみとして、1966年に «地震保険» の制度がつくられました。新潟の経験が、いまの私たちの暮らしを守るルールにつながっているのです。","いま信濃川の岸辺を歩いても、当時のようすを思いうかべるのはむずかしいかもしれません。けれど、亡くなった方や、町を立て直した人びとがいたことを心にとめて、写真や資料で «あの日» の新潟を見てみてください。"],"tl":[["1964年6月","新潟国体（春季大会）が開かれる"],["1964年6月16日","新潟地震が発生（M7.5）。新潟市などで大きな被害"],["同日","昭和大橋が落ち、川岸町のアパートが横だおしに。石油タンク火災も"],["1964年","液状化の研究が国内外で本格化"],["1966年","地震保険の制度がつくられる"]],"who":[["新潟の市民","被災し、町を立て直した人びと"],["研究者たち","液状化を調べ、建物や地盤の基準づくりに生かした"],["国と保険業界","地震保険のしくみをつくった"]],"deep":["«液状化» の言葉と研究は、この地震とほぼ同じ年のアラスカ地震（1964年3月）をきっかけに世界で広まりました。川岸町のアパートの写真は、今も教科書にのる有名な一枚です。","たおれたアパートは建物自体がほとんどこわれず、中にいた人の多くが助かったといわれます。地盤が建物の «土台» であることを示す例です。","昭和大橋の落橋は、橋げたをのせる部分が地盤の変形でずれたことが原因とされ、のちの橋の «落ちない工夫» の研究につながりました。","石油タンクの火災は長く燃えつづけ、消し止めるまでに何日もかかりました。石油施設の地震対策が見直されるきっかけになりました。","1966年の «地震保険に関する法律» は、新潟地震を受けて、国が保険会社と協力して地震の被害を補う制度として生まれました。"],"look":["信濃川ぞいの川岸町・昭和大橋周辺（当時の被害の場所）","萬代橋（地震にたえた古い橋）","新潟市の資料館・図書館で当時の写真や記録を見る","防災・液状化の説明パネルがある施設"],"q":["新潟地震で、砂の地面が水とまざって建物を支えられなくなる現象を何という？","«液状化»。川岸町のアパートが横にたおれた原因として、世界中で研究されるようになりました。"],"koji":[],"myth":"","img":["液状化現象","昭和大橋","地震保険"],"wp":"新潟地震","rel":{"ev":[],"grave":[]},"ph":[["c:4/42/Liquefaction_at_Niigata.JPG",500,297,"液状化現象"]]},{"id":"15_yamakoshi","n":"山古志（中越地震の被災と復興）","yomi":"やまこし","cat":"事件","rank":"A","y":2004,"era":["heisei"],"sh":"","ad":"長岡市山古志地区（旧山古志村）","st":"JR長岡駅から車で約40分。路線バスもあるが本数が少ない","la":37.315,"lo":138.895,"hook":"全村の人がヘリコプターで村を離れた。それでも人びとは «帰ろう» と言った。錦鯉と棚田の村の再生の物語。","lead":"2004年10月23日の新潟県中越地震で、山古志村は道がすべて寸断され、全村避難となりました。川がせき止められて集落が水にしずみ、人びとは長い避難生活を送りました。それでも多くの人がふるさとに戻り、棚田と錦鯉、牛の角突きの村を立て直しました。","story":["山古志は、長岡の東にひろがる山あいの村でした。急な斜面に棚田と、鯉を育てる «棚池» が段々に並び、錦鯉のふるさととして世界に知られていました。2004年10月23日、夕方5時56分。中越地方を大きなゆれがおそいます。最大震度7。山古志のまわりの山は、いたるところでくずれ落ちました。","道路はすべて寸断され、村は陸の孤島になりました。«このままでは村に人を残せない» 。村長の決断で、村の人たちは自衛隊のヘリコプターで村を離れ、長岡市内の避難所へ移りました。全村避難です。家族同然の牛や鯉を残していく人たちの胸の内は、どれほどつらかったでしょう。","村の中を流れる芋川では、くずれた土砂が川をせき止め、«天然ダム» ができました。水位はどんどん上がり、東竹沢の木籠（こごも）集落の家々が水につかっていきました。それでも人びとは、仮設住宅でも近所どうしで暮らすくふうをし、«山古志に帰ろう» と話し合いつづけました。","2005年、山古志村は長岡市に合併します。道路や棚田、棚池が少しずつ直され、2007年には避難指示がすべて解除されました。人びとは戻り、牛の角突きも復活しました。水につかった木籠の家は、あえてそのまま残され、地震の記憶を伝える場所になっています。","地震で亡くなった方は中越地方全体で68人（災害関連死をふくむ）。山古志を訪れたら、復興の歩みを伝える施設に立ちより、失われたものと、取り戻したものの両方に思いをよせてみてください。"],"tl":[["2004年10月23日","新潟県中越地震（M6.8、最大震度7）"],["2004年10月","山古志村が全村避難。芋川に天然ダムができる"],["2005年4月","山古志村が長岡市に合併"],["2007年","避難指示がすべて解除され、帰村が進む"],["その後","木籠の水没家屋を保存。復興を伝える施設がつくられる"]],"who":[["長島忠美","当時の山古志村長。全村避難を決め、復興を率いた"],["山古志の人びと","避難生活をへて村へ戻り、暮らしを立て直した"],["自衛隊・支援の人びと","ヘリでの避難や復旧にあたった"]],"deep":["中越地震では川口町（現長岡市）で震度7が観測されました。震度計の記録で震度7が確かめられたのは、このときが初めてです。","芋川の河道閉塞（天然ダム）は複数できたといわれ、決壊をふせぐため、排水ポンプや水路づくりの工事が急いで行われました。","木籠集落の水没家屋は «木籠メモリアルパーク» として保存され、地震の爪あとを伝えています。","山古志は錦鯉発祥の地といわれ、江戸時代に食用の鯉から色のちがう鯉が生まれたのが始まりと伝わります。今は世界中にファンがいます。","«牛の角突き» は国の重要無形民俗文化財（«牛の角突きの習俗»）で、地震のあとも牛を救い出し、行事を守りぬきました。勝ち負けをつけない «引き分け» にするのが特徴です。"],"look":["木籠メモリアルパーク（水につかった家々）","棚田・棚池の景色","牛の角突き（開催日は要確認）","復興を伝える交流施設"],"q":["山古志の «牛の角突き» では、ふつう勝ち負けをどうする？","勝負をつけず «引き分け» にするのがならわし。大切な牛を傷つけないためといわれます。"],"koji":[],"myth":"錦鯉の起源は伝承。","img":["新潟県中越地震","牛の角突き","錦鯉"],"wp":"山古志村","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Bullfighting_in_Yamakoshi%2C_Nagaoka_04.jpg",1280,738,"山古志村"],["c:8/84/Chuetsu_earthquake-Yamabe_Bridge.jpg",1766,1325,"新潟県中越地震"],["c:1/10/Ojiya_Nishikigoi_no_Sato_ac_%283%29.jpg",6016,4000,"錦鯉"]]},{"id":"15_seki_kawa_seki","n":"関川関所（北国街道の関所）","yomi":"せきかわせきしょ","cat":"街道","rank":"B","y":1650,"era":["edo"],"sh":"","ad":"妙高市関川","st":"えちごトキめき鉄道 妙高高原駅から車で約5分（歩くと約20〜30分）","la":36.856,"lo":138.196,"hook":"«入り鉄砲に出女»――越後と信濃の境、川一本をはさんで、旅人は手形と身なりをきびしく調べられた。","lead":"関川関所は、北国街道の越後と信濃の国境に置かれた江戸時代の関所です。高田藩が守り、通る人の手形を調べました。いまは «道の歴史館» として関所のようすが復元され、当時の旅を体験できます。","story":["妙高山のふもと、関川という川が越後と信濃の境になっています。川にかかる橋をわたると、そこはもう別の国。江戸時代、この境に置かれたのが関川関所です。北国街道を通る人は、だれでもここで止められ、通行手形を見せなければなりませんでした。","関所がとくにきびしく見はったのは «入り鉄砲に出女» といわれます。江戸へ持ちこまれる鉄砲と、江戸から出ていく女性です。大名の妻は人質として江戸に住むきまりだったので、ひそかに国へ逃げ帰ることがないよう、女性の旅は念入りに調べられました。«なぜ女の人だけ?» それは、幕府が大名の反乱をなによりおそれていたからです。","関所には番所があり、役人が旅人の名前、行き先、手形の中身を確かめました。女性の場合は «改め女（あらためおんな）» と呼ばれる女性が、髪の中まで調べたといわれます。関所をさけて山道をぬける «関所やぶり» は重い罪でした。","この街道は、佐渡の金銀を江戸へ運ぶ道でもあり、加賀藩の大名行列も通りました。すぐ南の信濃・柏原は俳人・小林一茶のふるさとです。江戸と故郷を行き来した一茶も、この関所を通ったことでしょう。","明治のはじめに関所は廃止されました。いまは «関川関所 道の歴史館» として番所が復元され、人形や展示で旅のようすがわかります。雪の多い季節は、ここがどれほどきびしい国境だったかも想像してみてください。"],"tl":[["江戸時代初め","高田藩が関川に関所を置く（設置年は諸説）"],["江戸時代","北国街道の関所として旅人を調べる。佐渡の金銀輸送も通る"],["1763年","小林一茶が信濃・柏原で生まれる"],["1869年","関所が廃止される"],["平成時代","«関川関所 道の歴史館» として復元・公開"]],"who":[["高田藩","関所を管理した藩"],["小林一茶","近くの柏原生まれの俳人"],["改め女","女性の旅人の身なりを調べた役目の女性"],["加賀藩前田家","参勤交代で北国街道を使うことがあった"]],"deep":["関川関所は、信濃側の関所と対になって国境を守ったといわれます。北国街道の中でも重要な関所の一つでした。","«手形» には旅人の名前・住所・行き先・目的が書かれ、女性用の «女手形» はとくに細かく、髪型やほくろまで書くことがあったといわれます。","関所の «改め» は、役人の判断で通せるかどうかが決まるため、手形の書き方に不備があると通れず、何日も足止めされることもありました。","関所の設置年や、建物の細かな姿については記録によって異なり、復元は絵図や記録をもとにした推定をふくみます。","妙高のこのあたりは冬に数メートルの雪がつもる豪雪地です。冬の街道は雪を踏み固めて道をつくり、旅人を通しました。"],"look":["復元された番所と関所の門","関川にかかる橋（越後と信濃の境）","道の歴史館の展示（手形・旅道具）","近くの北国街道の旧道"],"q":["関所がとくに見はったといわれる «入り鉄砲に出女»。«出女» とはだれのこと？","江戸から国もとへ出ていく女性。人質として江戸にいる大名の妻が逃げ帰らないよう、きびしく調べました。"],"koji":[{"w":"入り鉄砲に出女","m":"江戸へ入る鉄砲と、江戸から出る女性をとくにきびしく調べた、関所の取りしまりを表すことば"}],"myth":"設置年、女性の改めの細部には諸説。一茶が通ったことは推測。","img":["関所","北国街道","小林一茶","通行手形"],"wp":"関川関所","rel":{"ev":[],"grave":[]},"ph":[["c:7/7f/Ishibe_shukubanosato02s3200.jpg",3200,1800,"関所"],["c:b/bd/Kobayashi_Issa-Portrait.jpg",224,356,"小林一茶"]]},{"id":"15_chikuni","n":"塩の道・千国街道（糸魚川起点）","yomi":"しおのみち・ちくにかいどう","cat":"街道","rank":"B","y":1568,"era":["muromachi","edo"],"sh":"","ad":"糸魚川市（市街地〜根知谷）","st":"JR・えちごトキめき鉄道 糸魚川駅から起点付近へ歩いてすぐ。根知谷の旧道へは車が便利","la":37.039,"lo":137.862,"hook":"海のない信濃へ、塩は牛の背と人の背で運ばれた。«敵に塩を送る» の舞台と伝わる、山ごえの道。","lead":"千国街道は、日本海の糸魚川から信濃の松本までを結んだ道です。海の塩や魚を山国へ、山の麻やたばこを海へ運んだので «塩の道» と呼ばれます。上杉謙信が武田信玄に塩を送ったという話の舞台とも伝わります。","story":["人は塩がないと生きていけません。けれど海のない信濃（長野県）では、塩をつくることができませんでした。そこで日本海の糸魚川から、姫川ぞいの谷を通り、山をいくつも越えて松本まで塩を運びました。これが千国街道、«塩の道» です。","塩を運んだのは、牛と «ボッカ（歩荷）» と呼ばれる人たちでした。牛方は何頭もの牛をつれ、ボッカは背中に重い荷を背負って、雪の残る峠を歩きました。冬の深い雪で牛が通れない季節は、人の力だけが頼りだったといわれます。道ぞいには牛方が泊まる宿や、旅の安全を祈る石仏が残っています。","戦国時代、甲斐の武田信玄は、今川氏と北条氏から «塩止め» にあい、困ってしまったと伝わります。そのとき、ライバルの上杉謙信が «争うのは弓矢で、米や塩ではない» と、越後の塩を送ったというのです。これが «敵に塩を送る» のもとになった話です。","«本当に謙信は塩を送ったの?» じつは、確かな史料は見つかっていません。江戸時代の軍記物などで広まった話と考えられています。それでも、松本では塩が届いたことを祝ったのが始まりとされる «あめ市» が毎年1月に開かれ、この物語は人びとに愛されてきました。","いま糸魚川から根知谷をたどると、旧道の石畳や道祖神、関所の跡などが点々とあります。一歩ずつ山道を登ると、重い塩を背負って歩いた人たちのがんばりが身にしみてわかります。"],"tl":[["古代〜中世","日本海と信濃を結ぶ交易路として使われる"],["1567〜1568年ごろ","今川・北条の塩止めと、謙信が塩を送ったという話が生まれた時期とされる"],["江戸時代","松本藩などが管理し、塩や海産物の運搬がさかんに"],["明治以降","道路・鉄道の整備で役目を終える"],["昭和末〜平成","«塩の道» として旧道が整備され、歩く人がふえる"]],"who":[["上杉謙信","武田信玄に塩を送ったと伝わる"],["武田信玄","今川・北条に塩止めをされたといわれる甲斐の大名"],["牛方・ボッカ","牛や人の背で荷を運んだ人びと"]],"deep":["«千国» の名は、長野県小谷村の千国にあった番所の地名から。街道の距離は約30里（約120km）といわれます。","謙信の塩の話は、同時代の確かな史料では確かめられず、江戸時代の軍記や逸話集で広まったと考えられています。","松本の «あめ市» は、塩が届いたことを祝った «塩市» が始まりと伝わり、今も1月に開かれます。これも伝承です。","牛は荷をつんだまま道ばたで休めるよう、牛方は «牛つなぎ石» や牛の水飲み場をつくりました。道ぞいに残る石造物はその名残です。","糸魚川はヒスイの産地でもあり、縄文時代からヒスイが各地へ運ばれました。塩の道のルートは、それより古い «ヒスイの道» と重なるとみる人もいます。"],"look":["根知谷の旧道と石畳","道ばたの石仏・道祖神","関所・番所の跡","糸魚川市街の街道起点の案内"],"q":["塩の道で、背中に荷物を背負って運んだ人を何という？","«ボッカ（歩荷）»。牛が通れない雪の季節などは、人の背だけが頼りでした。"],"koji":[{"w":"敵に塩を送る","m":"争っている相手でも、困っているときには助けること。謙信と信玄の逸話がもとといわれる"}],"myth":"謙信が信玄に塩を送った話・あめ市の由来は伝承で、史料では確かめられない。","img":["敵に塩を送る","上杉謙信","武田信玄"],"wp":"千国街道","rel":{"ev":[],"grave":[]},"ph":[["c:7/7e/Shio-no-michi_Museum.jpg",900,609,"千国街道"],["c:6/6d/Ushi-tsunagi-ishi01s2010.jpg",2010,1340,"敵に塩を送る"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"]]},{"id":"15_amatsu","n":"天津神社（糸魚川・越後一宮）","yomi":"あまつじんじゃ","cat":"寺社","rank":"B","y":800,"era":["heian","edo"],"sh":"","ad":"糸魚川市一の宮","st":"JR・えちごトキめき鉄道 糸魚川駅から歩いて約10分","la":37.04,"lo":137.868,"hook":"春の «けんか祭り» で、2台の神輿が激しくぶつかりあう。ヒスイの女神・奴奈川姫の伝説がねむる、糸魚川の一宮。","lead":"天津神社は、糸魚川の町の中にある古い神社で、越後国の «一宮» と伝わります。同じ境内には、ヒスイの女神ともいわれる奴奈川姫をまつる奴奈川神社があります。毎年4月の «けんか祭り» と舞楽で知られます。","story":["糸魚川駅から少し歩くと、大きな木にかこまれた天津神社があります。ここは地元で «一の宮さん» と呼ばれ、越後国でいちばん格の高い神社の一つとされてきました。越後には一宮を名のる神社がいくつかあり、«どこが本当の一宮?» という話題は、歴史好きのあいだで今もつきません。","同じ境内の奴奈川神社にまつられるのは奴奈川姫です。『古事記』には、出雲の大国主命が越の国の沼河比売（ぬなかわひめ）に求婚しに来て、歌をかわす場面があります。«沼河» は糸魚川の姫川のあたりだと考えられ、姫はヒスイの女神ともいわれます。糸魚川は、日本でヒスイがとれる数少ない土地なのです。","毎年4月10日の春の大祭は «けんか祭り» と呼ばれます。2つの地区が担ぐ神輿が、境内で何度もぶつかり合い、押し合います。どちらが勝つかで、その年の豊作や豊漁をうらなったといわれます。見ている人も思わず力が入る、迫力満点の祭りです。","けんか祭りのあとには、舞台で «舞楽» が奉納されます。都から伝わったといわれる古い舞で、子どもたちがきらびやかな衣装と面をつけて舞います。糸魚川の舞楽は、能生の白山神社の舞楽とともに、国の重要無形民俗文化財に指定されています。","荒々しい神輿と、しずかで優雅な舞楽。対照的な二つが一日に見られるのが、天津神社の春です。ヒスイの女神の伝説とあわせて、古代から続く «越の国» の文化を感じてみてください。"],"tl":[["古代","創建と伝わる（年代ははっきりしない）"],["平安時代","越後の一宮の一つとして信仰されたといわれる"],["江戸時代","糸魚川藩の保護を受ける"],["昭和時代","«糸魚川・能生の舞楽» が国の重要無形民俗文化財に指定される"],["毎年4月10日","春の大祭（けんか祭り）と舞楽の奉納"]],"who":[["奴奈川姫","『古事記』の沼河比売。境内の奴奈川神社にまつられる。ヒスイの女神ともいわれる"],["大国主命","奴奈川姫に求婚したと『古事記』に描かれる出雲の神"],["糸魚川の氏子たち","けんか祭りと舞楽を守り伝えてきた人びと"]],"deep":["越後の一宮は、天津神社のほか、弥彦神社（彌彦神社）や上越市の居多神社も名のっており、諸説があります。時代によって扱いが変わったと考えられます。","『古事記』の «八千矛神（大国主）と沼河比売の歌» は、古代の越と出雲のつながりを示すものとして注目されています。","糸魚川のヒスイは縄文時代から加工され、遠く各地の遺跡から見つかっています。昭和の初めに «再発見» されるまで、国内でヒスイがとれることは忘れられていました。","けんか祭りの神輿は、押し合ったあと、境内を走り回って拝殿へかけこむといわれ、その勢いは見ものです。","舞楽は稚児（子ども）の舞が中心で、演目の中には大阪の四天王寺から伝わったとされるものもあるといわれます。"],"look":["天津神社の社殿と境内の大木","奴奈川神社（奴奈川姫をまつる）","4月10日のけんか祭りと舞楽（開催日確認を）","糸魚川のヒスイの展示施設"],"q":["『古事記』で、出雲の大国主命が求婚しに来た越の国の姫の名前は？","沼河比売（ぬなかわひめ）。天津神社の境内の奴奈川神社にまつられ、ヒスイの女神ともいわれます。"],"koji":[],"myth":"一宮の位置づけ、奴奈川姫とヒスイの結びつき、舞楽の伝来は伝承・諸説。","img":["奴奈川姫","ヒスイ","越後国"],"wp":"天津神社","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Suwa_taisha_Shimosha_Harumiya_%2C_%E8%AB%8F%E8%A8%AA%E5%A4%A7%E7%A4%BE_%E4%B8%8B%E7%A4%BE_%E6%98%A5%E5%AE%AE_%E5%AD%90%E5%AE%89%E7%A4%BE_-_panoramio.jpg",2400,1600,"奴奈川姫"],["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"ヒスイ"]]},{"id":"15_watatsu","n":"度津神社（佐渡一宮）","yomi":"わたつじんじゃ","cat":"寺社","rank":"B","y":900,"era":["heian","edo"],"sh":"","ad":"佐渡市羽茂飯岡","st":"小木港から車で約15分。両津港からは車で約1時間","la":37.848,"lo":138.352,"hook":"海をわたる神、木を植える神。島の人びとは、この社に航海の安全と山の恵みを祈ってきた。","lead":"度津神社は、佐渡の南部・羽茂にある佐渡国の一宮です。平安時代の『延喜式』に名がのる古い神社で、木の神・海をわたる神とされる五十猛命（いたけるのみこと）をまつります。緑の山にかこまれた静かな社です。","story":["佐渡の南、羽茂川の流れる谷に、度津神社はあります。«わたつ» という名前は、«海をわたる港» を意味するともいわれます。四方を海にかこまれた佐渡の人びとにとって、海を無事にわたることは、なによりの願いでした。","まつられているのは五十猛命。『日本書紀』には、父のスサノオといっしょに木の種を持って天からくだり、日本じゅうの山に木を植えて緑にしたという話がのっています。«なぜ木の神が島の一宮に?» 船をつくるには木が必要です。海をわたる力と山の恵み、その両方を守る神として、佐渡の人びとにたよられたのかもしれません。","平安時代にまとめられた『延喜式』の神名帳には、佐渡国の神社として度津神社の名があります。このなかで佐渡の «一宮» とされ、国の役人も重んじた神社だったと考えられています。","神社の伝えでは、昔は羽茂川の近くにありましたが、大水で流され、いまの場所に移ったといわれます。戦国時代には羽茂の本間氏が近くに城をかまえ、この神社もその領地の大切な社でした。","佐渡は古代から «国» として扱われ、国府や国分寺が置かれました。都から役人が来ると、まず国の大切な神社を順にお参りするのがならわしで、その最初にお参りするのが «一宮» だったといわれます。遠い海の向こうの島でも、都と同じしくみで神さまがまつられていたのです。度津神社は、その佐渡の神社の «代表» として、長いあいだ島の人びとと国の役人の両方から大切にされてきました。","境内は大きな木にかこまれ、鳥の声と川の音だけが聞こえます。佐渡の «一宮» という重い名とはうらはらに、あたたかく素朴な村の社の雰囲気です。春の例祭には、島の芸能が奉納されることもあります。"],"tl":[["古代","創建と伝わる（年代は不明）"],["927年","『延喜式』神名帳に度津神社の名がのる（佐渡国羽茂郡）"],["中世","佐渡国の一宮として信仰される"],["戦国時代","羽茂本間氏の領地の社として大切にされる"],["江戸時代","佐渡奉行所の支配のもとで崇敬を受ける"]],"who":[["五十猛命","まつられている神。木を植えた神、海をわたる神とされる"],["スサノオ","五十猛命の父とされる神"],["羽茂本間氏","近くに城をかまえた戦国時代の領主"]],"deep":["『延喜式』神名帳には佐渡国の神社が9座のっており、度津神社はその一つで、格の高い社として扱われました。","«度津» は «渡津（わたりのつ）»、つまり渡し場の意味とする説があり、海上交通との結びつきが考えられています。","五十猛命は和歌山の伊太祁曽神社などでもまつられる «木の神» で、林業や造船の神としても信仰されます。","神社の移転の話は社伝によるもので、移った年代や元の場所ははっきりしていません。","近くの羽茂地区には、羽茂本間氏の羽茂城跡があり、中世の佐渡南部の中心地でした。","佐渡の神社の «一宮・二宮» といった序列は、時代によって伝えがちがい、はっきりしない部分があります。一宮という呼び名自体、平安時代後期ごろから広まったと考えられています。"],"look":["大木にかこまれた社殿と参道","羽茂川ぞいの景色","近くの羽茂城跡","小木の港町・宿根木もあわせて","境内の古い石灯籠や狛犬（奉納した人や年を刻んだ文字を探してみよう）"],"q":["度津神社にまつられる五十猛命は、神話でどんなことをした神？","父スサノオとともに木の種をまき、日本の山を緑にしたと『日本書紀』に書かれています。"],"koji":[],"myth":"社名の由来・移転の話は社伝・諸説。","img":["五十猛神","延喜式神名帳","一宮"],"wp":"度津神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fc/Watatsu-jinja.JPG",2352,1568,"度津神社"],["c:9/99/Isotakeru_shinbutsu-zue.jpg",993,1324,"五十猛神"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"15_hamochi_jo","n":"羽茂城（羽茂本間氏）","yomi":"はもちじょう","cat":"城","rank":"B","y":1589,"era":["muromachi","azuchi"],"sh":"","ad":"佐渡市羽茂本郷","st":"小木港から車で約15分。城跡は山の中で、足もとに注意","la":37.84,"lo":138.345,"hook":"上杉の大軍がせまる中、佐渡南部の王は最後まで城を守ろうとした。島の中世が終わった場所の一つ。","lead":"羽茂城は、戦国時代に佐渡の南部を治めた羽茂本間氏の城です。本間一族の中でも力の強い家でしたが、1589年、上杉景勝が佐渡に攻めこむとほろびました。いまは山の中に曲輪（くるわ）や堀のあとが残ります。","story":["戦国時代の佐渡は、ひとつの国なのに «小さな戦国時代» のようでした。守護代の本間氏が一族に分かれ、雑太、河原田、羽茂、沢根などにそれぞれ城をかまえ、土地や金銀山をめぐって争っていたのです。羽茂本間氏は島の南部をおさえ、小木の港や海の道にも力をもっていました。","とくに激しかったのが、北の河原田本間氏との争いです。両家は何度も兵をぶつけ、島の人びとは戦いにまきこまれました。«同じ本間の一族なのに、なぜ争うの?» 金銀山や港からあがる富が大きかったからだとも考えられます。島の中の小さな争いでも、戦う人びとにとっては命がけでした。田畑は荒れ、港を行き来する船も止まったことでしょう。","そのころ本土では、豊臣秀吉が天下をまとめようとしていました。越後の上杉景勝は秀吉の許しを得て、1589年、佐渡に大軍を送ります。本間一族はばらばらで、まとまって戦うことができませんでした。河原田が落ち、やがて羽茂城もせめられます。","羽茂の城主・本間高貞は城を捨てて逃れようとしましたが、とらえられて処刑されたと伝わります。こうして鎌倉時代から続いた本間氏の佐渡支配は終わり、島は上杉の、そして江戸時代には幕府の直轄地となって、金銀山の島へと生まれ変わっていきます。","いま羽茂城跡を歩くと、山の尾根を切った堀や、平らにならした曲輪のあとが見られます。木々の間から見える羽茂の里と海をながめ、島の武士たちが守ろうとしたものを想像してみてください。"],"tl":[["室町時代","本間氏の一族が羽茂に入り、城をきずいたとされる"],["戦国時代","河原田本間氏とたびたび争う"],["1589年","上杉景勝の佐渡攻め。羽茂城が落ち、本間高貞が処刑されたと伝わる"],["1600年ごろ","佐渡は徳川の支配となり、のちに幕府の直轄地に"]],"who":[["本間高貞","羽茂城の最後の城主と伝わる"],["河原田本間氏","羽茂本間氏と争った本間一族"],["上杉景勝","1589年に佐渡を攻め、本間氏をほろぼした"],["直江兼続","景勝の重臣。佐渡攻めにかかわったといわれる"]],"deep":["羽茂城は山の尾根を利用した山城で、曲輪・堀切・土塁などのあとが確認されています。石垣を多用しない、中世の土の城です。","羽茂本間氏と河原田本間氏の争いは、佐渡の戦国時代の中心的なできごとでした。細かい合戦の年や経過は史料によってちがいます。","1589年の佐渡攻めでは、上杉軍は小木方面から上陸したともいわれますが、上陸地点には諸説があります。","本間高貞の最期（処刑の場所や経過）は伝承によるところが多く、はっきりしません。","近くには佐渡一宮の度津神社があり、羽茂が中世佐渡の南部の中心だったことがわかります。","本間氏の一族は、佐渡の各地に城や館をもち、地名を名字のように使って «雑太本間» «河原田本間» «羽茂本間» などと呼び分けられています。これは後世の研究で使われる呼び名でもあります。"],"look":["曲輪・堀切のあと","城跡から見る羽茂の里と海","近くの度津神社","羽茂の町並みと能舞台","羽茂の里に残る寺社（中世の本間氏の保護を受けたと伝わるもの）"],"q":["1589年、佐渡に攻めこんで本間氏をほろぼした越後の大名はだれ？","上杉景勝。豊臣秀吉の許しを得て佐渡を攻めたといわれます。"],"koji":[],"myth":"本間高貞の最期、上陸地点、築城年は伝承・諸説。","img":["本間氏","上杉景勝","佐渡国"],"wp":"羽茂城","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"]]},{"id":"15_kawarada_jo","n":"河原田城（河原田本間氏）","yomi":"かわらだじょう","cat":"城","rank":"B","y":1589,"era":["muromachi","azuchi"],"sh":"","ad":"佐渡市河原田","st":"両津港から車で約30分。佐和田地区の中心部","la":38.03,"lo":138.365,"hook":"佐渡でいちばん勇ましかったといわれる本間の一族。最後の城主は、上杉の大軍を前に城と運命をともにしたと伝わる。","lead":"河原田城は、戦国時代に佐渡の中部・西側を治めた河原田本間氏の城です。«獅子ヶ城» の名でも呼ばれました。1589年、上杉景勝の佐渡攻めで落城し、いまは城跡のまわりが学校などになっています。","story":["佐渡の真野湾に面した河原田は、島のまん中の国仲平野と、金銀山のある北西部をつなぐ要の土地でした。ここに城をかまえたのが本間一族の河原田本間氏です。のちに相川の金山が開かれる地域にも近く、この家は島の中でも大きな力をもつようになりました。","河原田本間氏は、南の羽茂本間氏としばしば争いました。どちらも本間の一族ですが、島の覇権をめぐってゆずりません。«一族なのに、なぜ争いが絶えなかったの?» 本家の雑太本間氏の力が弱まり、分家どうしが «だれが佐渡の主か» をきそったからだと考えられます。","河原田の城は、海に近い台地の上にきずかれ、湾を行き来する船を見はることができました。城の名 «獅子ヶ城» は、城のある地形が獅子のように見えたからとも伝わります。海と平野の両方をにらむ、佐渡の戦国の城らしい場所です。","1589年、豊臣秀吉の許しを得た上杉景勝が、佐渡に大軍を送りこみます。佐渡の本間氏は一つにまとまれず、河原田城も上杉軍に囲まれました。城主の本間高統は、城に火を放ち自害したと伝わります。島の武士としての誇りを守ったとも、追いつめられた末の最期だったともいえるでしょう。","いまの城跡は学校の敷地などになり、昔の姿はほとんど残っていません。それでも、台地の上から真野湾をながめると、なぜここに城がきずかれたのかがよくわかります。説明板や碑を探しながら歩いてみましょう。"],"tl":[["室町時代","本間一族が河原田に入り、城をきずいたとされる"],["戦国時代","羽茂本間氏とたびたび争う"],["1589年","上杉景勝の佐渡攻めで落城。城主の本間高統が自害したと伝わる"],["江戸時代","佐渡は幕府の直轄地に。城は使われなくなる"],["近代以降","城跡が学校などの敷地になる"]],"who":[["本間高統","河原田城の最後の城主と伝わる"],["羽茂本間氏","河原田本間氏と争った一族"],["上杉景勝","1589年に佐渡を攻め、河原田城を落とした"],["直江兼続","景勝の重臣。佐渡攻めにかかわったといわれる"]],"deep":["河原田城は «獅子ヶ城» の名でも知られます。名前の由来は地形説などがありますが、はっきりしません。","城跡は現在、県立佐渡高校の敷地などになっているといわれ、遺構はわずかです。見学のときは学校の敷地に入らないよう注意しましょう。","河原田本間氏は沢根本間氏などとも結びつき、北西部の鉱山地帯に近い位置をおさえていました。鶴子銀山の開発とも関係があったと考えられます。","本間高統の最期の様子は後世の記録や伝承によるもので、細部は確かではありません。","佐渡の戦国時代の本間一族の系図は、史料によって名前や続柄が食いちがうことが多く、研究者のあいだでも議論があります。"],"look":["城跡の台地（学校まわりの説明板・碑）","台地から見る真野湾","近くの佐和田の町並み","あわせて鶴子銀山跡や相川の金山へ"],"q":["河原田城の別名は？","«獅子ヶ城»。地形が獅子に見えたからなど、名の由来には諸説があります。"],"koji":[],"myth":"別名の由来、本間高統の最期、城跡の範囲は伝承・諸説。","img":["本間氏","上杉景勝","佐渡国"],"wp":"河原田城","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"]]},{"id":"15_arato_jo","n":"荒戸城（御館の乱の境目の城）","yomi":"あらとじょう","cat":"城","rank":"B","y":1578,"era":["azuchi"],"sh":"","ad":"南魚沼郡湯沢町神立","st":"JR越後湯沢駅から車で約15分。城跡へは山道を歩く","la":36.953,"lo":138.823,"hook":"関東から北条の大軍が来る――景勝は峠の道に、わずかの間で城をつくらせた。雪がすべてを決めた戦い。","lead":"荒戸城は、1578年に上杉謙信が亡くなったあとの跡目争い «御館の乱» のとき、上杉景勝が三国街道を守るためにきずいた山城です。関東の北条軍を食い止める «境目の城» でした。土を掘って固めた堀や土塁のあとが、よく残っています。","story":["1578年春、上杉謙信が春日山城で急に亡くなりました。謙信には実の子がなく、二人の養子がいました。姉の子である景勝と、北条氏康の子である景虎です。«だれが謙信の跡をつぐのか?» 家臣は二つに分かれ、越後じゅうを巻きこむ戦い、«御館の乱» が始まりました。","景虎の実家・北条氏は関東の大大名です。弟を助けるため、北条の軍が三国峠をこえて越後へ攻めこんでくるおそれがありました。景勝は、自分のふるさとでもある魚沼の坂戸城を守るため、三国街道の要所に急いで城をきずかせます。それが荒戸城です。","城は、街道を見下ろす山の上にありました。石垣はなく、山を削って平らな曲輪をつくり、深い堀と土塁でかためた «土の城» です。«短い時間で、どうやって強い城をつくったの?» 地形をたくみに利用し、敵が登ってくる道をせまく曲げて、上から攻撃できるようにしたのです。","北条軍は三国峠をこえて越後に入り、荒戸城を落としたとも伝わります。さらに坂戸城にせまりましたが、守りは固く、やがて雪の季節が来ます。雪深い魚沼で冬を越すことはできず、北条軍は関東へ引き上げました。«越後の雪» が景勝を助けたのです。翌年、景虎は敗れ、景勝が謙信の跡をつぎました。","いま城跡の山を歩くと、深い堀や、曲がりくねった道のあとがはっきり見られます。短い期間しか使われなかったからこそ、戦国の «境目の城» の姿がそのまま残った、めずらしい城跡です。"],"tl":[["1578年3月","上杉謙信が亡くなる"],["1578年","御館の乱が始まる。景勝が荒戸城をきずく"],["1578年秋","北条軍が三国峠をこえて越後に入る。荒戸城を落としたとも伝わる"],["1578年冬","雪のため北条軍が関東へ引き上げる"],["1579年","景虎が敗れて自害し、景勝が上杉家をつぐ"]],"who":[["上杉景勝","謙信の養子。荒戸城をきずかせ、御館の乱に勝った"],["上杉景虎","北条氏康の子で謙信の養子。景勝と争い敗れた"],["北条氏","景虎の実家。越後へ援軍を送った"],["上杉謙信","越後の大名。その死が乱のきっかけになった"]],"deep":["荒戸城は、築城から廃城までの期間が短かったと考えられ、戦国末期の山城の «設計図» がそのまま残っている例として評価されています。","城は三国街道と清水峠方面の道を見はる位置にあり、北条軍の侵入路をふさぐ役目をもっていました。","北条軍が荒戸城を落としたかどうか、どのくらいの期間占領したかは史料によって書き方がちがい、諸説があります。","城の縄張り（設計）には、敵の進む方向を曲げる «折れ» や、出入り口をせまくする工夫が見られます。","坂戸城は景勝の生まれた城で、上田長尾氏の本拠でした。荒戸城はその «前線の砦» だったといえます。"],"look":["深い空堀と土塁","曲輪の平らな面と、曲がった通路のあと","城跡から見る三国街道の谷","あわせて南魚沼市の坂戸城跡へ"],"q":["御館の乱で、上杉景勝と跡目を争ったもう一人の養子はだれ？","上杉景虎。北条氏康の子で、乱に敗れて自害しました。"],"koji":[],"myth":"北条軍による荒戸城の攻略の有無・時期は諸説。","img":["御館の乱","上杉景勝","上杉景虎"],"wp":"荒戸城","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/%E8%8D%92%E6%88%B8%E5%9F%8E%E5%9C%9F%E5%A1%81.jpg",1600,1200,"荒戸城"],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:a/a1/%E4%B8%8A%E6%9D%89%E6%99%AF%E8%99%8E%EF%BC%88%E5%8C%97%E6%9D%A1%E4%B8%89%E9%83%8E%EF%BC%89%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1850,1536,"上杉景虎"]]},{"id":"15_akada_jo","n":"赤田城（斎藤朝信の居城）","yomi":"あかだじょう","cat":"城","rank":"B","y":1578,"era":["muromachi","azuchi"],"sh":"","ad":"刈羽郡刈羽村赤田町方","st":"JR越後線 刈羽駅から車で約10分。城跡は山道","la":37.431,"lo":138.638,"hook":"«越後の鍾馗» とたたえられた猛将は、戦場だけでなく交渉の場でも上杉を救った。その本拠の山城。","lead":"赤田城は、上杉謙信・景勝の二代につかえた重臣・斎藤朝信の城です。朝信は戦の強さで知られ、御館の乱では景勝の味方につき、武田氏との同盟の交渉にもかかわったといわれます。山の上に曲輪や堀のあとが残ります。","story":["柏崎の東、刈羽の山あいに赤田城の跡があります。ここをおさめたのが斎藤朝信です。上杉家の家臣の中でも、とくに戦上手の武将として知られ、のちの軍記物では «越後の鍾馗（しょうき）» とたたえられました。鍾馗は、悪い鬼をこらしめる中国の強い神さまです。","朝信は謙信の関東出兵や、北陸での戦いに加わったといわれます。謙信の家臣団の中で、奉行として国の政治も動かす、重く用いられた人でした。«なぜそこまで信頼されたの?» 戦いの強さに加え、冷静に物事を進める力があったからだと考えられます。","1578年、謙信が亡くなり、跡目争いの御館の乱が起こります。朝信は景勝の側につきました。このとき大きな問題は、景虎を助けようとする北条氏と、その同盟相手である甲斐の武田勝頼でした。景勝方は武田と手を結ぶ交渉を進め、朝信もその使者としてかかわったと伝わります。武田が景勝方につくと、形勢は大きく景勝に傾きました。","戦いに勝った景勝のもとでも、朝信は重臣として重んじられたといわれます。しかし豊臣秀吉の命令で上杉家が会津へ移ると、越後の城の多くは役目を終えます。赤田城もそのころに使われなくなったと考えられています。","城跡の山に登ると、尾根を断ち切った堀や、段々になった曲輪のあとが見られます。ふもとの赤田の里をながめながら、上杉家をささえた猛将の姿を思いうかべてみてください。"],"tl":[["戦国時代","斎藤氏が赤田に城をかまえる"],["謙信の時代","斎藤朝信が上杉家の重臣として活躍"],["1578年","御館の乱。朝信は景勝方につく"],["1579年","景勝が乱に勝ち、武田との同盟（甲越同盟）が結ばれる"],["1598年","上杉家が会津へ移る。赤田城はやがて使われなくなる"]],"who":[["斎藤朝信","赤田城主。上杉家の重臣で «越後の鍾馗» とたたえられた"],["上杉謙信","朝信の主君"],["上杉景勝","御館の乱で朝信が味方した"],["武田勝頼","景勝と同盟を結んだ甲斐の大名"]],"deep":["«越後の鍾馗» のあだ名は、江戸時代の軍記物などで語られたもので、同時代の史料の言葉ではないと考えられます。","甲越同盟の交渉では、上杉方から武田方へ金を贈ったといわれ、それが勝頼の態度を変えたという説があります。朝信の具体的な役割には諸説があります。","赤田城は、曲輪・堀切・土塁などをもつ中世の山城で、ふもとに館があったと考えられています。","朝信の生没年ははっきりしない部分があり、史料によって異なります。","刈羽のあたりは、柏崎の琵琶島城などとともに、越後の中部海岸を守る城のネットワークの一部だったとみられます。","御館の乱のあと、景勝は越後の武士の土地や役目を大きく入れかえました。その中で朝信のような古くからの重臣が残ったことは、景勝の政権づくりにとって大きな意味があったと考えられます。"],"look":["尾根の堀切","段になった曲輪のあと","城跡から見る赤田の里","あわせて柏崎の琵琶島城跡へ","ふもとの赤田の集落（館があったと考えられる場所の地形）"],"q":["斎藤朝信は、後の世の軍記物で何とたたえられた？","«越後の鍾馗（しょうき）»。鬼をこらしめる強い神にたとえられました。"],"koji":[],"myth":"あだ名、甲越同盟での役割、廃城年は伝承・諸説。","img":["斎藤朝信","御館の乱","甲越同盟"],"wp":"赤田城","rel":{"ev":[],"grave":[]}},{"id":"15_biwajima","n":"琵琶島城（宇佐美氏・柏崎）","yomi":"びわじまじょう","cat":"城","rank":"B","y":1550,"era":["muromachi","azuchi"],"sh":"","ad":"柏崎市元城町","st":"JR柏崎駅から歩いて約15分","la":37.37,"lo":138.552,"hook":"«謙信の軍師» として名高い宇佐美定満。でもその姿の多くは、子孫が書いた物語から生まれたものだった。","lead":"琵琶島城は、柏崎の海の近くにあった城で、上杉謙信の家臣・宇佐美定満の城と伝わります。定満は謙信の «軍師» として有名ですが、その活躍の多くは江戸時代の物語でつくられたものと考えられています。いまは住宅地の中に碑が立つだけの «跡» です。","story":["柏崎の町の中、鵜川が海に近づくあたりに、琵琶島城がありました。川と湿地にかこまれた土地が琵琶の形に見えたことから、この名がついたといわれます。ここは日本海の港にも近く、北国街道の通る、交通の要でした。","この城の主と伝わるのが宇佐美定満です。定満ははじめ謙信の父・長尾為景と対立したこともありましたが、やがて謙信（長尾景虎）につかえました。«なぜ敵だった家が味方に?» 越後の国の中では、有力な武士たちが時に争い、時に手を組みながら生き残りをはかっていたのです。","1564年、謙信の姉の夫で、景勝の父でもある長尾政景が、野尻池（坂戸城の近くとされる）で舟遊びの最中におぼれて亡くなりました。このとき定満もいっしょに水にしずんだと伝わります。«事故だったのか、それとも…?» 定満が謙信の命で政景を道づれにしたという話もありますが、確かな証拠はありません。","江戸時代、宇佐美定満の子孫を名のる宇佐美定祐（さだすけ）が、軍記物『北越軍談』などを書きました。そこでは定満が謙信の天才軍師として大活躍します。これがもとで «宇佐美流» という軍学まで生まれ、定満は «謙信の軍師» として有名になりました。しかし、その多くは史料で確かめられない話です。","いまの城跡は住宅地になり、遺構はほとんど残っていません。でも、碑の前に立ち、海と川にかこまれた昔の地形を想像すると、港町・柏崎を守った城の姿が浮かんできます。"],"tl":[["戦国時代前期","宇佐美氏が琵琶島を本拠とする"],["1530年代ごろ","宇佐美氏が長尾為景と対立したといわれる"],["謙信の時代","宇佐美定満が謙信につかえる"],["1564年","長尾政景とともに定満が野尻池でおぼれて亡くなったと伝わる"],["江戸時代","宇佐美定祐が『北越軍談』などを書き、定満の軍師伝説が広まる"]],"who":[["宇佐美定満","琵琶島城主と伝わる。謙信の «軍師» として物語で有名に"],["上杉謙信","定満の主君"],["長尾政景","景勝の父。定満とともに亡くなったと伝わる"],["宇佐美定祐","江戸時代の軍学者。定満の子孫を名のり『北越軍談』を書いた"]],"deep":["«謙信の軍師・宇佐美定満» の姿は、『北越軍談』など江戸時代の軍学書による部分が大きく、同時代の史料では確かめにくいとされます。","長尾政景の死は、事故・暗殺など諸説があり、定満が関わったとする話も後世の伝えです。場所の «野尻池» も、長野県の野尻湖ではなく坂戸城近くの池とする説が有力です。","琵琶島城の名は «琵琶島» という地形の名にちなむといわれ、城の範囲や縄張りは詳しくわかっていません。","宇佐美氏の名は «宇佐美駿河守» として史料に見えますが、実名の «定満» は同時代史料では確かでないともいわれます。","NHK大河ドラマなどでも «軍師・宇佐美» はよく描かれますが、それは物語の中の姿として楽しむのがよいでしょう。"],"look":["琵琶島城跡の碑","鵜川と海の位置関係（昔の地形を想像）","柏崎の港まわり","あわせて刈羽村の赤田城跡へ"],"q":["宇佐美定満を «謙信の軍師» として広めた江戸時代の軍記物は？","『北越軍談』。子孫を名のる宇佐美定祐が書きました。"],"koji":[],"myth":"定満の軍師像は後世の創作が多い。長尾政景の死の真相・場所、実名にも諸説。","img":["宇佐美定満","長尾政景","上杉謙信","北越軍談"],"wp":"琵琶島城","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Usami_Suruga_no_kami.jpg",800,1200,"宇佐美定満"],["c:b/bd/Nagao_Masakage_and_His_wife.jpg",2553,1446,"長尾政景"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"15_nomine_jo","n":"直峰城（春日山の支城網）","yomi":"のうみねじょう","cat":"城","rank":"B","y":1560,"era":["muromachi","azuchi"],"sh":"","ad":"上越市安塚区安塚","st":"ほくほく線 虫川大杉駅から車で約10分。城跡へは山道を歩く","la":37.13,"lo":138.428,"hook":"春日山から関東へ。謙信の軍が雪の峠を越えるとき、道を守ったのが山の上のこの城だった。","lead":"直峰城は、上越市安塚区の山の上にある戦国時代の城跡です。春日山城と関東を結ぶ道を守る «支城» として、上杉謙信のころに大切にされました。山頂からは頸城の山なみが一望でき、曲輪や堀のあとが残ります。","story":["春日山城のある上越から、東の魚沼や関東へ向かうには、いくつもの山をこえなければなりません。その道の途中、安塚の山の上にそびえるのが直峰城です。南北朝時代に南朝方の武士・風間氏がきずいたと伝わり、長い歴史をもつ山城です。","謙信の時代、上杉の軍は関東へたびたび出陣しました。«大軍が山道を安全に進むには何が必要?» 答えは、道ぞいに点々と置かれた城です。城は見はり台になり、兵や食料の中継地点になりました。直峰城は、春日山城を中心に広がる «支城網» の大切な一つだったのです。","城は尾根の上に、いくつもの曲輪を階段のように並べてつくられています。尾根を断ち切った堀切や、敵が登ってくるのを防ぐ切岸（きりぎし）が今もよくわかります。山の上からは、敵が来ればすぐに見つけられ、のろしで春日山へ知らせることもできたでしょう。","1578年の御館の乱では、上越と魚沼を結ぶこのあたりも戦いにまきこまれたと考えられます。やがて上杉家が会津へ移ると、越後には堀氏が入り、多くの城が役目を終えました。直峰城も江戸時代のはじめには使われなくなったとみられます。","いまは城跡公園として整備され、山頂まで歩いて登れます。春の桜、秋の紅葉のころは特に気持ちのよい山歩きになります。頂上に立ち、遠くの春日山の方角を探してみましょう。"],"tl":[["南北朝時代","風間氏がきずいたと伝わる"],["戦国時代","上杉氏の支城として整えられる"],["謙信の時代","関東出兵の道を守る城として重視される"],["1578年","御館の乱。周辺も争いにまきこまれたとみられる"],["1598年","上杉家が会津へ移り、堀氏が越後に入る"],["江戸時代初め","廃城となったとみられる"]],"who":[["風間信濃守","南北朝時代に城をきずいたと伝わる南朝方の武士"],["上杉謙信","城を関東への道を守る支城として用いた"],["上杉景勝","御館の乱のころの上杉家の当主"],["堀秀治","上杉家のあと越後に入った大名"]],"deep":["直峰城は、春日山城から東へ向かう道（のちの松之山街道方面）をおさえる位置にあり、支城網の «東の守り» と考えられています。","城の縄張りは尾根に曲輪を連ねる連郭式で、堀切や切岸がよく残り、中世山城の見本として紹介されます。","風間氏の築城は伝承で、南北朝時代の城の姿と、戦国時代に改修された姿がまじっていると考えられます。","城跡は «直峰城跡» として整備され、登山道や説明板が設けられています。山頂近くの本丸跡からは、晴れた日に頸城平野の方角まで見わたせます。","安塚は «雪だるま財団» や雪の宅配便で知られる豪雪地。城の暮らしも、冬の雪との戦いだったはずです。","山城は «戦うための城»、ふもとの館は «暮らすための屋敷»。ふだん城主はふもとに住み、戦のときだけ山の城にこもるのが、中世の越後の城の一般的なすがたでした。"],"look":["山頂の本丸からの眺め","尾根の堀切と切岸","階段状に並ぶ曲輪","登り口の説明板と城跡公園","ふもとの安塚の町（城下の名残の地形を探そう）"],"q":["春日山城を中心に、道ぞいなどに置かれた小さな城のつながりを何という？","«支城網»。見はりや連絡、兵の中継に使われました。"],"koji":[],"myth":"風間氏の築城は伝承。廃城の年ははっきりしない。","img":["春日山城","上杉謙信","南北朝時代 (日本)"],"wp":"直峰城","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Kasaugayama_Castle.jpg",5248,3936,"春日山城"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"15_tsugawa_jo","n":"津川城（麒麟山城・会津との境）","yomi":"つがわじょう","cat":"城","rank":"B","y":1589,"era":["kamakura","muromachi","azuchi"],"sh":"","ad":"東蒲原郡阿賀町津川","st":"JR磐越西線 津川駅から車で約5分。城跡へは麒麟山の登山道を歩く","la":37.675,"lo":139.458,"hook":"越後なのに、ここは長いあいだ «会津» だった。大河・阿賀野川を見下ろす麒麟山の上の、国境の城。","lead":"津川城は、阿賀野川と常浪川が合流する麒麟山の上にきずかれた山城です。会津の蘆名氏の重臣・金上氏がこの城を守り、越後との国境をおさえました。江戸時代も津川は会津藩の領地で、川の港としてにぎわいました。","story":["新潟から阿賀野川をさかのぼると、両岸に山がせまり、川が大きく曲がるところに、切り立った岩山が見えてきます。これが麒麟山、そして津川城の跡です。川が天然の堀となり、岩山が天然の石垣となる、まさに «天然の要害» でした。","«津川は新潟県なのに、なぜ会津なの?» じつは津川のあたりは、明治のはじめまで会津（福島県）の領地でした。鎌倉時代に会津に入った蘆名氏の一族・金上氏が津川城に入ったと伝わり、越後との境を守ったのです。越後の上杉と会津の蘆名がにらみ合う、最前線の城でした。","戦国時代の終わり、金上盛備は蘆名家の宿老として、家を支える知恵者として知られました。しかし1589年、伊達政宗が摺上原の戦いで蘆名軍を破り、盛備はこの戦いで討死したと伝わります。蘆名氏はほろび、津川城も持ち主を変えていきます。","1598年、上杉景勝が越後から会津へ移ると、津川城は上杉の城となり、重臣の藤田信吉が入りました。ところが1600年、信吉は上杉家を離れ、徳川家康のもとへ走ります。関ヶ原の戦いの直前、津川は大きな時代の波をかぶりました。城は江戸時代のはじめに役目を終えたとみられます。","その後、津川は阿賀野川の舟運の «河港» として栄え、会津の米や荷物が船で新潟へ運ばれました。麒麟山には狐火の伝説があり、毎年5月には «つがわ狐の嫁入り行列» が行われます。城跡に登り、川と町を見下ろして、国境の町の歴史を感じてみてください。"],"tl":[["鎌倉時代","金上氏が津川に城をきずいたと伝わる（1252年とする説も）"],["戦国時代","蘆名氏の越後との境の城として重視される"],["1589年","摺上原の戦いで蘆名氏がやぶれ、金上盛備が討死したと伝わる"],["1598年","上杉景勝が会津に移り、藤田信吉が津川城に入る"],["1600年","藤田信吉が上杉家を出奔し、徳川方へ"],["江戸時代","津川は会津藩の河港として栄える"],["1886年","東蒲原郡が福島県から新潟県へ移る"]],"who":[["金上盛備","蘆名氏の宿老で津川城主。摺上原で討死したと伝わる"],["伊達政宗","摺上原の戦いで蘆名氏を破った"],["上杉景勝","会津へ移り、津川城を支配下においた"],["藤田信吉","上杉家の重臣で津川城主。1600年に出奔した"]],"deep":["東蒲原郡は明治のはじめまで会津（福島県）に属し、1886年に新潟県へ移されました。津川の町に会津の文化が色こく残るのはそのためです。","津川城の築城は鎌倉時代の1252年とする伝えがありますが、同時代史料による確認はされていません。","城は麒麟山の岩山と、阿賀野川・常浪川の合流を天然の堀として利用しています。越後側から攻めるには川をわたり、けわしい岩山を登らねばならず、攻めにくい城として知られました。","藤田信吉の出奔は、上杉家が家康と対立を深めた時期のできごとで、関ヶ原の戦いへの流れの中でよく語られます。","津川は阿賀野川舟運の要で、会津からの荷を船に積みかえる港でした。«日本三大河港» の一つといわれることもあります。"],"look":["麒麟山の城跡（本丸のあと・岩場の眺め）","阿賀野川と常浪川の合流点","津川の町並み","5月の «狐の嫁入り行列»（開催日は要確認）"],"q":["津川のある東蒲原郡は、明治のはじめまでどこの領地だった？","会津（いまの福島県）。1886年に新潟県へ移されました。"],"koji":[],"myth":"築城年・金上氏の入城は伝承。«三大河港» は地元の呼び方。","img":["金上盛備","蘆名氏","藤田信吉"],"wp":"津川城","rel":{"ev":[],"grave":[]},"ph":[["c:6/69/%E3%83%8B%E3%83%8E%E6%9B%B2%E8%BC%AA%E8%B7%A1.jpg",3024,4032,"津川城"]]},{"id":"15_akadani_jo","n":"赤谷城（新発田重家の乱）","yomi":"あかだにじょう","cat":"城","rank":"B","y":1587,"era":["azuchi"],"sh":"","ad":"新発田市上赤谷","st":"JR新発田駅から車で約25分。城跡は山の中","la":37.915,"lo":139.43,"hook":"会津からの援軍の道を断て――7年にわたった «新発田重家の乱» は、この山城が落ちたことで終わりに向かった。","lead":"赤谷城は、新発田の東、会津へ向かう道ぞいの山城です。上杉景勝に反旗をひるがえした新発田重家を、会津の蘆名氏が助けるための拠点になりました。1587年、上杉軍がこの城を落とし、重家の乱は終わりへ向かいます。","story":["1578年からの御館の乱で、新発田重家は上杉景勝の側について大活躍しました。ところが戦いのあと、重家は十分なほうびをもらえなかったといわれます。«命がけで戦ったのに、なぜ?» 重家の不満は大きくなり、1581年、ついに景勝にそむいて立ち上がりました。","重家の背後には、強い味方がいました。西からせまる織田信長、そして東の会津の蘆名氏です。上杉家を弱らせたい大名たちが、重家を助けたのです。会津から新発田へ兵や食料を送る道の途中、その中継点になったのが赤谷城でした。城には蘆名氏の家臣が入って守ったと伝わります。","1582年、本能寺の変で信長がたおれると、景勝は重家に集中できるようになりました。とはいえ、新発田のあたりは低い湿地が広がり、攻めにくい土地です。重家はねばり強く戦い、乱は何年も続きました。«重家を支える会津からの道を断たなければ!» 景勝は赤谷城を攻める作戦を立てます。","1587年、上杉軍は赤谷城を攻め落としました。会津からの助けが断たれた新発田城はまもなく落城し、重家は最後の突撃ののちに討死したと伝わります。7年にわたった乱は、こうして終わりました。景勝はこのあと越後全体をまとめ、豊臣政権の大名として力を固めていきます。","いま赤谷の山に登ると、曲輪や堀のあとが森の中に残っています。会津へ続く谷を見下ろすと、この城が «援軍の道» をおさえていた意味がよくわかります。"],"tl":[["1578〜1579年","御館の乱。新発田重家は景勝方として活躍"],["1581年","重家が景勝にそむく（新発田重家の乱）"],["1582年","本能寺の変。景勝への圧力が弱まる"],["1580年代","蘆名氏が赤谷城を拠点に重家を支援"],["1587年","上杉軍が赤谷城を落とし、続いて新発田城も落城。重家が討死"]],"who":[["新発田重家","景勝にそむいた武将。7年にわたり戦った"],["上杉景勝","重家の乱をしずめ、越後をまとめた"],["蘆名氏","会津の大名。赤谷城を拠点に重家を助けた"],["小田切盛昭","蘆名氏の家臣で赤谷城を守ったと伝わる"],["織田信長","重家を支援したといわれる"]],"deep":["重家がそむいた理由は、御館の乱のほうびへの不満が大きいといわれますが、織田方からのさそいなど、複数の理由が重なったと考えられます。","赤谷は会津と越後を結ぶ道（のちの会津街道の一つ）の越後側の入り口にあたり、兵や食料の補給路として重要でした。","赤谷城を守った武将の名や、落城の月日は史料によってちがいがあり、諸説があります。","新発田のあたりは当時、潟や湿地が多く、大軍が動きにくい土地でした。これが重家が長く戦えた理由の一つとされます。","重家の乱をしずめたことで、景勝は越後統一をはたし、のちの豊臣政権のもとでの «五大老» へとつながる力を得ました。"],"look":["森の中に残る曲輪と堀のあと","城跡から見る会津方面への谷","ふもとの赤谷の集落","あわせて新発田城跡へ"],"q":["新発田重家を会津から助けた大名家はどこ？","蘆名氏。赤谷城を拠点にして、兵や食料を送ったといわれます。"],"koji":[],"myth":"城を守った武将名・落城の日付、重家の反乱理由には諸説。","img":["新発田重家","新発田重家の乱","上杉景勝","蘆名氏"],"wp":"赤谷城","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/Shibata_Shigeie.jpg",853,1280,"新発田重家"],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"]]},{"id":"15_kasugayama_jinja","n":"春日山神社（謙信を祀る）","yomi":"かすがやまじんじゃ","cat":"寺社","rank":"B","y":1901,"era":["muromachi","meiji"],"sh":"","ad":"上越市大豆（春日山城跡のふもと）","st":"えちごトキめき鉄道 春日山駅から車で約5分。バスで «春日山下» 付近から歩いて登る","la":37.1395,"lo":138.203,"hook":"謙信の城のふもとに、明治の人がつくった社。建てたのは、あの童話作家・小川未明の父だった。","lead":"春日山神社は、上杉謙信をまつる神社です。謙信の本拠・春日山城のふもとにあり、明治時代の1901年につくられました。建てたのは、童話作家・小川未明の父、小川澄晴です。","story":["戦国時代、春日山城は上杉謙信の本拠でした。謙信は «毘» の旗をかかげて戦い、«義» を重んじた武将として語りつがれています。1578年、謙信はこの城で亡くなりました。けれど、上杉家はのちに会津、そして米沢へと移り、謙信の遺体も米沢へ運ばれます。越後には謙信をまつる大きな神社がなくなってしまいました。","«謙信公のふるさとに、謙信公をまつる社がないのはさびしい» 。そう考えたのが、明治の人・小川澄晴でした。澄晴は神社をつくろうと力をつくし、1901年、春日山のふもとに春日山神社が生まれました。地元の人びとの寄付と協力にささえられての創建だったと伝わります。","澄晴の息子が、のちに『赤いろうそくと人魚』などの童話で知られる小川未明です。未明は高田の生まれで、少年時代をこの春日山の近くで過ごしました。父が謙信の神社をつくる姿を、未明はどんな思いで見ていたのでしょう。神社のまわりには未明ゆかりの場所もあります。","神社から山道を登れば、春日山城跡の本丸へ行けます。山全体が城になった巨大な山城で、国の史跡です。本丸からは直江津の海や高田平野が見わたせます。謙信が見た景色と同じ景色が、いまも広がっているのです。","毎年夏には上越市で «謙信公祭» がひらかれ、武者行列や川中島の戦いの再現が行われます。まずは春日山神社でお参りをしてから、謙信の城を歩いてみてはいかがでしょうか。"],"tl":[["1530年","長尾景虎（のちの上杉謙信）が春日山城で生まれる"],["1578年","謙信が春日山城で亡くなる"],["1598年","上杉家が会津へ移る"],["1901年","小川澄晴らにより春日山神社が創建される"],["1935年","春日山城跡が国の史跡に指定される"]],"who":[["上杉謙信","神社にまつられる戦国武将"],["小川澄晴","神社をつくった人。小川未明の父"],["小川未明","童話作家。父が神社を建てた"],["上杉景勝","謙信の跡をつぎ、のちに会津へ移った"]],"deep":["謙信の遺体は上杉家とともに会津、そして米沢へ移され、米沢の上杉家廟所にまつられています。米沢の上杉神社も謙信をまつる代表的な神社です。","春日山神社は明治時代の創建で、戦国時代からある神社ではありません。謙信の時代の宗教施設としては、城の中にあったといわれる «毘沙門堂» が知られます。","春日山城は、山全体に曲輪や堀をめぐらせた大規模な山城で、日本100名城にも選ばれています。","小川未明は «日本のアンデルセン» とよばれることもあり、上越市には未明の文学をしょうかいする施設があります。","謙信の «義» のイメージは、江戸時代の軍記物や明治以降の歴史観でさらにふくらんだ面もあり、実際の謙信は現実的な政治家でもありました。","上杉家の家紋 «竹に雀» や、謙信の旗印 «毘» «龍» は、神社や城跡周辺の案内でもよく目にします。«毘» は謙信があつく信仰した毘沙門天の一字です。"],"look":["春日山神社の社殿","山道を登って春日山城跡の本丸へ","城跡の毘沙門堂","夏の謙信公祭（開催日は要確認）"],"q":["春日山神社をつくった小川澄晴の息子で、童話作家になった人はだれ？","小川未明。『赤いろうそくと人魚』などで知られます。"],"koji":[{"w":"敵に塩を送る","m":"謙信が武田信玄に塩を送ったと伝わる逸話から。困っている相手を、敵であっても助けること（逸話は伝承）"}],"myth":"«敵に塩を送る» の逸話は伝承。謙信の «義» の人物像には後世の脚色がある。","img":["春日山城","上杉謙信","小川未明"],"wp":"春日山神社","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/Kasugayama_jinjya_1.jpg",640,480,"春日山神社"],["c:e/ea/Kasaugayama_Castle.jpg",5248,3936,"春日山城"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:9/90/Ogawa_Mimei.JPG",406,601,"小川未明"]]},{"id":"15_soma_gyofu","n":"相馬御風宅（糸魚川）","yomi":"そうまぎょふたく","cat":"近代","rank":"B","y":1916,"era":["taisho","showa"],"sh":"","ad":"糸魚川市大町","st":"JR・えちごトキめき鉄道 糸魚川駅から歩いて約5分","la":37.039,"lo":137.861,"hook":"«都の西北» も «春よ来い» も、この人の詩。東京の文壇をはなれ、ふるさとの小さな町に帰った詩人の家。","lead":"相馬御風は、糸魚川出身の詩人・文学者です。早稲田大学の校歌 «都の西北» や、童謡 «春よ来い» の歌詞を書きました。34歳でふるさとに戻り、良寛の研究にうちこみました。その住まいが今も残ります。","story":["明治の終わり、東京の早稲田大学に、糸魚川から来た若い文学青年がいました。相馬御風です。まだ20代前半の御風は、大学の校歌の歌詞を頼まれ、«都の西北 早稲田の森に» で始まる詩を書きました。いまでも全国の人が知っている、あの歌です。","御風は詩人・評論家として東京の文壇で活躍しました。劇作家の島村抱月といっしょに «カチューシャの唄» の歌詞をつくり、大流行させたことでも知られます。ところが1916年、30代なかばの御風は、とつぜん東京をはなれ、ふるさとの糸魚川に帰ってしまいます。«なぜ、人気の最中に?» 御風は、都会の文学の世界に疑問を感じ、自分の生き方を見つめ直したかったといわれます。","糸魚川に戻った御風は、江戸時代の越後の僧・良寛の研究にうちこみました。良寛の和歌や書、質素な生き方を調べ、多くの本を書いて、良寛を全国に知らせました。いまの良寛の人気は、御風の仕事に負うところが大きいといわれます。","子どもたちのための詩も書きました。«春よ来い 早く来い あるきはじめた みいちゃんが» で始まる童謡 «春よ来い» は、雪深い北国で春を待つ気持ちを歌ったものです。雪国・糸魚川に暮らしたからこそ生まれた言葉なのかもしれません。","御風は、糸魚川にヒスイが出ることに気づくきっかけをつくった人とも伝わります。古代の奴奈川姫の伝説からヒスイがあるはずだと語り、その話を聞いた人が探して、1938年、小滝川でヒスイが見つかったといいます。家の中を歩くと、書斎や庭から、ふるさとを愛した文学者の暮らしが伝わってきます。"],"tl":[["1883年","相馬御風が糸魚川に生まれる"],["1907年","早稲田大学校歌 «都の西北» の歌詞をつくる"],["1914年","島村抱月と «カチューシャの唄» の歌詞をつくる"],["1916年","東京をはなれ、糸魚川に帰る"],["1918年","良寛研究の本『大愚良寛』を出す"],["1923年","童謡 «春よ来い» の歌詞を発表"],["1938年","小滝川でヒスイが見つかる（御風の話がきっかけと伝わる）"],["1950年","糸魚川で亡くなる"]],"who":[["相馬御風","詩人・文学者。この家に住んだ"],["島村抱月","劇作家。«カチューシャの唄» をともにつくった"],["良寛","江戸時代の僧・歌人。御風が研究し広めた"],["弘田龍太郎","«春よ来い» の作曲者"]],"deep":["«都の西北» は1907年、早稲田大学の創立25周年のころにつくられました。作曲は東儀鉄笛です。","«カチューシャの唄» は、トルストイの『復活』の舞台のために作られ、松井須磨子が歌って大ヒットしました。レコード時代の流行歌のはしりといわれます。","御風の良寛研究は、学問としての研究だけでなく、良寛の生き方を «手本» として紹介したもので、大正時代の良寛ブームのきっかけになりました。","ヒスイ発見のいきさつは、御風が奴奈川姫とヒスイの話をし、それを聞いた人がさらに知人に伝え、伊藤栄蔵という人が小滝川で見つけた、という流れで伝わっています。","御風宅は糸魚川市の文化財として公開されています。開館日や時間は季節によって変わることがあるので、事前に確かめましょう。"],"look":["御風が暮らした家と書斎","庭のたたずまい","糸魚川歴史民俗資料館（御風の資料）","あわせてフォッサマグナミュージアムでヒスイを見る"],"q":["相馬御風が歌詞を書いた大学の校歌は？","早稲田大学校歌 «都の西北»。1907年につくられました。"],"koji":[],"myth":"ヒスイ発見のきっかけは伝え。","img":["早稲田大学校歌","良寛","ヒスイ"],"wp":"相馬御風","rel":{"ev":[],"grave":[]},"ph":[["c:d/d5/Soma_Gyofu.JPG",449,596,"相馬御風"],["c:2/2b/Okuma_Auditorium.jpg",2600,2600,"早稲田大学校歌"],["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"ヒスイ"]]},{"id":"15_horibe","n":"堀部安兵衛生誕地（新発田）","yomi":"ほりべやすべえせいたんち","cat":"伝承","rank":"B","y":1670,"era":["edo"],"sh":"","ad":"新発田市（新発田城周辺）","st":"JR新発田駅から歩いて約20分（新発田城方面）","la":37.9535,"lo":139.327,"hook":"«高田馬場の決闘» で江戸の人気者になり、赤穂浪士として散った剣士。そのふるさとは、越後の城下町だった。","lead":"赤穂浪士の一人として有名な堀部安兵衛は、1670年、新発田藩の家臣・中山家の子として新発田に生まれました。のちに江戸に出て、«高田馬場の決闘» で名をあげ、赤穂藩の堀部家の養子になりました。新発田には安兵衛ゆかりの場所があります。","story":["新発田は、溝口家が治めた城下町です。1670年、その家臣・中山弥次右衛門の子として生まれたのが中山安兵衛、のちの堀部安兵衛です。ところが父は、城の火事の責任を問われて家を失ったと伝わり、安兵衛は幼くして苦しい暮らしを送ることになりました。","成長した安兵衛は江戸へ出て、剣の道にはげみました。1694年、親しくしていた菅野六郎左衛門が高田馬場で決闘をすることになり、安兵衛は助太刀にかけつけます。«ここで逃げては武士の名がすたる!» 安兵衛はめざましい働きを見せ、たちまち江戸じゅうの評判になりました。これが «高田馬場の決闘» です。","この話を聞いた赤穂藩の堀部弥兵衛は、安兵衛にほれこみ、«ぜひ娘のむこに» と願いました。安兵衛ははじめ、中山の家名をすてることをためらったといわれます。それでも熱心なたのみに心を動かされ、堀部家の養子となって赤穂藩につかえることになりました。","1701年、主君・浅野内匠頭が江戸城で刃傷事件を起こし、切腹。赤穂藩はとりつぶされます。安兵衛は «すぐにでもかたきを討つべきだ» と主張した急進派の中心でした。1702年12月、安兵衛は仲間とともに吉良邸に討ち入り、翌年、ほかの浪士とともに切腹しました。","新発田には、安兵衛の生まれた地を示す碑や、ゆかりの寺があり、郷土の英雄として大切にされています。新発田城の堀ばたを歩きながら、この城下町から江戸へ旅立った少年の姿を思いうかべてみてください。"],"tl":[["1670年","新発田藩士・中山弥次右衛門の子として生まれる"],["少年時代","父が失職し、苦しい暮らしを送ったと伝わる"],["1694年","高田馬場の決闘で助太刀し、江戸で評判になる"],["その後","赤穂藩・堀部弥兵衛の養子になる"],["1701年","浅野内匠頭の刃傷事件。赤穂藩とりつぶし"],["1702年12月14日","吉良邸討ち入り"],["1703年","ほかの浪士とともに切腹"]],"who":[["堀部安兵衛武庸","新発田生まれの赤穂浪士。高田馬場の決闘で有名"],["中山弥次右衛門","安兵衛の父。新発田藩士"],["堀部弥兵衛","赤穂藩士。安兵衛を養子にむかえた"],["菅野六郎左衛門","高田馬場の決闘で安兵衛が助太刀した相手"],["浅野内匠頭","赤穂藩主。安兵衛の主君"]],"deep":["«高田馬場の十八人斬り» という話は講談や芝居での誇張で、実際に安兵衛が倒した人数は数人ほどと考えられています。","安兵衛が «堀部» の家名を名のることを渋った話は、中山家の家名を残したかったからといわれます。養子の条件をめぐる逸話には諸説があります。","安兵衛は江戸にいた赤穂浪士の急進派の中心で、大石内蔵助に早く討ち入るよう何度も求めたことが、手紙の記録からわかっています。","父・中山弥次右衛門が家を失った理由は、城の櫓の火事の責任とする伝えがありますが、細部ははっきりしません。","新発田では安兵衛は郷土の英雄で、ゆかりの寺や碑を訪ねる人が多くいます。場所や公開の状況は、市の観光案内で確かめましょう。"],"look":["新発田城の表門と隅櫓（国の重要文化財）","安兵衛生誕の地を示す碑","安兵衛ゆかりの寺","城下町の寺町や堀ばた"],"q":["堀部安兵衛が江戸で有名になった決闘は、どこで行われた？","高田馬場（いまの東京都新宿区のあたり）。親しい人の助太刀をしました。"],"koji":[],"myth":"«十八人斬り» は講談の誇張。父の失職の理由・養子の経緯は伝承・諸説。","img":["新発田城","赤穂事件","高田馬場の決闘"],"wp":"堀部武庸","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Utagawa_Kunisada-c1850-Horibe_Yahei-Horibe_Yasubei.jpg",880,1254,"堀部武庸"],["c:e/eb/Shibata_Castle_001_May2020.jpg",2364,1773,"新発田城"],["c:a/aa/Ohiroma_Honmaru_Edo_Castle_4.JPG",3567,2675,"赤穂事件"]]},{"id":"15_ayamezuka","n":"菖蒲塚古墳（越後最大級の前方後円墳）","yomi":"あやめづかこふん","cat":"遺跡","rank":"B","y":380,"era":["kofun"],"sh":"国指定史跡","ad":"新潟市西蒲区竹野町","st":"JR越後線巻駅から車で約10分（公共交通では行きにくい）","la":37.73,"lo":138.86,"hook":"角田山のふもとの森に眠る、越後でいちばん大きな前方後円墳。名前には、都から来た «美しい姫» の伝説が重なる。","lead":"菖蒲塚古墳は、新潟市の西のはし、角田山のふもとにある古墳時代の前方後円墳です。長さは約53mで、越後（今の新潟県本土）では最大級。ヤマト王権と結びついた有力者が、日本海に近いこの地を治めていたことを物語ります。","story":["新潟平野の西に、こんもりとした角田山がそびえています。そのふもと、木々に囲まれた丘の上に、かぎ穴の形をした大きな墓がひっそりとあります。«前方後円墳» は、奈良の大王（おおきみ）の墓と同じ形。なぜ、都から遠く離れた越後に、この形の墓が作られたのでしょう?","古墳が作られた4世紀ごろ、越後はヤマト王権の «北のはずれ» でした。その先には、王権に従わない人びとの世界が広がっていたと考えられています。前方後円墳を作ることは、«わたしはヤマトの大王とつながっている» という目に見える宣言でした。この墓の主は、日本海と平野の両方を見わたせる土地で、人びとを束ねたリーダーだったのでしょう。","江戸時代には、墓の中から鏡が見つかったと伝わります。古代の鏡は、ただの化粧道具ではありません。大王から配られたり、お祭りに使われたりした、力のしるしでした。«鏡をもらえる人» であることが、この地の首長の自慢だったのかもしれません。","では、なぜ «菖蒲塚» という名前なのでしょう。地元には、平安時代の武将・源頼政の妻 «菖蒲御前（あやめごぜん）» が、夫の死後にこの地へ逃れて亡くなり、ここに葬られたという言い伝えがあります。もちろん古墳は頼政の時代より800年ほども古いので、これは伝説です。それでも、大きな墓を見た昔の人が «きっと身分の高い美しい人が眠っているにちがいない» と想像した気持ちは、よくわかります。","今、古墳のまわりは静かな森です。墳丘に立つと、1600年前の首長が見たのと同じように、越後平野の広がりと角田山の緑が目に入ります。歴史の教科書では «近畿の話» になりがちな古墳時代が、ここ越後でもたしかに動いていたことを実感できる場所です。"],"tl":[["4世紀後半ごろ","菖蒲塚古墳が築かれる（時期は推定・諸説）"],["江戸時代","墳丘から鏡などが出土したと伝わる"],["昭和時代","国の史跡に指定される"],["近年","周辺の調査が進み、越後の古墳時代研究の手がかりに"],["現在","森の中の史跡として見学できる"]],"who":[["墓の主（名前は不明）","越後平野の西部を治めた首長と考えられる"],["菖蒲御前","源頼政の妻と伝わる女性。ここに葬られたという伝説の主人公"],["源頼政","平安時代末の武将。1180年に平家と戦って敗れた"]],"deep":["全長は約53mとされ、越後（佐渡を除く新潟県）の前方後円墳では最大級。近畿の巨大古墳と比べると小さいが、«北限に近い地域で作られた» ことに大きな意味がある。","日本海側の前方後円墳の分布をたどると、北へ行くほど数が減る。越後平野の古墳群は、ヤマト王権の影響がどこまで及んだかを考えるときの重要な材料になっている。","角田山の周辺には、ほかにも小さな古墳が点在している。菖蒲塚古墳はその中で飛びぬけて大きく、地域の «王» の墓と見られる。","出土したと伝わる鏡については、種類や出土の事情に不明な点があり、研究者の間でも慎重に扱われている。","«菖蒲御前がここに眠る» 話は、各地に残る頼政・菖蒲御前伝説のひとつ。古墳の名前が伝説から付いた例は全国に多く、昔の人が古墳をどう見ていたかを知る手がかりになる。","7世紀に «越» の国が越前・越中・越後に分かれるずっと前、この地は «越（こし）» と呼ばれる広い地域の一部だった。"],"look":["かぎ穴形がわかる墳丘の形（前方部と後円部のつなぎ目）","墳丘の上からの越後平野のながめ","史跡の説明板","近くの角田山のハイキング道とあわせて歩く"],"q":["菖蒲塚古墳の名前のもとになった伝説の女性はだれ?","源頼政の妻と伝わる «菖蒲御前»。ただし古墳の方がずっと古く、名前は後の時代の伝説から付いたものです。"],"myth":"菖蒲御前がここに葬られたという話は伝説。築造時期・出土した鏡の詳細は諸説あり。","img":["前方後円墳","角田山","源頼政"],"wp":"菖蒲塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:3/31/Ayamezuka_Kofun%2C_Niigata%2C_Niigata%2C_Japan%2C_August_2022.jpg",4032,3024,"菖蒲塚古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:a/a5/Mount_Kakuda_from_Uwasekigata_Park_002_June2020.jpg",2508,1672,"角田山"],["c:f/ff/Minamoto_no_Yorimasa2.jpg",1332,1951,"源頼政"]]},{"id":"15_teraji","n":"寺地遺跡（縄文のヒスイ工房と配石遺構）","yomi":"てらじいせき","cat":"遺跡","rank":"B","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"糸魚川市寺地","st":"えちごトキめき鉄道青海駅から歩いて約15分","la":37.03,"lo":137.8,"hook":"日本でいちばん古い «宝石工房» のひとつ。縄文人は、硬くて緑に光るヒスイをどうやって磨いたのか。","lead":"寺地遺跡は、糸魚川市の青海地区にある縄文時代のむらの跡です。近くの川や海岸でとれるヒスイを加工した工房の跡や、石を並べて木の柱を立てた不思議な «配石遺構» が見つかりました。ここで作られたヒスイの玉は、遠い地方まで運ばれたと考えられています。","story":["糸魚川の海岸を歩くと、白や緑の小石にまじって、ときどき深い緑色に光る石が見つかります。それがヒスイです。とても硬く、鉄のナイフでも傷がつきません。今から数千年前、縄文の人びとはこの石に目をつけ、穴をあけ、つやつやに磨いて、首かざりの玉を作りました。","«鉄も機械もないのに、どうやって?» と思いますよね。寺地遺跡からは、ヒスイのかけらや、作りかけの玉、みがくのに使った砥石が見つかっています。硬い石に砂と水をつけ、何日も何日もこすり続けたのでしょう。穴をあけるときは、竹や棒を回して砂でけずったと考えられています。気の遠くなるような手仕事でした。","遺跡の中でも目を引くのが、石をたくさん並べた «配石遺構» です。その中心近くでは、太い木の柱の根元が4本見つかりました。ここで何が行われていたのか、はっきりとはわかりません。お墓だったのか、お祭りの場だったのか。ヒスイの工房のすぐそばに «特別な場所» があったことは、この石が人びとにとって神聖なものだったことを想像させます。","糸魚川で作られたヒスイの玉は、東北や関東、さらに遠くまで運ばれたと考えられています。«糸魚川の緑の石» は、縄文時代の日本列島をつなぐブランド品だったのです。やがて古墳時代には «勾玉（まがたま）» として王たちの宝になりました。","ところが、その後ヒスイの加工はすたれ、日本でヒスイがとれること自体が長く忘れられていきます。糸魚川でヒスイが «再発見» されるのは、なんと昭和になってから。寺地遺跡は、忘れられた «日本の宝石» の物語の、いちばん最初の章が眠る場所なのです。"],"tl":[["縄文時代中期ごろ","寺地でむらが営まれ、ヒスイの加工が行われる"],["縄文時代晩期ごろ","配石遺構が作られたと考えられている"],["昭和時代（戦前）","糸魚川の小滝川でヒスイが見つかり、国内にも産地があるとわかる"],["昭和時代後半","発掘調査でヒスイ工房や配石遺構が確認される"],["昭和時代後半","国の史跡に指定される"],["2016年","ヒスイが «国石» に選ばれる（日本鉱物科学会）"]],"who":[["縄文のヒスイ職人","ヒスイの玉を作った人びと。名前は残っていない"],["奴奈川姫（ぬながわひめ）","『古事記』に登場する越の姫。糸魚川ではヒスイと結びつけて語られる"],["相馬御風","糸魚川出身の文学者。奴奈川姫の伝説からヒスイの産地を考えたといわれる"]],"deep":["ヒスイ（硬玉）は、とても硬いだけでなく «ねばり強い» 石。割れにくいので、穴をあけたり磨いたりするのに大変な時間がかかる。加工の技術そのものが、縄文人の高い技術力を示している。","配石遺構で見つかった木柱の根は、太い柱を立てた跡と考えられる。青森の三内丸山遺跡の大型掘立柱など、各地の «柱の祭祀» と比べる研究もある。","糸魚川市内には、同じくヒスイ加工で知られる長者ケ原遺跡もあり、この地域一帯がヒスイ文化の中心だったとみられる。","日本各地の遺跡から出るヒスイの多くは、成分分析などから糸魚川周辺の産と考えられている。原産地から遠く離れた場所にまで届いていたことになる。","ヒスイが «再発見» されたきっかけには、『古事記』の奴奈川姫が «玉» と関係するという考えがあったと伝わる。神話が科学的な発見のヒントになった珍しい例として語られる。","ヒスイは現在、周辺の川などで採取が禁止・制限されている場所がある。海岸で拾えるのは、川から流れ出た石が波で運ばれたものだ。"],"look":["配石遺構のあとと、木柱が立っていた場所","史跡の説明板と復元された様子","近くの青海の海岸（ヒスイ海岸）","糸魚川市内のヒスイ関連の展示施設とあわせて見る"],"q":["糸魚川のヒスイは、日本の «何の石» に選ばれた?","«国石»。2016年に日本鉱物科学会が選びました。縄文時代から続く日本人とヒスイの長いつきあいが理由のひとつです。"],"myth":"配石遺構の用途（墓・祭祀など）は諸説。奴奈川姫とヒスイを結びつける話は後世の解釈を含む。","img":["ヒスイ","長者ケ原遺跡","奴奈川姫","糸魚川ユネスコ世界ジオパーク"],"wp":"糸魚川市","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Itoigawa_Montage.jpg",1024,1300,"糸魚川市"],["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"ヒスイ"],["c:3/35/Suwa_taisha_Shimosha_Harumiya_%2C_%E8%AB%8F%E8%A8%AA%E5%A4%A7%E7%A4%BE_%E4%B8%8B%E7%A4%BE_%E6%98%A5%E5%AE%AE_%E5%AD%90%E5%AE%89%E7%A4%BE_-_panoramio.jpg",2400,1600,"奴奈川姫"]]},{"id":"15_araya","n":"荒屋遺跡（旧石器・細石刃）","yomi":"あらやいせき","cat":"遺跡","rank":"B","y":-13000,"era":["kyuseki"],"sh":"国指定史跡","ad":"長岡市川口荒屋","st":"JR上越線越後川口駅から歩いて約20分","la":37.27,"lo":138.86,"hook":"長さ数センチの小さな石の刃が、氷河期の日本と遠いシベリアを一本の線でつなぐ。","lead":"荒屋遺跡は、信濃川と魚野川が合流する近くの台地にある、旧石器時代の終わりごろの遺跡です。«細石刃（さいせきじん）» というとても小さな石の刃や、«荒屋型彫器» と名づけられた道具がたくさん見つかり、日本の旧石器研究で名前がよく知られています。","story":["今から1万数千年前、日本列島はまだ氷河期の終わりにいました。今よりずっと寒く、人びとは土器も田んぼもない暮らしをしていました。獲物を追って移動しながら暮らした人びとが、川の合流点を見下ろすこの台地に、何度もやって来ていました。","荒屋遺跡でたくさん見つかったのが «細石刃» です。長さ数センチ、幅は数ミリの、カミソリの刃のような小さな石。«こんなに小さくて何に使うの?» と思いますよね。じつは、骨や木で作った柄に、細石刃をいくつも並べてはめこみ、槍やナイフにしていたと考えられています。刃が欠けたら、その部分だけ取りかえればよい。とても頭のよい «交換式の刃» でした。","もうひとつの主役が、«荒屋型彫器（ちょうき）» です。石の先をけずって作った小さな道具で、骨や角に溝を彫るのに使われたと考えられています。この形の道具はほかの遺跡でも見つかり、遺跡の名前を取って «荒屋型» と呼ばれるようになりました。一つの遺跡の名前が、日本中の研究で使われる «ものさし» になったのです。","おどろくのは、似た道具がシベリアやアラスカなど、北の大地でも見つかっていることです。«北から来た人たちの技術なの?» ―― 研究者たちは、細石刃の技術がどの道を通って日本列島に広がったのかを、今も議論しています。荒屋遺跡は、その大きななぞを解く重要な場所のひとつです。","昭和30年代に、大学の研究者たちが発掘を行い、その成果が全国に知られました。今、遺跡のある台地は静かな畑や草地です。けれど足もとには、氷河期を生きた狩人たちの足あとが、今も眠っているのです。"],"tl":[["約1万数千年前","細石刃を使う人びとが台地を利用する（年代は推定・諸説）"],["1957年ごろ","明治大学の研究者らが発掘し、細石刃や彫器が大量に見つかる"],["その後","«荒屋型彫器» の名が研究で広く使われるようになる"],["昭和〜平成","追加の調査で住居の跡の可能性がある遺構も確認される"],["平成時代","国の史跡に指定される"]],"who":[["旧石器時代の狩人たち","細石刃を作り、この台地を利用した人びと"],["芹沢長介","旧石器時代の研究者。荒屋遺跡の発掘に関わったことで知られる"]],"deep":["細石刃は、あらかじめ形を整えた石のかたまり（細石刃核）から、同じ形の小さな刃を次々とはがして作る。材料のむだが少なく、持ち運びにも便利な «効率のよい技術» だった。","荒屋遺跡の細石刃核は、船の底のような形をした «舟底形» などが知られ、北海道や大陸の技術との関係が議論されてきた。","荒屋型彫器は、日本海側の東北・北陸を中心に見つかり、分布を地図にすると北方との結びつきが浮かびあがるとされる。","遺跡は信濃川と魚野川の合流点に近い段丘の上にある。川は魚や動物が集まる場所で、狩人にとって好都合だったと考えられる。","出土品の多さから、ここは一時的な «キャンプ» ではなく、何度も繰り返し使われた場所だったという見方がある。","旧石器時代の遺跡は、土器や建物が残らないため目立たない。石器の «形» と «作り方» が、当時の人の動きや文化を知る最大の手がかりになる。"],"look":["遺跡のある段丘の地形（川を見下ろす位置）","史跡の説明板","信濃川と魚野川の合流点付近の景色","長岡市内の博物館で出土品のレプリカや解説を見る"],"q":["細石刃はどうやって使われた?","骨や木の柄に何本も並べてはめこみ、槍やナイフの刃にしたと考えられています。欠けたら取りかえられる便利な道具でした。"],"myth":"年代・細石刃技術の伝わった経路は諸説。","img":["細石刃","旧石器時代","信濃川"],"wp":"荒屋遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:c/cb/Araya_arch._site._Tools.Tokyo_National_Museum.jpg",2055,1995,"荒屋遺跡"],["c:b/b8/Microlith_-16%2C000_Japan.JPG",2750,1867,"細石刃"],["c:7/7a/Find47_Niigata-River_%28Shinano_River%2C_Ojiya_City%29-m.jpg",1920,1280,"信濃川"]]},{"id":"15_hachimanbayashi","n":"八幡林官衙遺跡（古代郡家と木簡）","yomi":"はちまんばやしかんがいせき","cat":"遺跡","rank":"B","y":720,"era":["nara","heian"],"sh":"国指定史跡","ad":"長岡市島崎","st":"JR越後線小島谷駅から車で約10分","la":37.58,"lo":138.78,"hook":"土の中から出てきた木の札に «沼垂城» の文字。幻だった古代の城柵が、ここで一気に現実になった。","lead":"八幡林官衙遺跡は、奈良時代から平安時代にかけての役所（官衙）の跡です。古代の «郡» の役所にかかわる建物の跡や、文字を書いた木の札 «木簡（もっかん）» がたくさん見つかりました。中でも «沼垂城» と書かれた木簡は、古代史の大発見として話題になりました。","story":["今から1300年ほど前、奈良に都があったころ、国は «国» と «郡» に分けて治められていました。郡ごとに役所が置かれ、税を集めたり、人びとの名簿を作ったりしていました。八幡林官衙遺跡は、そんな役所の一つの跡です。丘の上に大きな建物が並び、役人たちが行き来していました。","役人たちの仕事に欠かせなかったのが «木簡» です。紙がとても貴重だったので、うすい木の板に墨で文字を書き、連絡や記録に使いました。書き終わると表面をけずって、また使うこともありました。土の中の湿り気のおかげで、1000年以上たった今も文字が読める木簡が残っていたのです。","平成のはじめ、この遺跡の木簡の中から «沼垂城» という文字が見つかりました。«沼垂（ぬたり）» は、『日本書紀』に647年に作られたと書かれた «渟足柵（ぬたりのき）» と同じ場所を指すと考えられています。渟足柵は、ヤマト王権が北の «蝦夷（えみし）» に備えて作った «とりで» ですが、場所がわからず、«本当にあったの?» という疑問も残っていました。","«書物にしか出てこなかった柵が、同じ時代の役人の文字で確認された!» ―― 研究者たちの興奮が目に浮かびます。木簡には、郡の長官が部下に命令を出す «郡符木簡» と呼ばれるものも含まれ、古代の地方役所がどう動いていたかを生き生きと伝えてくれます。","今、遺跡は静かな丘になっていますが、史跡として整備され、説明板で当時の役所の様子を知ることができます。小さな木の札が、教科書の一行にすぎなかった古代の越後に、たしかな手ざわりを与えてくれた場所です。"],"tl":[["647年","『日本書紀』に渟足柵を作ったと記される"],["648年","磐舟柵が作られる（『日本書紀』）"],["8世紀前半ごろ","八幡林の役所が活発に使われる（時期は推定）"],["平安時代","役所の機能がしだいに衰える"],["1990年ごろ","発掘調査で «沼垂城» と書かれた木簡などが出土"],["1995年ごろ","国の史跡に指定される"]],"who":[["古志郡の役人たち","郡の役所で記録や命令を扱った人びと"],["郡司","郡を治めた地元の有力者。役所の長"],["蝦夷（えみし）","古代、ヤマト王権に従わなかった東北などの人びと。柵はこれに備えて作られた"]],"deep":["«沼垂城» 木簡は、奈良時代初めごろのものと考えられ、渟足柵が «城» とも呼ばれ、この時期にも存在していたことを示す重要な資料とされる。","渟足柵の正確な場所は今もわかっていない。新潟市の沼垂付近とする説が有力だが、遺構は見つかっていない。","«郡符木簡» は、郡の長が村の責任者などに人や物を呼び出す命令書。ふつうの木簡よりずっと長く大きなものが知られ、命令の «重み» を形で示したとも考えられている。","遺跡は古代の古志郡の役所、またはそれに関わる施設と考えられているが、どの役所だったかについては議論がある。","八幡林遺跡のある島崎は、江戸時代の僧・良寛が晩年を過ごした土地でもある。古代と近世の二つの物語が同じ町に重なる。","木簡は、地下水につかった状態で空気にふれなかったため残った。掘り出した後は乾くとすぐに傷むので、特別な保存処理が必要になる。"],"look":["丘の上の遺跡の広がり（役所の建物が並んでいた場所）","史跡の説明板","周辺の地形（平野を見下ろす位置）","近くの良寛ゆかりの隆泉寺・良寛の里とあわせて歩く"],"q":["八幡林官衙遺跡の木簡で見つかった、幻の城柵の名前は?","«沼垂城»。『日本書紀』に出てくる渟足柵のことと考えられ、実在を裏づける発見になりました。"],"koji":[],"myth":"役所の性格（どの郡家か）や渟足柵の場所は諸説。","img":["木簡","渟足柵","郡衙","蝦夷"],"wp":"八幡林官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/Wooden_tablets_%28copy%29_in_7-8th_c.jpg",3112,1535,"木簡"],["c:2/23/Monument_to_Aterui_and_More2.jpg",856,1147,"蝦夷"]]},{"id":"15_iwafune","n":"磐舟柵の伝承地（岩船）","yomi":"いわふねのきのでんしょうち","cat":"伝承","rank":"B","y":648,"era":["asuka"],"sh":"","ad":"村上市岩船","st":"JR羽越本線岩船町駅から車で約10分","la":38.19,"lo":139.43,"hook":"1400年近く前、ヤマトの国の «いちばん北のとりで» があったのは、この海辺のどこか。","lead":"磐舟柵（いわふねのき）は、飛鳥時代の648年に作られたと『日本書紀』に書かれた «柵（とりで）» です。正確な場所はまだ見つかっていませんが、村上市岩船の周辺にあったという説が有力で、地元には伝承地が残ります。","story":["大化の改新の少しあと、ヤマト王権は国の北の境を広げようとしていました。その先に住んでいたのが、王権に従わない «蝦夷（えみし）» と呼ばれた人びとです。647年、まず今の新潟市あたりに «渟足柵» が作られ、翌648年、さらに北の海辺に «磐舟柵» が作られました。","『日本書紀』は、磐舟柵について «蝦夷に備え、越と信濃の人を選んで、はじめて柵戸（きのへ）を置いた» という意味のことを記しています。柵戸とは、とりでのまわりに移り住んで畑を耕し、いざというときには守りにつく人びとのこと。«ふるさとを離れて、知らない北の土地へ» ―― 選ばれた人びとは、どんな気持ちで海を渡ってきたのでしょう。","とりでがあった場所は、1300年以上たった今も見つかっていません。岩船の町には石船神社（いわふねじんじゃ）があり、この近くの丘が柵の場所ではないかと考える人もいます。村上市内には «磐舟柵跡» と伝わる場所があり、そこに碑が立てられています。","磐舟柵が作られてから約10年後、阿倍比羅夫（あべのひらふ）という将軍が大船団を率いて日本海を北へ進み、秋田や津軽の蝦夷と向き合ったと『日本書紀』は伝えます。磐舟柵は、その北へ向かう道の «前線基地» の一つだったと考えられています。","«岩船» という地名は、今も港町の名前として残っています。静かな海辺に立つと、ここがかつて国の境だったとは信じられないほどです。見つかっていないからこそ、いつかの発掘で新しい手がかりが出てくるかもしれない ―― そんな期待を抱かせる場所です。"],"tl":[["645年","乙巳の変。大化の改新が始まる"],["647年","渟足柵が作られる（『日本書紀』）"],["648年","磐舟柵が作られ、柵戸が置かれる（『日本書紀』）"],["658年ごろ","阿倍比羅夫が日本海沿いを北へ遠征したと伝わる"],["8世紀以降","出羽国が置かれ、境はさらに北へ移る"],["現在","場所は未確定。岩船周辺に伝承地が残る"]],"who":[["柵戸の人びと","越や信濃から移り住み、柵のまわりで暮らした人びと"],["阿倍比羅夫","飛鳥時代の将軍。日本海沿いを北へ遠征したと『日本書紀』に記される"],["蝦夷（えみし）","ヤマト王権に従わなかった北の人びと"],["孝徳天皇","磐舟柵が作られたときの天皇"]],"deep":["«柵» は、木の柵や土塁で囲んだ役所兼とりでで、兵だけでなく移住した農民（柵戸）を置いて «開発の拠点» にするのが特徴。軍事と開拓がセットだった。","磐舟柵の場所は、村上市岩船の周辺とする説が一般的だが、確かな遺構は見つかっていない。遺跡としての確認は今後の課題とされる。","渟足柵と磐舟柵はわずか1年ちがいで作られており、王権が短い間に一気に北へ進もうとしたことがわかる。","『続日本紀』には、698年に越後国に磐舟柵を修理させたという記事があるとされ、作られてから半世紀たっても使われていた可能性がある。","岩船の石船神社は、神が «岩の船» に乗ってやって来たという由来を伝え、地名の由来とも結びつけて語られる。","8世紀に出羽国（今の山形・秋田）ができると、国の «北の境» はさらに北へ動き、磐舟柵の役割は小さくなっていったと考えられている。"],"look":["岩船の港町と海辺の景色","石船神社（地名にかかわる古い神社）","磐舟柵跡の伝承地と碑","村上市内の郷土資料の展示（開館情報は事前に確認）"],"q":["磐舟柵のまわりに置かれた «柵戸» とはどんな人?","越や信濃から選ばれて移り住み、畑を耕しながら、いざというときにとりでを守った人びとです。"],"myth":"磐舟柵の場所は未確定で、伝承地はあくまで候補。修理記事の年代は史料の読み方に諸説。","img":["渟足柵","阿倍比羅夫","蝦夷"],"wp":"磐舟柵","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Abe_no_Hirafu.JPG",1001,1512,"阿倍比羅夫"],["c:2/23/Monument_to_Aterui_and_More2.jpg",856,1147,"蝦夷"]]},{"id":"15_anju","n":"安寿と厨子王供養塔（直江津）","yomi":"あんじゅとずしおうくようとう","cat":"伝承","rank":"B","y":1915,"era":["heian","taisho"],"sh":"","ad":"上越市中央（直江津）","st":"えちごトキめき鉄道直江津駅から歩いて約15分","la":37.18,"lo":138.245,"hook":"«安寿恋しや、ほうやれほ»――母と子が引き裂かれた悲しい物語は、この直江津の浜から始まる。","lead":"«安寿と厨子王» は、人買いにだまされて母と別れ、つらい奴隷生活を送った姉弟の物語です。昔の語り物 «さんせう太夫» や、森鷗外の小説『山椒大夫』で知られ、物語の中で一家が引き裂かれるのが «直江の浦»、今の直江津です。町には姉弟と母をしのぶ供養塔が建てられています。","story":["むかし、陸奥（東北）の役人だった父が遠い筑紫に流され、母と姉の安寿、弟の厨子王、そして乳母の4人は、父に会うための長い旅に出ました。越後の直江の浦までたどり着いたとき、«船で送ってあげよう» と親切そうに声をかけてきた男がいました。それが人買いだったのです。","沖に出ると、船は二つに分けられました。母と乳母は佐渡へ、安寿と厨子王は丹後（京都府北部）へ。«安寿や、厨子王や!» ―― 母の叫びは波の音にかき消されていきます。乳母は悲しみのあまり海に身を投げたと語られます。物語の中で、家族がばらばらになるいちばんつらい場面が、この直江津の海でした。","丹後の山椒大夫のもとで、姉弟は «しおくみ» と «しば刈り» の苦しい仕事をさせられます。やがて安寿は弟だけを逃がし、自分は犠牲になりました。«あなたは生きて、お父さまとお母さまをさがして» ―― その願いを胸に、厨子王は都へのぼり、のちに立派な身分になります。","物語の最後、厨子王は佐渡へわたり、目が見えなくなった母と再会します。母は «安寿恋しや ほうやれほ、厨子王恋しや ほうやれほ» と歌いながら、鳥を追っていました。森鷗外は、この昔話を1915年に小説『山椒大夫』として書き直し、多くの人に読まれるようになりました。","«物語なのに、どうして供養塔があるの?» と思うかもしれません。それだけこの話が、直江津の人びとの心に深くしみこんでいたからでしょう。海を見ながら、引き裂かれた親子をしのぶ ―― 供養塔は、物語の登場人物を本当の人のように悼んできた町の気持ちの表れなのです。"],"tl":[["平安時代（物語の舞台）","物語では、この時代に一家が直江の浦で人買いにだまされるとされる"],["中世〜江戸時代","語り物 «説経節» の «さんせう太夫» として広まる"],["1915年","森鷗外が小説『山椒大夫』を発表"],["1954年","映画『山椒大夫』（溝口健二監督）が公開される"],["現在","直江津に供養塔が建ち、物語を伝えている"]],"who":[["安寿","物語の姉。弟を逃がして自らは犠牲になる"],["厨子王","物語の弟。のちに出世し、佐渡で母と再会する"],["山椒大夫","丹後の長者。姉弟をこき使った人物として描かれる"],["森鷗外","明治・大正の作家。物語を小説『山椒大夫』に書き直した"]],"deep":["«さんせう太夫» は、中世から江戸時代にかけて語られた «説経節» の代表的な演目。鷗外の小説は、元の話の残酷な場面をやわらげ、姉の自己犠牲を中心にすえた書き直しになっている。","物語の中の «直江の浦» は、関川の河口にあった古い港町を指すと考えられる。直江津は古くから越後の国府に近い港として栄えた。","母が送られた佐渡にも、安寿と厨子王の母にまつわる伝承地があり、日本海をはさんで同じ物語の舞台が向かいあっている。","丹後（京都府舞鶴市・宮津市周辺）にも山椒大夫や安寿姫の伝承地があり、物語の «旅の地図» は日本海沿いの広い範囲に広がる。","物語は実話ではなく語り物だが、人買いによって人が売られる社会の現実が背景にあったと考えられている。","鷗外の小説は教科書にも取り上げられ、映画化もされて、物語の広まりに大きな役割を果たした。"],"look":["安寿と厨子王の供養塔","関川の河口と直江津の海（物語の «直江の浦»）","近くの港の景色（佐渡への航路を想像しながら）","町に残る物語ゆかりの案内板"],"q":["物語で、母と姉弟はそれぞれどこへ連れていかれた?","母は佐渡へ、安寿と厨子王は丹後へ。直江の浦で船が二つに分けられました。"],"myth":"安寿と厨子王は語り物・小説の登場人物で、実在は確かめられていない。供養塔は物語をしのんで建てられたもの。","img":["森鷗外","説経節","直江津"],"wp":"山椒大夫","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Mori_Ogai_in_the_atelier_of_Sculptor_Takeishi_Kozaburo_in_1916.jpg",740,1118,"森鷗外"],["c:f/fe/Shintokumaru.jpg",1265,1840,"説経節"],["c:e/e4/Naoetsu_city.PNG",405,326,"直江津"]]},{"id":"15_honjoji","n":"本成寺（三条・法華宗本山）","yomi":"ほんじょうじ","cat":"寺社","rank":"B","y":1297,"era":["kamakura","edo"],"sh":"","ad":"三条市西本成寺","st":"JR弥彦線北三条駅から歩いて約15分","la":37.63,"lo":138.965,"hook":"節分の日、お寺の本堂に赤鬼・青鬼があばれこむ。7百年の歴史をもつ本山の、ちょっと変わった名物行事。","lead":"本成寺は、三条市にある法華宗陣門流の総本山です。鎌倉時代の終わりごろに開かれたと伝わり、広い境内に大きなお堂が建ち並びます。毎年の節分に行われる «鬼踊り» は、三条の冬の名物として知られています。","story":["鎌倉時代、日蓮は «法華経こそが人を救う» と説き、厳しい迫害にあいながら教えを広めました。その流れをくむ僧・日印（にちいん）が、越後で教えを広める拠点として開いたのが本成寺だと伝わります。やがて本成寺は、法華宗の中の一つの流れ «陣門流» のいちばん大もとのお寺 «総本山» になりました。","戦国時代、越後の寺々は戦乱に巻きこまれ、本成寺も焼けたり再建されたりをくり返したと伝わります。それでも信仰は絶えませんでした。江戸時代には多くの末寺をもつ大寺院として栄え、三条の町の人びとの心のよりどころになっていきます。","本成寺の名物といえば、節分の «鬼踊り» です。ほら貝の音とともに、赤や青の鬼たちが金棒を持って本堂にあばれこみます。«鬼は外!» ―― お坊さんや年男が豆をまくと、鬼たちはたまらず退散。見物の人びとから大きな歓声があがります。鬼が大暴れするほど、その年の災いがはらわれると考えられてきました。","«なぜお寺で鬼が踊るの?» 鬼踊りの始まりにはいくつかの言い伝えがあります。お寺を守ろうとした人びとが鬼の姿で盗賊を追い払ったのが始まり、という話もありますが、はっきりしたことはわかっていません。昔からの言い伝えと、今の人びとの楽しみが重なりあって続いてきた行事なのです。","三条は «金物の町» として知られ、職人たちが多く住む町でした。本成寺の大きな山門や本堂は、そんな町の人びとに長く支えられてきました。ふだんの境内は静かで、大きな屋根の下に立つと、700年の祈りの時間がゆっくりと流れているのを感じます。"],"tl":[["1297年ごろ","日印が本成寺を開いたと伝わる"],["室町〜戦国時代","戦乱などで焼失と再建をくり返したと伝わる"],["江戸時代","陣門流の総本山として多くの末寺をもつ"],["近代","節分の鬼踊りが三条の名物行事として広く知られる"],["現在","法華宗陣門流総本山として法灯を伝える"]],"who":[["日印","鎌倉時代の僧。本成寺を開いたと伝わる"],["日蓮","鎌倉時代の僧。法華宗の祖。佐渡に流されたことでも知られる"],["三条の町衆","職人や商人たち。寺を支えてきた人びと"],["石川雲蝶","幕末の彫り物師。三条に住み、越後各地に作品を残した"]],"deep":["法華宗陣門流は、日蓮の教えをくむ宗派の一つ。本成寺はその総本山で、全国に末寺があるとされる。","日蓮は1271年に佐渡へ流されており、越後・佐渡は日蓮ゆかりの地が多い。越後で法華の教えが広まった背景として語られる。","鬼踊りは節分会（せつぶんえ）の行事。鬼たちが本堂で暴れまわり、豆まきで追い出されるという «劇» のような構成になっている。","鬼踊りの由来は諸説あり、確かな起源はわかっていない。地元に伝わる話として紹介されることが多い。","三条出身ではないが、彫り物師・石川雲蝶は三条に住み、越後の寺社に作品を残した。三条と雲蝶の縁を語るときに本成寺の名が出ることもある。","本成寺の門前一帯は «本成寺» という地名にもなっており、お寺が町の成り立ちに深くかかわってきたことがわかる。"],"look":["大きな山門と本堂","広い境内の伽藍の配置","節分の鬼踊り（開催日時は事前に確認）","三条の町なかの寺町の雰囲気"],"q":["本成寺の節分に登場する名物行事は?","«鬼踊り»。赤や青の鬼が本堂で暴れ、豆まきで追い払われます。"],"myth":"開山の年、鬼踊りの起源、雲蝶と本成寺の関わりの詳細は諸説・伝承を含む。","img":["法華宗陣門流","日蓮","節分"],"wp":"本成寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"],["c:1/1d/Hokusai_Setsubun_no_Oni.jpg",360,523,"節分"]]},{"id":"15_saifukuji","n":"西福寺開山堂（石川雲蝶の彫刻）","yomi":"さいふくじかいさんどう","cat":"寺社","rank":"B","y":1857,"era":["edo"],"sh":"県指定有形文化財","ad":"魚沼市大浦","st":"JR上越線小出駅から車で約10分","la":37.205,"lo":138.955,"hook":"天井を見上げたとたん、息をのむ。彫って、塗って、飾りつくした «越後のミケランジェロ» の空間。","lead":"西福寺は魚沼市にある曹洞宗のお寺です。境内の開山堂は幕末に建てられ、内部は彫り物師・石川雲蝶による、色あざやかな彫刻で天井から壁までうめつくされています。その迫力から、雲蝶は «越後のミケランジェロ» と呼ばれています。","story":["お堂は、外から見ると雪国の落ち着いた建物です。ところが中に入って天井を見上げると、景色が一変します。木を深く彫りこみ、色をつけた巨大な彫刻が、天井いっぱいに広がっているのです。«これ、本当に木なの?» と思わず声が出るほどの立体感です。","作ったのは石川雲蝶。江戸で生まれ育った彫り物師で、腕を見こまれて越後にやって来たと伝わります。三条に住まいをもち、そこから越後のあちこちの寺社をまわって仕事をしました。西福寺の開山堂は、雲蝶が何年もかけて打ちこんだ大仕事でした。","天井の中心にあるのは、曹洞宗を開いた道元が、とらをしずめる場面を描いたとされる彫刻です。雲の間からあらわれるとらの迫力、道元の静かな表情。ひとつの天井の中に、物語の «一瞬» がとじこめられています。そのまわりには、鳥や花、人物の彫刻がびっしりとならびます。","雲蝶には、お酒と賭けごとが大好きだったという話が伝わっています。«酒を切らさないでくれるなら、いい仕事をする» ―― そんな約束で越後にとどまったという言い伝えもあります。本当かどうかはわかりませんが、自由で豪快な職人の姿が浮かびあがってきます。","雲蝶の名は、明治以降しばらくの間、あまり知られていませんでした。近年、彫刻のすばらしさが再発見され、«越後のミケランジェロ» として多くの人が訪れるようになりました。雪深い山あいの小さなお堂が、じつは日本でも指折りの «彫刻の小宇宙» だったのです。"],"tl":[["1534年ごろ","西福寺が開かれたと伝わる"],["1814年","石川雲蝶が江戸に生まれる"],["1857年","開山堂が建てられる（時期は伝承による）"],["幕末","雲蝶が数年をかけて開山堂の彫刻を手がける"],["1883年","石川雲蝶が亡くなる"],["昭和〜平成","開山堂が新潟県の文化財に。雲蝶の再評価が進む"]],"who":[["石川雲蝶","幕末〜明治の彫り物師。開山堂の彫刻・絵を手がけた"],["道元","鎌倉時代の僧。曹洞宗を開いた。天井彫刻の主題"],["西福寺の住職","雲蝶に開山堂の仕事をたのんだ寺の人びと"]],"deep":["開山堂の天井彫刻は «道元禅師猛虎調伏の図» と呼ばれる。道元が中国で修行していたとき、とらをしずめたという話にもとづくとされる。","雲蝶の作品は、彫刻に色をつけた «彩色彫刻» が特徴。木の厚みを生かした深い彫りで、光の当たり方によって表情が変わる。","開山堂は外から見ると雪国の建物らしく落ち着いた姿だが、中にはぜいたくな装飾が隠されている。«外は質素、内は豪華» の対比も、雪深い土地のお堂らしさといえる。","雲蝶の作品は西福寺のほか、魚沼市の永林寺など、越後各地の寺社に残るとされる。作品をめぐる «雲蝶巡り» を楽しむ人も多い。","«越後のミケランジェロ» という呼び名は近年広まったもので、天井いっぱいの作品をシスティーナ礼拝堂にたとえたもの。","雲蝶が越後にとどまった理由については、酒やばくちの話など、面白い言い伝えが多いが、確かな記録は少ない。"],"look":["開山堂の天井彫刻（道元ととらの場面）","壁や欄間の彩色彫刻の細部","雪国らしい外観と、内部のギャップ","境内の本堂や周辺の山あいの景色"],"q":["石川雲蝶は何と呼ばれている?","«越後のミケランジェロ»。天井いっぱいの彩色彫刻が、ミケランジェロの天井画にたとえられています。"],"myth":"雲蝶の酒やばくちの話は言い伝え。西福寺の開創年・開山堂の建立年は伝承による。","img":["石川雲蝶","道元","曹洞宗","魚沼市"],"wp":"西福寺 (魚沼市)","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/SaifukujiKaizandou.jpg",1920,2560,"西福寺 (魚沼市)"],["c:0/09/Soto-Zen-Master-Dogen-Zenji-Portrait.png",900,1935,"道元"],["c:7/7a/Dongshan_Liangjie_Image_Zen.jpg",300,450,"曹洞宗"],["c:a/a9/Lake_Okutadami_004.jpg",2925,1950,"魚沼市"]]},{"id":"15_hakusan","n":"白山神社（新潟町の総鎮守）","yomi":"はくさんじんじゃ","cat":"寺社","rank":"B","y":1655,"era":["edo","meiji"],"sh":"","ad":"新潟市中央区一番堀通町","st":"JR新潟駅からバスで約15分、«市役所前» 下車すぐ","la":37.915,"lo":139.04,"hook":"港町・新潟が «引っ越し» したとき、神さまもいっしょに移ってきた。町の成り立ちを見守る総鎮守。","lead":"白山神社は、新潟の町全体を守る «総鎮守» として大切にされてきた神社です。江戸時代、新潟の町が今の場所に移ったときに、神社もこの地に移されました。となりの白山公園は、明治時代のはじめに作られた、日本でもっとも古い公園のひとつです。","story":["新潟は、信濃川と阿賀野川が海にそそぐ河口の港町です。川の流れは気まぐれで、洪水や砂の動きで町の姿はたびたび変わりました。江戸時代のはじめ、新潟の町は大きな «引っ越し» をすることになります。そして町の人びとがいっしょに運んだのが、町の守り神・白山神社でした。","白山神社がまつるのは、菊理媛（くくりひめ）という女神です。白山（石川・岐阜の県境の山）の神で、«くくる=結ぶ» という名前から、縁結びの神さまとしても親しまれてきました。«港町の人びとと海の向こうの人びとを結ぶ» ―― 港町にぴったりの神さまだったのかもしれません。","江戸時代、新潟は北前船が行き交う日本海側で指折りの港になりました。米や品物が集まり、商人が栄えました。白山神社は «新潟町の総鎮守» として、港の安全や町の繁盛を祈る場所になりました。境内には、商人たちが奉納した品々が今も残っています。","明治になると、神社のとなりに «白山公園» が作られました。1873年、国が «公園を作りなさい» という方針を出したとき、最初に選ばれた公園のひとつです。«みんなが自由に遊べる庭» という新しい考え方が、この神社の森から始まったのです。","今も、白山神社は新潟の人びとの暮らしに寄りそっています。初詣や七五三、夏の祭り。港の町が大きく変わっても、神社の森だけは静かに残り、«ここが新潟のはじまりの場所のひとつ» であることを伝えています。"],"tl":[["創建","はっきりしない（平安時代ごろとも伝わるが諸説）"],["江戸時代前期","新潟町の移転にともない、現在地へ移る"],["江戸時代","新潟町の総鎮守として港町の人びとに信仰される"],["1869年","新潟港が開港（開港五港のひとつ）"],["1873年","隣に白山公園が作られる（日本初期の公園のひとつ）"],["現在","新潟総鎮守として初詣などでにぎわう"]],"who":[["菊理媛（くくりひめ）","白山の女神。白山神社の主な祭神"],["新潟町の商人たち","港町を栄えさせ、神社を支えた人びと"],["北前船の船乗り","日本海を行き交った船の人びと。港の神に安全を祈った"]],"deep":["新潟町の移転は、川の流れや洪水などへの対策とされ、江戸時代前期の1650年代ごろに行われたと伝わる。白山神社もこのとき現在地に移った。","白山公園は、1873年の太政官の布達をきっかけに生まれた、日本で最も早い時期の公園のひとつ。2019年に国の名勝に指定された。","公園内には、明治時代の商家の建物を移築した «燕喜館（えんきかん）» があり、見学できる。","白山神社は全国に数多くあり、石川県の白山比咩神社が総本宮。新潟の白山神社もその流れをくむ。","新潟は江戸時代から «みなと町» として発展し、明治に開港五港のひとつになった。白山神社は、その港町の «心の中心» だった。","境内には、港町の商人たちが奉納した品々が伝わり、新潟の商業の歴史を知る手がかりになっている。"],"look":["本殿と拝殿（新潟町の総鎮守）","となりの白山公園と燕喜館","境内の奉納品や石碑","近くの信濃川やりゅーとぴあ周辺の景色"],"q":["白山神社のとなりにある白山公園は、どんな点で有名?","明治時代のはじめ、1873年の国の方針をきっかけに作られた、日本で最も早い時期の公園のひとつです。"],"myth":"創建の年代は不明で諸説。移転の正確な年は史料により異なる。","img":["白山神社 (新潟市)","白山公園","燕喜館","菊理媛神"],"wp":"白山神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Niigata_Enkikan_20130811-01.JPG",1600,1200,"燕喜館"],["c:e/eb/Mount_Haku_from_Onanjimine_2011-07-17.jpg",2560,1707,"菊理媛神"]]},{"id":"15_kyu_saito","n":"旧齋藤家別邸（新潟の豪商）","yomi":"きゅうさいとうけべってい","cat":"近代","rank":"B","y":1918,"era":["taisho"],"sh":"国指定名勝","ad":"新潟市中央区西大畑町","st":"JR新潟駅からバスで約15分、最寄りバス停から歩いて数分","la":37.9225,"lo":139.043,"hook":"砂丘の坂をまるごと庭にした、大正の豪商の «夏の家»。座敷に座ると、緑の庭が絵のように広がる。","lead":"旧齋藤家別邸は、新潟の豪商・齋藤家の4代目が、大正時代の1918年に建てた別荘です。砂丘の斜面を生かした庭と、庭を見わたすように作られた建物がひとつになっていて、国の名勝に指定されています。","story":["大正時代のはじめ、第一次世界大戦で日本は «好景気» にわきました。船や商売で大きなもうけを得た人びとは «成金» と呼ばれました。新潟の豪商・齋藤家も、海運などで大きな財産を築いた家です。4代目の齋藤喜十郎は、1918年、町の高台に、お客をもてなすための別荘を建てました。","この別荘のすごいところは、庭です。新潟の町は、海からの風が運んだ砂が積もった «砂丘» の上にあります。別荘は、その砂丘の坂をそのまま生かし、高いところから低いところへと流れる滝や池、木々を配置しました。«自然の地形がそのまま庭になる» ―― 砂丘の町ならではのアイデアでした。","建物の中に入ると、広い座敷の大きなガラス戸いっぱいに、庭の緑が広がります。部屋から見たときにいちばん美しく見えるよう、建物と庭が一緒に設計されているのです。2階に上がると、また違った角度から庭を見下ろすことができます。«家が額縁、庭が絵»。そんなふうに言いたくなる景色です。","ここでは、多くの客人がもてなされました。当時の新潟には芸妓（げいぎ）の文化も栄え、宴の席は華やかだったでしょう。«みなと町・新潟» の豊かさと誇りが、この別荘にはつまっています。","その後、建物は持ち主が変わりながら残り、やがて新潟市のものとなって公開されるようになりました。2015年には国の名勝に指定されています。今は季節ごとの庭の姿を楽しめるほか、古町芸妓の踊りが披露されることもあり、大正時代の «おもてなしの空間» がよみがえっています。"],"tl":[["江戸時代後期","齋藤家が新潟で商売を広げる"],["明治時代","齋藤家が海運などで大きく発展する"],["1918年","4代目齋藤喜十郎が別邸を建てる"],["昭和時代","持ち主が変わりながら建物と庭が守られる"],["平成時代","新潟市が取得し、一般公開される"],["2015年","国の名勝に指定される"]],"who":[["齋藤喜十郎（4代目）","新潟の豪商。別邸を建てた人物"],["庭を作った職人たち","砂丘の地形を生かした庭を作り上げた人びと"],["古町芸妓","新潟の花街・古町の芸妓。別邸で踊りを披露することもある"]],"deep":["別邸は «近代和風建築» と «回遊式庭園» が一体になった例として評価され、建物と庭の両方が見どころになっている。","庭は砂丘の傾斜を利用した «池泉回遊式» の庭で、斜面を流れる滝や石組みが特徴。平らな土地では作れない立体的な景色になっている。","新潟の豪商は、北前船の時代から明治・大正にかけて海運や米の取引で財を築いた。齋藤家はその代表的な家のひとつとされる。","周辺の西大畑・旭町一帯は、明治から昭和にかけての洋館や屋敷が残る地区で、«新潟のお屋敷町» の雰囲気を歩いて楽しめる。","別邸は2015年に «旧齋藤氏別邸庭園» として国の名勝になった。名勝は、景色の美しさや芸術的な価値を認めて指定される。","大正時代は第一次世界大戦の好景気で、全国の成金たちが豪華な別荘や庭を作った。旧齋藤家別邸はその時代の空気を今に伝える。"],"look":["座敷の大きなガラス戸ごしに見る庭","砂丘の斜面を生かした滝と池","2階からの庭のながめ","周辺の西大畑のお屋敷町（北方文化博物館新潟分館など）"],"q":["旧齋藤家別邸の庭は、どんな地形を生かして作られている?","新潟の町の «砂丘» の斜面。高低差を生かして滝や池を配置しています。"],"myth":"","img":["古町芸妓","名勝","新潟市"],"wp":"旧齋藤家別邸","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/%E6%97%A7%E9%BD%8B%E8%97%A4%E6%B0%8F%E5%88%A5%E9%82%B8%E5%85%A5%E5%8F%A3.jpg",5472,3648,"旧齋藤家別邸"],["c:8/8f/Niigata_ozashiki_blue.jpg",3916,2634,"古町芸妓"],["c:4/4f/Kamikouchi.JPG",640,480,"名勝"],["c:a/a5/Niigata_Montage3.png",1493,2359,"新潟市"]]},{"id":"15_kyu_ozawa","n":"旧小澤家住宅（新潟の廻船問屋）","yomi":"きゅうおざわけじゅうたく","cat":"町","rank":"B","y":1880,"era":["edo","meiji"],"sh":"","ad":"新潟市中央区上大川前通12番町","st":"JR新潟駅からバスで約15分、«本町» 付近から歩いて約5分","la":37.924,"lo":139.048,"hook":"米と船で栄えた港町・新潟。川べりの商家の奥へ進むと、帳場、蔵、庭と、豪商の暮らしがそのまま残る。","lead":"旧小澤家住宅は、江戸時代の終わりから明治にかけて、米の商売や船での運送（廻船業）で栄えた小澤家の家です。信濃川の近く、昔の港町の中心にあり、店、住まい、蔵、庭が一つの敷地にまとまって残っています。今は一般に公開され、港町・新潟の商人の暮らしを知ることができます。","story":["江戸時代、新潟の町は信濃川の河口にあり、川ぞいに船着き場が並んでいました。越後平野でとれた米は川舟で新潟へ運ばれ、ここから大きな船に積みかえられて、大坂や江戸へ運ばれていきました。小澤家は、そんな港町で米などをあつかう商人として力をつけた家です。","明治になると、小澤家は自分の船を持って品物を運ぶ «廻船業» にも乗り出しました。日本海を行き来する «北前船» の時代です。北海道のニシンや昆布、上方の品物が新潟に集まり、越後の米が各地へ出ていきました。«船が一回うまく往復すれば、大きなもうけになる» ―― そのかわり、嵐にあえばすべてを失う。まさに命がけの商売でした。","家の中に入ると、まず店の間があります。ここで客と取引をし、帳面をつけました。奥へ進むと、家族の住まい、そして大事な品物をしまう土蔵。表から奥へと細長く続く «うなぎの寝床» のようなつくりは、町家の典型です。庭には、北前船で運ばれてきたと伝わる石も置かれています。","1869年、新潟は横浜や神戸などとともに、外国に開かれた港 «開港五港» のひとつになりました。港町の商人たちは、時代の大きな変化の中で、新しい商売の道を探していきます。小澤家の住宅には、そうした明治の港町の空気が残っています。","建物は長く小澤家の人びとに守られ、のちに新潟市のものとなって、整備のうえ公開されるようになりました。«港の町だった新潟» は、今は大きな都市になり、昔の姿は見えにくくなっています。この家の中を歩くと、川と船と米で結ばれていた町の記憶がよみがえってきます。"],"tl":[["江戸時代後期","小澤家が新潟で米穀などの商売をはじめる"],["1869年","新潟港が開港（開港五港のひとつ）"],["明治時代","小澤家が廻船業に進出し、家が大きく発展"],["明治〜大正","主屋や蔵などが整えられる"],["平成時代","新潟市の所有となり、整備のうえ一般公開"],["現在","港町・新潟の商家の暮らしを伝える施設として公開"]],"who":[["小澤家の人びと","米の商売と廻船業で栄えた新潟の商家"],["北前船の船頭たち","日本海を行き来し、各地の品物を運んだ人びと"],["新潟の町衆","港町を支えた商人や職人たち"]],"deep":["小澤家住宅は、店・住まい・蔵・庭が一つの敷地にまとまって残る点が貴重とされる。新潟の町なかでは、こうした商家の建物はほとんど失われている。","北前船は、大坂と北海道を日本海回りで結んだ «買い積み船»。船主が自分で品物を買い、寄港先で売って利益を得た。","新潟は信濃川と阿賀野川の河口にあり、川舟で運ばれてきた内陸の米が集まる «米の港» だった。","庭の石には、北前船が船の重しとして積んできた石が使われたという話が伝わる。各地の港町で同じような話が語られている。","新潟の町は明治以降の大火や戦後の開発で古い建物の多くを失っており、この家は港町の古い姿を伝える貴重な存在になっている。","開港五港は、横浜・神戸・長崎・函館・新潟。日本海側では新潟だけが選ばれた。"],"look":["店の間と帳場のしつらえ","奥へ細長く続く町家のつくり","土蔵と庭（北前船ゆかりと伝わる石）","近くの信濃川と旧港町のまち並み"],"q":["明治時代に新潟港が選ばれた、外国に開かれた5つの港をまとめて何という?","«開港五港»。横浜・神戸・長崎・函館・新潟で、日本海側では新潟だけでした。"],"myth":"庭石が北前船で運ばれたという話は伝承。建物の建築年代は部分ごとに異なる。","img":["北前船","廻船問屋","新潟港"],"wp":"旧小澤家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Former_Ozawa_Family_Residence_20131106.JPG",1600,1200,"旧小澤家住宅"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:6/69/Mura_House.jpg",3264,2448,"廻船問屋"],["c:9/9c/Niigata_West_Port_2019.jpg",4320,2883,"新潟港"]]},{"id":"15_sasagawa","n":"旧笹川家住宅（大庄屋の屋敷）","yomi":"きゅうささがわけじゅうたく","cat":"町","rank":"B","y":1826,"era":["edo"],"sh":"国の重要文化財","ad":"新潟市南区味方","st":"JR新潟駅から車で約40分（バスもあるが本数が少ない）","la":37.7845,"lo":139.0,"hook":"8つの村をたばねた大庄屋の屋敷。門をくぐると、そこは «村の役所» であり «小さなお城» だった。","lead":"旧笹川家住宅は、江戸時代に «味方組» と呼ばれる8つの村をたばねた大庄屋・笹川家の屋敷です。表門や大きな主屋、蔵などがそろって残り、国の重要文化財に指定されています。江戸時代の村の «まとめ役» が、どれほどの力を持っていたかがよくわかる場所です。","story":["江戸時代、村々は «庄屋（名主）» が中心になって治めていました。そのうえに立つのが «大庄屋»。いくつもの村をたばね、年貢を集め、村どうしのもめごとをまとめる、殿さまと村人をつなぐ大事な役目です。笹川家は、中ノ口川ぞいの味方組8か村の大庄屋を代々つとめた家でした。","屋敷の入り口にある大きな表門は、ふつうの農家にはない立派なものです。門をくぐると、広い土間と、いくつもの座敷がつながる主屋があります。ここは家族の住まいであると同時に、村の «役所» でもありました。役人が見回りに来たときには、ここで迎え、話し合いをしたのです。","«なぜ農家の家にお城のような門や座敷があるの?» ―― それは、藩の役人や身分の高い客を迎えるための «格式» が必要だったからです。座敷の造りや部屋の並びには、客の身分によって通す部屋を変える、きびしい決まりが反映されています。","越後平野は、今でこそ日本有数の米どころですが、昔は «水との戦い» の土地でした。川はたびたびあふれ、田んぼは腰までつかる «深田» が多くありました。大庄屋は、堤防や用水の工事を村々にとりまとめ、洪水から田を守る役目も負っていました。笹川家の屋敷は、そうした苦労と努力の中心だったのです。","明治になって大庄屋の制度はなくなりましたが、屋敷は守られ、昭和になって国の重要文化財に指定されました。今は一般に公開され、座敷に上がって江戸時代の空気を感じることができます。広い屋敷を歩いていると、村人たちが年貢を運びこむ声が聞こえてくるようです。"],"tl":[["江戸時代初期","笹川家が味方組の大庄屋をつとめるようになる"],["江戸時代","8か村の年貢や治水などをとりまとめる"],["1826年ごろ","火災のあと、主屋（居室部）が建て直されたと伝わる"],["1871年","廃藩置県。やがて大庄屋の役目は終わる"],["昭和時代","国の重要文化財に指定される"],["現在","新潟市が管理し一般公開"]],"who":[["笹川家の当主たち","味方組8か村の大庄屋を代々つとめた"],["味方組の村人たち","年貢を納め、治水工事に参加した人びと"],["藩の役人","見回りなどで屋敷を訪れた人びと"]],"deep":["大庄屋は、藩によって «割元» «大肝煎» などと呼び名がちがう。笹川家は、村々と藩の間に立つ中間役として大きな権限をもった。","屋敷は表門・主屋・蔵などが一体で残り、大庄屋の屋敷構えが丸ごとわかる例として重要文化財に指定されている。","主屋は «表の役所としての部分» と «家族の住まいの部分» に分かれ、使い分けがはっきりしている。","越後平野の «深田» では、腰まで泥につかって田植えをすることもあった。大規模な排水や治水が進むのは明治以降で、とくに昭和の土地改良で様子が大きく変わった。","味方は中ノ口川ぞいの地域。«川の恵み» と «川の脅威» の両方と向き合ってきた土地で、治水の歴史は地域の暮らしそのものだった。","近くには、郷土の画家の作品を展示する施設など、味方の歴史を伝える場所があり、あわせて訪れる人も多い。"],"look":["大庄屋の格式を示す表門","客の身分で使い分けた座敷の並び","広い土間と主屋の大きな屋根","敷地内の蔵や庭"],"q":["大庄屋とはどんな役目?","いくつもの村をたばね、年貢の取りまとめや村のもめごとの解決、治水などを担当した、殿さまと村人をつなぐ役です。"],"myth":"主屋の建築年は伝承・資料により幅がある。","img":["大庄屋","中ノ口川","越後平野"],"wp":"旧笹川家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/NiigataCityOpenData_kyusasagawake02.jpg",4752,3168,"旧笹川家住宅"],["c:2/2c/Okuda_House%2CHirano.jpg",1600,1200,"大庄屋"],["c:a/a1/Nakanokuchigawa_Sluice.jpg",4146,2332,"中ノ口川"],["c:c/c6/Echigo-plain.jpg",2848,1868,"越後平野"]]},{"id":"15_ashigaru","n":"旧新発田藩足軽長屋","yomi":"きゅうしばたはんあしがるながや","cat":"大名屋敷","rank":"B","y":1842,"era":["edo"],"sh":"国の重要文化財","ad":"新発田市大栄町","st":"JR羽越本線新発田駅から歩いて約15分","la":37.955,"lo":139.33,"hook":"かやぶき屋根の下に、同じ間取りの部屋がずらり。殿さまの家来で «いちばん下の武士» たちは、ここでどう暮らしたのか。","lead":"旧新発田藩足軽長屋は、江戸時代の終わりごろに建てられた、足軽（身分の低い武士）たちの集合住宅です。かやぶきの長い平屋に、いくつもの家族が壁一枚で並んで暮らしました。武士の住まいで、このような長屋がそのまま残る例はとても少なく、国の重要文化財に指定されています。","story":["新発田藩は、溝口家が治めた藩です。江戸時代のはじめに溝口家がこの地に入り、城と城下町を作りました。武士にもいろいろな身分があり、殿さまに近い家老もいれば、いちばん下で城の警備や雑用をつとめる «足軽» もいました。足軽長屋は、その足軽たちの住まいです。","長屋に入ると、小さな土間、板の間、そして畳の部屋。どの家もほぼ同じ間取りです。«狭い!» と思うかもしれません。でも、当時の足軽の暮らしとしては、ごくふつうの広さでした。壁の向こうからはとなりの家族の声が聞こえ、子どもたちの笑い声が長屋じゅうに響いていたでしょう。","足軽の給料はとても少なく、それだけでは暮らしていけませんでした。そこで多くの足軽は、傘張りや細工物などの «内職» をして家計を助けました。«武士は食わねど高楊枝» ということわざがありますが、実際の足軽たちは、刀を置いて手仕事に精を出す毎日だったのです。","この長屋の建物の中からは、建てた年を書いた «棟札（むなふだ）» が見つかっていて、1842年（天保13年）に建てられたことがわかっています。年代がはっきりしていることも、この建物の大きな価値です。","明治になって武士の身分はなくなり、長屋は町の人びとの住まいとして使われ続けました。それがかえって、建物が取りこわされずに残る理由になりました。今は修理されて公開され、すぐそばの大名庭園 «清水園» とあわせて、殿さまの庭と足軽の家という «武士の上と下» を見くらべることができます。"],"tl":[["1598年","溝口秀勝が新発田に入り、新発田藩が始まる"],["江戸時代前期","新発田城と城下町が整えられる"],["1842年","足軽長屋が建てられる（棟札による）"],["1871年","廃藩置県。新発田藩がなくなる"],["昭和時代","国の重要文化財に指定され、修理のうえ公開"],["現在","近くの清水園とともに見学できる"]],"who":[["足軽たち","新発田藩の下級武士。長屋に住み、内職をしながら暮らした"],["溝口秀勝","新発田藩の初代藩主"],["堀部安兵衛","新発田出身と伝わる赤穂浪士の一人"]],"deep":["足軽長屋は、かやぶき屋根の平屋が細長く続くつくり。一棟を壁で仕切って数戸に分けており、武士の集合住宅の形がよくわかる。","棟札によって建築年がわかる武家住宅は多くない。年代の «ものさし» になる建物として研究上も重要とされる。","足軽の給料は «何石» ではなく «何俵» などで表されることが多く、上級武士とは暮らしぶりが大きくちがった。内職は当たり前だった。","近くの清水園は、新発田藩主・溝口家の下屋敷の庭園で、国の名勝。同じ藩の «上» と «下» の住まいを歩いて比べられる。","新発田は、赤穂浪士の堀部安兵衛の出身地と伝わり、町には安兵衛ゆかりの場所がある。","新発田城の表門と旧二の丸隅櫓は国の重要文化財で、三匹の鯱をのせた三階櫓（復元）も見られる。"],"look":["かやぶき屋根の長い平屋の外観","同じ間取りが並ぶ室内（土間・板の間・畳の間）","長屋の前を流れる川と周辺の景色","すぐ近くの大名庭園・清水園"],"q":["足軽長屋が建てられた年がわかるのはなぜ?","建物の中から、建てた年を書いた «棟札» が見つかったから。1842年（天保13年）とわかっています。"],"koji":[{"w":"武士は食わねど高楊枝","m":"武士は貧しくても、それを表に出さず気位を高くもつ、という意味。実際の足軽は内職で家計を支えていた"}],"myth":"堀部安兵衛の出身地は新発田とされるが、生まれた場所には諸説ある。","img":["清水園","新発田城","足軽"],"wp":"新発田藩","rel":{"ev":[],"grave":[]},"ph":[["c:6/60/160716_Shimizuen_Shibata_Niigata_pref_Japan29s3.jpg",6000,4000,"清水園"],["c:e/eb/Shibata_Castle_001_May2020.jpg",2364,1773,"新発田城"],["c:1/1e/Lacquered_boxes_against_rain.jpg",1989,2822,"足軽"]]},{"id":"15_shiozawa","n":"牧之通り（塩沢宿・鈴木牧之『北越雪譜』）","yomi":"ぼくしどおり","cat":"町","rank":"B","y":1837,"era":["edo"],"sh":"","ad":"南魚沼市塩沢","st":"JR上越線塩沢駅から歩いて約5分","la":37.04,"lo":138.85,"hook":"«雪国の暮らしを、江戸の人は何も知らない»――一人の商人の熱い思いが、江戸のベストセラーを生んだ。","lead":"牧之通りは、三国街道の宿場町だった塩沢に、雁木（がんぎ）のある町並みを整えた通りです。名前は、この町の商人で、雪国の暮らしを本にした『北越雪譜』の作者・鈴木牧之からとられました。通りには牧之の記念館もあります。","story":["鈴木牧之は、江戸時代の中ごろ、塩沢の «縮（ちぢみ）» の仲買などをする商家に生まれました。縮は、雪の上で布をさらして作る麻の織物で、越後の名産品です。牧之は商売で江戸に出かけたとき、おどろきました。«江戸の人は、雪国の雪がどれほど深いか、まったく知らない!»","江戸では、雪は «風流なもの»。雪見をしながら酒を飲み、歌を詠むものでした。でも越後の雪は、家をうずめ、道を閉ざし、ときには人の命も奪う «くらしの相手» です。牧之は «雪国の本当の姿を伝えたい» と考え、雪の結晶の図や、雪下ろし、雪崩、雪の中の祭りや仕事のことを、こつこつと書きためていきました。","ところが、本にするまでがたいへんでした。牧之は江戸の有名な作家たちに協力をたのみましたが、話はなかなか進みません。何十年もの年月がたち、ようやく戯作者の山東京山の協力を得て、1837年に『北越雪譜』の初編が出版されました。牧之はそのとき、もう60歳をこえていました。","本は大評判になりました。雪の結晶の図、雪の中で布をさらす女性たちの姿、雪国の動物や不思議な話 ―― 江戸の人びとは、見たこともない «北の世界» に夢中になりました。『北越雪譜』は、今でも雪国を知るための第一級の資料として読まれています。","塩沢の町は、江戸と越後を結ぶ三国街道の宿場町としてにぎわいました。牧之通りでは、昔の町並みを思わせる雁木や格子の建物が整えられ、冬には雪の中を歩く人びとの姿が見られます。«雪とともに生きる町» の心は、牧之の本とともに、今もこの通りに生きています。"],"tl":[["1770年","鈴木牧之が塩沢に生まれる"],["江戸時代後期","牧之が雪国の暮らしを書きため、出版を目指す"],["1837年","『北越雪譜』初編が江戸で出版される"],["1841年","『北越雪譜』二編が出版される"],["1842年","鈴木牧之が亡くなる"],["平成時代","牧之通りとして町並みが整えられる"]],"who":[["鈴木牧之","塩沢の商人・文人。『北越雪譜』の作者"],["山東京山","江戸の戯作者。『北越雪譜』の出版に協力した"],["山東京伝","京山の兄。牧之は出版の協力をたのんだと伝わる"],["曲亭馬琴","『南総里見八犬伝』の作者。牧之と交流があった"]],"deep":["『北越雪譜』には、顕微鏡で見た雪の結晶の図が載っている。これは古河藩主・土井利位の『雪華図説』を参考にしたとされ、江戸の «雪の結晶ブーム» ともつながっている。","牧之が出版を思い立ってから実現するまで、長い年月がかかった。有名作家とのやりとりがうまくいかなかったことが、手紙などから知られている。","縮は «雪の上でさらす» ことで白く仕上がるとされる。雪国の気候を生かした布づくりで、『北越雪譜』でもくわしく紹介されている。","塩沢は三国街道の宿場町。三国峠を越えて上州（群馬）へ、そして江戸へと続く道で、越後の大名の参勤交代にも使われた。","塩沢の «塩沢紬» や «越後上布» は、今も伝統工芸として作られている。越後上布は国の重要無形文化財でもある。","牧之は絵もよくし、『北越雪譜』の挿絵の元になる絵を自分で描いたといわれる。"],"look":["雁木と格子のある町並み（牧之通り）","鈴木牧之記念館（『北越雪譜』の資料）","冬の雪景色の中の通り","塩沢紬などの伝統工芸にまつわる店"],"q":["鈴木牧之が『北越雪譜』を書こうと思ったきっかけは?","江戸の人が雪国の雪の深さや暮らしをまったく知らないことにおどろき、本当の姿を伝えたいと考えたからです。"],"koji":[],"myth":"出版の経緯（京伝・馬琴とのやりとり）には史料の解釈に諸説。","img":["北越雪譜","三国街道","越後上布"],"wp":"鈴木牧之","rel":{"ev":[],"grave":[]},"ph":[["c:0/01/Hokuetsu_Seppu_Part_2_volume_1.jpg",1753,2776,"北越雪譜"],["c:5/50/FutaiChouseichi.jpg",1280,960,"三国街道"]]},{"id":"15_gangi","n":"高田の雁木通り","yomi":"たかだのがんぎどおり","cat":"町","rank":"B","y":1614,"era":["edo","meiji"],"sh":"","ad":"上越市本町・仲町など（高田地区）","st":"えちごトキめき鉄道高田駅からすぐ","la":37.103,"lo":138.249,"hook":"雪が屋根まで積もっても、町の人は «屋根の下の道» を歩いて買い物に行けた。日本一長い雪国のアーケード。","lead":"雁木とは、家の前に屋根をのばして作った、雪国ならではの «屋根つきの歩道» です。上越市高田には雁木が長く連なり、その長さは合わせて約16kmといわれ、日本一とされます。江戸時代の城下町の町並みとともに、雪と生きてきた人びとの知恵を伝えています。","story":["冬の高田は、日本でも有数の豪雪地です。一晩で何十センチも雪が積もり、家の一階がうまってしまうこともありました。«こんなに雪が降ったら、どうやって外を歩くの?» ―― その答えが雁木です。家の前に屋根をのばし、その下を歩けるようにしたのです。","雁木の下は、それぞれの家の «持ち物» です。でも、となりの家の雁木とつながって、町じゅうに一本の道ができあがります。«自分の家の前を、みんなのために使う»。雁木は、雪国の人びとの助け合いの心から生まれた道でした。","高田の町は、1614年に徳川家康の六男・松平忠輝の城として高田城が築かれたときに作られた城下町です。町の人びとは、早い時期から雁木を作って冬を乗り切ってきたと考えられています。町家は間口がせまく奥行きが長いつくりで、雁木の下には店の入り口が並びました。","明治以降、高田には陸軍の師団が置かれ、町はにぎわいました。雁木の下には商店が並び、冬でも人びとが行き来しました。«雪が降っても、町は止まらない»。雁木は、雪国の町の暮らしそのものを支えるしくみだったのです。","今も高田の町を歩くと、雁木がどこまでも続いています。古い町家を生かした交流施設や、明治に建てられた映画館など、歴史を感じる建物も残ります。雁木の下を歩きながら、ふと見上げると、雪を支えるための太い柱や梁（はり）が目に入ります。何百年も雪と向き合ってきた町の知恵が、そこにあります。"],"tl":[["1614年","松平忠輝の居城として高田城が築かれ、城下町が作られる"],["江戸時代","城下町で雁木が作られ、つながっていく"],["1908年","陸軍第13師団が高田に置かれる"],["1911年","高田でレルヒ少佐によるスキー指導が行われる"],["昭和時代","豪雪の年にも雁木が町の暮らしを支える"],["現在","総延長約16km、日本一の雁木の町として知られる"]],"who":[["松平忠輝","徳川家康の六男。高田城を築いた"],["高田の町人たち","自分の家の前に雁木を作り、つなげてきた人びと"],["レルヒ少佐","オーストリアの軍人。高田で日本に本格的なスキーを伝えた"]],"deep":["雁木は、家の «ひさし» を長くのばして柱で支えたもの。雪の重さに耐えるため、太い柱と梁が使われる。","雁木の下の土地は各家のものなので、形や高さ、材料は家ごとに少しずつちがう。歩いていると、雁木の «つなぎ目» の段差や屋根のちがいに気づく。","高田の雁木は «日本一の長さ» とされるが、数え方によって数字に幅がある。約16kmという数字がよく使われる。","高田は «日本一の豪雪地のひとつ» といわれ、江戸時代には «この下に高田あり» という立て札が立ったという話がある（伝承）。","高田城は石垣を使わず土塁で作られた城で、天守はなく、三重櫓が建てられた（現在のものは復元）。","明治に建てられた映画館 «高田世界館» は、現役の映画館として知られ、町なみ歩きの見どころのひとつになっている。"],"look":["どこまでも続く雁木の町並み（本町・仲町・大町など）","雪を支える太い柱や梁","古い町家を生かした交流施設","高田世界館や高田城址公園"],"q":["雁木とは何?","家の前に屋根をのばして作った «屋根つきの歩道»。雪が積もっても下を歩けるようにした、雪国の知恵です。"],"myth":"«この下に高田あり» の立て札は伝承。雁木の総延長は数え方により異なる。","img":["高田城","松平忠輝","高田世界館"],"wp":"雁木","rel":{"ev":[],"grave":[]},"ph":[["c:b/b6/Himeji_Castle_No09_015.jpg",2304,3456,"雁木"],["c:6/69/Takada_Castle_yagura.JPG",3763,2504,"高田城"],["c:8/8f/Matsudaira_Tadateru.jpg",299,368,"松平忠輝"],["c:e/e0/TakadaSekaikan2019-03-30.jpg",3264,2448,"高田世界館"]]},{"id":"15_shidancho","n":"旧師団長官舎（高田）","yomi":"きゅうしだんちょうかんしゃ","cat":"近代","rank":"B","y":1910,"era":["meiji","taisho"],"sh":"","ad":"上越市大手町","st":"えちごトキめき鉄道高田駅から歩いて約15分","la":37.1085,"lo":138.2455,"hook":"雪国の城下町に建った、白い洋館。ここの主が «スキーを広めよう» と決めたことで、日本のスキーの歴史が始まった。","lead":"旧師団長官舎は、明治時代の終わり、陸軍第13師団が高田に置かれたときに、師団のトップ «師団長» の住まいとして建てられた洋館です。師団長の一人・長岡外史は、オーストリアの軍人レルヒ少佐を迎えてスキーを学ばせ、高田は «日本スキー発祥の地» となりました。","story":["1908年、高田に陸軍の «第13師団» がやって来ました。何千人もの兵士が集まり、城下町はにぎやかになりました。そして師団の長の住まいとして、1910年、洋風の官舎が建てられます。雪国の町に建った白い洋館は、人びとの目にどれほど新しく映ったことでしょう。","この官舎に住んだ師団長の一人が、長岡外史です。長岡は、とても新しいもの好きの軍人でした。«雪の中で兵隊が動けなければ、北国では戦えない» ―― 彼が目をつけたのは、ヨーロッパの軍隊が使っていた «スキー» でした。","1911年、オーストリアの軍人テオドール・フォン・レルヒ少佐が高田にやって来ました。そして1月12日、金谷山のふもとで、将校たちへのスキー指導が始まります。1本のつえを使う «一本杖» のスキーでした。はじめは転んでばかりの兵士たちも、やがて雪の斜面をすべり下りられるようになりました。","スキーは、軍隊だけでなく、町の人びとや学校の子どもたちにも広がっていきました。«雪は閉じこめられるもの» から «雪は楽しむもの» へ。雪国の人びとにとって、それは大きな発想の転換でした。高田から始まったスキーは、やがて日本中の雪国に広がっていきます。","官舎は、戦後もさまざまに使われながら残り、今は修理されて公開されています。洋風の部屋に和室も組み合わせた造りは、明治の軍人の暮らしぶりを伝えています。近くの金谷山には、レルヒ少佐の像が今も町を見守っています。"],"tl":[["1908年","陸軍第13師団が高田に移ってくる"],["1910年","師団長官舎が建てられる"],["1911年1月12日","レルヒ少佐が高田でスキー指導を始める（日本スキー発祥）"],["1925年","第13師団が廃止される（軍縮）"],["戦後","建物がさまざまな用途に使われる"],["現在","修理され、一般公開されている"]],"who":[["長岡外史","第13師団の師団長。スキー導入をすすめた"],["テオドール・フォン・レルヒ","オーストリアの軍人。高田で日本に本格的なスキーを伝えた"],["高田の人びと","スキーを学び、雪国の新しい楽しみとして広めた"]],"deep":["第13師団は日露戦争のころにつくられた師団で、1908年に高田に置かれ、1925年の宇垣軍縮で廃止された。","レルヒ少佐が伝えたのは、1本の長いつえを使う «一本杖スキー» で、アルペンスキーの初期のスタイルとされる。","1月12日は «スキーの日» とされ、高田でスキー指導が始まった日にちなむ。","官舎は洋風の外観だが、内部には和室もあり、明治末の «和洋折衷» の住まいのかたちがわかる。","長岡外史は、スキーのほか飛行機にも強い関心をもった人物として知られ、新しい技術を積極的に取り入れようとした軍人だった。","近くの金谷山には «日本スキー発祥記念館» やレルヒ少佐の像があり、官舎とあわせて訪ねるとスキー伝来の物語がよくわかる。"],"look":["明治末の洋風の外観","和と洋を組み合わせた室内","師団の歴史を伝える展示","近くの金谷山（レルヒ像・日本スキー発祥記念館）"],"q":["日本で本格的なスキー指導が始まったのはいつ、どこ?","1911年1月12日、高田（今の上越市）の金谷山周辺。レルヒ少佐が第13師団の将校に教えました。"],"myth":"官舎の建築年・使われ方の細部は資料により差がある。","img":["長岡外史","テオドール・フォン・レルヒ","金谷山"],"wp":"第13師団 (日本軍)","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/%E6%97%A5%E6%9C%AC%E9%99%B8%E8%BB%8D%E7%AC%AC%E5%8D%81%E4%B8%89%E5%B8%AB%E5%9B%A3%E3%81%AB%E3%82%88%E3%82%8B%E8%BB%8D%E4%BA%8B%E6%BC%94%E7%BF%92.jpg",600,385,"第13師団 (日本軍)"],["c:7/79/Lieutenant_General_Gaishi_Nagaoka.jpg",950,1214,"長岡外史"],["c:9/97/Theodor_Edler_von_Lerch.jpg",300,438,"テオドール・フォン・レルヒ"],["c:4/48/Mountain_Ski_Kanaya_01.jpg",4288,3216,"金谷山"]]},{"id":"15_iwanohara","n":"岩の原葡萄園（川上善兵衛）","yomi":"いわのはらぶどうえん","cat":"産業","rank":"B","y":1890,"era":["meiji","showa"],"sh":"","ad":"上越市北方","st":"えちごトキめき鉄道高田駅から車で約15分","la":37.1,"lo":138.3,"hook":"雪国でワインを? 笑われても、1万回以上の交配をくり返した男がいた。日本のワインぶどうの «父» の畑。","lead":"岩の原葡萄園は、明治時代の1890年に川上善兵衛が開いたぶどう園・ワイナリーです。善兵衛は、日本の気候に合うぶどうを求めて品種の交配を重ね、今も日本中で育てられている «マスカット・ベーリーA» を生み出しました。「日本のワインぶどうの父」と呼ばれています。","story":["川上善兵衛は、高田の近くの大きな地主の家に生まれました。まわりの村人たちは、雪が多く、田んぼに向かない土地で苦しい暮らしをしていました。«この土地でも育つ作物で、みんなを豊かにしたい» ―― 善兵衛が選んだのが、ぶどうとワインでした。","1890年、善兵衛は自分の家の庭をつぶして、ぶどう園を開きました。«雪国でぶどう? しかもワイン?» と、まわりの人びとはあきれたといいます。外国からぶどうの苗を取り寄せて育ててみると、日本の湿気や病気にやられて、うまく育たないものがたくさんありました。","«外国のぶどうがだめなら、日本に合うぶどうを作ればいい»。善兵衛は、ちがう品種のぶどうをかけ合わせる «交配» を始めました。その数は1万回をこえたといわれます。何十年もの努力の末に生まれたのが «マスカット・ベーリーA»。病気に強く、日本の気候でもよく育ち、おいしいワインになるぶどうでした。","ワインづくりには、もう一つのくふうがありました。発酵のときに温度が上がりすぎると、ワインの味が悪くなります。そこで善兵衛は、冬に積もった雪を石蔵に運びこみ、その冷たさでワインを冷やしたのです。«じゃまものの雪を、味方にする» ―― 雪国ならではの知恵でした。","善兵衛のぶどう園は、何度も経営の危機に直面しましたが、協力者に支えられて続きました。今も岩の原葡萄園ではワインづくりが行われ、雪室として使われた石蔵が残っています。善兵衛が生んだマスカット・ベーリーAは、国際的なワインの品種としても登録され、世界に «日本のぶどう» として知られるようになりました。"],"tl":[["1868年","川上善兵衛が生まれる"],["1890年","岩の原葡萄園を開く"],["明治時代後半","雪の冷たさを利用する石蔵（雪室）をつくる"],["1927年","マスカット・ベーリーAの交配が行われる"],["1934年","寿屋（のちのサントリー）の鳥井信治郎が経営を支援"],["1944年","川上善兵衛が亡くなる"],["2013年","マスカット・ベーリーAが国際機関（OIV）に品種登録される"]],"who":[["川上善兵衛","岩の原葡萄園の創設者。ぶどうの品種改良に生涯をささげた"],["鳥井信治郎","寿屋（サントリーの前身）の創業者。善兵衛の葡萄園を支援した"],["坂口謹一郎","上越出身の発酵学者。善兵衛の研究を応援したとされる"],["勝海舟","善兵衛の父と交流があり、善兵衛もその影響を受けたといわれる"]],"deep":["マスカット・ベーリーAは、アメリカ系のぶどう «ベーリー» とヨーロッパ系の «マスカット・ハンブルグ» をかけ合わせて生まれたとされる。","善兵衛が生み出した品種のうち、特にすぐれたものとして «優良品種» に選ばれたものがいくつかあり、ブラック・クイーンなども知られる。","雪室の石蔵は、冬の雪を貯めて低温を保つしくみ。電気冷蔵庫のない時代に、発酵温度をおさえる工夫として使われた。","2013年のOIV（国際ぶどう・ぶどう酒機構）への登録により、ヨーロッパなどへ輸出するワインのラベルに品種名を表示できるようになった。","善兵衛は品種改良の成果を論文にまとめ、全国の栽培家に苗を広めたとされる。日本各地のワインづくりの土台をつくった人物といえる。","善兵衛と勝海舟の交流については、屋敷を訪ねたなどの話が伝わるが、詳しい関係には不明な点もある。"],"look":["雪室として使われた石蔵","ぶどう畑と、善兵衛ゆかりの展示","ワインショップ・見学施設（営業時間は要確認）","畑から見る頸城平野の景色"],"q":["川上善兵衛が生み出し、今も日本中で育てられているぶどうの品種は?","«マスカット・ベーリーA»。病気に強く、日本の気候でもよく育つ赤ワイン用のぶどうです。"],"myth":"«交配1万回以上» は伝えられる数字。勝海舟・坂口謹一郎との関わりの詳細は諸説。","img":["川上善兵衛","マスカット・ベーリーA","雪室"],"wp":"岩の原葡萄園","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/Zenb%C4%93_Kawakami_%281936%29.jpg",640,909,"岩の原葡萄園"],["c:4/4e/NevatersMassanella.jpg",300,201,"雪室"]]},{"id":"15_naoetsu_pow","n":"直江津捕虜収容所跡（平和記念公園）","yomi":"なおえつほりょしゅうようじょあと","cat":"昭和","rank":"B","y":1942,"era":["showa","heisei"],"sh":"","ad":"上越市（直江津地区・関川の近く）","st":"えちごトキめき鉄道直江津駅から歩いて約15分","la":37.175,"lo":138.248,"hook":"遠い南の国から連れてこられた兵士たちと、この町の人びと。悲しい記憶を、和解の場所に変えた公園。","lead":"太平洋戦争中、直江津には連合国軍の捕虜を収容する施設がありました。ここに収容されたオーストラリアの兵士たちのうち、多くの人が寒さや病気、栄養不足などで亡くなりました。戦後、この場所は平和記念公園として整備され、亡くなった人びとを悼み、両国の和解と友好を願う場所になっています。","story":["1942年、太平洋戦争のさなか、東南アジアでとらえられたオーストラリアの兵士たちが、船で直江津に送られてきました。彼らは、近くの工場で働かされました。南の国から来た兵士たちにとって、越後の冬は想像を絶する寒さでした。","食べ物は足りず、着るものも薄く、病気が広がりました。戦争が終わるまでに、収容されたオーストラリア兵のうち、およそ60人が亡くなったとされています。ふるさとから遠く離れた雪の町で命を落とした若者たちのことを思うと、胸がしめつけられます。","戦争が終わると、捕虜の扱いについて裁判が行われました。収容所で働いていた日本人の職員たちが責任を問われ、そのうち何人もが死刑になりました。一つの収容所から、これほど多くの死刑が出たことは、戦後の裁判の中でも重い出来事として記憶されています。亡くなったのは、捕虜だけではなかったのです。","«この悲しい歴史を、どう伝えていけばいいのか» ―― 直江津の人びとは長い時間をかけて考えました。そして戦後50年の1995年、収容所の跡地に平和記念公園がつくられました。公園には、オーストラリアと日本の両方の犠牲者を悼む像や碑が建てられています。","公園をきっかけに、オーストラリアの元捕虜やその家族と、上越の人びとの交流が生まれました。«憎しみではなく、友情を次の世代へ»。静かな公園に立つと、戦争がもたらした苦しみと、それを乗りこえようとした人びとの努力の両方が伝わってきます。訪れるときは、亡くなったすべての人への敬意をもって歩きたい場所です。"],"tl":[["1941年","太平洋戦争が始まる"],["1942年","直江津に捕虜収容所が置かれ、オーストラリア兵が送られてくる"],["1942〜1945年","厳しい環境の中で、約60人の捕虜が亡くなったとされる"],["1945年","戦争が終わり、捕虜が解放される"],["戦後","収容所の職員が裁判で裁かれ、死刑になった人もいた"],["1995年","跡地に平和記念公園がつくられる"]],"who":[["オーストラリア兵の捕虜たち","東南アジアでとらえられ、直江津に送られた兵士たち"],["収容所の日本人職員","戦後の裁判で責任を問われた人びと"],["上越の市民","平和記念公園をつくり、オーストラリアとの交流を続けてきた人びと"]],"deep":["直江津の収容所は、東京俘虜収容所の分所の一つとして置かれた。全国に同じような収容所が多数あった。","亡くなった捕虜は約60人とされ、多くは最初の冬を越せなかったといわれる。寒さ、栄養不足、病気が重なったと考えられている。","戦後の横浜での裁判（BC級戦犯裁判）で、この収容所の職員8人が死刑になったとされ、一つの収容所としては特に多い例として知られる。","平和記念公園には、両国の犠牲者を悼む像や碑があり、«加害と被害の両方を見つめる» 場所として作られた点が特徴的。","公園の整備をきっかけに、元捕虜やその家族が上越を訪れるなど、市民レベルの交流が続けられてきた。","捕虜の扱いについては当時から国際的な取り決め（ジュネーブ条約など）があったが、日本は批准しておらず、戦後大きな問題となった。"],"look":["平和記念公園の像と碑（亡くなった人への黙とうを）","公園内の説明板（収容所の歴史）","関川の河口に近い直江津の町並み","公園の静かな空気の中で、戦争と和解について考える"],"q":["平和記念公園がつくられたのは、戦後何年の年?","戦後50年の1995年。オーストラリアと日本の両方の犠牲者を悼む場所として整備されました。"],"myth":"亡くなった捕虜の人数・死刑となった職員の人数は資料により表現が異なる場合がある。","img":["直江津捕虜収容所","捕虜","BC級戦犯"],"wp":"上越市","rel":{"ev":[],"grave":[]},"ph":[["c:b/b2/Joetsu_Montage.jpg",1024,1447,"上越市"],["c:8/8b/Gorskii._Austrian_prisoners_of_war_in_Olonets_province.jpg",3234,2792,"捕虜"]]},{"id":"15_okutadami","n":"奥只見ダム","yomi":"おくただみだむ","cat":"昭和","rank":"B","y":1960,"era":["showa"],"sh":"","ad":"魚沼市湯之谷（奥只見）","st":"JR上越新幹線浦佐駅から路線バスで約80分（冬期は道路閉鎖）","la":37.155,"lo":139.245,"hook":"高さ157m。山奥にそびえる «コンクリートの城壁» は、戦後の日本を電気で動かすための大工事だった。","lead":"奥只見ダムは、新潟県と福島県の県境近くを流れる只見川につくられた、大きな発電用のダムです。1960年に完成し、重力式コンクリートダムとしては日本で最も高い約157mをほこります。戦後の電力不足を解消するため、深い山の中で行われた大工事でした。","story":["戦争が終わったあとの日本は、電気が足りませんでした。工場を動かし、家に明かりをともすには、たくさんの電気がいります。そこで目をつけられたのが、雪どけ水が豊かに流れる只見川でした。«この川の水で、日本を明るくしよう» ―― 国を挙げた大プロジェクトが始まります。","ところが、ダムをつくる場所は、道もない深い山の奥。人も機械も運べません。そこでまず、工事の資材を運ぶための道路がつくられました。山をくりぬくトンネルを次々と掘り、ようやくダムの現場へたどり着いたのです。この道は今 «奥只見シルバーライン» と呼ばれ、道の大部分がトンネルという珍しい道路です。","ダムの工事は、雪との戦いでもありました。冬は何メートルもの雪にとざされ、作業は危険と隣り合わせでした。工事の中で、多くの人が命を落としました。巨大なダムの陰には、厳しい自然の中で働いた人びとの汗と犠牲があったのです。","1960年、ついにダムが完成しました。高さ約157m。重いコンクリートの重さそのもので水をせき止める «重力式» のダムとして、日本一の高さです。せき止められた水は、大きな人造湖 «奥只見湖» となり、発電所へと送られていきました。","今、奥只見湖では遊覧船が走り、秋には山々が赤や黄色に染まります。ダムの上に立つと、湖の広さと、谷底までの深さに足がすくみます。«このダムがあったから、戦後の日本は明るくなった» ―― そう思うと、山の中のコンクリートの壁が、少しちがって見えてきます。"],"tl":[["1952年","電源開発株式会社が設立される"],["1950年代前半","只見川の電源開発が本格化する"],["1950年代","工事用道路（のちの奥只見シルバーライン）が建設される"],["1960年","奥只見ダムが完成し、発電を開始"],["2000年代","発電所の増設が行われる"],["現在","奥只見湖は遊覧船や紅葉の名所として親しまれる"]],"who":[["工事に携わった人びと","雪と山の中で工事を進め、中には命を落とした人もいた"],["電源開発株式会社","戦後の電力不足を解消するためにつくられた会社。ダムを建設"],["只見川流域の人びと","ダムの建設で暮らしが大きく変わった人びと"]],"deep":["«重力式コンクリートダム» は、コンクリートの重さで水圧に耐える形式。奥只見ダムの高さ約157mは、この形式では日本一とされる。","奥只見湖の貯水量は日本でも最大級で、戦後の «只見川電源開発» の中心となるダムだった。","奥只見シルバーラインは、ダム建設の資材を運ぶためにつくられた道路で、全長の大部分がトンネル。のちに一般に開放された。","只見川では、奥只見ダムのほか田子倉ダムなど大きなダムが次々とつくられ、首都圏などに電気を送った。","ダム湖の底には、かつての山あいの集落や道が沈んでいる。発電の恩恵のかげで、ふるさとを離れた人びとがいたことも忘れてはならない。","冬は深い雪のため、シルバーラインは閉鎖される。訪れることができるのは、おおむね春の終わりから秋までの期間だけ。"],"look":["高さ157mのダムの堤体と、ダムの上からのながめ","奥只見湖の遊覧船（運航期間に注意）","奥只見シルバーラインのトンネル群","秋の紅葉（見ごろは例年10月ごろ）"],"q":["奥只見ダムは、どんな形式のダムとして日本一の高さ?","«重力式コンクリートダム»。コンクリートの重さで水をせき止める形式で、約157mは日本一です。"],"myth":"","img":["奥只見湖","奥只見シルバーライン","只見川"],"wp":"奥只見ダム","rel":{"ev":[],"grave":[]},"ph":[["c:c/cf/Okutadamidam-0A3N80pbxFs6g.JPG",400,299,"奥只見ダム"],["c:3/31/Tadamigawa.jpg",600,448,"只見川"]]},{"id":"15_awashima","n":"粟島（本保・内浦の島）","yomi":"あわしま","cat":"島","rank":"B","y":1964,"era":["edo","showa"],"sh":"","ad":"岩船郡粟島浦村","st":"村上市の岩船港から高速船で約55分、普通船で約1時間半（季節により便数が変わる）","la":38.465,"lo":139.25,"hook":"周りの海が島ごと持ち上がった――地震で生まれ変わった、日本海に浮かぶ小さな島。","lead":"粟島は、村上市の沖合に浮かぶ小さな島で、島全体が «粟島浦村» という一つの村になっています。島には内浦と釜谷の二つの集落があり、漁業とともに暮らしてきました。1964年の新潟地震では島が大きく隆起し、今も海岸にその跡を見ることができます。","story":["岩船港から船に乗ってしばらくすると、水平線に緑の島が見えてきます。それが粟島です。周りはおよそ20km余り。島には車もあまり走っておらず、波の音と鳥の声が聞こえる、のんびりとした島です。","島の人びとは、昔から海とともに生きてきました。魚をとり、海藻をとり、ときには本土と行き来して暮らしを立ててきました。島の名物 «わっぱ煮» は、木の器に焼いた魚と汁を入れ、そこへ真っ赤に焼いた石を放りこんで一気に煮たてる料理です。«ジュワッ» という音とともに湯気が立ちのぼり、海の香りが広がります。漁師たちが浜で作っていた料理だと伝わります。","1964年6月16日、新潟地震が起きました。震源は粟島の近くの海の底でした。このとき、粟島の島全体が大きく持ち上がり、海岸の岩場が一気に陸地になったといわれます。«昨日まで海だったところが、今日は歩ける» ―― 島の人びとの驚きはどれほどだったでしょう。","島には、古い家々の由来や、神社にまつわる言い伝えが残っています。源平の時代の落人が住みついたという話や、本土から渡ってきた人びとの話など、いくつもの伝承があります。小さな島だからこそ、代々の記憶が大切に語り継がれてきたのです。","今、粟島は «島留学» で子どもたちを受け入れるなど、新しい取り組みも行っています。海岸を歩けば、地震で持ち上がった岩場や、日本海に沈む夕日。本土からわずか1時間ほどなのに、時間の流れがまったくちがう島です。"],"tl":[["古代〜中世","島に人が住み、海とともに暮らす（詳しいことは伝承による）"],["江戸時代","村上藩の領地として漁業を中心に暮らす"],["明治時代","町村制により、島全体で一つの村となる"],["1964年6月16日","新潟地震。震源に近い粟島が大きく隆起する"],["平成時代","«しおかぜ留学» などの島留学が始まる"],["現在","離島の村として、観光と漁業で暮らしを支える"]],"who":[["粟島の漁師たち","海とともに暮らし、わっぱ煮などの文化を伝えてきた人びと"],["島の旧家の人びと","島の成り立ちにまつわる伝承を語り継いできた人びと"],["島留学の子どもたち","本土から島に来て学ぶ子どもたち"]],"deep":["新潟地震（マグニチュード7.5）の震源は粟島の南の海底とされ、島は1m前後隆起したと報告されている。岩場の海岸に、隆起の跡とされる地形が見られる。","粟島浦村は、島全体が一つの村。新潟県で人口がもっとも少ない自治体として知られる。","わっぱ煮は «わっぱ»（杉などの薄板を曲げて作った器）で作る漁師料理。焼いた石を入れることで一気に煮立たせる。","島の集落は、島の東側の内浦と、西側の釜谷の二つ。港は内浦にあり、本土からの船が着く。","島には野鳥が多く、渡り鳥の中継地としても知られる。春や秋にはバードウォッチングの人びとも訪れる。","島の旧家や集落の成り立ちについては、源平の落人伝説や本土からの移住など、いくつもの言い伝えがあり、確かな史料は少ない。"],"look":["新潟地震で隆起したとされる海岸の岩場","内浦の港と集落","島の名物・わっぱ煮","島の西側から見る日本海の夕日"],"q":["粟島の名物料理 «わっぱ煮» は、何を使って一気に煮立たせる?","真っ赤に焼いた石。木の器に魚と汁を入れ、焼き石を放りこんで煮ます。"],"myth":"島の旧家の起源（落人伝説など）は伝承。隆起量は測り方によって数字に幅がある。","img":["粟島浦村","新潟地震","わっぱ煮"],"wp":"粟島","rel":{"ev":[],"grave":[]},"ph":[["c:8/8e/Uchiura.jpg",1280,857,"粟島浦村"],["c:b/bd/%E3%82%8F%E3%81%A3%E3%81%B1%E7%85%AE.jpg",3840,2160,"わっぱ煮"]]},{"id":"15_yoneyama","n":"米山峠（北国街道の峠）","yomi":"よねやまとうげ","cat":"街道","rank":"B","y":1700,"era":["edo"],"sh":"","ad":"柏崎市米山町・上越市柿崎区の境","st":"JR信越本線米山駅から歩いて旧道入口まで約10分（峠越えは山道。車利用が便利）","la":37.28,"lo":138.485,"hook":"«米山さんから雲が出た»――越後を二つに分ける山のすそを、佐渡の金も、殿さまの行列も越えていった。","lead":"米山峠は、江戸時代の北国街道が米山のすそを越える、けわしい峠道です。米山は上越と中越を分ける山で、海ぎわまで山がせまるため、昔の旅人はここを «難所» として恐れました。佐渡で掘られた金銀も、この道を通って江戸へ運ばれていきました。","story":["新潟県の海沿いを走ると、柏崎と上越の間で、山がぐっと海にせまってきます。その中心にそびえるのが米山です。昔の街道は、この山のすそを上り下りしながら越えるしかありませんでした。«米山三里（約12km）» といわれ、旅人にとってはひと苦労の道でした。","北国街道は、中山道の追分（長野県）から善光寺・高田を通って、日本海沿いを北へ進む道です。江戸時代、佐渡の金山で掘られた金銀は、船で出雲崎に運ばれ、そこから北国街道を通って江戸へ送られました。«御金荷（ごきんに）» と呼ばれたこの大切な荷物も、米山のけわしい峠を越えていったのです。","峠のふもとの鉢崎（はっさき）には、関所が置かれていました。旅人は手形を見せ、荷物を調べられてから先へ進みます。«入り鉄砲に出女»――とくに武器と女性の出入りはきびしく見張られました。関所の近くには宿もあり、峠を越える前の旅人たちが体を休めました。","米山は、昔から信仰の山でもありました。山頂近くには薬師如来がまつられ、海を行く船乗りたちは、米山を目印にして航海の安全を祈ったといいます。柏崎の民謡 «三階節» には «米山さんから雲が出た、今に夕立が来るやら» と歌われ、人びとが米山の空模様で天気を読んでいたことがわかります。","明治になって鉄道が海沿いに通ると、峠道を歩く人は少なくなりました。それでも、今も旧道の一部をたどることができ、木々の間から日本海がのぞく景色は、昔の旅人と同じものです。«越後を二つに分ける山» を、自分の足で越えてみると、街道の旅のたいへんさと面白さが実感できます。"],"tl":[["江戸時代初期","北国街道が整備され、米山の峠道が使われる"],["江戸時代","鉢崎に関所が置かれ、旅人や荷物を改める"],["江戸時代","佐渡の金銀が出雲崎から北国街道を通って江戸へ運ばれる"],["1689年","松尾芭蕉と曽良が『おくのほそ道』の旅で越後の海沿いを通る"],["明治時代","海沿いに鉄道が通り、峠道の役目は小さくなる"],["現在","旧道の一部を歩くことができる"]],"who":[["街道の旅人たち","米山の峠道を越えて行き来した人びと"],["御金荷を運んだ役人・人足","佐渡の金銀を江戸へ運んだ人びと"],["松尾芭蕉","江戸時代の俳人。『おくのほそ道』の旅で越後の海沿いを歩いた"],["関所の役人","鉢崎の関所で旅人を改めた人びと"]],"deep":["米山は標高約993m。上越地方と中越地方の境となる山で、«米山から西が上越、東が中越» という感覚が地元にはある。","佐渡の金銀が本土に上げられた港は出雲崎。そこから北国街道・中山道を通って江戸に運ばれ、その道筋は «佐渡路» とも呼ばれる。","鉢崎の関所は、北国街道の要所を押さえる関所の一つ。関所跡の近くには、当時をしのぶ案内などがある。","芭蕉の旅に同行した曽良の日記には、越後の海沿いの道中や宿泊地のことが記されており、このあたりも通ったと考えられている。","«三階節» は柏崎を代表する民謡で、米山が歌いこまれている。山の雲を見て天気を予想するのは、海の近くの人びとにとって大切な知恵だった。","米山の信仰は、薬師如来をまつる寺と結びついており、山の開山についてはさまざまな言い伝えがある。"],"look":["米山峠の旧道（木々の間から見える日本海）","鉢崎の関所跡と周辺の案内","米山の山容（海沿いの国道からよく見える）","米山駅周辺の海岸の景色"],"q":["佐渡の金銀は、どの港に上げられ、どの道を通って江戸へ運ばれた?","出雲崎の港に上げられ、北国街道などを通って江戸へ運ばれました。米山の峠も越えていきました。"],"koji":[{"w":"入り鉄砲に出女","m":"江戸に入る鉄砲と、江戸から出る女性（大名の妻など）を関所がきびしく調べたこと"}],"myth":"米山の開山や薬師信仰の起源は伝承。芭蕉の具体的な通過地点は日記の読み方に諸説。","img":["米山 (新潟県)","北国街道","三階節","出雲崎町"],"wp":"柏崎市","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Kashiwazaki_Lover%E2%80%99s_Cape_April2022.jpg",4032,2688,"柏崎市"],["c:4/41/Find47_Niigata-_Ryokan_and_Yuhi-no-oka_Park_%28Izumozaki_Town%29-m.jpg",1920,1280,"出雲崎町"]]},{"id":"15_yukyuzan","n":"悠久山と蒼柴神社（長岡藩）","yomi":"ゆうきゅうざんとあおしじんじゃ","cat":"寺社","rank":"B","y":1781,"era":["edo","meiji"],"sh":"","ad":"長岡市悠久町","st":"JR長岡駅からバスで約20分、«悠久山» 下車","la":37.438,"lo":138.88,"hook":"長岡の殿さまが «永遠に続け» と願って名づけた森。桜の下に、城下町の祈りと誇りが眠る。","lead":"悠久山は、長岡市の東にある小高い山と森で、江戸時代に長岡藩主・牧野家がつくった蒼柴神社（あおしじんじゃ）があります。今は «悠久山公園» として、桜の名所や市民のいこいの場になっています。長岡城をかたどった郷土史料館もあり、長岡の歴史を学ぶことができます。","story":["長岡藩は、江戸時代のはじめから明治まで、牧野家が治めた藩です。牧野家は «常在戦場（つねに戦場にいる心がまえで）» という家の教えで知られていました。その牧野家が、江戸時代の中ごろ、町の東の山に神社を建てました。それが蒼柴神社です。","«悠久» とは、«はてしなく長く続くこと»。藩が、そして長岡の町が、いつまでも続きますように ―― 山の名前には、そんな願いがこめられていると伝わります。神社は藩の人びとにとって大切な場所となり、祭りのときには城下町から多くの人がお参りに訪れました。","ところが幕末、長岡藩は大きな試練をむかえます。1868年の戊辰戦争で、家老・河井継之助は新政府軍と戦う道を選び、長岡の町は戦火に包まれました。«北越戦争» と呼ばれるこの戦いで、長岡城は落城し、町の多くが焼けてしまいました。","戦いに敗れた長岡藩には、食べる物も足りませんでした。そこへ届けられた見舞いの米百俵を、藩の大参事・小林虎三郎は «みんなで食べてしまえばすぐなくなる。学校をつくって、未来の人を育てよう» と、学校の資金にあてました。この «米百俵» の話は、今も長岡の誇りとして語り継がれています。","焼け野原から立ち上がった長岡の人びとにとって、悠久山は町の «心のふるさと» でした。やがて山は公園として整えられ、多くの桜が植えられました。春、桜の下を歩き、長岡城を模した郷土史料館を見上げると、«悠久» の名に込められた願いが、今も生きているように感じられます。"],"tl":[["1618年","牧野忠成が長岡に入り、長岡藩が始まる"],["1781年ごろ","蒼柴神社が悠久山に建てられる"],["1868年","戊辰戦争（北越戦争）。長岡城が落城し、町が焼ける"],["1870年","小林虎三郎が «米百俵» を学校の資金にあてる"],["1968年","長岡城をかたどった郷土史料館が悠久山に建つ"],["現在","桜の名所・悠久山公園として親しまれる"]],"who":[["牧野家の藩主たち","長岡藩を治め、蒼柴神社を建てた"],["河井継之助","幕末の長岡藩家老。北越戦争で新政府軍と戦った"],["小林虎三郎","«米百俵» で学校をつくった長岡藩の人物"],["山本五十六","長岡出身の軍人。郷土史料館などで長岡の偉人として紹介される"]],"deep":["蒼柴神社は、長岡藩9代藩主・牧野忠精のころに建てられたとされ、藩主家ゆかりの神をまつる。祭神については資料によって説明に幅がある。","«常在戦場» は長岡藩牧野家の家訓として有名で、今も長岡市の精神的なスローガンとして使われることがある。","悠久山公園の郷土史料館は、長岡城の天守をイメージした建物だが、実際の長岡城には天守がなく、三階櫓が天守の代わりだったとされる。","北越戦争で河井継之助は、ガトリング砲を用意したことで知られる。長岡城はいったん奪い返されたものの、再び落城した。","«米百俵» の話は、戦後に山本有三の戯曲で広く知られ、近年は国会の演説でも引用されて全国的に有名になった。","悠久山公園には桜が多く植えられ、春には多くの花見客でにぎわう。小動物園もあり、市民に親しまれている。"],"look":["蒼柴神社の社殿と森","長岡城をかたどった郷土史料館（長岡の歴史展示）","春の桜並木","公園からの長岡の町のながめ"],"q":["長岡藩の小林虎三郎が、見舞いの米を学校のために使った話を何という?","«米百俵»。今の食べ物より未来の人づくりを選んだ話として、長岡の誇りになっています。"],"koji":[{"w":"常在戦場","m":"いつも戦場にいるような心がまえで物事にのぞむこと。長岡藩牧野家の家訓"},{"w":"米百俵","m":"目先の利益より、将来のための教育や人づくりを大切にすること"}],"myth":"蒼柴神社の祭神・創建年、«悠久山» の命名の由来には諸説。","img":["長岡藩","河井継之助","米百俵"],"wp":"悠久山","rel":{"ev":[],"grave":[]},"ph":[["c:1/12/Nagaoka_u.jpg",640,480,"悠久山"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"]]},{"id":"15_ryosen","n":"隆泉寺（良寛の墓）","yomi":"りゅうせんじ","cat":"墓所","rank":"B","y":1831,"era":["edo"],"sh":"","ad":"長岡市島崎","st":"JR越後線小島谷駅から歩いて約20分","la":37.575,"lo":138.785,"hook":"子どもたちと手まりをついて遊んだお坊さん・良寛。その人生の終わりの地に、静かな墓が立つ。","lead":"隆泉寺は、江戸時代後期の僧・良寛が晩年を過ごした長岡市島崎（旧和島村）にあるお寺で、良寛の墓があります。良寛はこの地の木村家に身を寄せ、1831年に亡くなりました。近くには良寛ゆかりの美術館や、良寛が住んだ庵の跡もあります。","story":["良寛は、1758年、出雲崎の名主の家に生まれました。けれども家を継がず、若くして出家します。岡山の円通寺で厳しい修行をしたあと、ふるさとの越後に帰ってきました。寺に住まず、山の小さな庵に暮らし、托鉢をしながら生きる道を選んだのです。","良寛は、子どもたちが大好きでした。村へ托鉢に出ると、子どもたちが «良寛さま、遊ぼう!» と集まってきます。良寛は手まりをついたり、かくれんぼをしたり。かくれんぼで隠れたまま、子どもたちが帰ってしまっても、翌朝まで隠れていたという話まで伝わっています。本当かどうかはわかりませんが、良寛の人がらをよく表す話として愛されてきました。","年をとって体が弱った良寛は、70歳近くになって、島崎の木村家の庵に移りました。ここで、若い尼僧・貞心尼と出会います。二人は和歌をやりとりし、心を通わせました。貞心尼が良寛の歌をまとめた『はちすの露』には、二人のやりとりが残されています。","1831年のはじめ、良寛は木村家の庵で静かに亡くなりました。最期には、貞心尼たちがそばにいたと伝わります。«うらを見せ おもてを見せて 散るもみぢ» ―― 良寛が最期に口にしたとされるこの句は、飾らずに生きた人生そのもののようです。","良寛の墓は、木村家の菩提寺である隆泉寺に建てられました。今も墓の前には花がたむけられ、良寛を慕う人びとが全国から訪れます。子どもと遊び、歌を詠み、ものを持たずに生きた良寛。その静かな墓の前に立つと、«本当の豊かさとは何だろう» と考えさせられます。"],"tl":[["1758年","良寛が出雲崎に生まれる"],["1779年ごろ","備中玉島（岡山県）の円通寺で修行を始める"],["江戸時代後期","越後に帰り、国上山の五合庵などで暮らす"],["1826年ごろ","島崎の木村家の庵に移る"],["1827年ごろ","貞心尼と出会う"],["1831年","良寛が島崎で亡くなる。隆泉寺に墓が建てられる"],["1835年","貞心尼が良寛の歌をまとめた『はちすの露』を編む"]],"who":[["良寛","江戸時代後期の僧・歌人・書家。晩年を島崎で過ごした"],["貞心尼","良寛の晩年に交流した尼僧。『はちすの露』を編んだ"],["木村元右衛門","良寛を自分の家の庵に迎えた島崎の人"],["由之","良寛の弟。兄を支えたと伝わる"]],"deep":["良寛の書は、細くのびやかな線で知られ、江戸時代の書の中でも独特の美しさがあると高く評価されている。","«うらを見せ おもてを見せて 散るもみぢ» は、良寛の辞世として伝えられるが、良寛自身の作ではなく、別の人の句を口にしたものともいわれる。","良寛の墓には、良寛の詩が刻まれているとされる。墓の建立には、弟の由之ら身近な人びとが関わったと伝わる。","近くには «良寛の里美術館» や、良寛が住んだ木村家の庵室跡があり、あわせて訪ねると晩年の暮らしがよくわかる。","良寛は «大愚（たいぐ）» と名乗った。«大いなる愚か者» という意味で、欲をもたず、ありのままに生きる姿勢を表している。","同じ島崎には、古代の役所跡・八幡林官衙遺跡もある。«古代の役人» と «江戸の僧» の物語が一つの町に重なっている。"],"look":["隆泉寺の良寛の墓","木村家の庵室跡（良寛が亡くなった場所）","良寛の里美術館（書や資料）","島崎の静かな町並みと周辺の田園"],"q":["良寛と和歌をやりとりし、その歌を『はちすの露』にまとめた尼僧はだれ?","貞心尼。良寛の晩年に出会い、心を通わせました。"],"koji":[{"w":"散る桜 残る桜も 散る桜","m":"良寛の句として伝わる言葉。今咲いている桜もいつかは散る、命のはかなさを表す"}],"myth":"かくれんぼの話や辞世の句は伝承。«散る桜» の句も良寛作と確定しているわけではない。","img":["貞心尼","五合庵","出雲崎町"],"wp":"良寛","rel":{"ev":[],"grave":[]},"ph":[["c:4/41/Find47_Niigata-_Ryokan_and_Yuhi-no-oka_Park_%28Izumozaki_Town%29-m.jpg",1920,1280,"出雲崎町"]]},{"id":"15_ogi_ko","n":"小木港（佐渡の番所と北前船寄港地）","yomi":"おぎこう","cat":"島","rank":"B","y":1700,"era":["edo","meiji"],"sh":"","ad":"佐渡市小木町","st":"両津港から車で約1時間／直江津港からの航路あり（運航期間・便数は要確認）","la":37.815,"lo":138.28,"hook":"金銀を積んだ船が出ていき、北前船が帆をたたんだ港。たらい舟がゆれる小さな湾に、佐渡の «海の玄関» の記憶が残る。","lead":"小木港は、佐渡の南のはしにある港です。江戸時代には、佐渡金山の金銀を本土へ運び出す港として、また日本海を行き交う北前船が立ち寄る港として栄えました。港を見張る番所も置かれていました。近くには、船大工の町・宿根木があります。","story":["佐渡の南のはし、小さな岬に囲まれた湾が小木港です。湾は深く、波もおだやかで、船をとめるのにぴったりの場所でした。江戸時代のはじめ、佐渡金山で金銀がたくさん掘られるようになると、小木は、その金銀を本土へ運び出す港として大切にされました。","金銀を積んだ船は、小木から海を渡って出雲崎に着き、そこから陸路で江戸へ運ばれました。«一粒たりともなくしてはならない» ―― 大切な荷物を守るため、港には番所が置かれ、船や人の出入りがきびしく調べられました。","江戸時代の中ごろになると、日本海には «北前船» が行き交うようになります。大坂から瀬戸内海をまわり、日本海を北へ、北海道まで。小木港は、風を待ったり、品物を売り買いしたりする «寄港地» としてにぎわいました。港には船宿や問屋が並び、上方や北国の品物が集まりました。","すぐ近くの宿根木（しゅくねぎ）は、北前船の船主や船大工が住んだ集落です。狭い土地に家がぎっしりと並び、船の材料や技術を生かした家づくりが見られます。«船で稼いだお金で家を建てた» ―― 小さな集落に、海の男たちの誇りがつまっています。","小木の海では、昔から «たらい舟» が使われてきました。大きなたらいのような舟で、岩の多い入り江でサザエやアワビをとるのに便利な舟です。今は観光用のたらい舟にも乗ることができます。ゆらゆらゆれるたらい舟から港を見わたすと、金銀と北前船でにぎわった昔の小木の姿が浮かんでくるようです。"],"tl":[["江戸時代初期","佐渡金山の金銀を運び出す港として整備される"],["江戸時代","番所が置かれ、船や人の出入りを見張る"],["江戸時代中期〜明治","北前船の寄港地としてにぎわう"],["1802年","佐渡小木地震が起こり、周辺の土地が隆起したといわれる"],["1991年","宿根木が国の重要伝統的建造物群保存地区に選ばれる"],["現在","佐渡と本土を結ぶ港の一つ。たらい舟の観光も人気"]],"who":[["佐渡奉行所の役人","金銀の運び出しや港の出入りを管理した"],["北前船の船主・船頭","日本海を行き交い、小木に立ち寄った人びと"],["宿根木の船大工","北前船をつくり、港町の暮らしを支えた"],["小木の漁師たち","たらい舟で漁をしてきた人びと"]],"deep":["佐渡の金銀は、小木から出雲崎へ海を渡り、そこから陸路で江戸へ運ばれるのが主なルートだった。小木と出雲崎は «金の道» の両はしといえる。","1802年の佐渡小木地震では、小木周辺の土地が隆起し、港の使い勝手にも影響があったといわれる。海岸の地形にその跡が見られるとされる。","北前船は «動く総合商社» ともいわれ、寄港地で品物を売り買いしながら航海した。小木にも問屋が集まった。","宿根木は、船大工の技術を生かした家づくりが特徴で、三角形の敷地に建つ «三角家» はよく知られる。","たらい舟は «はんぎり» とも呼ばれ、もとは洗たく用などのおけを漁に使ったのが始まりと伝わる。","小木は、佐渡と上越（直江津）を結ぶ航路の港でもあり、今も佐渡の «南の玄関口» の役割を持つ。"],"look":["小木港の湾とおだやかな海","たらい舟（観光用に乗ることができる）","近くの宿根木の町並みと三角家","港の周辺に残る番所や問屋にまつわる史跡・案内"],"q":["佐渡の金銀は、小木港から船でどこへ運ばれた?","本土の出雲崎。そこから陸路で江戸へ運ばれました。"],"myth":"番所の正確な位置や、たらい舟の起源は伝承を含む。1802年の地震による隆起の程度は資料により異なる。","img":["宿根木","たらい舟","北前船"],"wp":"小木港","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Sadokisen_Ogi_terminal.jpg",5736,3828,"小木港"],["c:0/0c/Sado_Shukunegi.jpg",5184,3456,"宿根木"],["c:9/99/%E7%9F%A2%E5%B3%B6%E7%B5%8C%E5%B3%B6%E3%81%9F%E3%82%89%E3%81%84%E8%88%9F_-_panoramio.jpg",3000,2002,"たらい舟"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"]]},{"id":"15_mushukunin","n":"無宿人の墓（佐渡相川）","yomi":"むしゅくにんのはか","cat":"墓所","rank":"B","y":1778,"era":["edo"],"sh":"","ad":"佐渡市相川地区","st":"両津港からバスで約1時間、«佐渡金山前» 方面へ。相川の町なかから歩いて行ける","la":38.035,"lo":138.245,"hook":"江戸の町から «宿のない人» たちが送られ、金山の暗い坑道で水をくみ続けた。名もなき人びとの小さな墓。","lead":"無宿人の墓は、佐渡金山で働かされ、亡くなった «無宿人» たちを供養する墓です。江戸時代の後半、江戸などで住まいや戸籍のない人びとが捕らえられ、佐渡に送られて、坑道にたまる水をくみ出すきびしい仕事をさせられました。今も地元の人びとによって供養が続けられています。","story":["江戸時代の後半、江戸の町には、住む家も、帳面に名前もない人びとが大勢いました。飢饉で村を追われた人、家を出た人 ―― 彼らは «無宿（むしゅく）» と呼ばれました。幕府は、町の治安を守るという理由で、無宿の人びとを捕らえ、遠く佐渡の金山へ送ることにしました。","佐渡金山は、掘り進むほど坑道が深くなり、地下水があふれて困っていました。水をくみ出さなければ、金銀は掘れません。無宿人たちに任されたのが、この «水替（みずかえ）» の仕事でした。暗く、湿った坑道の底で、交代しながら朝から晩まで水をくみ続ける。体をこわして命を落とす人も少なくありませんでした。","«一度佐渡へ送られたら、生きては帰れない»――そんなうわさが、江戸の町に広まったといわれます。無宿人たちは、ふるさとの家族に会うことも、名前を残すこともなく、佐渡の地で亡くなっていきました。","無宿人の墓は、そうした人びとを弔うために建てられました。墓石には、亡くなった人びとの名前が刻まれているとされます。«名もなき人» とされた彼らの名前を、せめて石に残そうとした人びとがいたのです。","2024年、«佐渡島の金山» は世界文化遺産に登録されました。きらびやかな金の歴史の陰に、ここで働き、亡くなった人びとがいたことを忘れてはなりません。毎年、地元では無宿人の供養祭が行われています。墓の前では、静かに手を合わせたい場所です。"],"tl":[["1601年ごろ","佐渡金山で本格的な採掘が始まったとされる"],["江戸時代中期","坑道が深くなり、地下水の処理が大きな問題になる"],["1778年","江戸の無宿人が佐渡へ送られ、水替の仕事につかされる"],["江戸時代後期〜幕末","多くの無宿人が佐渡へ送られ続ける"],["江戸時代後期","亡くなった無宿人を供養する墓が建てられる"],["2024年","«佐渡島の金山» が世界文化遺産に登録される"]],"who":[["無宿人たち","江戸などから送られ、金山の水替をさせられた人びと"],["佐渡奉行所","金山を管理し、無宿人を使った役所"],["相川の人びと","無宿人の墓を守り、供養を続けてきた人びと"]],"deep":["無宿人を佐渡へ送る制度は1778年（安永7年）に始まったとされ、幕末までに送られた人は約1,800人といわれる。","水替は、坑道の底から水をくみ上げる仕事。桶や手動のポンプを使い、昼夜の交代で続けられた。金山の中でも特に過酷な仕事とされた。","無宿人は、犯罪者として裁かれた人ばかりではなかった。住む場所や身分がないというだけで捕らえられた人も多かったとされる。","無宿人の墓には、亡くなった人の名前や出身地が刻まれているとされ、名もなき労働者の存在を伝える貴重な資料になっている。","地元では毎年、無宿人の供養祭が行われており、地域の人びとが犠牲者を弔い続けている。","世界遺産 «佐渡島の金山» は、相川鶴子金銀山と西三川砂金山からなる。登録にあたっては、金山で働いた人びとの歴史をどう伝えるかも議論になった。"],"look":["無宿人の墓（静かに手を合わせる）","墓石に刻まれた文字","近くの佐渡金山（史跡佐渡金山・道遊の割戸）","相川の町並み（金山の町としての歴史）"],"q":["佐渡に送られた無宿人たちが主にさせられた仕事は?","«水替»。金山の坑道にたまる地下水をくみ出す、とても過酷な仕事でした。"],"myth":"送られた人数・墓の建立年は資料により幅がある。«生きては帰れない» という話は伝承。","img":["無宿","相川 (佐渡市)","道遊の割戸"],"wp":"佐渡金山","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Dohyu_Mine_ac_%282%29.jpg",5973,3971,"佐渡金山"],["c:d/d8/Sado_bugyousyo.JPG",3072,2304,"相川 (佐渡市)"]]}];
